[
	{
		"src": "Eestis ja Hispaanias peeti kinni neli Kemerovo grupeeringu liiget",
		"tgt": "Four members of the Kemerovo group arrested in Estonia and Spain"
	},
	{
		"src": "Postimehe andmetel pidas politsei Hispaanias kinni Eesti allilmas tegutseva niinimetatud Kemerovo grupeeringu juhi Slava Gulevit\u0161i, keda kuritegelikus maailmas tuntakse Slava Kemerovski nime all.",
		"tgt": "According to Postimees, police in Spain have arrested Slava Gulevich, the head of the so-called Kemerovo group operating in the Estonian underworld, known in the criminal world by the name of Slava Kemerovsky."
	},
	{
		"src": "Hispaanias kinni peetud Gulevit\u0161 vahistati kohtu loal.",
		"tgt": "A court had issued for the arrest of Gulevich in Spain."
	},
	{
		"src": "Eile v\u00f5ttis kohus ka kolm Eestis kinni peetud kahtlustatavat vahi alla.",
		"tgt": "Yesterday the court also ordered that three suspects detained in Estonia be held."
	},
	{
		"src": "Kahtlustuse j\u00e4rgi on tegemist niinimetatud Kemerovo kuritegeliku \u00fchenduse liikmetega vanuses 27-57 eluaastat, kes panevad peamiselt toime narkokuritegusid.",
		"tgt": "According to the complaint, they are members of the so-called Kemerovo criminal organization ranging in age from 27 to 57 and committing primarily drug-related crimes."
	},
	{
		"src": "Hispaanias Malaga provintsis Mijases peeti kinni kuritegeliku \u00fchenduse v\u00e4idetav juht.",
		"tgt": "In the Mijas province of Malaga in Spain, the alleged boss of a criminal organization was detained."
	},
	{
		"src": "Eestis peeti kahtlustatavana kinni kolm meest, neist \u00fcks on kogutud andmete kohaselt kuritegeliku \u00fchenduse juhtfiguur ning kaks on kuritegeliku \u00fchenduse liikmed.",
		"tgt": "Three men were detained as suspects in Estonia; according to the gathered evidence, one of them is a leading figure of a criminal organization and two of them are members of a criminal organization."
	},
	{
		"src": "Kogutud andmed viitavad sellele, et kuritegelikus \u00fchenduses olid selgelt \u00e4ra jaotatud \u00fclesanded ja rollid.",
		"tgt": "The gathered information points to a clear division of roles and functions in the criminal organization."
	},
	{
		"src": "Kuritegeliku \u00fchenduse tegevuse eesm\u00e4rk oli toime panna narkokuritegusid ning seel\u00e4bi teenida kriminaaltulu\", kommenteeris kriminaalasja kohtueelse menetluse juht, riigiprokur\u00f6r Vahur Verte.",
		"tgt": "The objective of the criminal organizations activity was to commit to drug crimes, and thereby earn criminal gains,\u201d commented the head of pretrial proceedings in the criminal case, public prosecutor Vahur Verte."
	},
	{
		"src": "\"Me ei v\u00e4lista, et k\u00f5nealuses kriminaalasjas kahtlustatavate ring suureneb\", lisas prokur\u00f6r.",
		"tgt": "\u201cWe can\u2019t rule out that the number of suspects in this criminal case will increase.\u201d"
	},
	{
		"src": "Tegemist on inimestega, kes on ka varem \u00f5iguskaitseasutuste huviorbiiti sattunud, ning m\u00f5ned neist on narkokuritegude eest karistust kandnud.",
		"tgt": "These are people who have been in the sphere of interest for law-enforcement agencies in the past and some of them have been punished for drug crimes."
	},
	{
		"src": "Verte r\u00f5hutas, et kogu uurimise v\u00e4ltel on olulisel kohal olnud koost\u00f6\u00f6 Hispaania kolleegidega.",
		"tgt": "Verte emphasized that cooperation with Spanish colleagues has played an important part throughout the investigation."
	},
	{
		"src": "\"Rahvusvaheline koost\u00f6\u00f6 on meie jaoks tavap\u00e4raseks muutunud ning sellen\u00e4dalane operatsioon n\u00e4itab koost\u00f6\u00f6 edukust\", kommenteeris prokur\u00f6r Verte.",
		"tgt": "\u201cInternational cooperation has become the standard for us and this week\u2019s operation shows success of the cooperation,\u201d commented prosecutor Verte."
	},
	{
		"src": "Keskkriminaalpolitsei talituse juht Ago Leis \u00fctles, et kinnipidamistele eelnes ligi poolteist aastat kestnud eeluurimine.",
		"tgt": "Head of the central criminal police division Ago Leis said that the arrests were preceded by a preliminary investigation that lasted almost a year a half."
	},
	{
		"src": "\"N\u00e4dala esimeses pooles pikaaegne t\u00f6\u00f6 realiseerus ning pidasime samaaegselt Eestis ja Hispaanias kuritegudes kahtlustavad kinni\", lausus ta.",
		"tgt": "\u201cThe long-running work came to fruition in the first half the week and we made simultaneous arrests of the suspects in these crimes in Estonia and Spain,\u201d he said."
	},
	{
		"src": "Leis lisas, et keskkriminaalpolitsei ametnikud olid Hispaanias kinnipidamisel abiks.",
		"tgt": "Leis added that central criminal police officials assisted in the Spanish arrests."
	},
	{
		"src": "Juba aastaid on meil hea kontakt ning \u00fcksteisem\u00f5istmine Hispaania politsei ja tsiviilkaardiv\u00e4ega.",
		"tgt": "For years now, we have had good contacts and mutual understanding with the Spanish police and civil guard forces."
	},
	{
		"src": "Need kinnipidamised on j\u00e4rjekordsed s\u00f5numid kurjategijatele, et saame nad k\u00e4tte ka teisest Euroopa otsast\", \u00fctles Leis.",
		"tgt": "These arrests send yet another message to criminals that and we will get them from the other end of Europe,\u201d said Leis."
	},
	{
		"src": "Seni kogutud teave osutab \u00fcheselt, et vabaduses viibides v\u00f5ivad kahtlustuse saanud mehed j\u00e4tkata uute kuritegude toimepanemist, mist\u00f5ttu taotles prokuratuur nende vahistamist ja kohus kiitis selle ka heaks.",
		"tgt": "The information gathered to this point shows unequivocally that if they remained at liberty, the men named in the complaint could continue committing new crimes, which is why the prosecutor\u2019s office sought their arrests and the court approved it as well."
	},
	{
		"src": "Hispaanias vahistatud meest ootab tema loovutamine Eestile.",
		"tgt": "A man arrested in Spain now faces extradition to Estonia."
	},
	{
		"src": "K\u00f5nealuse kriminaalasja raames on konfiskeerimise tagamiseks arestitud kinnisvara, s\u00f5idukid ja sularaha.",
		"tgt": "In the framework of this criminal case, real estate, vehicles and cash were impounded to secure the confiscation."
	},
	{
		"src": "Kriminaalasja kohtueelset menetlust viib l\u00e4bi keskkriminaalpolitsei organiseeritud kuritegude b\u00fcroo ning juhib riigiprokuratuur.",
		"tgt": "The pretrial proceedings in the criminal case are being conducted by the criminal police\u2019s organized crime office and headed by the public prosecutor\u2019s office."
	},
	{
		"src": "Tallinna linnakohus m\u00f5istis Slava Gulevit\u0161i 2005. aastal s\u00fc\u00fcdi v\u00e4ljapressimises ja karistas teda viieaastase vangistusega.",
		"tgt": "In 2005, Tallinn City Court convicted Slava Gulevich of extortion and sentenced him to five years in prison."
	},
	{
		"src": "Eelmise k\u00fcmnendi keskel peeti Gulevit\u0161it toonase allilmaliidri Nikolai Tarankovi j\u00e4rel Eesti kuritegelikus maailmas t\u00e4htsuselt teiseks meheks.",
		"tgt": "In the middle of last decade, he was considered to rank second in the Estonian criminal world after the underworld leader Nikolai Tarankov."
	},
	{
		"src": "Kemerovost p\u00e4rit Gulevit\u0161 t\u00f5usis Eesti allilmas esile 1990. aastate alguses, kui ta hakkas Tallinnas tegelema v\u00e4ljapressimistega.",
		"tgt": "Gulevich, who is from Kemerovo, became prominent in the Estonian underworld in the early 1990s when he became involved in extortion in Tallinn."
	},
	{
		"src": "V\u00e4idetavalt maksustas ta erinevate hotellide juures tegutsenud taksojuhid ja prostituudid ning n\u00f5udis \u00e4rimeestelt igakuist katusemaksu.",
		"tgt": "He allegedly put the squeeze on taxi drivers and prostitutes operating at different hotels, and demanded monthly pay off from businessmen."
	},
	{
		"src": "Rahvusvahelised \u00fchisoperatsioonid, kriminaaltulu konfiskeerimised ja j\u00f5ustunud kohtuotsused kinnitavad, et v\u00f5itlus organiseerutud kuritegevuse vallas on t\u00f5hus.",
		"tgt": "Joint international operations, confiscation of criminal gains, and court decisions handed down all confirmed that the fight against organized crime is effective."
	},
	{
		"src": "N\u00e4iteks viimased kohtuotsused, niinimetatud Dikajevi kuritegeliku \u00fchenduse kriminaalasjast eraldatud kaheksa s\u00fc\u00fcdistatavat, kellelt konfiskeeriti kriminaaltulu 80 000 eurot, v\u00f5i kohtuotsus \u00fcheksa isiku suhtes selles, et Igor Aleynikov l\u00f5i 2006. aastal kuritegeliku \u00fchenduse, mis oli suunatud salasigarettide ebaseaduslikule kauplemisele ja inimkaubandusega seotud kuritegude toimepanemisele Ida-Virumaal ja L\u00f5una-Eestis.",
		"tgt": "For example the latest court decisions, the eight accused to be tried separately from the so-called Dikajev crime organization criminal case, from whom 80,000 euros was confiscated, or the court decision with regard to nine persons accusing Igor Aleynikov of establishing in 2006 a crime organization engaged in illegal trade in contraband cigarettes and commission of crimes related to human smuggling in Ida-Viru County and southern Estonia."
	},
	{
		"src": "Konfiskeeritud kriminaaltulu suuruseks on seal ligi 71 500 eurot.",
		"tgt": "The amount of criminal gains confiscated in that case was close to 71,500 euros."
	},
	{
		"src": "Nendes kriminaalasjades on taganud edu see, et politseinikud vahetavad iga p\u00e4ev v\u00e4liskolleegidega infot ja prokur\u00f6rid t\u00f5endeid ning vajadusel tehakse koos toiminguid \u00fcksk\u00f5ik mis Euroopa Liidu riigis.",
		"tgt": "What has ensured success in these criminal cases is the fact that police offices exchange information each day with their colleagues and prosecutors exchange evidence, and if necessary they conduct operations jointly in any other European Union member state."
	},
	{
		"src": "Kodaniku\u00f5iguste r\u00fchmitus hoiatab Missourisse reisimise eest",
		"tgt": "Civil rights group issues travel warning for Missouri"
	},
	{
		"src": "Organisatsioon National Association for the Advancement of Colored People (NAACP) on hoiatanud Missourisse reisivaid mustanahalisi inimesi osariigi diskrimineeriva poliitika ja rassistlike r\u00fcnnakute eest.",
		"tgt": "The National Association for the Advancement of Colored People has put out an alert for people of color traveling to Missouri because of the state's discriminatory policies and racist attacks."
	},
	{
		"src": "R\u00fchmituse avalduses on kirjas: \"Missouri osariigi kohta v\u00e4ljastatud NAACP reisim\u00e4rkus, mis kehtib kuni 2017. aasta 28. augustini, kutsub k\u00f5iki afroameeriklastest reisijaid, k\u00fclastajaid ja missourilasi olema terves osariigis ringi liikudes eriti t\u00e4helepanelikud ja \u00fclimalt ettevaatlikud, arvestades tervet rodu kahtlaseid rassip\u00f5hiseid s\u00fcndmuseid, mis on viimasel ajal \u00fcle osariigi toimunud ja siinkohal ka v\u00e4lja toodud.\"",
		"tgt": "\"The NAACP Travel Advisory for the state of Missouri, effective through August 28th, 2017, calls for African American travelers, visitors and Missourians to pay special attention and exercise extreme caution when traveling throughout the state given the series of questionable, race-based incidents occurring statewide recently, and noted therein,\" the group's statement reads."
	},
	{
		"src": "NAACP s\u00f5nul \u00e4rgitasid r\u00fchmitust reisihoiatust v\u00e4ljastama nii hiljutine Missouri seadus, mis teeb diskrimineerimist puudutavate kohtuasjade v\u00f5itmise raskemaks, kui ka asjaolu, et osariigi korrakaitsjate sihtm\u00e4rkideks on ebav\u00f5rdselt suures osas just v\u00e4hemused.",
		"tgt": "A recent Missouri law making it harder for people to win discrimination lawsuits, as well as the state's law enforcement disproportionately targeting minorities prompted the group to issue the travel alert, the NAACP said."
	},
	{
		"src": "\"Inimeste kodaniku\u00f5igusi rikutakse.",
		"tgt": "\"You have violations of civil rights that are happening to people."
	},
	{
		"src": "Nad t\u00f5mmatakse teeserva nende nahav\u00e4rvi t\u00f5ttu, neid pekstakse v\u00f5i tapetakse,\" \u00fctles NAACP Missouri haru president Rod Chapel ajalehele The Kansas City Star.",
		"tgt": "They're being pulled over because of their skin color, they're being beaten up or killed,\" the president of the Missouri NAACP, Rod Chapel, told The Kansas City Star."
	},
	{
		"src": "\"Me pole kunagi varem nii tihedalt kaebusi saanud.\"",
		"tgt": "\"We are hearing complaints at a rate we haven't heard before.\""
	},
	{
		"src": "Tegu on esimese taolise hoiatusega, mille organisatsioon on USA osariigi kohta v\u00e4ljastanud.",
		"tgt": "It is the first such warning that the organization has issued for a state in the US."
	},
	{
		"src": "R\u00fchmitus viitas sellistele s\u00fcndmustele nagu rassistlikud solvangud mustanahaliste \u00fcli\u00f5pilaste suunal Missouri \u00dclikoolis ja Tennessee'st p\u00e4rit 28-aastase mustanahalise Tory Sandersi surm.",
		"tgt": "The group cited incidents such as racial slurs against black students at the University of Missouri and the death of Tory Sanders, 28, a black man from Tennessee."
	},
	{
		"src": "Sanders suri selle aasta alguse poole kahtlastel asjaoludel p\u00e4rast seda, kui tal sai osariigist l\u00e4bi s\u00f5ites bensiin otsa ja Missouri politsei v\u00f5ttis ta vahi alla, ilma et teda oleks kuriteos s\u00fc\u00fcdistatud.",
		"tgt": "Sanders died under questionable circumstances earlier this year after he ran out of gas while traveling through the state, and was taken into custody by Missouri police without being accused of a crime."
	},
	{
		"src": "Lisaks viitab m\u00e4rkus Missouri peaprokur\u00f6ri hiljuti koostatud aruandele, mis n\u00e4itab, et osariigis peatatakse mustanahaliste autojuhtide autosid 75% suurema t\u00f5en\u00e4osusega kui valgenahaliste omi.",
		"tgt": "The advisory also points to a recent report by the Missouri Attorney General's Office showing that black drivers in the state were 75 percent more likely to be pulled over than whites."
	},
	{
		"src": "\"M\u00e4rkus on m\u00f5eldud selleks, et inimesed oleksid teadlikud ning hoiataksid oma perekondi, s\u00f5pru ja t\u00f6\u00f6kaaslasi selle eest, mis v\u00f5ib Missouris juhtuda,\" \u00fctles Chapel.",
		"tgt": "\"The advisory is for people to be aware, and warn their families and friends and co-workers of what could happen in Missouri,\" Chapel said."
	},
	{
		"src": "\"Inimesed peavad valmis olema, t\u00e4hendagu see siis kautsjoniraha kaasav\u00f5tmist v\u00f5i sugulaste teavitamist sellest, et nad osariiki l\u00e4bivad.\"",
		"tgt": "\"People need to be ready, whether it's bringing bail money with them, or letting relatives know they are traveling through the state.\""
	},
	{
		"src": "FBI vihakuritegudest teavitamise programmi v\u00e4rskeimate andmete p\u00f5hjal dokumenteeriti Missouris 2015. aastal 100 vihakuritegu, mis paigutab osariigi sarnaste rikkumiste arvu poolest riigi l\u00e4bil\u00f5ikes 16. kohale.",
		"tgt": "Missouri recorded 100 hate crimes in 2015, according to the latest figures from the FBI's hate crime reporting program, ranking the state at 16th in the country in terms of the number of such violations."
	},
	{
		"src": "Reisihoiatus on ka vastuseks Missouri uuele seadusele, mis raskendab ettev\u00f5tte kohtusse kaebamist eluaseme v\u00f5i t\u00f6\u00f6 otsinguil diskrimineerimise p\u00e4rast.",
		"tgt": "The travel warning is also a response to a new Missouri law that would make it more difficult to sue a business for housing or employment discrimination."
	},
	{
		"src": "Ameerika Kodanikuvabaduste \u00dchendus (American Civil Liberties Union \u0096 ACLU) oli v\u00e4ljastanud varem reisim\u00e4rkused Texase ja Arizona kohta p\u00e4rast seda, kui need osariigid v\u00f5tsid vastu immigratsiooniseadused, mis kohustasid kohalikke v\u00f5ime inimesi immigratsioonialaste rikkumiste eest vahistama, sest ACLU s\u00f5nul suurendab see rassilist profileerimist.",
		"tgt": "Previously, the American Civil Liberties Union (ACLU) had issued travel advisories for Texas and Arizona after the states passed immigration enforcement laws requiring local law enforcement to detain people on immigration violations which the ACLU said would increase racial profiling."
	},
	{
		"src": "Tavaliselt annab reisihoiatusi v\u00e4lja v\u00e4lisministeerium teiste riikide kohta, aga viimasel ajal on hakanud huvigrupid kasutama seda meedet vastureaktsioonina teatud USA-sisestele seadustele ja trendidele.",
		"tgt": "Travel warnings are usually issued by the State Department for other countries, but lately, advocacy groups have resorted to the measure in response to certain laws and trends inside the US."
	},
	{
		"src": "Hepatiit: mida v\u00f5iks iga\u00fcks teada selle raske haiguse erinevatest vormidest?",
		"tgt": "Hepatitis: what should everyone know about the different forms of this serious disease?"
	},
	{
		"src": "Hepatiit ehk maksap\u00f5letik v\u00f5ib olla p\u00f5hjustatud viie erineva - A, B, C, D ja E hepatiidiviiruse poolt.",
		"tgt": "Hepatitis \u2013 inflammation of the liver \u2013 may be caused by any of five hepatitis viruses \u2013 A, B, C, D and E."
	},
	{
		"src": "K\u00f5ik need viirused kutsuvad esile maksakoe \u00e4geda p\u00f5letiku.",
		"tgt": "All of these viruses cause acute inflammation of liver tissue."
	},
	{
		"src": "Halvaloomulise kuluga on aga krooniline B ja C hepatiit, mis v\u00f5ib edasi areneda maksa tsirroosiks ehk maksa kortsumuseks ja maksav\u00e4hiks.",
		"tgt": "Chronic hepatitis B and C have a malignant profile, which can progress to cirrhosis and liver cancer."
	},
	{
		"src": "Terviseameti epidemioloogian\u00f5unik Kuulo Kutsar r\u00e4\u00e4gib, et \u00e4geda hepatiidi haigusn\u00e4hud on k\u00f5ikide maksap\u00f5letiku liikide korral \u00fchesugused - palavik, v\u00e4simus, isutus, iiveldus, oksendamine, k\u00f5huvalu, hallikas v\u00e4ljaheide, tume uriin, lihase- ja liigesevalu ning naha ja limaskestade kollasus.",
		"tgt": "Health Board epidemiology advisor Kuulo Kutsar says that the symptoms of acute hepatitis are the same for all types of liver inflammation \u2013 fever, fatigue, loss of appetite, nausea, vomiting, abdominal pain, greyish stools, dark urine, muscle and joint pain and yellowness of skin and mucous membranes."
	},
	{
		"src": "Viimasest haigustunnusest p\u00e4rineb ka maksap\u00f5letiku rahvap\u00e4rane nimetus kollat\u00f5bi.",
		"tgt": "The latter condition is the origin of the popular name for hepatitis in Estonian, kollat\u00f5bi or yellow disease."
	},
	{
		"src": "Lastel v\u00f5ib hepatiit kulgeda haigusn\u00e4htudeta.",
		"tgt": "In children, hepatitis can progress without symptoms."
	},
	{
		"src": "Maksap\u00f5letiku erinevaid liike on v\u00f5imalik kindlaks m\u00e4\u00e4rata ainult laboratoorse uuringu andmete p\u00f5hjal.",
		"tgt": "The various types of hepatitis can be diagnosed only through laboratory testing."
	},
	{
		"src": "\u00c4ge hepatiit v\u00f5ib \u00fcle minna krooniliseks hepatiidiks ja kulgeda aastak\u00fcmneid ilma haigusn\u00e4htudeta, mis t\u00e4hendab, et inimene ei pruugi midagi teada oma ohtlikust maksa kahjustavast haigusest.",
		"tgt": "But hepatitis can change over to the chronic form of the disease and have a course of decades without symptoms, which means that people may not necessarily be aware that they have a dangerous disease that damages the liver."
	},
	{
		"src": "Kuulo Kutsar toob v\u00e4lja erinevad hepatiidivormid ja kirjeldab nende kulgu l\u00e4hemalt.",
		"tgt": "Kutsar notes the different forms of hepatitis and describes their course in detail."
	},
	{
		"src": "A hepatiidi viirused levivad haigelt inimeselt ja nakatavad meid saastunud toidu s\u00f6\u00f6misel v\u00f5i vee joomisel, seksi teel, nakatunud inimese v\u00e4ljaheitest k\u00e4tele ja k\u00e4telt toiduainetele, pindadele, esemetele, suhu sattumisel ning narkootikumide tarbimisel.",
		"tgt": "Hepatitis A viruses spread from a sick person and infect us through eating of contaminated food or drinking of water, during sex, contact between hands and faeces from infected people and from hands to food, surfaces, objects, through contact with the mouth, and drug use."
	},
	{
		"src": "A hepatiiti nakatumise ohu- ehk riskir\u00fchma kuuluvad haigestunu pereliikmed ja hooldajad, kroonilisi maksahaigusi p\u00f5devad inimesed, nakatunuga seksivad inimesed, meestega seksivad mehed, narkomaanid, A hepatiidi k\u00f5rge levikuga riike k\u00fclastavad reisijad.",
		"tgt": "Among the risk group for hepatitis A infection are family members and caregivers, people with chronic liver diseases, sex partners of infected people, men who have sex with men, drug abusers, and travellers to countries with a high incidence of hepatitis A."
	},
	{
		"src": "Nakatumist saab ennetada vaktsineerides, eelk\u00f5ige soovitatakse vaktsineerimist palju reisivatele ja A hepatiidi riskir\u00fchma kuuluvatele inimestele.",
		"tgt": "Infection can be prevented through vaccination. Above all, vaccination is recommended for people who travel often and people in the hepatitis A risk group."
	},
	{
		"src": "Lisaks on oluline igap\u00e4evane h\u00fcgieenin\u00f5uete t\u00e4itmine: pesta v\u00f5i desinfitseerida k\u00e4si, enne toiduks tarvitamist pesta k\u00f5iki puu- ja juurvilju.",
		"tgt": "In addition, following everyday good hygiene is important: washing or disinfecting hands, washing all fruits and vegetable before use as food."
	},
	{
		"src": "B hepatiidi viirused levivad haige inimese verega kokkupuutumisel, narkootikumide s\u00fcstimisel, t\u00e4toveerimisel, augustamisel, verega saastunud olmeesemete (hambaharjad, raseerimisvahendid) kasutamisel, doonoriverega, hepatiidikahtlase isikuga seksimisel ning hepatiidihaigelt emalt lootele/vasts\u00fcndinule.",
		"tgt": "Hepatitis B viruses spread through contact with the blood from a sick person, drug injecting, tattooing, piercing, use of everyday items contaminated with blood (toothbrushes, shaving accessories), donor blood, sex with a person suspected of having hepatitis, and from mother infected with hepatitis to a foetus/newborn."
	},
	{
		"src": "B hepatiidi nakatumise riskir\u00fchma kuuluvad s\u00fcstivad narkomaanid, nakatunud inimese seksipartnerid, meestega seksivad mehed, nakatunud ema vasts\u00fcndinud, haige pereliikmed ja hooldajad, vere ja muude kehavedelikega kokku puutuvad tervishoiu-, p\u00e4\u00e4stet\u00f6\u00f6tajad ja politseinikud ning B hepatiidi k\u00f5rge haigestumisega riike k\u00fclastavad reisijad.",
		"tgt": "Among the risk group for hepatitis B infection are drug abusers, sex partners of infected persons, men who have sex with men, infected mother to a newborn, family members and caregivers of the sick, healthcare, rescue and police workers exposed to blood and other bodily fluids and travellers visiting countries with high incidence of hepatitis B."
	},
	{
		"src": "B hepatiidi ennetamiseks on v\u00f5imalik inimesi vaktsineerida; eelk\u00f5ige on soovitatakse vaktsineerida riskir\u00fchma kuuluvaid inimesi ning lisaks kroonilisi maksahaigusi p\u00f5devaid, HIV-nakkusega, sugulisel teel levivaid haigusi ja diabeeti p\u00f5devaid isikuid.",
		"tgt": "Prevention of hepatitis B is possible by vaccinating people; vaccination is also recommended for people in risk groups, along with people with chronic liver diseases, and people with HIV, STDs and diabetes."
	},
	{
		"src": "B hepatiidi muudeks ennetusmeetmeteks on: hoidumine v\u00f5\u00f5raste h\u00fcgieeni- ja manik\u00fc\u00fcrivahendite, muude terav-vahendite ning s\u00fcstalde-n\u00f5elte kasutamisest, t\u00e4toveerimisest ja augustamisest ning kondoomi kasutamine nakatumisohtliku seksi korral v\u00f5i seksuaalse riskik\u00e4itumise v\u00e4ltimine.",
		"tgt": "Other ways of preventing hepatitis B are: refraining from sharing personal hygiene and manicure accessories, other objects with blades and syringes and needles, refraining from tattooing and piercing, and using a condom during sex with the risk of infection or sexual abstinence."
	},
	{
		"src": "B-hepatiidi vastu vaktsineerimine on Eestis riikliku immuniseerimiskava osa ja lastele tasuta.",
		"tgt": "In Estonia, hepatitis B vaccinations are a part of the state immunization plan and are free for children."
	},
	{
		"src": "C hepatiidi viirused levivad haige inimese verega kokku puutumisel, narkootikumide s\u00fcstimisel, t\u00e4toveerimisel, augustamisel, verega saastunud olmeesemete kasutamisel, doonoriverega, hepatiidikahtlase isikuga seksimisel ning hepatiidihaigelt emalt lootele/vasts\u00fcndinule.",
		"tgt": "Hepatitis C viruses spread from exposure to the blood of a sick person, drug injecting, tattooing, piercing, use of everyday items contaminated with blood, donor blood, sex with a person suspected of having hepatitis and from a mother sick with hepatitis to foetus/newborn."
	},
	{
		"src": "C-hepatiidi nakatumise riskir\u00fchma kuuluvad s\u00fcstivad narkomaanid, nakatunud inimese seksipartnerid, meestega seksivad mehed, nakatunud ema vasts\u00fcndinud, haige pereliikmed ja hooldajad, vere ja muude kehavedelikega kokku puutuvad tervishoiu-, p\u00e4\u00e4stet\u00f6\u00f6tajad ja politseinikud, HIV-nakkusega isikud ning C hepatiidi k\u00f5rge haigestumisega riike k\u00fclastavad reisijad.",
		"tgt": "Among the risk group for hepatitis B infection are injecting drug abusers, sex partners of infected persons, men who have sex with men, an infected mother to newborn, family members and caregivers of the sick, healthcare, rescue and police workers exposed to blood and other bodily fluids, people infected with HIV, and travellers visiting countries with high incidence of hepatitis C."
	},
	{
		"src": "C hepatiidi ennetusmeetmeks on: hoidumine v\u00f5\u00f5raste h\u00fcgieeni- ja manik\u00fc\u00fcrivahendite, muude terav-vahendite ning s\u00fcstalde-n\u00f5elte kasutamisest, t\u00e4toveerimisest ja augustamisest ning kondoomi kasutamine nakatumisohtliku seksi korral.",
		"tgt": "Preventive measures for hepatitis C are: refraining from sharing personal hygiene and manicure accessories, other objects with blades and syringes and needles, refraining from tattooing and piercing; and using a condom during sex with the risk of infection or sexual abstinence."
	},
	{
		"src": "C hepatiidi vastu vaktsiini ei ole.",
		"tgt": "There is no vaccine for hepatitis C."
	},
	{
		"src": "D hepatiiti p\u00f5hjustab D hepatiidi viirus, mis paljuneb B hepatiidi viiruse juuresolekul.",
		"tgt": "Hepatitis D is caused by the hepatitis D virus, which reproduces in the presence of the hepatitis B virus."
	},
	{
		"src": "Sellet\u00f5ttu esineb D hepatiidi nakkus koos B hepatiidiga v\u00f5i superinfektsioonina kroonilise B hepatiidi haigetel.",
		"tgt": "Thus hepatitis D is co-morbid with hepatitis B or a superinfection among those with chronic hepatitis B."
	},
	{
		"src": "D hepatiidi viirused levivad kokkupuutel vere ja muude kehavedelikega, nendega saastunud s\u00fcstalde-n\u00f5eltega, sugulisel teel ja harva nakatunud emalt lootele.",
		"tgt": "Hepatitis D viruses spread through exposure to blood and other bodily fluids, syringes and needles contaminated with blood and other bodily fluids, sexual transmission and, rarely, from infected mother to foetus."
	},
	{
		"src": "D hepatiidi riskir\u00fchmaks on kroonilised B hepatiidi viirusekandjad ja B hepatiidi vastast immuunsust mitteomavad inimesed.",
		"tgt": "The risk group for hepatitis D is chronic carriers of hepatitis D virus and people who lack immunity to hepatitis B."
	},
	{
		"src": "T\u00f5hus ennetusmeede on vaktsineerimine B hepatiidi vaktsiiniga, mis kaitseb inimest ka D hepatiidi viirusega nakatumise eest.",
		"tgt": "An effective preventive measure is vaccination with the hepatitis B vaccine, which also protects people from hepatitis D infection."
	},
	{
		"src": "E hepatiidi viirused levivad fekaal-oraalsel teel joogivee ja toiduga, sealhulgas v\u00e4he kuumt\u00f6\u00f6deldud loomaliha, kala ja merekarpide s\u00f6\u00f6misel, doonoriverega, \u00fchiskasutatavate s\u00fcstaldega ja nakatunud emalt lootele.",
		"tgt": "Hepatitis E viruses are spread through the faecal-oral route involving drinking water and food, including undercooked meat, consumption of fish and shellfish, through donor blood, shared syringes and from infected mother to foetus."
	},
	{
		"src": "Reisijad v\u00f5ivad nakatuda E hepatiidi k\u00f5rge haigestumisega maades.",
		"tgt": "Travellers may become infected with hepatitis E in countries with high incidence."
	},
	{
		"src": "E hepatiidi ennetusmeetmeteks on h\u00fcgieenin\u00f5uete t\u00e4itmine: pesta v\u00f5i desinfitseerida k\u00e4ed p\u00e4rast tualetis k\u00e4imist, enne toiduvalmistamist ja s\u00f6\u00f6mist, p\u00e4rast haige hooldamist.",
		"tgt": "Preventive measures for hepatitis E are following good hygiene: washing or disinfecting hands after using the washroom, before food preparation and eating, and after providing care to patients."
	},
	{
		"src": "Puu- ja k\u00f6\u00f6giviljad pesta enne tarbimist, v\u00e4ltida v\u00e4he kuumt\u00f6\u00f6deldud loomaliha, kala ja mereandide s\u00f6\u00f6mist, juua ainult ohutut joogivett ning hoiduda narkootikumide tarbimisest.",
		"tgt": "Wash fruits and vegetables before consumption, avoid eating undercooked meat, fish and seafood, drink only safe drinking water and refrain from use of drugs."
	},
	{
		"src": "Kuigi viimasel ringil proovisid konkurendid neljakordset ol\u00fcmpiav\u00f5itjat rajalt minema tr\u00fcgida, leidis 34-aastane Farah l\u00f5pusirgel j\u00f5udu ning v\u00f5itis ajaga 26.49,51.",
		"tgt": "Although challengers tried to crowd out the four-time Olympic champion in the final lap, 34-year-old Farah dug deep on the home stretch and won with a time of 26:49.51."
	},
	{
		"src": "Farah ei m\u00f5elnud pikalt, t\u00f5mmates p\u00e4rast fini\u0161it endaga rajale kaasa abikaasa Tania ning lapsed.",
		"tgt": "Without breaking stride, Farah brought his wife Tania and his children on to the track with him after he finished."
	},
	{
		"src": "See oli minu jaoks eriline hetk.",
		"tgt": "It was a special moment for me."
	},
	{
		"src": "Igatsen oma peret v\u00e4ga.",
		"tgt": "I really miss my family."
	},
	{
		"src": "Nendega rajal olemine oli imeline\", s\u00f5nas Farah ajakirjanikele.",
		"tgt": "Having them with me on the track was amazing,\u201d Farah told the journalists."
	},
	{
		"src": "Farah sihib Londonis viiendat tiitliv\u00f5istlust j\u00e4rjest 5000 ja 10 000 meetri jooksu kuldset duublit.",
		"tgt": "In London, Farah is eyeing a double victory in the 5000 and 10000 metres for a fifth championship in a row."
	},
	{
		"src": "K\u00f5ik on v\u00f5imalik, kui sellesse usud.",
		"tgt": "Everything is possible if you believe in it."
	},
	{
		"src": "Vaatamata pealkirjale sukeldub Anne-Marie O'Connori \"Daam kullas. Gustav Klimti meistriteose, Adele Bloch-Baueri portree erakordne lugu\" \u00fche kunstiteose s\u00fcnniloost m\u00e4rksa s\u00fcgavamale 19. sajandi l\u00f5pu ja 20. sajandi alguse Viini kultuuriellu.",
		"tgt": "Despite the title, Anne-Marie O\u2019Connor\u2019s Lady in Gold. The extraordinary story of Gustav Klimt\u2019s masterpiece, the portrait of Adele Bloch-Bauer, delves a good bit deeper into the late 19th and early 20th century history of Vienna cultural life."
	},
	{
		"src": "Aga veelgi p\u00f5hjalikumalt ajalukku.",
		"tgt": "But it delves even deeper into history."
	},
	{
		"src": "Aukartust\u00e4ratavale infohulgale kulunuks \u00e4ra ehk k\u00f5vem k\u00e4rpekirves, kitsam teema lasknuks pealkirjas lubatud portree erakordsel lool rohkem m\u00f5jule p\u00e4\u00e4seda.",
		"tgt": "The awe-inspiring amount of information could have benefited from less sparing cuts, and a narrower focus would have allowed the portrait promised in the heading to shine more."
	},
	{
		"src": "Praegu oleks \u00fchtede kaante vahel justkui kaks raamatut: Gustav Klimti ja tema maalil \"Daam kullas\" kujutatud Adele Bloch-Baueri lugu ning m\u00e4rksa mahukam ja laiahaardelisem ajalooraamat lugupeetud juudiperekondadest ja Saksa okupatsioonist koos selle j\u00e4relm\u00f5judega Austrias.",
		"tgt": "Right now, it\u2019s as if two books were inside one cover: the story of Gustav Klimt and Adele Bloch-Bauer depicted in his painting The Lady in Gold and a much larger and more sweeping history book of distinguished Jewish families and the German occupation and its aftereffects in Austria."
	},
	{
		"src": "Raamatu esimene kolmandik viib keset pulbitsevat Viini kultuurielu ja kes ise Austria pealinna sattunud, v\u00f5ib v\u00e4himagi vaevata ette kujutada, kuidas enam kui sada aastat tagasi elu Ringstrasse \u00fcmbruses k\u00e4is v\u00f5i kuidas Centrali kohvikus k\u00f5ik pead p\u00f6\u00f6rasid, kui Klimt sisse astus.",
		"tgt": "The first third of the book leads us into the vibrant Viennese cultural life \u2013 and anyone who has been to the Austrian capital will have little trouble imagining what life was like more than a hundred years ago around the Ringstrasse or how all heads turned in the Central Caf\u00e9 when Klimt entered."
	},
	{
		"src": "Kultuuritegelaste kontsentratsioon oli Euroopa \u00fches rikkamas linnas k\u00f5rge ja raamatus tuttavat nime n\u00e4hes tunned endki justkui grammikese kultuursemalt.",
		"tgt": "The concentration of cultural figures in one of Europe\u2019s wealthiest cities was high and upon seeing a familiar name in the book, you feel that you yourself are a tiny bit more cultured."
	},
	{
		"src": "Samas n\u00e4iteks fakt, et Sigmund Freud tegutses linnas, kus vohas ravimatu s\u00fc\u00fcfilis ja oli Euroopa k\u00f5rgeim enesetappude tase, loo arengule justkui midagi juurde ei anna.",
		"tgt": "At the same time, the fact that, say, Sigmund Freud lived and worked in a city teeming with untreated syphilis raged and having Europe\u2019s highest suicide rate doesn\u2019t lend much to the story\u2019s development."
	},
	{
		"src": "V\u00f5i ehk siiski - ka iga paarilauseline pintslit\u00f5mme lisab v\u00e4rve 20. sajandi alguse kultuurielule Viinis.",
		"tgt": "And yet perhaps \u2013 every brushstroke of a few sentences adds tone colour to the early 20th century cultural life in Vienna."
	},
	{
		"src": "Unistus reisist N\u00f5ukogude Liitu",
		"tgt": "Dream of a trip to the Soviet Union"
	},
	{
		"src": "19. sajandi viimastel k\u00fcmnenditel oli juutide hulk Viinis plahvatuslikult kasvanud, muutudes suurimaks juudi kogukonnaks L\u00e4\u00e4ne-Euroopas.",
		"tgt": "In the closing decades of the 19th century, the number of Jews in Vienna had grown explosively, becoming the biggest Jewish community in Western Europe."
	},
	{
		"src": "Sajandivahetusel oli pea iga k\u00fcmnes Viini elanik juut.",
		"tgt": "At the turn of the century, one in ten Vienna residents was Jewish."
	},
	{
		"src": "Ka Adele vanemad olid Viinis uustulnukad, aga selleks ajaks, kui Adele abiellus endast kaks kord avanema T\u0161ehhi suhkrumagnaadi Ferdinand Blochiga ja Klimtile tema kuulsate maalide jaoks poseeris, oli tema isa pank saanud juba suuruselt seitsmendaks pangaks Habsburgide impeeriumis.",
		"tgt": "Adele\u2019s parents as well were newcomers to Vienna, but by the time Adele married a Czech sugar magnate twice her age, Ferdinand Bloch, and posed for the Klimt\u2019s famous paintings, her father\u2019s bank had become the seventh largest bank in the Habsburg empire."
	},
	{
		"src": "Kuid Adelet kogu see glamuurne elu, kuhu ta kuulus, ei t\u00f5mmanud.",
		"tgt": "But Adele was not drawn by the whole glamorous life she was a part of."
	},
	{
		"src": "Kui vaadata \"Daami kullas\", on raske uskuda, et elu l\u00f5pupoole nakatus see suursugune daam sotsialismist ja unistas reisist N\u00f5ukogude Liitu.",
		"tgt": "If we look at Lady in Gold, it\u2019s hard to believe that toward the end of her life, this grand dame was infected by socialism and dreamed of a trip to the USSR."
	},
	{
		"src": "1903. aastaks, kui Ferdinand Bloch otsustas oma abikaasa portree tellida Klimtilt, oli viimane hetke kuumim maalikunstnik Viinis.",
		"tgt": "By 1903, when Ferdinand Bloch decided to commission a portrait of his wife from Klimt, the latter was the hottest painter in Vienna."
	},
	{
		"src": "Klimti tellimus maksis tol ajal 4000 krooni, veerandi hea asukohaga maamaja hinnast.",
		"tgt": "Klimt\u2019s commission at the time was 4,000 crowns, a quarter of the price of a good country house."
	},
	{
		"src": "See, et m\u00f5negi portree puhul kahtlustati meistri armulugu modelliga, suhkrumagnaati ei heidutanud.",
		"tgt": "The fact that in the case of some portraits, the master was suspected of having an affair with the model didn\u2019t deter the magnate."
	},
	{
		"src": "Mis Adelesse puutub, siis ainus kindel fakt on, et t\u00f6\u00f6 k\u00e4igus tekkinud modelli ja kunstniku l\u00e4hedane suhe j\u00e4tkus elu l\u00f5puni.",
		"tgt": "As to Adele, the only thing known for certain is that the close bond that developed between the model and the artist during the painting process persisted until the end of their lives."
	},
	{
		"src": "Anne-Marie O'Connor - \"Daam kullas.",
		"tgt": "Anne-Marie O\u2019Connor \u2013 Lady in Gold."
	},
	{
		"src": "Gustav Klimti meistriteose, Adele Bloch-Baueri portree erakordne lugu\", Varrak 2016, inglise keelest t\u00f5lkinud Aldo Randmaa.",
		"tgt": "The extraordinary story behind the Gustav Klimt masterpiece, the portrait of Adele Bloch-Bauer, Varrak 2016, translated from English by Aldo Randmaa."
	},
	{
		"src": "Vahetult enne t\u00f6\u00f6 algust Adelega oli Klimt k\u00e4inud Ravennas San Vitale basiilikas ning uurijad arvavad, et just seal n\u00e4htud hiilgavad mosaiigid keisrinna Theodorast andsid kunstnikule idee teha kuldne portree Adelest v\u00e4rvitud mosaiigina.",
		"tgt": "Immediately before starting work with Adele, Klimt had been to the San Vitale Basilica in Ravenna and scholars believe that it was the brilliant mosaics of the empress Theodora he saw there that gave the artist the idea of creating a golden portrait of Adele in the form of a painted mosaic."
	},
	{
		"src": "Klimt esitles oma \"Daami kullas\" Viinis 1908. aastal ja umbes samal ajal (aastatel 1907-1908) s\u00fcndis teinegi kuldne maal \"Suudlus\".",
		"tgt": "Klimt presented his Lady in Gold in Vienna in 1908, and around the same time (1907-1908) another golden painting called Kiss was conceived."
	},
	{
		"src": "Kunstiajaloolastel ei j\u00e4\u00e4nud kahe naise sarnasus mitte m\u00e4rkamata.",
		"tgt": "The similarity between the two women was not overlooked by art historians of course."
	},
	{
		"src": "Kuidas on looga seotud Hitler?",
		"tgt": "How is Hitler tied in to the story?"
	},
	{
		"src": "\"Arvan, et oma s\u00f5bra Klimti m\u00e4letuseks olen ma talle v\u00f5lgu, et teha tema k\u00e4tet\u00f6\u00f6 \u00fcldsusele k\u00e4ttesaadavaks\", kirjutas Adele Bloch-Bauer paar aastat p\u00e4rast kunstniku lahkumist (Klimt suri veebruaris 1918) Belvedere muuseumi direktorile ja soovis, et nende pere Klimti kollektsioon l\u00e4heks muuseumile.",
		"tgt": "\u201cI think that in memory of my friend Klimt, I am in his debt that I should make his handiwork accessible to the public;\u201d Adele Bloch-Bauer wrote to the director of Belvedere Museum a few years after the demise of the artist (Klimt died in February 1918) and expressed the wish that their family\u2019s Klimt collection pass to the museum."
	},
	{
		"src": "Kuus aasta enne surma oli Klimtil valminud Adelest teinegi portree.",
		"tgt": "Six years before his death, Klimt had painted another portrait of Adele."
	},
	{
		"src": "Ka oma testamendis (Adele lahkus veebruaris 1925) palus ta, et abikaasa j\u00e4taks tema kaks portreed ja neli Gustav Klimti maastikumaali Austria Galeriile.",
		"tgt": "In her testament as well (Adele died in February 1925), she asked that her husband leave her two portraits and four Klimt landscape paintings to the Austrian Gallery."
	},
	{
		"src": "Oma ehted p\u00e4randas ta \u00f5et\u00fctardele Mariale ja Luisele.",
		"tgt": "She left her jewellery to her nieces Maria and Luise."
	},
	{
		"src": "Aasta p\u00e4rast seda, kui Klimt oli l\u00f5petanud \"Austria Mona Lisa\", oli \u00fcritanud Viini Kaunite Kunstide Akadeemiasse p\u00e4\u00e4seda 17aastane Adolf Hitler, aga kukkus joonistamiseksamil l\u00e4bi.",
		"tgt": "A year after Klimt finished work on the \u201cAustrian Mona Lisa,\u201d the 17-year-odl Adolf Hitler had striven for admission to the Vienna fine Art Academy, but failed his drawing examination."
	},
	{
		"src": "Kuigi m\u00f5nikord peetakse Hitleri hilisema antisemitismi p\u00f5hjuseks seda, et juudi professorid teda akadeemiasse vastu ei v\u00f5tnud, polnud \u00fckski tema eksamineerijatest tegelikult juut.",
		"tgt": "Although Hitler\u2019s later anti-Semitism is sometimes attributed to Jewish professors not admitting him to the academy, in fact none of his examiners was a Jew."
	},
	{
		"src": "Igatahes oli Maria testamendis viidatud Austria Galerii \u00fclesanne 1939. aastaks m\u00e4rgatavalt muutunud - oluliseks oli saanud Viini rikkalikest juudi kunstikogudest natsiparteile meelep\u00e4raste t\u00f6\u00f6de leidmine.",
		"tgt": "In any case, the function of the Austrian Gallery mentioned in Maria\u2019s will had changed markedly by 1939 \u2013 it was no important to find works from among Vienna\u2019s richly endowed Jewish art collections that were to the liking of the Nazi Party."
	},
	{
		"src": "Hitleri isiklikku kunstivaramusse sobisid ka m\u00f5ned Adele kodus olnud t\u00f6\u00f6d, ent mitte Klimti omad.",
		"tgt": "Some of the works in Adele\u2019s home were suitable for Hitler\u2019s personal art treasury, but not those of Klimt."
	},
	{
		"src": "Kuusk\u00fcmmend aastat p\u00e4rast natside kunstir\u00f6\u00f6ve sai alguse k\u00fcmneaastane kohtuvaidlus Austria valitsuse ja Bloch-Bauerite p\u00e4rijate vahel.",
		"tgt": "Sixty years after the Nazi art heists, a 10-year-long court dispute between the Austrian government and the successors of the Bloch-Bauers began."
	},
	{
		"src": "Siinkohal olgu vaid m\u00e4rgitud, et kui \"Suudlust\" n\u00e4eb Viinis Belvedere lossis, siis Adele Bloch-Bauerit kujutavat \"Daami kullas\" tuleb vaatama s\u00f5ita New Yorgi Neue Galeriesse.",
		"tgt": "Let it be noted here that while Kiss can be seen in Belvedere Castle in Vienna, a trip to New York\u2019s Neue Galerie is required to see the depiction of Adele Bloch-Bauer in Lady in Gold."
	},
	{
		"src": "Ja enne Viini s\u00f5itu lugeda l\u00e4bi ka eelnimetatud raamat.",
		"tgt": "And before a trip to Vienna, read the abovementioned book."
	},
	{
		"src": "Isegi siis, kui te Klimti t\u00f6id vaatama minna ei plaani, sest v\u00e4hemalt minu emotsioonid keerlesid p\u00e4rast raamatu sulgemist rohkem natsi- ja juuditeema kui 135 miljoni dollari eest m\u00fc\u00fcdud maali ja modell Adele Bloch-Bauer \u00fcmber.",
		"tgt": "Even if you don\u2019t plan to go see works by Klimt, after closing the book, at least my own emotions revolved around Nazi and Jewish themes more than the painting sold for 135 million dollars and the model Adele Bloch-Bauer."
	},
	{
		"src": "Seega mitte niiv\u00f5rd portree, kui pigem suguv\u00f5sa saatuselugu - ja v\u00e4gagi liigutav lugu.",
		"tgt": "Thus it is not so much a portrait but more of a story of the fate of a family \u2013 and a very moving story at that."
	},
	{
		"src": "M\u00e4rgatavalt h\u00f5lbustas s\u00fcndmustes orienteerumist raamatu algul \u00e4ra toodud Bauerite sugupuu.",
		"tgt": "The Bauer family tree reproduced at the start of the book made it significantly easier to orientate with regard to the events."
	},
	{
		"src": "17-aastane ujuja oli Kanadas v\u00e4ga l\u00e4hedal Eesti rekordile",
		"tgt": "17-year-old swimmer in Canada comes very close to Estonian record"
	},
	{
		"src": "Eelujumises oli Gold enda 200 m seliliujumise isiklikule rekordile v\u00e4ga l\u00e4hedal ujudes 2.16,62.",
		"tgt": "In the preliminary heat, Gold was very close to her personal record in the 200 m backstroke, with a time of 2:16.62."
	},
	{
		"src": "Tippmark p\u00e4rineb 17-aastasel piigal n\u00e4dala tagusest ajast, kui Kanada juunioride meistriv\u00f5istlustel sai ajaks 2.16,58, vahendab Priit Aaviku Ujumisblogi.",
		"tgt": "The 17-year-old PB comes from just a week ago, when her time in the Canadian juniors championship was 2:16.58, Priit Aavik reports in his Swimming Blog."
	},
	{
		"src": "Gold p\u00e4\u00e4ses viimasena ehk k\u00fcmnendana A-finaali.",
		"tgt": "Gold got the last, 10th berth in the A final."
	},
	{
		"src": "Finaalis l\u00e4bis ta distantsi ajaga 2.15,76 ning saavutas tubli seitsmenda koha uue v\u00f5imsa tippmargiga.",
		"tgt": "In the final, she covered the distance in a time of 2:15.76 for a solid seventh place with a new imposing personal best."
	},
	{
		"src": "Alina Kendziorile kuuluvast Eesti rekordist (2.15,13) j\u00e4i Goldi lahutama veidi \u00fcle poole sekundi.",
		"tgt": "Gold was just over half a second off Alina Kendzior\u2019s Estonian record (2:15.13)."
	},
	{
		"src": "Eesti k\u00f5igi aegade edetabelis t\u00f5usis Gold kolmandaks ning tema v\u00e4rske isiklik tippmark on Eesti k\u00f5igi aegade viies tulemus.",
		"tgt": "In Estonia\u2019s all-time rankings, Gold rose to third and her latest personal best is the fifth all-time Estonian result."
	},
	{
		"src": "Noor tulevikulootus on Kanada t\u00e4iskasvanute meistriv\u00f5istlustel veel startimas 100 m, 200 m ja 400 m vabaltujumises ning 200 m- ja 400 m kompleksujumises.",
		"tgt": "At the adult championships of Canada, the young future hopeful will also start in the 100 m, 200 m and 400 m freestyle and 200 m and 400 m medleys."
	},
	{
		"src": "M\u00f6\u00f6dunud n\u00e4dalal toimusid Torontos Kanada juunioride meistriv\u00f5istlustel ning Gold tegi edukaid starte ka seal.",
		"tgt": "Last week, the Canadian junior championships were held in Toronto, and Gold had successful starts there as well."
	},
	{
		"src": "Ta v\u00f5itis 200 m vabaltujumises h\u00f5bemedali ajaga 2.03,22.",
		"tgt": "She won a silver medal in the 200 m freestyle with a time of 2:03.22."
	},
	{
		"src": "Nii kiiresti ujuti seda distantsi eestlanna poolt viimati 2008 aastal.",
		"tgt": "The last time the distance was swum so fast by an Estonian woman was in 2008."
	},
	{
		"src": "Goldist kiiremini l\u00e4bi aegade on Eestis seda distantsi ujunud vaid Eesti rekordinaine Elina Part\u00f5ka.",
		"tgt": "Only the record-setting Estonian Elina Part\u00f5ka has swum the distance faster than Gold."
	},
	{
		"src": "Kanadas elav eestlanna v\u00f5itis veel pronksmedali 100 m vabaltujumises suurep\u00e4rase isikliku rekordiga ning uue Eesti hooaja tippmargiga 56.66.",
		"tgt": "The Estonian living in Canada also won a bronze in the 100 m freestyle with a superb personal best and a new Estonian season high mark of 56.66."
	},
	{
		"src": "N\u00e4iteks temast aasta vanem Kertu Ly Alnek on seda distantsi ujunud vaid \u00fche sajandiku v\u00f5rra kiiremini.",
		"tgt": "Kertu Ly Alnek, a year older than her, has swum the distance just one hundredth of a second faster."
	},
	{
		"src": "Isikliku tippmargini j\u00f5udis ta veel 100 m seliliujumises saades teateujumise avavahetuses kirja aja 1.03,69.",
		"tgt": "She also set a person best in the 100 m backstroke relay, with a time of 1.03.69 as the starting swimmer."
	},
	{
		"src": "Poole pikemal distantsil saavutas ta alles seitsmenda koha, kui ujus finaalis 2.17,31.",
		"tgt": "In the event twice that distance, she only managed seventh, with a time of 2.17.31 in the final."
	},
	{
		"src": "Gold on hetkel juhtimas Eesti hooaja edetabelit neljal erineval distantsil.",
		"tgt": "Gold currently has the season\u2019s best Estonian time in four different distances."
	},
	{
		"src": "President Trump l\u00e4heb puhkusele, kriitikud teritavad hambaid",
		"tgt": "Donald Trump goes on holiday, critics sharpen their teeth"
	},
	{
		"src": "Puhkuste aeg on k\u00e4es - see t\u00e4hendab l\u00f5\u00f5gastust ka USA presidendile Donald Trumpile.",
		"tgt": "Vacation season is here, which means relaxation for US President Donald Trump as well."
	},
	{
		"src": "Kuna Trump on aga siiani olnud \u00fcks enim puhkusep\u00e4evi v\u00e4lja v\u00f5tnud president, teritavad kriitikud juba hambaid.",
		"tgt": "As Trump is one of the presidents who has taken the most days of holiday, critics are already sharpening their teeth."
	},
	{
		"src": "USA Today ja CNNi teatel on presidendi plaanis 17-p\u00e4evane puhkus veeta omanimelises golfiklubis Bedminsteris, mis asub New Jerseys.",
		"tgt": "USA Today and CNN report that the president plans to spend his 17-day holiday at the golf club named after him in Bedminster, which is located in New Jersey."
	},
	{
		"src": "Kuigi presidendi puhkus algas eile, on Trumpi vastased puhkuse teemal s\u00f5na v\u00f5tnud juba n\u00e4dalajagu.",
		"tgt": "Although the president\u2019s holiday started yesterday, Trump\u2019s opponents have been speaking out on the topic of the vacation for about a week now."
	},
	{
		"src": "Nad heidavad Trumpile ette liiga sagedat puhkamist.",
		"tgt": "They criticize Trump for going on vacation too often."
	},
	{
		"src": "Nimelt on presidendil tavaks veeta n\u00e4dalavahetuseti aega oma Florida, Virginia ja New Jersey villades.",
		"tgt": "Namely, the president is in the habit of spending the weekends in his villas in Florida, Virginia and New Jersey."
	},
	{
		"src": "Muuseas, Trump ei ole oma 196 ametip\u00e4eva jooksul k\u00f5ige enam puhanud president.",
		"tgt": "By the way, Trump in his 196 days in office has not taken the most vacation time of any president."
	},
	{
		"src": "N\u00e4iteks George W. Bush j\u00f5udis selle ajaga puhkusel olla juba 67 p\u00e4eva, Barack Obama aga poole v\u00e4hem kui Trump, vaid 21 p\u00e4eva.",
		"tgt": "For instance, George W. Bush had already taken 67 days of holiday y that time, and Barack Obama half as much as Trump \u2013 only 21 days."
	},
	{
		"src": "K\u00fcll aga kipuvad Trumpil asjad kiirelt ununema.",
		"tgt": "But Trump does tend to forget things quickly."
	},
	{
		"src": "Loetud p\u00e4evad p\u00e4rast presidendiks saamist \u00fctles Trump saates \"60 minutit\", et pikkadeks puhkusteks tema ametaja jooksul aega ei j\u00e4\u00e4, kuna v\u00e4ga palju on vaja \u00e4ra teha.",
		"tgt": "Just a few days after becoming president, Trump told 60 Minutes that he would not have time for long vacations during his term in office, as there is so much to be done."
	},
	{
		"src": "Samuti avaldas ta kolm aastat tagasi pahameelt Barack Obama puhkuse \u00fcle.",
		"tgt": "Three years ago, he also expressed displeasure over Barack Obama\u2019s vacations."
	},
	{
		"src": "Praegune president kirjutas toona Twitteris: \"Sel ajal kui Obama on puhkusel, m\u00e4ngib golfi, k\u00e4ib pidudel ja d\u017e\u00e4sskontsertidel, raiub ISIS ajakirjanikel p\u00e4id otsast\".",
		"tgt": "The now president wrote on Twitter back then: While Obama vacations, golfs, attends parties & jazz concerts, ISIS is chopping heads off of journalists.\""
	},
	{
		"src": "Valge Maja ametnike teatel ei ole 17-p\u00e4evane golfiklubi k\u00fclastus \u00f5ieti mingi l\u00f5\u00f5gastus.",
		"tgt": "White House officials say a 17-day golf club visit isn\u2019t really relaxing."
	},
	{
		"src": "Seda nimetatakse ametlikult hoopis t\u00f6\u00f6puhkuseks, mille jooksul pole Trumpil aega lugemiseks v\u00f5i muudeks meelistegevusteks.",
		"tgt": "It is being official called a working vacation instead, during which Trump will have no time to read or other favourite activities."
	},
	{
		"src": "Lisaks pidi t\u00f6\u00f6puhkusel olema ka teine p\u00f5hjus.",
		"tgt": "In addition, there was said to be another reason for the working vacation."
	},
	{
		"src": "Nimelt vahetatakse Valge Maja l\u00e4\u00e4netiivas konditsioneeris\u00fcsteem v\u00e4lja ja seet\u00f5ttu tuli kogu personalil sealt lahkuda.",
		"tgt": "Namely, the air conditioning ion the West Wing of the White House is being replaced and thus all staff had to move out."
	},
	{
		"src": "L\u00e4\u00e4netiivas asub ka Ovaalkabinet ning teised presidendi t\u00f6\u00f6ruumid.",
		"tgt": "The West Wing is where the Oval Office and other working areas for the present are located."
	},
	{
		"src": "\"Ma ei usu, et keegi teist tahaks augustis l\u00e4\u00e4netiivas olla, kui seal on 38 kraadi ja pole konditsioneeri\", s\u00f5nas Valge Maja k\u00f5neisik Lindsay Walters, kes r\u00f5hutas, et president j\u00e4tkab puhkuse ajal t\u00f6\u00f6tamist.",
		"tgt": "\u201cI don\u2019t think any of you would like to be in the West Wing in an August D.C. summer day when it\u2019s over 100 degrees with no air conditioning,\u201d said White House spokesperson Lindsay Walters, who stressed that the president would continue working during his vacation."
	},
	{
		"src": "Sellest, kus president Trump j\u00e4rgnevad 17 p\u00e4eva veedab, saad aimu videost.",
		"tgt": "As to where President Trump will spend the next 17 days, the video gives some idea."
	},
	{
		"src": "Kriitikute blokeerimine Facebookist \u0096 \u00e4rge kandideerige riigiametisse, kui te ei talu h\u00e4\u00e4letajate kriitikat",
		"tgt": "Blocking critics from Facebook: Don't run for public office, if you can't take heat from voters"
	},
	{
		"src": "Meie riigi isa teadis ebasoodsast meediakajastusest nii m\u00f5ndagi.",
		"tgt": "The father of our country knew something about bad press."
	},
	{
		"src": "Ameeriklased armastasid George Washingtoni, ent ajalehtedel ei l\u00e4inud kaua, et hakata teda t\u00fcmitama k\u00f5ige eest alates sisepoliitikast kuni ta poliitiliste p\u00f5him\u00f5teteni v\u00e4lja.",
		"tgt": "Americans loved George Washington, but it didn't take long for newspapers to start slamming him on everything from domestic policy to his political principles."
	},
	{
		"src": "Kriitika loomulikult \u00e4rritas teda.",
		"tgt": "He chafed at the criticism, sure."
	},
	{
		"src": "Aga ta ei sundinud oma kriitikuid vaikima.",
		"tgt": "But he did not silence his critics."
	},
	{
		"src": "Sest aastal 1783 \u00fctles Washington, et \"s\u00f5navabadus v\u00f5idakse meilt \u00e4ra v\u00f5tta ning tummalt ja vaikides v\u00f5idakse meid lammaste kombel tapatalgutele juhatada\".",
		"tgt": "Because back in 1783, Washington said, \"the freedom of Speech may be taken away - and, dumb & silent we may be led, like sheep, to the Slaughter.\""
	},
	{
		"src": "See toob mind Marylandi kuberneri Larry Hogani juurde, kel tuleb vaeva n\u00e4ha, et olla rohkem Washingtoni moodi.",
		"tgt": "That brings me to Maryland Gov. Larry Hogan, who needs to work on being more like Washington."
	},
	{
		"src": "Hogani alluvad on blokeerinud ja kustutanud v\u00e4hemalt 450 inimese postitused, kes avaldasid tema ametlikul Facebooki lehel oma arvamust.",
		"tgt": "Hogan's staff has blocked and deleted the posts of at least 450 people who voiced their opinions on his official Facebook page."
	},
	{
		"src": "Ja n\u00e4dala alguse poole kaebas Ameerika Kodanikuvabaduse Liit (American Civil Liberties Union \u0096 ACLU) ta seet\u00f5ttu kohtusse.",
		"tgt": "And the American Civil Liberties Union sued him for that earlier this week."
	},
	{
		"src": "Kuberneri ametnikkond tembeldas hagi t\u00fchiseks ja veebikommentaariumid kubisesid vastureaktsioonidest stiilis \"Keda huvitab?\".",
		"tgt": "The governor's staff dismissed the lawsuit as frivolous, and the online commentary was rich with a \"who cares?\" backlash."
	},
	{
		"src": "\"See on k\u00f5igest Facebook,\" \u00fctlesid paljud.",
		"tgt": "\"It's only Facebook,\" plenty of folks said."
	},
	{
		"src": "Aga see loeb k\u00fcll.",
		"tgt": "But it matters."
	},
	{
		"src": "Ja see loeb eriti palju, kui tegu on sellise mehega nagu Hogan.",
		"tgt": "And it especially matters when it's a guy like Hogan."
	},
	{
		"src": "Tegu on h\u00e4mmastavalt populaarse vabariiklasest kuberneriga \u00fclekaalukalt demokraatlikus osariigis.",
		"tgt": "This is a Republican governor in an overwhelmingly Democratic state who is astonishingly popular."
	},
	{
		"src": "Tema heakskiiduprotsent on riigi 50 kuberneri seas paremuselt teisel kohal.",
		"tgt": "He has the second-highest approval rating of the nation's 50 governors."
	},
	{
		"src": "Hogan ei ole m\u00f5tlemata reageeriv tuisupea.",
		"tgt": "Hogan is not a reactionary hothead."
	},
	{
		"src": "Ta on juhtinud osariiki kindlal k\u00e4el ja j\u00e4\u00e4nud oma p\u00f5him\u00f5tetele rangelt kindlaks.",
		"tgt": "He's shown a steady hand in leading his state and a stern adherence to principles."
	},
	{
		"src": "Lisaks on ta kasutanud peamise vahendina oma valijatega suhtlemisel \u00fcsna vilunult Facebooki, esitledes n\u00e4iteks p\u00e4rast keemiaravi esimest korda lustakalt oma kiilast pead.",
		"tgt": "He's also been pretty deft at using Facebook as a primary means to connect with his constituents, playfully debuting his hairless head after chemo treatments on his page."
	},
	{
		"src": "Seega on kuberneri lehte \u0096 mis on ametliku m\u00e4rgistusega avalik foorum, mida haldab maksumaksjate dollaritest palka saav personal \u0096 k\u00fclastavate inimeste blokeerimine ebavajalik ja l\u00f5ppkokkuv\u00f5ttes ohtlik.",
		"tgt": "So blocking people who come to the governor's page - which is a public forum, labeled as official and administered by staff members paid public tax dollars - is unnecessary and ultimately dangerous."
	},
	{
		"src": "Hogani pressiesindaja Amelia Chasse kaitses The Washington Postile antud intervjuus kuberneri k\u00e4itumist, v\u00e4ites, et kommentaaride blokeerimine ei olnud midagi muud kui modereerimine.",
		"tgt": "In an interview with The Washington Post, Hogan spokeswoman Amelia Chasse defended the governor's actions, arguing that blocking the comments was nothing more than moderating them."
	},
	{
		"src": "Aga liiga lihtne on maalida pilti veebis s\u00f5imlevatest internetitrollidest, r\u00e4mpspostitajatest v\u00f5i viha t\u00e4is rahvast.",
		"tgt": "But it's too easy to use the image of trolls or spammers or hateful folks lashing out online."
	},
	{
		"src": "The Post vestles mitme p\u00e4ris inimesega, kelle Hogan blokeeris.",
		"tgt": "The Post talked to some of the real people blocked by Hogan."
	},
	{
		"src": "Ja just seda nad ongi \u0096 p\u00e4ris inimesed, kes suhtlevad oma valitud juhtidega. \u00d5petaja, ettev\u00f5tte omanik ja pastor, mitte internetitrollid.",
		"tgt": "And they're just that - real people talking to their elected leaders: a teacher, a business owner and a pastor, not trolls."
	},
	{
		"src": "Nad k\u00f5ik \u00fctlesid, et nende kommentaarid olid lugupidavad, l\u00e4bim\u00f5eldud ja sugugi mitte ropud.",
		"tgt": "They all said that their comments were respectful, thoughtful and not profane."
	},
	{
		"src": "Pastor tsiteeris oma postituses piiblit, r\u00f5hudes Hogani katoliiklusele.",
		"tgt": "The pastor quoted the Bible in his post, appealing to Hogan's Catholic faith."
	},
	{
		"src": "Marylandist Bowie'st p\u00e4rit advokaat Lakshmi Sarma Ramani ei \u00f5hutanud viha, vaid p\u00e4ris vihakuritegude kohta.",
		"tgt": "Attorney Lakshmi Sarma Ramani of Bowie, Md., wasn't hateful, but she asked about hate crimes."
	},
	{
		"src": "\"Kommenteerisin viisakalt, et olen pettunud, kuna ta ei ole reageerinud vihakuritegudele ega muudele hiljutistele uudistele,\" kirjutas ta The Posti uudisteloo kommentaarirubriigis.",
		"tgt": "\"I politely commented that I was disappointed in his lack of response to hate crimes and other recent news items,\" she wrote in the comment section of The Post's news story."
	},
	{
		"src": "\"Samuti ei meeldi mulle m\u00f5te, et kui rohkelt inimesi kommenteerib sama teemat, nimetab m\u00f5ni seda kohe \u00fcksk\u00f5ikselt kollektiivseks j\u00f5upingutuseks, selle asemel et tunnistada, et tegu on suure hulga mures kodanikega.\"",
		"tgt": "\"I also do not appreciate that idea that when a number of people comment on the same topic, they are immediately disregarded by some as a so-called collective effort, rather than recognized as a large group of concerned citizens.\""
	},
	{
		"src": "Seda, mida kuberneri ametnikkond nimetas \"suunatud r\u00e4mpspostir\u00fcnnakuks\", kutsuksid teised arvatavasti \"avalikuks toetuseks\".",
		"tgt": "What the governor's staff called a \"concentrated spam attack\" others would probably call \"advocacy.\""
	},
	{
		"src": "Facebooki-ajastu v\u00f5imaldab s\u00f5numeid h\u00f5lpsalt sobitada, blokeerides lihtsalt kriitiku v\u00f5i kustutades negatiivse kommentaari.",
		"tgt": "The Facebook era makes it easy to tailor a message by simply blocking a critic or deleting a negative comment."
	},
	{
		"src": "Asi on palju puhtam kui vanasti, mil sama tegemiseks tuli saata v\u00e4lja t\u00f6\u00f6tajad, et nad koguksid kriitiliste juhtkirjadega ajalehed kokku ja p\u00f5letaksid need v\u00f5i vahistaksid protestijad ning sunniksid nad vaikima.",
		"tgt": "It's a lot cleaner than the old days, when doing the same would have required sending staff out to collect and burn newspapers with critical editorials or arresting and silencing protesters."
	},
	{
		"src": "Aga t\u00e4pselt see praegu toimubki, lihtsalt digitaalselt.",
		"tgt": "But that's exactly what's happening, only digitally."
	},
	{
		"src": "Hogan ei ole esimene riigiametnik, keda kritiseeritakse Facebooki ja muude sotsiaalmeediakanalite hambutuks tegemise p\u00e4rast.",
		"tgt": "Hogan isn't the first public official to be criticized for defanging Facebook and other social media."
	},
	{
		"src": "President Trumpi on kaevanud kohtusse Twitteri kasutajad, kes on ta Twitteri voost blokeeritud.",
		"tgt": "President Trump is being sued by Twitter users who were blocked from his Twitter feed."
	},
	{
		"src": "\u00dcks esimesi m\u00e4rgilise t\u00e4hendusega kohtuotsuseid sel teemal tehti eelmine n\u00e4dal Virginias.",
		"tgt": "One of the first landmark rulings on this issue came down last week in Virginia."
	},
	{
		"src": "USA ringkonnakohtunik James C. Cacheris otsustas Alexandrias, et Loudouni maakonna j\u00e4relevalven\u00f5ukogu esinaine rikkus p\u00f5hiseaduse esimest parandust, kui ta blokeeris valija oma Facebooki lehelt.",
		"tgt": "The chair of the Loudoun County Board of Supervisors violated the First Amendment, according to U.S. District Judge James C. Cacheris in Alexandria, when she banned a constituent from her Facebook page."
	},
	{
		"src": "Kentuckys k\u00fclastas ACLU Facebooki ja Twitteri kasutamise p\u00e4rast ka kuberner Matt Bevinit (R).",
		"tgt": "And in Kentucky, Gov. Matt Bevin (R) also got a visit from the ACLU over his use of Facebook and Twitter."
	},
	{
		"src": "See ei tohiks nii raske olla.",
		"tgt": "This shouldn't be so hard."
	},
	{
		"src": "Washingtoni ajal oli taskukohastel postikuludel sarnane m\u00f5ju kui internetil.",
		"tgt": "In Washington's time, the era of affordable postage had an impact much like the Internet."
	},
	{
		"src": "Vahemikus 1776 kuni 1800 neljakordistus ajalehtede hulk ja anon\u00fc\u00fcmsed kirjakirjutajad t\u00fcmitasid tema juhtimisviisi.",
		"tgt": "The number of newspapers quadrupled between 1776 and 1800, and anonymous letter writers hammered his leadership."
	},
	{
		"src": "Ja isegi siis pidi Washington anon\u00fc\u00fcmsete trollidega rinda pistma.",
		"tgt": "And even back then, Washington had anonymous trolls."
	},
	{
		"src": "Inimesed kirjutasid ajalehtedele kirju selliste pseudon\u00fc\u00fcmide alt nagu Juricola, Valerius, Belisarius ja Portius, tehes Washingtoni otsuseid maatasa.",
		"tgt": "People using the pseudonyms \"Juricola,\" \"Valerius,\" \"Belisarius,\" and \"Portius\" all wrote letters to newspapers trashing Washington's decisions."
	},
	{
		"src": "Veebip\u00f5hise George Washingtoni kirjade kogumise projekti raames kokku korjatud ajalooliste dokumentide kohaselt mattus ta kabinet petitsioonide alla, mis kritiseerisid ta seisukohti seoses Suurbritanniaga s\u00f5lmitud s\u00f5prus-, kaubandus- ja laevanduslepingutega.",
		"tgt": "Petitions criticizing his stand on the Treaty of Amity, Commerce, and Navigation with Britain overwhelmed his office, according to the historical documents collected by the online Papers of George Washington Project."
	},
	{
		"src": "Aga ta ei sundinud neid vaikima.",
		"tgt": "But he did not silence them."
	},
	{
		"src": "S\u00f5navabadus, eriarvamused ja arutelud on meie riigi alustaladeks.",
		"tgt": "Freedom of speech, dissent and discourse lie at the very foundation of our nation."
	},
	{
		"src": "Ja \u00f5ige juhtimine t\u00e4hendab selle aktsepteerimist.",
		"tgt": "And true leadership means accepting that."
	},
	{
		"src": "Ronan Rafferty loodab Renaissance Clubis koduterritooriumi mugavusele",
		"tgt": "Ronan Rafferty hopes for home comforts at Renaissance Club"
	},
	{
		"src": "Endine Euroopa esinumber Ronan Rafferty loodab j\u00e4rgmise kolme p\u00e4eva jooksul koduterritooriumi mugavusele, kui East Lothiani Renaissance Clubi golfiradadel toimub 25. Scottish Senior Open.",
		"tgt": "Former European No 1 Ronan Rafferty will be hoping for home comforts over the next three days as the Renaissance Club in East Lothian hosts the 25th edition of the Scottish Senior Open."
	},
	{
		"src": "P\u00f5hjaiirlane, kes oli eelmisel aastal naabruses asuvatel Archerfield Linksi radadel viimase ringi eel enne Paul Ealesile allavandumist juhtimas, on uude toimumispaika kiindunud ning t\u00e4idab klubi asutaja ja tegevjuhi Jerry Sarvadi asemel turniiri saadiku rolli.",
		"tgt": "The Northern Irishman, who led next door at Archerfield Links heading into the final round last year before losing out to Paul Eales, is attached to the new venue and is acting as tournament ambassador on behalf of the club's founder and CEO Jerry Sarvadi."
	},
	{
		"src": "\"N\u00e4gin, kuidas Renaissance Clubi ehitati, ja n\u00fc\u00fcd n\u00e4eme, kuidas klubi selle \u00fcritusega t\u00e4ies hiilguses s\u00e4rama l\u00f6\u00f6b,\" lausus Rafferty.",
		"tgt": "\"I watched Renaissance Club being built, and we're seeing it come to its glory with this event,\" said Rafferty."
	},
	{
		"src": "\"M\u00e4ngijad n\u00e4evad rada oma parimas vormis, see on hiilgavas seisundis.",
		"tgt": "\"The players will see this course at its finest, it is in fabulous condition."
	},
	{
		"src": "Jerry on teinud selle koha rajamisel suurep\u00e4rast t\u00f6\u00f6d.",
		"tgt": "Jerry has done a fabulous job setting this place up."
	},
	{
		"src": "Ta on golfim\u00e4ngu innukas toetaja ja tunneb siin saavutatu \u00fcle uhkust.",
		"tgt": "He's a keen advocate of this game and is proud of his achievement here."
	},
	{
		"src": "See v\u00f5imaldab rada suurep\u00e4raselt esitleda.\"",
		"tgt": "This is a great showcase for this course.\""
	},
	{
		"src": "Inglane Eales ootab huviga, et ta saaks esimest korda meistritiitlit kaitsta, kuigi mees on oma 32-aastase karj\u00e4\u00e4ri jooksul v\u00f5itnud nii European Touril kui ka European Challenge Touril.",
		"tgt": "Englishman Eales is looking forward to defending a championship for the first time despite winning on both the European Tour and European Challenge Tour in his 32-year career."
	},
	{
		"src": "\"Seda saadab v\u00e4ga eriline tunne,\" s\u00f5nas Southportis pesitsev m\u00e4ngija.",
		"tgt": "\"This does feel really special,\" said the Southport-based player."
	},
	{
		"src": "\"Ma ei saanud oma Extremadura Openi tiitlit kaitsta, sest see v\u00f5eti aasta p\u00e4rast minu v\u00f5itu v\u00f5istluskalendrist maha.",
		"tgt": "\"I didn't get to defend the Extremadura Open because that was taken off the schedule the year after I won it."
	},
	{
		"src": "Maagiline on sellesse kanti tagasi tulla.",
		"tgt": "Coming back to this part of the world is magical."
	},
	{
		"src": "See on golfi m\u00e4ngimiseks suurep\u00e4rane koht.",
		"tgt": "It's a wonderful place to play golf in."
	},
	{
		"src": "Mulle meenuvad m\u00e4lestused eelmisest aastast, minu ja mu naise Sharoni jaoks oli eelmise aasta v\u00f5it eriline.",
		"tgt": "The memories from last year are coming back and it was special for me and my wife Sharon to win last year."
	},
	{
		"src": "Tegu oli v\u00e4ga erilise ajaga, mida me j\u00e4\u00e4me alatiseks s\u00fcdames kandma.\"",
		"tgt": "It was a really special time and one we will always cherish.\""
	},
	{
		"src": "Kodumaa pinnal naaseb taas v\u00f5istlustulle ka Gary Orr, kes liitus seeniorite Euroopa tuuriga selle aasta alguse poole, kui ta sai 50.",
		"tgt": "Making his return to action on home soil is Gary Orr, who joined the European Senior Tour after turning 50 earlier this year."
	},
	{
		"src": "Tegu on tema esimese \u00fcritusega \u0160otimaal p\u00e4rast 2013. aastal Aberdeen Asset Management Scottish Openil osalemist.",
		"tgt": "This event will be his first Scottish appearance since the Aberdeen Asset Management Scottish Open in 2013."
	},
	{
		"src": "\"Kodus m\u00e4ngida on alati natukene t\u00e4hendusrikkam,\" \u00fctles Helensburghi mees Orr.",
		"tgt": "\"It always means a little bit more when you're playing at home,\" said Helensburgh man Orr."
	},
	{
		"src": "\"Tahad h\u00e4sti esineda, aga samas tunned ka lisapinget.",
		"tgt": "\"You want to do well; but you do feel that extra pressure."
	},
	{
		"src": "Olen uuesti m\u00e4ngimist tohutult nautinud ja \u00fcsna korralikku golfim\u00e4ngu n\u00e4idanud.",
		"tgt": "I've really enjoyed playing again and I've played some solid golf."
	},
	{
		"src": "Olen asjade senise kulgemisega rahul.\"",
		"tgt": "I'm happy with how it's going so far.\""
	},
	{
		"src": "Trioga liituvad v\u00e4ljakul endine Mastersi turniiri v\u00f5itja Ian Woosnam ning seeniorite tuuri t\u0161empionid Paul Broadhurst, Roger Chapman, Mark James ja Mark McNulty.",
		"tgt": "Joining the trio in the field are former Masters winner Ian Woosnam and Senior major champions Paul Broadhurst, Roger Chapman, Mark James and Mark McNulty."
	},
	{
		"src": "Orr ja endine Ryderi karika kapten Sam Torrance on kaks kuuest v\u00f5istlustules olevast \u0161otlasest, \u00fclej\u00e4\u00e4nud neist on Andrew Oldcorn, Stephen McAllister, Bill Longmuir ja Ross Drummond.",
		"tgt": "Orr and former Ryder Cup captain Sam Torrance are among six Scots in the field, the others being Andrew Oldcorn, Stephen McAllister, Bill Longmuir and Ross Drummond."
	},
	{
		"src": "Sissep\u00e4\u00e4s on tasuta ning auto parkimine maksab \u00fche reisijaga autole 5 naela ja kahe v\u00f5i enama reisijaga autole 10 naela.",
		"tgt": "Admission is free of charge, with car parking charged at \u00a35 per car with one occupant and \u00a310 per car with two or more occupants."
	},
	{
		"src": "K\u00f5ik tulud l\u00e4hevad heategevusorganisatsioonile Prostate Cancer UK.",
		"tgt": "All proceeds go to Prostate Cancer UK."
	},
	{
		"src": "Vaesus ja surm Indoneesia kullarohkel maal",
		"tgt": "Poverty and Death in Indonesia's Land of Gold"
	},
	{
		"src": "Kui Bardina Degei \u00f5htus\u00f6\u00f6ki valmistab, ei kasuta ta pliiti.",
		"tgt": "When Bardina Degei cooks dinner, she doesn't use a stove."
	},
	{
		"src": "Ta kasutab isegi potti harva.",
		"tgt": "She rarely even uses a pot."
	},
	{
		"src": "Indoneesia t\u00f5rksa Paapua provintsi Paniai regentkonna pealinnas Enarotalis asuvas puidust majakeses asetab koduperenaine kohalikus keeles nota'ks kutsutava bataadi otse tuleasemele.",
		"tgt": "In her wooden home in Enarotali, the capital of Paniai regency in the restive Indonesian province of Papua, the housewife usually just places a sweet potato - known locally as \"nota\" - directly into the fireplace."
	},
	{
		"src": "Poole tunni p\u00e4rast v\u00f5etakse s\u00f6estunud mugul tulelt ja pistetakse pesemata k\u00e4tega innukalt nahka.",
		"tgt": "After half-an-hour, the charred tuber is retrieved and devoured with eager, unwashed hands."
	},
	{
		"src": "Degei istub mudast p\u00f5randal \u0096 m\u00f6\u00f6blit tal pole \u0096 ja sealsamas teeb ta ka oma igap\u00e4evaseid majapidamist\u00f6id, n\u00e4iteks peseb pesu l\u00e4hedalasuvast soost p\u00e4rit h\u00e4guse veega.",
		"tgt": "Degei sits on the mud floor - she has no furniture - which is where she also performs her daily chores, such as washing clothes with murky water from the nearby swamp."
	},
	{
		"src": "K\u00e4imla rolli t\u00e4idab \u00e4mber katuseta toas.",
		"tgt": "A bucket in a roofless room serves as a latrine."
	},
	{
		"src": "Kuna ta on oma abikaasa neljast naisest noorim, ei ole teda m\u00e4\u00e4ratud \u00fchegi p\u00f5llu eest hoolitsema.",
		"tgt": "As the youngest of her husband's four wives, she has been assigned no fields to tend."
	},
	{
		"src": "Pol\u00fcgaamia on siinmail tavaline.",
		"tgt": "Polygamy is common here."
	},
	{
		"src": "Hilja t\u00f6\u00f6tamine v\u00f5ib aga olla ohtlik \u0096 enamik k\u00fcla meestest on t\u00f6\u00f6tud ja paljud neist joovad k\u00f5vasti, lisaks on siin veel s\u00f5durid.",
		"tgt": "Of course, working late can be dangerous: Most of the village men are unemployed and many drink heavily, plus there are the soldiers."
	},
	{
		"src": "\"Mitte keegi ei julge p\u00e4rast kella viit \u00f5htul k\u00fclas ringi k\u00e4ia,\" \u00fctleb ta.",
		"tgt": "\"No one dares to walk around the village after 5 p.m.,\" she says."
	},
	{
		"src": "See on haruldane pilguheit ellu Paapua m\u00e4gismaal. Tegu on endise Hollandi kolooniaga, mis liideti Indoneesia alla 1969. aastal p\u00e4rast poleemikat tekitanud referendumit, mille k\u00e4igus sunniti k\u00f5igest 1026 vanurit okupandi v\u00e4gede silme all k\u00e4si t\u00f5stes h\u00e4\u00e4letama.",
		"tgt": "It's a rare glimpse of daily life in the highlands of Papua, a former Dutch colony that was absorbed into Indonesia in 1969 following a controversial referendum, when just 1,026 elders were forced to vote through a public show of hands before occupying troops."
	},
	{
		"src": "Hollandlaste \u00fclemv\u00f5imu alt vabanemist \u00f5hutanud liikumine suunas oma raevu kiiresti Jakarta valitsuse vastu, mis hoiab piirkonda endiselt oma tugeva kontrolli all, hoides eemale v\u00e4lisajakirjanikke ja inim\u00f5iguste j\u00e4relevalvajaid.",
		"tgt": "An existing movement agitating for independence against Dutch rule swiftly turned its ire against the Jakarta government, which maintains tight control over the region, barring foreign journalists or rights monitors."
	},
	{
		"src": "2003. aastal jaotati provints ametlikult Paapuaks ja L\u00e4\u00e4ne-Paapuaks, nii et iseseisvale Paapua Uus-Guineale j\u00e4i saare idaosa.",
		"tgt": "In 2003, the province was officially split into Papua and West Papua, with independent Papua New Guinea occupying the eastern part of the island."
	},
	{
		"src": "Enarotali on \u00fchtmoodi nii kauge kui ka mahaj\u00e4etud koht. Siia j\u00f5udmiseks tuleb lennata provintsi pealinnast Jayapurast 90 minutit Nabiresse ja l\u00e4bida seej\u00e4rel rendiautoga iiveldama panev viietunnine teekond.",
		"tgt": "Enarotali is as remote as it is desolate; the journey here involves a 90-minute flight from the provincial capital Jayapura to Nabire, and then a stomach-churning five-hour drive by hire car."
	},
	{
		"src": "\u00dchistransporti ei ole.",
		"tgt": "There is no public transport."
	},
	{
		"src": "Umbes 19 000 elanikuga linn koosneb puumajadest, mida \u00fcmbritsevad bambusest tarad ja katavad lainelised rauast katused, mille rooste on muutnud eri tooni kollakaspruunideks.",
		"tgt": "The town of some 19,000 people consists of wooden houses ringed by bamboo fencing, corrugated iron roofs transformed by rust into varying tawny shades."
	},
	{
		"src": "V\u00e4ga v\u00e4hesed indoneeslased on teekonna siia ette v\u00f5tnud, r\u00e4\u00e4kimata ajakirjanikest, samuti pole siin k\u00e4inud peaaegu \u00fcldse v\u00e4lismaalasi.",
		"tgt": "Very few Indonesians have made the journey here, let alone journalists, and practically no foreigners."
	},
	{
		"src": "Enne kristlike misjon\u00e4ride saabumist kummardasid Mee Pago paapuad jumalat nimega Uga Tamee.",
		"tgt": "Before Christian missionaries arrived, Mee Pago Papuans worshiped a God named Uga Tamee."
	},
	{
		"src": "Toimus ka teisi muutusi.",
		"tgt": "There were other changes, too."
	},
	{
		"src": "\"Me polnud harjunud selliseid riideid kandma,\" \u00fctleb Degei, viidates oma v\u00e4rvikirevale k\u00e4sitsi kootud turbanile, tumedale pluusile ja erksale seelikule.",
		"tgt": "\"We were not used to wearing these clothes,\" says Degei, indicating her vividly colored, hand-woven turban, dark shirt and a bright skirt."
	},
	{
		"src": "\"Enne seda kandsime kehal ainult taimelehti.\"",
		"tgt": "\"Before, we only wore leaves on our bodies.\""
	},
	{
		"src": "Paapua on Indoneesia k\u00f5ige vaesem provints, kus 28% inimestest elab allpool vaesuspiiri ning imikute suremuse ja kirjaoskamatuse statistika on \u00fcks Aasia halvimaid.",
		"tgt": "Papua is Indonesia's poorest province, where 28% of people live below the poverty line and with some of the worst infant mortality and literacy rates in Asia."
	},
	{
		"src": "Aga tegu on ka Indoneesia kullarohke maaga.",
		"tgt": "But it is also Indonesia's land of gold."
	},
	{
		"src": "K\u00f5igest 100 km kaugusel Paniaist, mis on umbes New Jersey suurune 153 000 elanikuga m\u00e4gine provints, asub maailma k\u00f5ige suurem ja tulusam kullakaevandus Grasberg, mis kuulub Phoenixis tegutsevale ettev\u00f5ttele Freeport McMoran.",
		"tgt": "The world's largest and most profitable gold mine, Grasberg, owned by Phoenix-based Freeport McMoran, lies just 60 miles from Paniai, a highland province around the size of New Jersey and home to 153,000 people."
	},
	{
		"src": "Ainu\u00fcksi 2015. aastal kaevandas Freeport siit umbes 3,1 miljardi USA dollari v\u00e4\u00e4rtuses kulda ja vaske.",
		"tgt": "In 2015 alone, Freeport mined some $3.1 billion worth of gold and copper here."
	},
	{
		"src": "Lisaks sellele saab Paapua uhkustada tarbepuiduvarudega, mille v\u00e4\u00e4rtus on hinnanguliselt 78 miljardit USA dollarit.",
		"tgt": "In addition, Papua boasts timber resources worth an estimated $78 billion."
	},
	{
		"src": "Ent need rikkused on paapuate kannatuste allikas, kuna need tingivad v\u00f5imsa Indoneesia s\u00f5jav\u00e4e l\u00e4mmatava kohalolu.",
		"tgt": "These riches are, however, a source of misery for Papuans, ensuring Indonesia's powerful military maintains a suffocating presence."
	},
	{
		"src": "Ajalehe The New York Times 2005. aasta uurimus n\u00e4itas, et Freeport maksis aastatel 1998 kuni 2004 kohalikele s\u00f5jav\u00e4elastele ja s\u00f5jav\u00e4e\u00fcksustele ligikaudu 20 miljonit USA dollarit, sealhulgas kuni 150 000 USA dollarit \u00fchele ohvitserile.",
		"tgt": "A 2005 investigation in The New York Times reported that Freeport paid local military personnel and units nearly $20 million between 1998 and 2004, including up to $150,000 to a single officer."
	},
	{
		"src": "Paapuate p\u00fc\u00fcdlused tagada suurem autonoomsus \u00e4hvardavad seda kuldhane ja nendega k\u00e4iakse armutult \u00fcmber.",
		"tgt": "Papuan calls for greater autonomy threaten this golden goose, and are dealt with mercilessly."
	},
	{
		"src": "Inim\u00f5iguste aktivistide s\u00f5nul on alates 1969. aastast tapetud rohkem kui 500 000 paapuat ning veel tuhandeid on Indoneesia s\u00f5jav\u00e4gi v\u00e4gistanud, piinanud ja vangistanud.",
		"tgt": "According to rights activists, more than 500,000 Papuans have been killed, and thousands more have been raped, tortured and imprisoned by the Indonesian military since 1969."
	},
	{
		"src": "Aasia inim\u00f5iguste komisjoni andmetel oli Paapua h\u00f5imudele kuuluvatel m\u00e4gismaadel 1970ndatel toimunud massiline tapmine genotsiidi m\u00f5\u00f5tu.",
		"tgt": "Mass killings in Papua's tribal highlands during the 1970s amounted to genocide, according to the Asia Human Rights Commission."
	},
	{
		"src": "Ainu\u00fcksi eelmisel aastal vahistas Indoneesia politsei piirkonnas \u00fcle 3900 rahumeelse protestija.",
		"tgt": "Indonesian police arrested more than 3,900 peaceful protesters in the region last year alone."
	},
	{
		"src": "Birsbane'i peapiiskopkonna 2016. aasta aruanne \"Me kaotame k\u00f5ik\" sisaldab tunnistusi eelneval aastal toime pandud julmuste kohta, nagu kohtuv\u00e4lised hukkamised, piinamine (\u00fche teise aruande kohaselt on eriti levinud v\u00e4gistamine ja elektril\u00f6\u00f6kide andmine) ja rahumeelsete meeleavalduste j\u00f5hker mahasurumine.",
		"tgt": "We Will Lose Everything, a 2016 report by the Archdiocese of Brisbane, contains testimony of atrocities committed the previous year, such as extrajudicial executions, torture - rape and electrocution are especially popular, according to another report - and the brutal crushing of peaceful demonstrations."
	},
	{
		"src": "\"Ohvrite arvu on raske kokku lugeda, sest selliseid intsidente toimub iga n\u00e4dal,\" \u00fctleb organisatsiooni Human Rights Watch Indoneesia uurija Andreas Harsono.",
		"tgt": "\"It's difficult to count the number of victims as incidents happen every week,\" says Andreas Harsono, Indonesia researcher for Human Rights Watch."
	},
	{
		"src": "Kruvid on veel tugevamalt kinni keeratud, sest Paapua loodusvarad on p\u00f5hjustanud uusasunike sissevoolu mujalt Indoneesiast.",
		"tgt": "The screws have tightened as Papua's resources bring an influx of settlers from elsewhere in Indonesia."
	},
	{
		"src": "83% provintsi 3,5 miljonist elanikust on kristlased, aga demograafia on muutumas, sest Indoneesia rahvarohketelt Jaava, Kalimantani, Sumatra ja Sulawesi saartelt saabub muslimitest majandusmigrante.",
		"tgt": "The province's 3.5 million population is 83% Christian, but the demographic is changing as Muslim economic migrants arrive from Indonesia's populous islands of Java, Borneo, Sumatra and Sulawesi."
	},
	{
		"src": "Jaavalaste peres\u00f6\u00f6klad m\u00fc\u00fcvad kr\u00f5bekana ja segak\u00f6\u00f6giviljadega gado-gado't, mida serveeritakse koos maap\u00e4hklikastmega.",
		"tgt": "Javanese warung canteens sell fried chicken and gado-gado mixed-vegetables served with peanut sauce."
	},
	{
		"src": "Kohalikud ei suuda nendega v\u00f5istelda.",
		"tgt": "Local people struggle to compete."
	},
	{
		"src": "\"Migrandid hakkasid m\u00fc\u00fcma kana ja k\u00f6\u00f6givilju traditsioonilisel turul kohalikest paapuatest odavamalt,\" seletab Paniais s\u00fcndinud 24-aastane Abeth You, kes kolis t\u00f6\u00f6 nimel provintsi pealinna Jayapurasse.",
		"tgt": "\"The migrants started to sell chicken and vegetables in the traditional market cheaper than the local Papuans,\" explains Abeth You, a 24-year-old Paniai native who moved to the provincial capital Jayapura for work."
	},
	{
		"src": "\"P\u00f5liselanikest paapuad \u0096 paapua mama-mama'd [naised] \u0096 kaotavad seet\u00f5ttu oma turuosa.\"",
		"tgt": "\"It made the native Papuans - the mama-mama [the women] of Papua - lose their market.\""
	},
	{
		"src": "Indoneesia president Joko Widodo, kes on rahva seas tuntud kui Jokowi, lubas oma 2014. aasta valimiskampaanias tegeleda nende ebav\u00f5rdsuste ja inim\u00f5iguste rikkumistega Paapuas.",
		"tgt": "Indonesian President Joko Widodo, popularly known as Jokowi, vowed to address the inequalities and rights abuses in Papua during his election campaign in 2014."
	},
	{
		"src": "Endine puusepp v\u00f5itis oma teel Jakarta presidendipaleesse Paapua 29 valimisringkonnast 27, sealhulgas Paniai.",
		"tgt": "The former carpenter secured 27 of Papua's total 29 districts - including Paniai - on the way to the Presidential Palace in Jakarta."
	},
	{
		"src": "Aga Paapuas on v\u00e4ga v\u00e4he muutunud ja kohalikud tunnevad end petetuna.",
		"tgt": "But precious little has changed in Papua, and today local people feel betrayed."
	},
	{
		"src": "\"Meie s\u00fcdamed on murtud, sest 2014. aastal h\u00e4\u00e4letasime Jokowi poolt ootuses, et ta t\u00e4idab meie lootused seoses \u00f5igluse taastamisega,\" \u00fctleb You.",
		"tgt": "\"Our hearts have been broken because in 2014 we voted for Jokowi, with the expectation that he would fulfill our hopes for justice to be restored,\" You says."
	},
	{
		"src": "Tegelikult vaevles Paniai k\u00f5igest kaks kuud p\u00e4rast Jokowi oktoobrikuist ametisse astumist madalseisus.",
		"tgt": "In fact, Paniai suffered a nadir just two months after Jokowi's October inauguration."
	},
	{
		"src": "2014. aasta 7. detsembril laulsid 11 last Enarotalis l\u00f5kke \u00e4\u00e4res j\u00f5ululaule, kui pimedusest ilmus mootorrattal kaks Indoneesia s\u00f5durit.",
		"tgt": "On Dec. 7, 2014 a group of 11 children were outside singing Christmas carols in front of a bonfire in Enarotali when two Indonesian soldiers on a motorbike broke through the gloom."
	},
	{
		"src": "Kohkunud lapsed \u00fctlesid neile, et nad peaksid esituled sisse l\u00fclitama.",
		"tgt": "The startled children told them that they should turn on their headlights."
	},
	{
		"src": "Kohaliku pastori Yavedt Tebai jutu j\u00e4rgi solvus \u00fcks s\u00f5duritest nende h\u00e4\u00e4letooni peale ja naasis hiljem koos nelja s\u00f5duriga.",
		"tgt": "One of the soldiers took umbrage at their tone and later returned with four soldiers, according to local Pastor Yavedt Tebai."
	},
	{
		"src": "Ohvrite ja pealtn\u00e4gijate s\u00f5nul ajasid joobes s\u00f5durid lapsi taga ja peksid neid oma p\u00fcsside k\u00e4epidemetega.",
		"tgt": "The soldiers, who had been drinking, chased and beat the group with their rifle butts, said victims and witnesses."
	},
	{
		"src": "Seej\u00e4rel tulistas \u00fcks s\u00f5duritest laste sekka.",
		"tgt": "Then one of the soldiers fired into the group of children."
	},
	{
		"src": "\u00dcht last, 16-aastast Yulianus Yeimot, peksti nii julmalt, et ta langes koomasse.",
		"tgt": "One child, 16-year-old Yulianus Yeimo, was beaten so badly he fell into a coma."
	},
	{
		"src": "Paar tundi hiljem pandi l\u00e4hedalasuv valimiskomisjoni hoone p\u00f5lema ja j\u00e4rgmisel p\u00e4eval eskaleerusid asjad veelgi.",
		"tgt": "A couple of hours later, the nearby government Election Commission building was set ablaze, and things escalated the following day."
	},
	{
		"src": "Umbes 1000 noort Paapua meest, naist ja last kogunes \u00f5igluse n\u00f5udmiseks kohaliku politseijaoskonna ja s\u00f5jalise juhtimiskeskuse ees olevale jalgpalliv\u00e4ljakule.",
		"tgt": "About 1,000 young Papuan men, women and children gathered on a soccer field in front of the local police station and military command center to demand justice."
	},
	{
		"src": "Nad kandsid tseremoniaalseid jahivibusid ja esitasid Paapua mee pago h\u00f5imu waita-tantsu, mille k\u00e4igus joosti ringi ja matkiti linnulaulu.",
		"tgt": "They carried ceremonial hunting bows and performed the waita dance - running in circles and simulating birdsong - of Papua's Mee Pago tribe."
	},
	{
		"src": "M\u00f5ned protestijad hakkasid politsei ja s\u00f5jav\u00e4eliste pihta kivisid loopima.",
		"tgt": "Some protesters started hurling stones at police and military posts."
	},
	{
		"src": "Pahameele \u00e4genemisel saadeti s\u00f5duritele siseraadio kaudu k\u00e4sk. \"Kui rahvamass osutab rohkem kui kolm korda vastupanu, laske nad maha,\" \u00f6eldi ametliku dokumendi kohaselt, mida on n\u00e4inud ajakiri TIME, aga mida pole kohalikele meediav\u00e4ljaannetele v\u00e4ljastatud.",
		"tgt": "As tempers grew more heated, an order was sent to the soldiers through internal radio: \"If the masses offer resistance more than three times, shoot them dead,\" it said, according to an official document seen by TIME that has not been released to the local media."
	},
	{
		"src": "Enarotali linna Kego Koto linnaosa vanem Yeremias Kayame (56) tunnetas \u00e4hvardavat ohtu ja kutsus \u00fcles rahu s\u00e4ilitama, paludes rahvahulgal koju minna.",
		"tgt": "Yeremias Kayame, 56, the head of the Kego Koto neighborhood of Enarotali, saw the impending danger and appealed for calm, imploring the crowd to go back home."
	},
	{
		"src": "Kellelgi polnud tahtmist kuulata.",
		"tgt": "Nobody was in the mood to listen."
	},
	{
		"src": "\"\u00dcmber p\u00f6\u00f6rates tulistati mind j\u00e4rsku vasakusse randmesse,\" \u00fctles ta ajakirjale TIME oma erksates v\u00e4rvides puumaja verandal.",
		"tgt": "\"When I turned around I suddenly got shot in my left wrist,\" he told TIME on the porch of his brightly painted wooden house."
	},
	{
		"src": "Kayame ei tea endiselt, kes tulistajaks oli, aga \u00fctleb, et kuul tuli kogunenud s\u00f5durite ridadest.",
		"tgt": "Kayame still doesn't know who fired but says the bullet came from the ranks of amassed soldiers."
	},
	{
		"src": "\"Rahvast oli palju, kostus rohkelt laske,\" lisab ta.",
		"tgt": "\"It was crowded, many shots were fired,\" he adds."
	},
	{
		"src": "Kohalik mees Alfius Youw sai tema tulistamist pealt n\u00e4inud n\u00f5bu s\u00f5nul pihta kolm korda.",
		"tgt": "Local man Alfius Youw was hit three times, according to his cousin who witnessed the shootings."
	},
	{
		"src": "\"Jooksin tema juurde ja uurisin ta keha l\u00e4bi, veendumaks, et tegu on temaga,\" lausus ajakirjale TIME s\u00fcngelt Yohanes, kes kasutab paljude indoneeslaste kombel ainult \u00fcht nime.",
		"tgt": "\"I ran to him and examined his body to make sure it was him,\" Yohanes, who like many Indonesians only goes by one name, told TIME somberly."
	},
	{
		"src": "\"N\u00e4gin, et ta on surnud... Suudlesin teda.\"",
		"tgt": "\"I saw he was dead ... I kissed him.\""
	},
	{
		"src": "Paapua politsei peainspektor Yotje Mende \u00fctles reporteritele, et tema alluvad tagasid ainult oma jaoskonna turvalisuse, kuna seda r\u00fcnnati.",
		"tgt": "The Papua Police Chief Inspector General Yotje Mende told reporters that his officers were only \"securing\" their station because it was under attack."
	},
	{
		"src": "\"Peame ennast kaitsma, kui meid \u00e4hvardatakse tappa,\" lausus 2015. aastal Paapua politsei pressiesindaja komissar Pudjo Sulistiyo.",
		"tgt": "\"We have to defend ourselves when people threaten to kill us,\" Papua Police spokesperson, Commissioner Pudjo Sulistiyo said in 2015."
	},
	{
		"src": "\"See on elu ja surma k\u00fcsimus.\"",
		"tgt": "\"It's a matter of life and death.\""
	},
	{
		"src": "Human Rights Watchi andmetel tapeti viis noort protestijat ja oli rohkelt vigastatuid.",
		"tgt": "According to Human Rights Watch, five young protesters were killed and many more injured."
	},
	{
		"src": "Uudis tapmiste kohta j\u00f5udis Jakartasse alles j\u00e4rgmisel p\u00e4eval.",
		"tgt": "News of the killings only filtered through to Jakarta the following day."
	},
	{
		"src": "Kolm n\u00e4dalat hiljem pidas Jokowi Jayapuras kirgliku k\u00f5ne, kus ta avaldas ohvrite perekondadele kaastunnet ja lubas Paapuas toimunud v\u00e4\u00e4rkohtlemistega tegeleda.",
		"tgt": "Three weeks later, Jokowi gave an impassioned speech in Jayapura, where he expressed sympathies with the victims' families and vowed to address the historic abuses in Papua."
	},
	{
		"src": "\"Tahan selle juhtumi kohe lahendada, et see ei korduks enam kunagi tulevikus,\" \u00fctles ta.",
		"tgt": "\"I want this case to be solved immediately so it won't ever happen again in the future,\" he said."
	},
	{
		"src": "Julgeolekuminister Wiranto \u00fctles 2016. aasta oktoobris, et ta kehtestab toimunud inim\u00f5igustevastaste kuritegude lahendamiseks kohtuv\u00e4lise mehhanismi.",
		"tgt": "Security Minister Wiranto said in October 2016 that he was setting up a non-judicial mechanism to settle historic human-rights violations."
	},
	{
		"src": "Aga peaaegu kohe j\u00e4rgnesid ka vabandused.",
		"tgt": "But the excuses started almost immediately."
	},
	{
		"src": "\"Enamik kuritegusid juhtus kaua aega tagasi.",
		"tgt": "\"Most of the violations occurred a long time ago."
	},
	{
		"src": "M\u00f5ned neist toimusid 1990ndatel ja 2000ndate alguses.",
		"tgt": "Some were in the '90s and in early 2000s."
	},
	{
		"src": "Asi on selles, et oleme p\u00fchendunud nende kuritegude lahendamisele, aga peame j\u00e4rgima teatud protsesse,\" lausus ta.",
		"tgt": "The point is we are committed to addressing these violations, but there are processes to go through,\" he said."
	},
	{
		"src": "Ajakirjaga TIME 5. juunil Jakartas r\u00e4\u00e4kides v\u00f5ttis Wiranto aga oma s\u00f5nad tagasi, \u00f6eldes, et tal pole mingisugust kavatsust luua Paapuas mehhanismi kaebustega tegelemiseks.",
		"tgt": "Then Wiranto backtracked when speaking to TIME in Jakarta on June 5, saying he has no plans to establish a grievance mechanism in Papua."
	},
	{
		"src": "Selle asemel \u00fctles ta, et \"k\u00f5ik lahendatakse seaduse j\u00e4rgi\".",
		"tgt": "Instead, \"All will be settled by law,\" he said."
	},
	{
		"src": "Wiranto, keda \u00dcRO on s\u00fc\u00fcdistanud inim\u00f5igustevastastes kuritegudes seoses rohkem kui 1000 inimese surmaga Ida-Timoris 1999. aasta verise iseseisvusreferendumi k\u00e4igus, \u00fctles, et 11 inim\u00f5igustevastast kuritegu on Paapuas juba lahendatud, sealhulgas ka Paniais toimunu.",
		"tgt": "Wiranto, who the U.N. has indicted for \"crimes against humanity\" relating to more than 1,000 deaths during East Timor's bloody 1999 independence vote, said that 11 cases of human-rights violations in Papua have already been settled, including the Paniai incident."
	},
	{
		"src": "Paniai ohvrite perekonnad v\u00f5tsid sellised v\u00e4ited vastu s\u00fcnge umbusuga.",
		"tgt": "Families of the Paniai victims greeted such claims with grim incredulity."
	},
	{
		"src": "\"Mind on viimase kolme aasta jooksul neli korda \u00fcle kuulatud, aga mingit edasiminekut pole toimunud,\" \u00fctles Yohanes.",
		"tgt": "\"I've been interviewed four times for the past three years, but there has been no progress at all,\" Yohanes says."
	},
	{
		"src": "\"Ma olen v\u00e4sinud.\"",
		"tgt": "\"I'm tired.\""
	},
	{
		"src": "Ta \u00fctleb, et elab aastaid hiljem endiselt hirmus.",
		"tgt": "He says that years later, he still lives in fear."
	},
	{
		"src": "\"Ma kardan,\" \u00fctleb ta.",
		"tgt": "\"I'm afraid,\" he says."
	},
	{
		"src": "\"Ma kardan, et s\u00f5jav\u00e4gi vahistab mind, kardan, et mind tulistatakse.\"",
		"tgt": "\"I'm afraid of being arrested by the military, afraid to be shot.\""
	},
	{
		"src": "Ta vend Yacobus kinnitas arvamust, et Paniai inimesed kardavad seda vahejuhtumit lahata.",
		"tgt": "His brother Yacobus echoed the view that people in Paniai are fearful of discussing the incident."
	},
	{
		"src": "Ta \u00fctles, et sai s\u00f5jav\u00e4e k\u00e4est peksa p\u00e4rast seda, kui ta oli aidanud nelja ohvrit maha matta.",
		"tgt": "He says he was beaten by the military after helping to bury four of the victims."
	},
	{
		"src": "\"P\u00e4rast surnukehade matmist tuli s\u00f5jav\u00e4gi mind otsima,\" \u00fctleb ta.",
		"tgt": "\"After burying the bodies, the military came looking for me,\" he says."
	},
	{
		"src": "Tulistamised pole lakanud.",
		"tgt": "The shootings haven't stopped."
	},
	{
		"src": "Teisip\u00e4eval tulistas Indoneesia politsei k\u00fclaelanikke Paniai naaberregentkonnas Deiyais.",
		"tgt": "On Tuesday, Indonesian police shot at villagers in Paniai's neighboring Deiyai regency."
	},
	{
		"src": "\u00dcks inimene sai surma ja 17 haavata, sealhulgas ka lapsed, kui l\u00e4ks s\u00f5neluseks k\u00fclaelanike ja ehitusettev\u00f5tte juhataja vahel, kes keeldus teadvusetut meest haiglasse transportimast.",
		"tgt": "One person died and 17 others were wounded, including children, during a confrontation between villagers and the manager of a construction company who refused to help transport an unconscious man to hospital."
	},
	{
		"src": "See meesterahvas, 24-aastane Ravianus Douw, kes uppus kala p\u00fc\u00fcdes l\u00e4hedalasuvasse j\u00f5kke, suri teel haiglasse.",
		"tgt": "The man, 24-year-old Ravianus Douw who drowned while he was fishing in a nearby river, died on the way to hospital."
	},
	{
		"src": "Vihased k\u00fclaelanikud protestisid ehitusplatsil ettev\u00f5tte kontori ees.",
		"tgt": "Incensed villagers protested in front of the company's site office."
	},
	{
		"src": "Politsei s\u00f5nul loopisid k\u00fclaelanikud politseinikke kividega, mille peale viimased vastasid hoiatuslaskudega.",
		"tgt": "Police said the villagers threw rocks at officers, who responded by firing warning shots."
	},
	{
		"src": "Aga kohalike v\u00e4itel hakkas mobiilne brigaad (Indoneesia s\u00f5jav\u00e4estatud politsei) rahva pihta tulistama, tappes \u00fche inimese.",
		"tgt": "But locals say the mobile brigade (Indonesian paramilitary police) began shooting at the crowd, killing one."
	},
	{
		"src": "\"Olime suures paanikas, kardame k\u00e4ttemaksu,\" \u00fctles ajakirjale TIME 29-aastane Dominggu Badii, kes elab haigla l\u00e4histel ja n\u00e4gi vigastatute sissekandmist pealt.",
		"tgt": "\"We were so panicked, we are afraid there will be revenge,\" 29-year-old Dominggu Badii, who lives near the hospital and witnessed the injured being hurried in, tells TIME."
	},
	{
		"src": "\"Olen end kaks p\u00e4eva oma majas peitnud.\"",
		"tgt": "\"I have been hiding in my house for two days.\""
	},
	{
		"src": "Deiyai parlament on n\u00f5udnud asjaga seotud politseinike vastutusele v\u00f5tmist ja politsei mobiilse brigaadi tagasit\u00f5mbamist piirkonnast.",
		"tgt": "The Deiyai parliament has called for the officers involved to be held to account and the police mobile brigade to be withdrawn from the area."
	},
	{
		"src": "Paniai on Indoneesia valitsuse jaoks alati probleemne koht olnud.",
		"tgt": "Paniai has always been a troublespot for the Indonesian government."
	},
	{
		"src": "M\u00f5testatud arengu puudumine toidab Paapua haljendaval keskm\u00e4gismaal elavate mee, moni, dani ja damali h\u00f5imude rahulolematust.",
		"tgt": "The lack of meaningful development feeds the discontent of the tribal Mee, Moni, Dani, and Damal peoples, who live sprawled across Papua's verdant central highlands."
	},
	{
		"src": "Paljud neist on liitunud Vaba Paapua Liikumisega (VPL) \u0096 m\u00e4ssajate armeega, mis kaitseb enda s\u00f5nul paapuate \u00f5igusi, korraldades Indoneesia s\u00f5durite seas juhukorras r\u00fcnnakuid ja inimr\u00f6\u00f6vihaaranguid.",
		"tgt": "Many joined the Free Papua Movement (OPM), the rebel army that claims to defend the rights of the Papuans by launching sporadic attacks and kidnapping raids on Indonesian soldiers."
	},
	{
		"src": "M\u00f5ned VPL-i eestvedajad on p\u00e4rit Paniaist, sealhulgas Tadius Yogi ja Daniel Yudas Kogoya.",
		"tgt": "Some of the top OPM leaders hail from Paniai, including Tadius Yogi and Daniel Yudas Kogoya."
	},
	{
		"src": "Vastuseks sellele on s\u00f5jav\u00e4gi \"riigi suver\u00e4\u00e4nsuse kaitsmise\" ettek\u00e4\u00e4ndel viimaste aastate jooksul vahistanud Paniais ja pidanud omavoliliselt kinni tuhandeid inimesi.",
		"tgt": "In response, thousands of people in Paniai have been arrested and arbitrarily detained by the military in recent years, under the guise of \"safeguarding national sovereignty.\""
	},
	{
		"src": "M\u00f5ned neist ei ilmugi enam kunagi v\u00e4lja.",
		"tgt": "Some never reappear."
	},
	{
		"src": "Paapua inimeste seas tuntakse Paniaid kui \"traagilist unustatud kohta\".",
		"tgt": "Among the people of Papua, Paniai is known as \"a tragic, forgotten place.\""
	},
	{
		"src": "Vaesus toidab rahulolematust.",
		"tgt": "Poverty feeds the discontent."
	},
	{
		"src": "V\u00e4hene riis, mida Enarotalis m\u00fc\u00fcakse, on kohalike jaoks ostmiseks liiga kallis.",
		"tgt": "The little rice on sale in Enarotali is too expensive for locals to buy."
	},
	{
		"src": "Leib on sama k\u00e4ttesaamatu.",
		"tgt": "Bread is just as out of reach."
	},
	{
		"src": "Inimesed kasvatavad kogu oma toidu ise \u0096 peamiselt bataati, lisaks natuke puuvilju ja lehtk\u00f6\u00f6givilju.",
		"tgt": "People here grow everything they eat: mainly nota plus some fruit and leafy vegetables."
	},
	{
		"src": "P\u00f5lluharimine on naiste t\u00f6\u00f6, kellest iga\u00fcks suudab hooldada nelja v\u00f5i viit bataadip\u00f5ldu.",
		"tgt": "Farming is the job of the women, who each can maintain four or five fields of the sweet potato."
	},
	{
		"src": "Nad hoiavad tavaliselt enamiku saagist perele, \u00fclej\u00e4\u00e4nu m\u00fc\u00fcvad kohalikul turul.",
		"tgt": "They usually keep most of the harvest for the family, with the rest sold in the local market."
	},
	{
		"src": "K\u00fcmme bataati maksab ainult 10 000 Indoneesia ruupiat (75 senti).",
		"tgt": "Ten pieces of nota cost only 10,000 Indonesian rupiah (75 cents)."
	},
	{
		"src": "Aja jooksul on s\u00fcvenenud majanduslik ebav\u00f5rdsus p\u00f5liste paapuate ja uute migrantide vahel, keda on Nabire lennujaama uute lennuliinide avamisest saati hulganisti saabunud.",
		"tgt": "Over time, economic inequalities have grown between the native Papuans and the new migrants, who have arrived in greater numbers since the opening of a new air routes to Nabire Airport."
	},
	{
		"src": "Need v\u00e4hesed t\u00f6\u00f6kohad, mis olemas on, l\u00e4hevad paremini haritud ja j\u00f5ukamatele migrantidele.",
		"tgt": "What few jobs exist typically go to the better-educated and wealthier migrants."
	},
	{
		"src": "Paapuatel endil puuduvad tihtipeale konkurentsiv\u00f5imelise \u00e4ri ajamiseks kapital v\u00f5i vajalikud oskused.",
		"tgt": "Papuans rarely have the capital or the necessary skills to run their own businesses competitively."
	},
	{
		"src": "\"Noored inimesed pole k\u00fclla j\u00e4\u00e4misest huvitatud, sest siin pole ei t\u00f6\u00f6kohti ega raha,\" \u00fctleb Paniai h\u00f5imude n\u00f5ukogu esimees John Gobai.",
		"tgt": "\"The young people are not interested to stay in the village ... because there's no jobs or money here,\" says John Gobai, the chairman of the tribal council of Paniai."
	},
	{
		"src": "Eraldatus hoiab maailma silmad Paapualt eemal.",
		"tgt": "Isolation keeps the world's eyes off Papua."
	},
	{
		"src": "Lisaks p\u00fcsivad v\u00e4lismeediale karmid piirangud.",
		"tgt": "In addition, reporting restrictions for international media remain tight."
	},
	{
		"src": "Selle aasta alguse poole saadeti Paapuast v\u00e4lja prantsuse ajakirjanikud Franck Escudie ja Basille Longchamp, kuna \"nad ei j\u00e4lginud asjakohaseid tavasid\", kuigi neile oli antud haruldane filmimisluba.",
		"tgt": "Earlier this year, French journalists Franck Escudie and Basille Longchamp were deported from Papua for a \"lack of coordination with related institutions\" despite having been granted rare permission to film."
	},
	{
		"src": "Human Rights Watchi Aasia osakonna juhataja aset\u00e4itja Phelim Kine s\u00f5nul ei ole viidud ellu Jokowi valimislubadusi kaotada l\u00e4bipaistvuse ja arengu edendamiseks reportaa\u017eidele seatud piirangud.",
		"tgt": "According to Phelim Kine, Deputy Asia Director of Human Rights Watch, Jokowi's election campaign pledges to lift reporting restrictions to boost transparency and development have not been realized."
	},
	{
		"src": "\"Indoneesias Paapua k\u00f5ige idapoolsematest rahututest provintsidest ja L\u00e4\u00e4ne-Paapuast reportaa\u017ee teha \u00fcritavaid ajakirjanikke \u00e4hvardavad uued ohud \u0096 viisa tagasil\u00fckkamine ja musta nimekirja kandmine,\" \u00fctles ta avalduses.",
		"tgt": "\"There are new hazards for foreign journalists attempting to report from Indonesia's restive easternmost provinces of Papua and West Papua: visa denial and blacklisting,\" he said in a statement."
	},
	{
		"src": "Ajakirjanduse puuriva pilgu puudumine t\u00e4hendab, et rahvusvaheline surve Indoneesia valitsusele piirdub suuresti Paapua l\u00e4hinaabritega.",
		"tgt": "The lack of press scrutiny means international pressure on the Indonesian government has been largely limited to Papua's immediate neighbors."
	},
	{
		"src": "M\u00e4rtsis kannustasid kuus Vaikse ookeani riiki \u0096 Tonga, Nauru, Belau, Tuvalu, Marshalli Saared ja Saalomoni Saared \u0096 \u00dcRO Inim\u00f5iguste N\u00f5ukogu uurima \"mitmesuguseid laiaulatuslikke kuritegusid\" Paapuas, sealhulgas ka Paniai tulistamist.",
		"tgt": "In March, six Pacific nations - Tonga, Nauru, Palau, Tuvalu, the Marshall Islands, and the Solomon Islands - urged the U.N. Human Rights Council to investigate the \"various and widespread violations\" in Papua, including the Paniai shooting."
	},
	{
		"src": "Needsamad riigid on toetanud ajalooliselt ka VPL-i.",
		"tgt": "These same countries have historically backed the OPM."
	},
	{
		"src": "Indoneesia v\u00e4lisministeeriumi pressiesindaja Arrmanatha Nasir heitis grupeeringu s\u00fc\u00fcdistused k\u00f5rvale, \u00f6eldes Jakartas ajakirjanikele: \"Indoneesias kehtib endiselt demokraatlik kord ja ajakirjandusvabadus, nii et inim\u00f5igustevastaste juhtumite t\u00f5endeid oleks raske maha matta.\"",
		"tgt": "Indonesian Foreign Ministry spokesperson Arrmanatha Nasir shrugged off the group's allegations, telling journalists in Jakarta, \"In Indonesia, a democratic system still applies and there's free media so it's hard for the evidence of human rights cases to be covered up.\""
	},
	{
		"src": "Kohalikud inimesed tahavad, et rohkem v\u00e4lisriikide valitsusi paneks t\u00e4hele.",
		"tgt": "Local people want more foreign governments to take note."
	},
	{
		"src": "Kui Hollandi ametlik delegatsioon eesotsas riigi inim\u00f5iguste saadiku Kees Van Baariga 4. mail Jayapurat k\u00fclastas, katkestasid kohalikud inimesed kohtumisel viibinud, kuid anon\u00fc\u00fcmseks j\u00e4\u00e4da soovinud allika s\u00f5nul oma vaikuse, paludes tungivalt: \"Me tahame vabadust.\"",
		"tgt": "When an official delegation from the Netherlands, headed by the nation's human rights ambassador Kees Van Baar, visited Jayapura on May 4, local people broke their silence, beseeching, \"We want freedom,\" according to a source who also attended the meeting but who asked to stay anonymous."
	},
	{
		"src": "Indoneesias toimuvad 2019. aastal uued presidendivalimised, aga paapuad ei usu, et nad uuesti Jokowi poolt h\u00e4\u00e4letavad.",
		"tgt": "Indonesia has another presidential election in 2019, but Papuans say they are unlikely to vote again for Jokowi."
	},
	{
		"src": "\"Jokowi on heade kavatsustega mees, kuid teda \u00fcmbritsevad inimesed, kes on seotud Paniai tulistamisega,\" \u00fctleb h\u00f5imude n\u00f5ukogu esimees Hobai.",
		"tgt": "\"Jokowi is a person who has good intentions, but he is surrounded by the people who are involved in the Paniai shooting,\" says Gobai, the tribal council chairman."
	},
	{
		"src": "Ta tahab Jokowile m\u00f5ista anda, et lisaks sellele, et Paniai inimesed elavad pidevalt kiskjaliku s\u00f5jav\u00e4e \u00e4hvardava ohu all, vaevlevad nad nigelate haridus- ja terviseteenuste t\u00f5ttu viletsuses.",
		"tgt": "He wants Jokowi to know that the Paniai people, aside from living under the looming threat of a rapacious military, wallow in destitution, with paltry education and health services."
	},
	{
		"src": "Gobai s\u00f5nul peavad Paniai inimesed, nagu ka teised paapuad, oma Jokowile antud h\u00e4\u00e4lt v\u00f5laks, mis tal tuleb tasuda.",
		"tgt": "Gobai says the Paniai people, like other Papuans, consider their vote to Jokowi as a \"debt\" he must repay."
	},
	{
		"src": "\"Nad ei vaja raha, nad tahavad \u00f5iglust,\" \u00fctleb ta.",
		"tgt": "\"They don't need money, they just want justice,\" he says."
	},
	{
		"src": "\u00c4hvardustele ja hirmutamisele vaatamata said Paniai tulistamisohvrite perekonnad hakkama veel viimase s\u00fcmboolse vastuhakuga \u0096 nad matsid \u00fche ohvri surnukeha politseijaoskonna ja s\u00f5jav\u00e4ebaasi vastas olevale maale.",
		"tgt": "Despite the threats and intimidation, families of the Paniai shooting victims carried out one last symbolic act of defiance: burying one victim's body on land just opposite the police and military station."
	},
	{
		"src": "Teades, et \u00f5iglust ei pruugitagi kunagi jalule seada, ei lase nad v\u00e4hemalt vastutajatel oma kuritegusid unustada.",
		"tgt": "Knowing that justice may never be served, at least they won't let those responsible forget their crimes."
	},
	{
		"src": "\"\u00dcks meie pereliikmetest tapeti,\" \u00fctleb Yacobus langetatud peaga.",
		"tgt": "\"A member of our family has been killed,\" says Yacobus, head bowed."
	},
	{
		"src": "\"Mida muud me teha saaksime?\"",
		"tgt": "\"What else could we do?\""
	},
	{
		"src": "Tuli neelas Dubai Torchi pilvel\u00f5hkuja juba teist korda enda alla",
		"tgt": "Fire engulfs Dubai's 'Torch' skyscraper for second time"
	},
	{
		"src": "Tuli s\u00f6\u00f6stis reedel l\u00e4bi \u00fche maailma k\u00f5ige k\u00f5rgema elamutorni Dubais, sundides sadu elanikke sellest 337 meetri k\u00f5rgusest ja 79-korruselisest ehitisest p\u00f5genema.",
		"tgt": "A fire ripped through one of the world's tallest residential towers in Dubai on Friday, forcing hundreds of occupants to flee the 337 metre-tall, 79-storey structure."
	},
	{
		"src": "See on teine tulekahju, mis on k\u00f5igest kahe aasta jooksul laastanud k\u00f5rgehitist, mida kutsutakse juhtumisi Torchiks ehk T\u00f5rvikutorniks.",
		"tgt": "It's the second blaze to sweep through the high-rise - which happens to be called the Torch tower - in just two years."
	},
	{
		"src": "Hoone evakueeriti, \u00fchestki vigastusest ei teatatud ja ei esitatud \u00fchtegi otsest tulekahju tekkep\u00f5hjust.",
		"tgt": "The building was evacuated, no injuries were reported, and there was no immediate word on the cause of the blaze."
	},
	{
		"src": "\"Me magasime ja \u00e4rkasime tulekahjualarmi ning inimeste karjumise peale.",
		"tgt": "\"We were sleeping and we woke up to the fire alarm and people screaming."
	},
	{
		"src": "Jooksime treppidest alla ja meil kulus 50. korruselt allaj\u00f5udmiseks umbes 10 minutit,\" \u00fctles Reutersile \u00fcks elanik, kes nimetas end George'iks.",
		"tgt": "We ran down the stairs and it took us about 10 minutes to reach from the 50th floor,\" a resident who gave his name as George told Reuters."
	},
	{
		"src": "Dubai tsiviilkaitseametnike s\u00f5nul kustutasid tulet\u00f5rjujad leegi umbes kell 4 hommikul kohaliku ajal j\u00e4rgi (00.00 GMT) ning jahutasid hoonet.",
		"tgt": "Dubai's civil defence authorities said firefighting squads put out the blaze at around 4.00 am local time (0000 GMT) and were cooling the building."
	},
	{
		"src": "Valitsus \u00fctles, et nad t\u00f6\u00f6tavad kannatanutele peavarju tagamise nimel.",
		"tgt": "The government said it was working on providing shelter for those affected."
	},
	{
		"src": "See vahejuhtum v\u00f5ib taas t\u00f5statada k\u00fcsimusi k\u00f5ikjal maailmas k\u00f5rgehitiste v\u00e4lispinnal kasutatavate materjalide ohutuse kohta.",
		"tgt": "The incident may revive questions about the safety of materials used on the exteriors of tall buildings across the world."
	},
	{
		"src": "Torchi juhatuse 2015. aasta tulekahju j\u00e4rel korraldatud uurimise k\u00e4igus leiti, et k\u00f5ige rohkem kahju kannatas fassaadikate - v\u00e4lispinna dekoratiivsed paneelid ja isolatsioon.",
		"tgt": "An investigation by the management of the Torch after its 2015 fire found that most of the damage was to the cladding, exterior panelling used for decoration or insulation."
	},
	{
		"src": "Suurbritannia politsei on \u00f6elnud, et nad usuvad, et Londoni Grenfell Toweri isolatsioon ja fassaadipaneelid v\u00f5isid panustada seal juunis toiminud tulekahju kiiresse levikusse, milles hukkus ligikaudu 80 inimest.",
		"tgt": "In the UK, police have said they believe the system of insulation and cladding panels on London's Grenfell Tower may have contributed to the rapid spread of a fire there in June in which some 80 people died."
	},
	{
		"src": "Vaata: neist telefonidest saavad ilmselt s\u00fcgisel m\u00fc\u00fcgihitid",
		"tgt": "Watch: these phones should become the autumn\u2019s top sellers"
	},
	{
		"src": "Kevad ja s\u00fcgis on tehnikaf\u00e4nnidele magus aeg, sest siis avalikustavad telefonitootjad oma uued tippmudelid.",
		"tgt": "The spring and autumn are a sweet time for tech fans, because that I when telephone manufacturers unveil their new top of the line models."
	},
	{
		"src": "Kevadel tulid m\u00fc\u00fcgile Samsung Galaxy S8, Huawei P10 ja Sony Xperia XZ Premium, ka s\u00fcgisel on oodata poelettidele uusi hitt-telefone.",
		"tgt": "The spring saw the Samsung Galaxy S8, Huawei P10 and Sony Xperia XZ Premium go on sale, and new hit smartphones are awaited on shelves in the autumn."
	},
	{
		"src": "Tele2 turundus- ja m\u00fc\u00fcgidirektori Kristjan Seema s\u00f5nul iseloomustab t\u00e4navusi lipulaevu uuenduslik disain, silmaiirise sk\u00e4nner, servast-servani 4K resolutsiooniga ekraan ja \u00fclikiire protsessor.",
		"tgt": "Tele2\u2019s marketing and sale director Kristjan Seema says today\u2019s flagships are characterized by an innovative design, iris scanner, edge-to-edge 4K resolution screen and ultra-fast processor."
	},
	{
		"src": "Suurt elevust tekitas tehnoloogiamaailmas Samsung Galaxy S8, mis on j\u00f5udnud ka Eesti nutitelefonide m\u00fc\u00fcgiedetabeli esiossa.",
		"tgt": "The Samsung Galaxy S8 caused ripples of excitement in the tech world, and it is now among the top sellers in Estonia."
	},
	{
		"src": "S\u00fcgis lubab nutihuvilistele veelgi v\u00e4ledamat kiirlaadimist, vastupidavamat akut, kvaliteetsemat kaamerat ja suuremat vee- ja tolmukindlust.",
		"tgt": "The autumn holds the promise of even faster rapid charging, longer battery life, higher quality cameras and better waterproofness and dust resistance."
	},
	{
		"src": "Ta lisas, et kuulduste p\u00f5hjal saab juba teha oletusi ja ennustada nelja tippmudelit, mis arvatavasti t\u00e4navusi m\u00fc\u00fcgiedetabeleid vallutavad.",
		"tgt": "He added that rumour allowed him to predict the four top models that will probably conquer the sales rankings this year."
	},
	{
		"src": "Need neli nutitelefonide tippmudelit j\u00f5uavad poelettidele veel selle aasta s\u00fcgisel.",
		"tgt": "These four top models of smartphones will go on sale only this autumn."
	},
	{
		"src": "Kauaoodatud iPhone 8 ja iPhone 8 Plus peaksid j\u00f5udma poelettidele juba septembri keskel.",
		"tgt": "The long-awaited iPhone 8 and iPhone 8 Plus should reach stores already in mid-September."
	},
	{
		"src": "Kuulujutte, milline aga uus Apple'i mudel v\u00e4lja n\u00e4eb ja mida sellega teha v\u00f5ib, levib palju.",
		"tgt": "Rumours are rife about what the new Apple model looks like and what can be done with it."
	},
	{
		"src": "Kui iPhone 7 ei toonud m\u00e4rkimisv\u00e4\u00e4rselt suuri erinevusi iPhone 6s-i k\u00f5rval, siis Apple'i k\u00fcmnenda s\u00fcnnip\u00e4eva puhul oodatakse, et uus mudel eristub varasematest t\u00e4ielikult.",
		"tgt": "Whereas the iPhone 7 didn\u2019t bring anything significantly different to the iPhone 6s, it\u2019s expected that on the occasion of Apple\u2019s 10th birthday the new model will be completely distinct from previous ones."
	},
	{
		"src": "R\u00e4\u00e4gitud on neljast v\u00e4rvist: must, valge, roosa kuld ja kroom.",
		"tgt": "Four colours have been mentioned: black, white, pink gold and chrome."
	},
	{
		"src": "Uue disaini \u00fcks elemente on ilmselt ekraan, mis katab kogu telefoni esipaneeli, kaotatud on kodunupp ja s\u00f5rmej\u00e4ljelugeja on ehitatud ekraani sisse.",
		"tgt": "One of the elements of the new design is doubtless the screen, which takes up the entire front panel of the phone, the home button has been scrapped and the fingerprint reader has been built into the screen."
	},
	{
		"src": "Apple'i disainijuht JonyIve n\u00f5uab, et uus iPhone'i mudel n\u00e4eks v\u00e4lja nagu sile klaas.",
		"tgt": "Apple\u2019s design chief JonyIve requires that the new iPhone model look like smooth glass."
	},
	{
		"src": "Sealjuures on juttu olnud ka iPhone'i keraamilisest versioonist.",
		"tgt": "There has also been talk of a ceramic version of the iPhone."
	},
	{
		"src": "Lisaks silmaiirise sk\u00e4nnerile, juhtmevabale laadimisele ja veel kvaliteetsemale kaamerale v\u00f5ib oodata kiiremat A11 protsessorit.",
		"tgt": "Besides iris scanner, wireless charging and an even better camera, a faster A11 processor can be expected."
	},
	{
		"src": "Kindlasti on see \u00fcks aasta oodatumaid nutitelefone.",
		"tgt": "It is certainly one of the year\u2019s most eagerly awaited smartphones."
	},
	{
		"src": "Uhiuue mudeli Galaxy Note 8 eeltellimine algab 23. augustil.",
		"tgt": "Pre-ordering of the brand-new Galaxy Note 8 begins on 23 August."
	},
	{
		"src": "Lekkinud on k\u00fcll palju kuuldusi, milline uus Galaxy Note 8 v\u00e4lja hakkab n\u00e4gema.",
		"tgt": "Many rumours have been leaked about what the new Galaxy Note 8 will look like."
	},
	{
		"src": "Kuuldavasti on m\u00f5eldud veelgi rohkem \u00e4rikasutaja peale ja S Pen v\u00f5imaldab veelgi suuremaid funktsionaalsusi.",
		"tgt": "It\u2019s been said that more attention has been given to business users and the S Pen allows even greater functionality."
	},
	{
		"src": "Telefonil peaks olema kaks kaamerat, millest \u00fcks on lainurk ja teine kitsama vaatev\u00e4ljaga teleobjektiiv.",
		"tgt": "The phone should have two cameras, of which one is wide-angle and the other one is a telephoto lens with narrower angle."
	},
	{
		"src": "Praegu ei tea veel keegi, milleks kaks tagumist kaamerat suutelised on, kuid igal juhul on see Samsungi esimene katsetus, mis on kvaliteedi poolest kindlasti v\u00f5rreldav iPhone 8-ga.",
		"tgt": "Currently no one knows what the two rear-facing cameras are capable of, but in any case, it is Samsung\u2019s first attempt, which is sure to be comparable to the iPhone 8 in terms of quality."
	},
	{
		"src": "Ootame aga pingsalt 23. augustit.",
		"tgt": "We are looking forward to 23 August with bated breath."
	},
	{
		"src": "Kuigi Nokia on sellel aastal m\u00fc\u00fcki toonud kolm nutitelefoni eesotsas Nokia 6-ga, on siiski puudu veel nende lipulaev - Nokia 8, mida esitletakse juba 16. augustil.",
		"tgt": "Although Nokia has launched three smartphones this year, led by the Nokia 6, their flagship is still missing \u2013 the Nokia 8, which will be released 16 August."
	},
	{
		"src": "Ootame Nokialt 5,3-tollist \u00e4\u00e4rest-\u00e4\u00e4reni ulatuvat ekraani ja \u00fclikiiret Qualcomm Snapdragon 835 protsessorit ja vastupidavamat akut.",
		"tgt": "We expect an edge-to-edge 5.3-inch screen, a blazingly fast Qualcomm Snapdragon 835 processor and a longer battery life."
	},
	{
		"src": "Nokia puhul r\u00e4\u00e4gitakse ka alumiiniumkorpusest ja m\u00e4rkimisv\u00e4\u00e4rsest vee- ja tolmukindluse astmest IP68.",
		"tgt": "A talking point for the Nokia is also the aluminium body and noteworthy IP68 waterproofness and dustproofness rating."
	},
	{
		"src": "Sarnaselt Samsungiga on Nokia uuel mudelil kaks tagumist kaamerat, mille optika toodab firma Zeiss.",
		"tgt": "Similarly to the Samsung, the new model of the Nokia has two rear-facing cameras, with Zeiss optics."
	},
	{
		"src": "Kui Sony kindel lipulaev on olnud seni XZ Premium, on tootja kinnitanud, et l\u00e4hiajal lisandub v\u00e4hemalt kaks nutitelefoni, millel on veelgi rohkem uuenduslikke funktsioone.",
		"tgt": "Sony\u2019s stable flagship has been the XZ Premium to this point, but the manufacturer has said that in the near future at least two smartphones with even more innovative functions will be added."
	},
	{
		"src": "Ootame nutitelefoni, mis on k\u00fcll veidi tagasihoidlikum kui XZ Premium, kuid v\u00e4hemalt sama hea v\u00f5i parema kaameraga.",
		"tgt": "We are awaiting a smartphone that while it is a little more modest than the XZ Premium, it will have a camera that is as good or better."
	},
	{
		"src": "Sony uue mudeli kohta on spekuleeritud, et selle ekraan on v\u00e4hemalt kuuetolline.",
		"tgt": "It has been speculated that the screen on the new Sony model will be at least 6-inch."
	},
	{
		"src": "Mis tegelikkus toob, saame n\u00e4ha juba \u00f5ige pea, sest traditsiooniliselt on Sony oma s\u00fcgisese lipulaeva avalikustanud rahvusvahelisel tehnoloogiamessil IFA, mis sel aastal toimub 1.-6. septembrini.",
		"tgt": "We\u2019ll get to see quite soon what the reality will be, as traditionally, Sony has released its autumn flagship at the IFA international tech fair, which runs from 1-6 September this year."
	},
	{
		"src": "Telefonik\u00f5nede lekkinud transkriptide andmetel survestas Trump Mehhikot piirim\u00fc\u00fcri eest maksmise osas",
		"tgt": "Trump pressured Mexico on border wall payment according to leaked phone call transcripts"
	},
	{
		"src": "The Washington Post avalikustas Ameerika \u00dchendriikide presidendi Donald Trumpi ning Mehhiko ja Austraalia riigijuhtide vaheliste telefonik\u00f5nede transkriptid.",
		"tgt": "Transcripts of phone calls between US President Donald Trump and leaders of Mexico and Australia have been leaked by the Washington Post."
	},
	{
		"src": "27. jaanuaril k\u00e4is Trump telefonik\u00f5nes Mehhiko presidendile Enrique Pena Nietole peale, et viimane l\u00f5petaks avaliku kuulutamise, et ta ei kavatse maksta v\u00e4ljapakutud piirim\u00fc\u00fcri eest.",
		"tgt": "On 27th January in a phone call to Mexican president, Enrique Pena Nieto, Trump urged him to stop publicly saying he would not pay for a proposed border wall."
	},
	{
		"src": "Ameerika president pragas temaga m\u00fc\u00fcri avaliku hukkam\u00f5istmise p\u00e4rast, lausudes: \"Sa ei tohi seda pressile \u00f6elda.\"",
		"tgt": "The US President berated him for publicly denouncing the wall, reportedly saying to him \"You cannot say that to the press.\""
	},
	{
		"src": "Trump p\u00fcstitas oma presidendikampaania lubadusele ehitada piki Ameerika \u00dchendriikide l\u00f5unapiiri m\u00fc\u00fcr ja vandus, et paneb Mehhiko selle projekti eest maksma.",
		"tgt": "Trump launched his presidential campaign on a promise to build a wall along the US southern border and vowed to make Mexico pay for the project."
	},
	{
		"src": "Avaldati ka transkriptid tema esimesest k\u00f5nest Austraalia peaministri Malcolm Turnbulliga, mis paljastavad pingelise m\u00f5ttevahetuse.",
		"tgt": "Transcripts of his first call with Australian Prime Minister Malcolm Turnbull were also published revealing a tense exchange."
	},
	{
		"src": "Trump \u00fctles Turnbullile, et kokkulepe, mille kohaselt Ameerika \u00dchendriikid v\u00f5tavad enda peale Austraaliasse suunduvad p\u00f5genikud, on \"naeruv\u00e4\u00e4rne\", \"n\u00e4rune\" ja \"rumal\". Ta v\u00e4itis, et kokkulepe, mis tehti Obama valitsuse ajal, j\u00e4taks temast \"juhmardi\" mulje, kuna ta on pakkunud v\u00e4lja p\u00f5genike Ameerika \u00dchendriikidesse \u00fcmberasustamise keelu.",
		"tgt": "Mr Trump told Mr Turnbull a deal for the US to take on refugees headed for Australia was \"ridiculous,\" \"rotten\" and \"stupid,\" insisting the deal, brokered under the Obama administration, would make him look like \"a dope\" after he had proposed a ban on refugee resettlement in the US."
	},
	{
		"src": "Trump l\u00f5petas k\u00f5ne, teatades Turnbullile, et \"tegemist oli p\u00e4eva k\u00f5ige ebameeldivama k\u00f5nega\".",
		"tgt": "Mr Trump ended the call after telling Mr Turnbull \"this is the most unpleasant call all day.\""
	},
	{
		"src": "Riigikohus ei v\u00f5tnud arutusele O\u00dc MRP Linna Liinid kaebust asjas, kus Tartu linn l\u00fckkas tagasi nende pakkumuse bussiliiniveo hankeks juulist 2019 kuni 2029.",
		"tgt": "The Supreme Court will not hear the appeal of O\u00dc MRP Linna Liinid in a matter where the city of Tartu rejected their tender in a bus transport tender for July 2019 to 2029."
	},
	{
		"src": "Tegemist on k\u00e4skkirjaga, millega l\u00fckati tagasi O\u00dc MRP Linna Liinid pakkumus Tartu bussihankel, kuna pakkumus ei vastanud n\u00f5uetele, selgitas Tartu Linnavalitsuse\u00f5igusteenistuse juhataja Anneli Apuhtin.",
		"tgt": "This is a directive rejecting the tender of O\u00dc MRP Linna Liinid I a Tartu bus procurement as the tender did not meet the requirements, explained Tartu City Government legal service director Anneli Apuhtin."
	},
	{
		"src": "Tegemist on Tartu linna sisese avalikubussiliiniveo hankega perioodiks 01.07.2019-30.06.2029.",
		"tgt": "This was the procurement for regular public bus transport within the city of Tartu for the period 1 July 2019 to 30 June 2029."
	},
	{
		"src": "MRP Linna Liinid kaebasid Riigikohtusse Tartu ringkonnakohtu otsuse.",
		"tgt": "MRP Linna Liinid appealed the Tartu circuit court decision to the Supreme Court."
	},
	{
		"src": "Riigikohus seda menetleda ei v\u00f5tnud.",
		"tgt": "The Supreme Court refused to hear it."
	},
	{
		"src": "Ehkki sotsiaalmeedias kurdavad paljud, et Weekend festivalilt kostuv l\u00e4rm h\u00e4irib nende \u00f6\u00f6und ning terve linn on joobes pidutsejaid t\u00e4is, siis leidub palju ka neid, kel pole rannas kestva festivali kohta \u00fchtegi halba s\u00f5na \u00f6elda.",
		"tgt": "Although many complain on social media that the noise from the Weekend Festival disturbs their sleep and that the whole city is full of drunken revellers, there are also many who have nothing negative to say about the festival on the beach."
	},
	{
		"src": "Ma olen isegi positiivselt \u00fcllatunud, et kaupluses olid pidulised nii viisakad!",
		"tgt": "I\u2019m actually positively surprised that the festivalgoers were so well behaved in the shop!"
	},
	{
		"src": "Ma ei n\u00e4inud \u00fchtegi h\u00e4gust olemist ega ebaviisakust.",
		"tgt": "I didn\u2019t see anyone in a stupor or being uncivil."
	},
	{
		"src": "Isegi lahkust n\u00e4gin\", s\u00f5nab p\u00e4rnakas Laine.",
		"tgt": "I even saw niceness,\u201d says Laine, from P\u00e4rnu."
	},
	{
		"src": "\"See on ju tore, et tullakse, ollakse ja tuntakse r\u00f5\u00f5mu P\u00e4rnust, mis on talviti nagu talveunne j\u00e4\u00e4nud\", lisab ta r\u00f5\u00f5msalt.",
		"tgt": "\u201cIt\u2019s so great that people come, have a stay and enjoy P\u00e4rnu, which goes into hibernation in winter,\u201d she adds cheerfully."
	},
	{
		"src": "Rannast kostuv t\u00fcmakas Laine und ei h\u00e4iri.",
		"tgt": "The pounding music heard from the beach doesn\u2019t keep Laine up at night."
	},
	{
		"src": "Kui kesklinnas elades kuulis ta ikka, et rannas muusikat m\u00e4ngitakse, siis n\u00fc\u00fcd pole muusika veel tema koduseinteni j\u00f5udnud.",
		"tgt": "Living in the city centre, she heard music coming from the beach, but now the walls of her home are out of range of the music."
	},
	{
		"src": "\"Aga ma loodan, et kuulen\", \u00fctleb ta r\u00f5\u00f5msalt.",
		"tgt": "\u201cBut I hope I do hear it,\u201d she says cheerfully."
	},
	{
		"src": "Ka \u00d5htulehega vestelnud Agnes r\u00e4\u00e4gib, et suurfestival on P\u00e4rnu jaoks pigem hea - aitab see ju tublisti kaasa kohalike kaupmeeste k\u00e4ibele.",
		"tgt": "Agnes, who also spoke with \u00d5htuleht, said that the summer festival was a good rather than a bad thing for P\u00e4rnu \u2013 it boosts local merchants\u2019 turnover, after all."
	},
	{
		"src": "Lisaks r\u00f5\u00f5mustab ta, et suvepealinna on k\u00fclla tulnud niiv\u00f5rd palju v\u00e4ljamaalasi.",
		"tgt": "She is also pleased that so many foreigners came to the summer capital."
	},
	{
		"src": "Peoliste melu naist ei sega.",
		"tgt": "The festivalgoers\u2019 revelry doesn\u2019t faze the woman."
	},
	{
		"src": "Olgugi, et ma enam rannas ei p\u00e4evita, aga tore, et rand on elavlenud.",
		"tgt": "Even though I don\u2019t go to the beach to sunbathe anymore, it\u2019s great that the beach has come to life."
	},
	{
		"src": "Ja tore, et rahvas liigub ja see on juba kolm korda nii olnud\", \u00fctleb naine.",
		"tgt": "And it\u2019s great that people are moving about and it\u2019s been that way for three times now,\u201d she says."
	},
	{
		"src": "Esimesel korral oli vist kord natuke halvem.",
		"tgt": "The first time it was a little worse, I think."
	},
	{
		"src": "\"Siis ehk oli kaebuseid\", m\u00f5tiskleb ta.",
		"tgt": "\u201cThat time there were complaints perhaps,\u201d she says, thinking."
	},
	{
		"src": "K\u00fcll aga ongi rannas toimuv melu tema s\u00f5nul suvepealinlaste jaoks tavaline.",
		"tgt": "But partying on the beach, she says, is a common thing for residents of the \u201csummer capital\u201d."
	},
	{
		"src": "\"See Weekend on v\u00e4ga hea promo meie v\u00e4ikesele linnale\", r\u00e4\u00e4gib pargis peesitav Harri.",
		"tgt": "\u201cThat Weekend is a great promo for our little city,\u201d says Harri, who is lolling in the park."
	},
	{
		"src": "Melu ja m\u00f6ll pole ka tema elur\u00fctmi v\u00f5nkesse l\u00f6\u00f6nud.",
		"tgt": "The revelry and carousing hasn\u2019t turned his life upside down."
	},
	{
		"src": "Aga misjaoks?!",
		"tgt": "But why?"
	},
	{
		"src": "Me peaksime k\u00f5ik kokku hoidma.",
		"tgt": "We all have to stick together."
	},
	{
		"src": "M\u00f5tlema nii, kuidas see rahvustevaheline suhtlemine parem oleks.",
		"tgt": "We have to think about how the international relations could be better."
	},
	{
		"src": "Valju muusika meest ei muserda.",
		"tgt": "Loud music doesn\u2019t get his spirits down."
	},
	{
		"src": "See ei sega, ehkki ma elan sealsamas l\u00e4hedal.",
		"tgt": "It doesn\u2019t bother me, even though I live close by."
	},
	{
		"src": "\"Head inimesed suudavad kokku hoida ja pole mingit pahandust\", k\u00f5neleb ta.",
		"tgt": "\u201cGood folks are able to stick together and there\u2019s no trouble,\u201d he says."
	},
	{
		"src": "P\u00e4rnusse tulnud k\u00fclalised on tema s\u00f5nul viisakad.",
		"tgt": "The visitors to P\u00e4rnu are well behaved, he says."
	},
	{
		"src": "\"Pudelitega on nad muidugi ka natuke liialdanud, ent noored on noored ja issand jumal - andke minna, ent olge inimesed ja saame hakkama!\" \u00fctleb ta.",
		"tgt": "\u201cThey hit the bottle pretty hard, of course, but kids will be kids and Lord, let it be, be decent and we\u2019ll get by,\u201d he says."
	},
	{
		"src": "Ranna\u00e4\u00e4rsed elanikud on selleks ajaks kuskile eemale reisinud, kas siis sugulaste v\u00f5i tuttavate juurde.",
		"tgt": "The people living in the beach area go somewhere else for that time, to visit friends or family."
	},
	{
		"src": "\"Aga \u00fcldiselt m\u00f5jutab festival elu positiivselt -inimestele meeldib selline melu\", r\u00e4\u00e4gib P\u00e4rnus lastega jalutanud Tiina.",
		"tgt": "\u201cBut in general, the festival life has a positive influence \u2013 people like that kind of revelry,\u201d says Tiina, who was out walking with her children in P\u00e4rnu."
	},
	{
		"src": "Ka tema perekonna und festivalimuusika ei h\u00e4iri, ehkki m\u00f6\u00f6dunud aastal kostus see t\u00e4navusest veelgi kaugemale.",
		"tgt": "The festival music doesn\u2019t bother her family\u2019s slumber, even though last year it was heard a bit further than this year."
	},
	{
		"src": "Eelmisel suvel oli lava teistpidi, siis kuulsime rohkem.",
		"tgt": "Last summer, the stage faced the other way. Then we heard more."
	},
	{
		"src": "Elame ise linnast v\u00e4ljas, et tegelikult kostub sinna kaugele P\u00e4rnu j\u00f5e \u00e4\u00e4rde p\u00e4ris h\u00e4sti\", r\u00e4\u00e4gib ta.",
		"tgt": "We actually live outside the city, and it can be heard quite well way over by the P\u00e4rnu River,\u201d she says."
	},
	{
		"src": "Pearson k\u00e4rbib veel 3000 t\u00f6\u00f6kohta ja v\u00e4hendab dividende, et \u00e4ri taaselustada",
		"tgt": "Pearson cuts another 3,000 jobs, slashes dividend to revive business"
	},
	{
		"src": "Briti haridusettev\u00f5te Pearson \u00fctles reedel, et k\u00e4rbib veel 3000 t\u00f6\u00f6kohta ja v\u00e4hendab oma vahedividende 72 protsendi v\u00f5rra, k\u00e4ivitades sellega \u00e4ri \u00e4hvardava kitsikuse lahendamiseks j\u00e4rjekordse \u00fcmberstruktureerimisprogrammi.",
		"tgt": "British education group Pearson said on Friday it would cut another 3,000 jobs and slash its interim dividend by 72 per cent as it started another restructuring programme to tackle the pressures facing its business."
	},
	{
		"src": "Kaotatavad t\u00f6\u00f6kohad, mis koondatakse tegevjuhi John Falloni s\u00f5nul suure t\u00f5en\u00e4osusega 2018. aasta l\u00f5pus ja 2019. aasta alguses, lisanduvad eelmise \u00fcmberstruktureerimise k\u00e4igus kaotatud 4000 ametikohale.",
		"tgt": "The job cuts, which Chief Executive John Fallon said will mostly come late in 2018 and in early 2019, are in addition to 4,000 roles lost in its previous restructuring."
	},
	{
		"src": "Pearson teatas maikuus plaanist k\u00e4rpida kolmanda kulude v\u00e4hendamise programmi raames kulusid veel 300 miljoni naela v\u00f5rra (394 miljonit USA dollarit), et \u00fcritada taaselustada \u00e4ri, mis on saanud kiire digitaalsele \u00f5ppele \u00fclemineku t\u00f5ttu hoobi.",
		"tgt": "Pearson announced a plan to cut costs by another 300 million pounds ($394-million U.S.) in May in a third cost-cutting programme to try to revive a business hit by the rapid move to digital learning."
	},
	{
		"src": "Ettev\u00f5te, mis n\u00f5ustus m\u00fc\u00fcma eelmisel kuul osaluse ettev\u00f5ttes Penguin Random House oma partnerettev\u00f5ttele Bertelsmann, \u00fctles, et nende ootus seoses aastaga ei ole muutunud p\u00e4rast seda, kui teatati m\u00fc\u00fcgitulu 1-protsendilisest kasvust 2,05 miljardi naelani aasta esimeses pooles.",
		"tgt": "The company, which agreed to sell its stake in Penguin Random House to partner Bertelsmann last month, said its outlook for the year was unchanged after it reported a 1 per cent rise in underlying sales in the first half to 2.05 billion pounds."
	},
	{
		"src": "P\u00fchap\u00e4eval j\u00e4tkub vihmahoogudega suviselt soe ilm",
		"tgt": "Seasonably warm summer weather with scattered showers continues on Sunday"
	},
	{
		"src": "Eestis tuleb p\u00fchap\u00e4eval vihmahoogudega \u00e4ikesev\u00f5imalusega suviselt soe ilm, tuulepuhangud on kohati v\u00e4ga tugevad.",
		"tgt": "On Sunday, Estonia will have seasonally warm summer temperatures with the chance of thunderstorms, with high gusts of wind at times."
	},
	{
		"src": "\u00d6\u00f6sel tuleb Eestis pilves selgimistega ilm.",
		"tgt": "Overnight, it will be partly cloudy in Estonia."
	},
	{
		"src": "Mitmel pool sajab hoovihma, v\u00f5ib olla \u00e4ikest.",
		"tgt": "There will be scattered showers with a chance of thunderstorms."
	},
	{
		"src": "Puhub edela- ja l\u00e4\u00e4netuul 5-11, puhanguti kuni 14, saartel ja rannikul kuni 18 m/s.",
		"tgt": "The wind from be from the southwest and west at 5-11 m/s, gusting to 14 m/s, and up to 18 m/s on the islands and coasts."
	},
	{
		"src": "\u00d5hutemperatuur on 13-17 kraadi.",
		"tgt": "The temperature will be between 13-17 degrees."
	},
	{
		"src": "P\u00e4eva tuleb vahelduva pilvisusega ilm.",
		"tgt": "The day will be partly cloudy."
	},
	{
		"src": "Mitmel pool sajab hoovihma, paiguti on v\u00f5imalik \u00e4ike.",
		"tgt": "There will be scattered showers with a chance of scattered thunderstorms."
	},
	{
		"src": "Puhub edelatuul 6-12, puhanguti kuni 15, saartel ja rannikul kuni 20 m/s.",
		"tgt": "The wind will be from the southwest at 6-12 m/s gusting to 15 and up to 20 m/s on the islands and coasts."
	},
	{
		"src": "\u00d5hutemperatuur on 18-21 kraadi.",
		"tgt": "The temperature will be between 18 and 21 degrees."
	},
	{
		"src": "Konvoir\u00fcnnak Kabulis: enesetapur\u00fcnnakus hukkus NATO s\u00f5dur",
		"tgt": "Kabul convoy attack: Nato soldier killed in suicide blast"
	},
	{
		"src": "Enesetapupommitaja r\u00fcndas ametnike s\u00f5nul Afganistani pealinnas Kabulis s\u00f5jav\u00e4ekonvoid, tappes \u00fche NATO s\u00f5duri ja haavates mitut teist.",
		"tgt": "A suicide bomber has attacked a military convoy in the Afghan capital, Kabul, killing a Nato soldier and wounding several others, officials say."
	},
	{
		"src": "NATO avalduses \u00f6eldi, et vigastada said viis s\u00f5durit ja t\u00f5lk.",
		"tgt": "Five soldiers and an interpreter were injured, a Nato statement said."
	},
	{
		"src": "Kinnitamata kohalike teadete v\u00e4itel sai linna Qarabaghi rajoonis toimunud intsidendis surma ka kolm tsiviilisikut.",
		"tgt": "Unconfirmed local reports say three civilians also died in the incident in the city's Qarabagh district."
	},
	{
		"src": "See pommitamine on viimane v\u00e4givallaaktidest, mis on Afganistani sel kuul tabanud - teisip\u00e4eval sai Herati mo\u0161eer\u00fcnnakus surma rohkem kui 30 inimest.",
		"tgt": "The bombing is the latest violence to have hit Afghanistan this month - on Tuesday more than 30 people were killed in a mosque blast in Herat."
	},
	{
		"src": "Esmasp\u00e4eval tappis enesetapupommitaja Kabulis Iraagi saatkonna l\u00e4hedal kaks inimest.",
		"tgt": "On Monday a suicide bomber killed two people near the Iraqi embassy in Kabul."
	},
	{
		"src": "NATO avaldus \u00fctles, et neljap\u00e4eva\u00f5htune plahvatus toimus, kui \u00fchispatrulli Afgaani armeega r\u00fcnnati \"inimese kantud ise valmistatud l\u00f5hkekehaga\".",
		"tgt": "A Nato statement said that Thursday evening's blast happened when a joint patrol with the Afghan army was attacked by a \"personnel-borne improvised explosive device.\""
	},
	{
		"src": "Avalduse v\u00e4itel on k\u00f5ik vigastatud stabiilses seisundis ja neid ravitakse USA militaarhaiglas Bagrami lennuv\u00e4ljal.",
		"tgt": "The statement said that all those injured are in a stable condition and are being treated at the US military hospital at Bagram airfield."
	},
	{
		"src": "Korrespondentide s\u00f5nul on Talibani ja grupi, mida tuntakse kui nn Islamiriiki (ISIS), aina kasvav j\u00f5ud Qarabaghis NATO Bagramis asuvate j\u00f5udude jaoks t\u00f5sine mureallikas.",
		"tgt": "Correspondents say the growing strength of the Taliban and the group known as so-called Islamic State (IS) in Qarabagh is a major source of concern to Nato forces based in nearby Bagram."
	},
	{
		"src": "\u00dcRO andmetel on 2017. aasta esimeses pooles saanud Afganistanis surma v\u00e4hemalt 1662 tsiviilisikut, neist ligikaudu 20% pealinnas.",
		"tgt": "According to the United Nations, Afghanistan saw at least 1,662 civilian deaths in the first half of 2017, with about 20% of those in the capital."
	},
	{
		"src": "Juuli l\u00f5pus tappis autopomm Kabulis peamiselt \u0161iiidide rajoonis v\u00e4hemalt 30 inimest.",
		"tgt": "At the end of July, a suicide car bomb killed at least 30 people in a mainly Shia district of Kabul."
	},
	{
		"src": "Talibani s\u00f5nul olid nemad r\u00fcnnaku taga.",
		"tgt": "The Taliban said they had carried out that attack."
	},
	{
		"src": "31. mail tappis suur pommir\u00fcnnak kesklinnas rohkem kui 150 inimest - see on k\u00f5ige rohkem surmi kaasa toonud s\u00f5jaline r\u00fcnnak riigis alates sellest, kui USA juhitud v\u00e4ed t\u00f5rjusid Talibani 2001. aastal v\u00f5imult.",
		"tgt": "On 31 May, a huge bombing in the centre of the city killed more than 150 people, the deadliest militant attack in the country since US-led forces ousted the Taliban from power in 2001."
	},
	{
		"src": "See v\u00e4givald r\u00f5hutab ebakindlat julgeolekuolukorda Afganistanis, samal ajal kui Ameerika \u00dchendriikide president Donald Trump kaalub, kas suurendada riigi s\u00f5jav\u00e4ge ja politseid aitavate USA v\u00e4gede arvu.",
		"tgt": "The violence underlines the precarious security situation in Afghanistan as US President Donald Trump weighs up whether to increase the number of US troops aiding the military and police in the country."
	},
	{
		"src": "Korrespondentide v\u00e4itel on viimastel n\u00e4dalatel Kabulis toimunud enesetapur\u00fcnnakud toonud \u00fchtlasi kaasa avalikkuse usalduskriisi valitsuse, selle poliitikate ja eriti president Ashraf Ghani vastu.",
		"tgt": "Correspondents say the suicide bombings in Kabul in recent weeks have also created a crisis of public confidence in the government, its policies and in particular the reputation of President Ashraf Ghani."
	},
	{
		"src": "EPA t\u00fchistas p\u00e4rast hagisid sudum\u00e4\u00e4ruse edasil\u00fckkamise otsuse",
		"tgt": "EPA reverses decision to delay smog rule after lawsuits"
	},
	{
		"src": "Ameerika \u00dchendriikide Keskkonnakaitseagentuur (United States Environmental Protection Agency \u0096 EPA) t\u00fchistas otsuse viivitada Obama-aegse m\u00e4\u00e4ruse kehtestamisega, mis kohustab osariike piirama sudu p\u00f5hjustavaid heitgaase, \u00fcks p\u00e4ev p\u00e4rast seda, kui 15 osariiki kaebasid agentuuri selle k\u00e4igu t\u00f5ttu kohtusse.",
		"tgt": "The U.S. Environmental Protection Agency reversed a decision to delay an Obama-era rule requiring states to curb smog-causing emissions, one day after 15 states sued the agency over the move."
	},
	{
		"src": "EPA teatas otsusest j\u00e4tkata \"2015. a osoonisisalduse m\u00e4\u00e4ramise toimingutega\" hilja kolmap\u00e4eval, \u00f6eldes, et see n\u00e4itab agentuuri p\u00fchendumust koost\u00f6\u00f6le osariikidega.",
		"tgt": "The EPA announced the decision to go ahead with the so-called \"2015 Ozone Designations\" late on Wednesday, saying it showed the agency's commitment to working with states."
	},
	{
		"src": "\"Usume, et peame oma osariikidest partneritega dialoogi pidama ja neid kuulda v\u00f5tma,\" \u00fctles EPA juht Scott Pruitt avalduses.",
		"tgt": "\"We believe in dialogue with, and being responsive to, our state partners,\" EPA Chief Scott Pruitt said in a statement."
	},
	{
		"src": "Pruitt oli teatanud juunikuus EPA kavatsusest l\u00fckata osoonisisalduse m\u00e4\u00e4ramised \u0096 mille k\u00e4igus m\u00f5\u00f5detakse riigi eri osades sudureostust, et teha kindlaks, kus tuleks selle taset karmimale \u00f5hukvaliteedi standardile vastamiseks v\u00e4hendada \u0096 \u00fche aasta v\u00f5rra edasi 2018. aasta oktoobrisse.",
		"tgt": "Pruitt in June had announced the EPA's intention to delay the ozone designations - in which existing smog pollution is measured in parts of the country to determine where cuts must be made to meet tougher air quality standard - by one year to October 2018."
	},
	{
		"src": "15 peamiselt demokraatlikku osariiki esitasid \u00fcheskoos Columbia ringkonnaga teisip\u00e4eval hagi, \u00f6eldes, et see otsus on ebaseaduslik.",
		"tgt": "A group of 15 mostly Democratic states, along with the District of Columbia, filed a suit on Tuesday saying the effort was illegal."
	},
	{
		"src": "President Donald Trumpi valitsus on \u00fcritanud t\u00f5mmata tagasi mitmeid endise presidendi Barack Obama kehtestatud keskkonnaregulatsioone. Trumpi s\u00f5nul on see osa laiahaardelisemast majanduskasvu turgutamise plaanist.",
		"tgt": "The administration of President Donald Trump has been seeking to roll back a wide array of environmental regulations imposed by former President Barack Obama, as part of a broader agenda Trump says is aimed at sparking economic growth."
	},
	{
		"src": "Aga need p\u00fc\u00fcdlused on tekitanud vastureaktsioone demokraatide ja looduskaitser\u00fchmituste seas, kes on mures suurenenud saasteainete m\u00f5ju p\u00e4rast inimeste tervisele.",
		"tgt": "But the efforts have triggered pushback by Democratics and conservation groups who are concerned about the impact of greater emissions on public health."
	},
	{
		"src": "EPA veebilehel on kirjas, et osooni sisaldava \u00f5hu sissehingamine \"v\u00f5ib kahandada kopsude t\u00f6\u00f6v\u00f5imet ja suurendada riski haigestuda hingamisteede haigustesse\", n\u00e4iteks astmasse.",
		"tgt": "The EPA's website says breathing air containing ozone \"can reduce lung function and increase respiratory symptoms\" like asthma."
	},
	{
		"src": "Saksa sigadel v\u00f5ib tulla pidu.",
		"tgt": "German pigs may have a field day."
	},
	{
		"src": "Saksamaa sigadel ja veistel v\u00f5ib tulla pidu, kuna tugevad vihmad ohustavad Euroopa Liidu suuruselt teise nisutootja saaki, kirjutab Bloomberg.",
		"tgt": "German pigs and cattle may have a field day as heavy rain is jeopardizing the harvest in the EU\u2019 second largest wheat producer, Bloomberg writes."
	},
	{
		"src": "T\u00e4navu v\u00f5ib minna sedasi, et n\u00e4dalaid kestnud sajuhood enne saagikoristust v\u00f5ib t\u00e4hendada, et leivat\u00f6\u00f6stuseks m\u00f5eldud vili k\u00f5lbab vaid loomadele s\u00f6\u00f6daks.",
		"tgt": "This year it may happen that the rains that have lasted weeks before the harvest may mean that grain intended for the bread industry is only suitable for animal feed."
	},
	{
		"src": "\"Nisu kvaliteet on kaugelt hullem kui mullu ja kehvem kui 2015. aastal\", \u00fctles Agravis Raiffeiseni anal\u00fc\u00fctik Bernhard Chilla.",
		"tgt": "\u201cThe quality of wheat is far worse than it was last year and worse than in 2015,\u201d said Agravis Raiffeisen analyst Bernhard Chilla."
	},
	{
		"src": "T\u00e4navu v\u00f5ib minna kuni 40 protsenti saksa nisust loomas\u00f6\u00f6daks, mida on topelt v\u00f5rreldes tavap\u00e4rasega, prognoosis Agravis.",
		"tgt": "This year, as much as 40 per cent of wheat may end up as feed, which is double the usual level, Agravis forecasted."
	},
	{
		"src": "Saksa p\u00f5llumehed nagu ka nende Euroopa kolleegid on t\u00e4navu puutunud kokku igasuguse ilmaga.",
		"tgt": "German farmers, and their ilk throughout Europe, have experienced all sorts of weather this year."
	},
	{
		"src": "K\u00f5igepealt oli talv liiga kuiv.",
		"tgt": "First, the winter was too dry."
	},
	{
		"src": "Siis tuli k\u00fclm kevad, mida juunis asendas kuumalaine.",
		"tgt": "Then came a cold spring, which was supplanted by a cold snap in June."
	},
	{
		"src": "Juulis tabas Saksamaad sajuhood, mis on j\u00e4tkunud ka augustis.",
		"tgt": "In July, showers hit Germany, and have continued in August, too."
	},
	{
		"src": "Paljude silmad on p\u00f6\u00f6ratud P\u00f5hja-Saksamaale, kus vihm takistab saagikoristust.",
		"tgt": "Many eyes are trained on northern Germany where rain is hampering the harvest."
	},
	{
		"src": "Seni on koristatud vaid viis protsenti nisust.",
		"tgt": "To this point, only five per cent of the wheat has been harvested."
	},
	{
		"src": "Enamus piirkonnas pole veel saagikoristus alanudki, teatas kohalik saagi kokkuostja Ceravis.",
		"tgt": "In most areas, harvesting has not even started, said local harvest buyer Ceravis."
	},
	{
		"src": "\"K\u00e4es on p\u00e4ris keerulised p\u00e4evad\", \u00fctles Ceravise vanemkaupleja Frank Deckert Rendsburgist.",
		"tgt": "\u201cSome rather complicated days are at hand,\u201d said Ceravis senior trade Frank Deckert from Rendsburg."
	},
	{
		"src": "Koosk\u00f5la k\u00f5iges ehk soomlaste sisekujunduse kavalad kiiksud",
		"tgt": "Harmony in everything \u2013 the Finns\u2019 clever interior design twists"
	},
	{
		"src": "Kaunis loodus m\u00e4ngib oma osa messikodude interj\u00f6\u00f6rides, sest suurte akende kaudu j\u00f5uavad Saimaa kallaste v\u00f5rratud vaated paljudesse (elu) tubadesse.",
		"tgt": "Scenic nature plays its role in the interiors of homes featured at the trade fair, as the incomparable views of the Saimaa coast can be seen in many (living) rooms."
	},
	{
		"src": "Igal sammul hakkab silma meie p\u00f5hjanaabrite p\u00fc\u00fcdlus luua \u00fchtaegu nii kargeid kui ka t\u00e4iuslikke (energias\u00e4\u00e4stlikke) kodusid.",
		"tgt": "At each step, we see our northern neighbours\u2019 striving to create homes that are at once cool in tone as well as perfect (energy-efficient)."
	},
	{
		"src": "Imetlust ja ka j\u00e4rgimist v\u00e4\u00e4rib soomlaste puidukasutamisoskus ehitus- ja viimistlusmaterjalina, m\u00f6\u00f6bli ja iluasjade valmistamisel.",
		"tgt": "The Finns also have an admirable ability to use wood as a construction and finishing material, in making furniture and aesthetic items."
	},
	{
		"src": "Virgutavaid v\u00f5tteid ja nutikaid lahendusi leiab messimajades nii ehitaja kui ka (kodu) kujundaja.",
		"tgt": "Both builder and (home) decorators will find inspirational techniques and clever solutions in the houses at the trade fair."
	},
	{
		"src": "Seal tuleb ilmekalt esile, et musta, valge ja halli varjundeist kooslused, kui neid t\u00e4iendavad puidutoonid ja toataimed, v\u00f5ivad olla v\u00e4ga meeleolukad.",
		"tgt": "It vividly highlights the fact that combinations of black, white and grey shades, when they are complemented by wood tones and house plants, can be very atmospheric."
	},
	{
		"src": "H\u00e4id ideid saab noppimas k\u00e4ia veel n\u00e4dal aega, sest mess kestab 13. augustini.",
		"tgt": "There\u2019s still a week for gleaning good ideas, as the fair runs until 13 August."
	},
	{
		"src": "Tarvikud ja \u00fcrdipotid vihjavad, et selles k\u00f6\u00f6gis kokatakse sageli.",
		"tgt": "Accessories and herb pots hint that a lot of cooking takes place in this kitchen."
	},
	{
		"src": "\u00d6\u00f6l vastu t\u00e4nast t\u00f5mmati joon alla t\u00e4navusele Weekend Festival Balticule ning Martin Garrix andis pealaval endast k\u00f5ik, et viimase esinejana meelde j\u00e4\u00e4da.",
		"tgt": "Last night, this year\u2019s Weekend Festival Baltic wrapped up, and Martin Garrix did his best on the main stage to be remembered as the final performer"
	},
	{
		"src": "Rahvas oli Garrixi esinemise ajal t\u00f5eliselt p\u00f6\u00f6rdes - lauldi, huilati, tantsiti ennastunustavalt.",
		"tgt": "The crowd went wild during Garrix\u2019s performance \u2013 they sang, rocked, danced with wild abandon."
	},
	{
		"src": "Kui Garrix l\u00f5petas, valguti \u00fchise massina P\u00e4rnu rannast linna peale laiali.",
		"tgt": "When Garrix finished, the crowd flowed from P\u00e4rnu beach into the streets of the city."
	},
	{
		"src": "Toome sinuni galerii, kus on koos k\u00f5ik pildid, mis meie fotograaf kolme p\u00e4eva jooksul Weekendil p\u00fc\u00fcdis.",
		"tgt": "We bring you a gallery with all of the pictures our photographer captured over three days at Weekend."
	},
	{
		"src": "Kindlasti oled ka sina m\u00f5nel neist, otsi end \u00fcles!",
		"tgt": "You\u2019re sure to be on some of them, look for yourself!"
	},
	{
		"src": "Mikey Garcia ja Vasyl Lomachenko kohtuvad esimest korda, arutavad v\u00f5imalikku vastasseisu",
		"tgt": "Mikey Garcia and Vasyl Lomachenko meet for the first time, discuss a possible showdown"
	},
	{
		"src": "Vasyl Lomachenko ja Mikey Garcia, kes peaksid olema kokkup\u00f5rkekursil, et minna vastamisi l\u00e4hituleviku k\u00f5ige k\u00f6itvamas poksimat\u0161is kuni 66,7 kg kaalukategoorias, kohtusid esimest korda neljap\u00e4eval.",
		"tgt": "Vasyl Lomachenko and Mikey Garcia, who should be on a collision course to stage the most compelling boxing match under 147 pounds in the near future, met each other for the first time Thursday."
	},
	{
		"src": "Nad olid ESPN-i kontoris Los Angeleses eraldi tubades, kuni Garcia, v\u00f5itmatu World Boxing Councili kergekaalut\u0161empion, jalutas koridori teise otsa, et tervitada Lomachenkot, World Boxing Organizationi sulgkaalut\u0161empionit.",
		"tgt": "They were in separate rooms at ESPN offices in Los Angeles until Garcia, the unbeaten World Boxing Council lightweight champion, walked down the hallway to greet Lomachenko, the World Boxing Organization super-featherweight champion."
	},
	{
		"src": "P\u00e4rast Garcia \u00fcksmeelse otsuse tulemusel saavutatud v\u00f5itu endise neljakordse maailmameistri Adrien Broneri \u00fcle laup\u00e4eval Showtime'is kuuluvad m\u00f5lemad v\u00f5itlejad kaaluedetabeli esiviisikusse.",
		"tgt": "After Garcia's victory by unanimous decision over former four-division world champion Adrien Broner on Saturday on Showtime, both fighters are members of the top-five pound-for-pound list."
	},
	{
		"src": "Garcia ulatas oma parema k\u00e4e ja \u00fctles: \"Kuidas sul l\u00e4heb, t\u0161empion?",
		"tgt": "Garcia extended his right hand and said, \"How you doing, champ?"
	},
	{
		"src": "Soovin sulle edu.\"",
		"tgt": "Best of luck to you.\""
	},
	{
		"src": "Lomachenko kaitseb oma v\u00f6\u00f6d Miguel Marriaga vastu laup\u00e4eva \u00f5htul kl 19 ESPN-is.",
		"tgt": "Lomachenko defends his belt against Miguel Marriaga on Saturday night at 7 on ESPN."
	},
	{
		"src": "Kui paar fotode jaoks poseeris, m\u00e4rkis Lomachenko m\u00e4ned\u017eer Egis Klimas, et v\u00f5imalik vastasseis v\u00f5itlejate vahel oleks \"t\u00e4iuslik m\u00f5\u00f5duv\u00f5tt\".",
		"tgt": "As the pair posed for photos, Lomachenko manager Egis Klimas noted that a potential showdown between the fighters would be \"perfect sizing.\""
	},
	{
		"src": "\"Olen endine sulgkaaluline,\" meenutas Garcia.",
		"tgt": "\"I'm a former featherweight,\" Garcia reminded."
	},
	{
		"src": "\"Liikusin Broneri jaoks \u00fcles [63,5 kg juurde], kuid ma ei ole nii suur.",
		"tgt": "\"I moved up for Broner [at 140 pounds], but I'm not that big."
	},
	{
		"src": "Ma olen 63,5 kg kohta v\u00e4ike.",
		"tgt": "I'm small for 140."
	},
	{
		"src": "Ma tahan liikuda allapoole kergekaalu.",
		"tgt": "I want to come down to lightweight."
	},
	{
		"src": "Ja tema peab liikuma \u00fclespoole kergekaalu [61,2 kg] ning seej\u00e4rel saame v\u00f5idelda.",
		"tgt": "And he's got to move up to lightweight [135 pounds] and then we have a fight."
	},
	{
		"src": "F\u00e4nnid on seda soovinud.",
		"tgt": "That's what the fans are asking for."
	},
	{
		"src": "Pakkugem neile siis seda.\"",
		"tgt": "Let's give them that.\""
	},
	{
		"src": "Lomachenko n\u00f5ustus.",
		"tgt": "Lomachenko agreed."
	},
	{
		"src": "\"Poksimaailm vajab seda v\u00f5itlust.\"",
		"tgt": "\"Boxing needs this fight.\""
	},
	{
		"src": "Klimas t\u00f5statas k\u00fcsimuse, kas selle vaatamine peaks olema tasuline. See on osa tema strateegiast, mille kohaselt ta tahab lasta Lomachenkol selle aasta l\u00f5pu poole deb\u00fc\u00fcteerida 61,2 kg klassis, et teha j\u00e4rgmiseks suveks v\u00f5imalikuks kohtumine Garciaga (37-0, 30 nokauti), kellel on \u00fchtlasi huvi v\u00f5idelda Jorge Linarese ja Luke Campbelli mat\u0161i v\u00f5itjaga p\u00e4rast nende 23. septembril toimuvat kergekaalu tiitliraundi Forumil.",
		"tgt": "Klimas asked if it should be on pay-per-view, part of a strategy he has to have Lomachenko fight a 135-pound debut bout later this year to set up a date next summer with Garcia (37-0, 30 knockouts), who also has interest in fighting the Jorge Linares-Luke Campbell winner following their Sept. 23 lightweight title bout at the Forum."
	},
	{
		"src": "\"Selle v\u00f5itluse vaatamine v\u00f5iks olla tasuline, kuna f\u00e4nnid on seda vastasseisu soovinud,\" s\u00f5nas Garcia, \u00f6eldes hiljem, et ta on avatud v\u00f5itlemisele \u00fcksk\u00f5ik millisel kanalil, mis pakub parimat rahalist paketti.",
		"tgt": "\"This fight could be on pay-per-view because all the fans have been asking about it,\" Garcia said, later expressing openness to fighting on whatever network offers the best financial package."
	},
	{
		"src": "\"Oleme p\u00f5hitegijad.",
		"tgt": "\"We're the main names."
	},
	{
		"src": "\u00dckski teine nimi ei suuda nii palju t\u00e4helepanu p\u00e4lvida.",
		"tgt": "No other names can generate that kind of attention."
	},
	{
		"src": "Millal iganes nad valmis on ... \"",
		"tgt": "Whenever they're ready ... .\""
	},
	{
		"src": "Garcia \u00fctles, et ta peab Lomachenkot \"v\u00e4gevaks v\u00f5itlejaks\" ja v\u00f5ib minna vaatama tema laup\u00e4evast mat\u0161i.",
		"tgt": "Garcia said he appreciates Lomachenko as \"a tremendous fighter,\" and may attend his Saturday bout."
	},
	{
		"src": "Lomachenko oli aga Garcia kiitmisel tagasihoidlik, \u00f6eldes, et tema meelest n\u00e4gi Riverside'ist p\u00e4rit kolme divisjoni meister v\u00e4lja \"v\u00e4ga aeglane; vabandust, Mikey... sa soovisid seda nokauti\".",
		"tgt": "But Lomachenko paused at lavish praise for Garcia, saying he thought the three-division champion from Riverside looked \"very slow, sorry Mikey ... you wanted the knockout.\""
	},
	{
		"src": "Garcia s\u00f5nul oli eesm\u00e4rk n\u00e4idata l\u00f6\u00f6gitugevust ja seej\u00e4rel poksida.",
		"tgt": "Garcia said the focus was to show punching strength, then box."
	},
	{
		"src": "M\u00f5lemad kinnitasid, et nad tunnevad, kuidas pinge nendevaheliseks j\u00f5ukatsumiseks kasvab.",
		"tgt": "They both said they can feel the momentum building for their own bout."
	},
	{
		"src": "\"See on v\u00f5itlus, mis ootab realiseerimist.",
		"tgt": "\"This is the fight to be made."
	},
	{
		"src": "\u00dckski teine vastasseis ei tekita nii palju t\u00e4helepanu ja suminat.",
		"tgt": "No other fight creates as much attention and buzz."
	},
	{
		"src": "Ma olen rohkem kui valmis selle nimel t\u00f6\u00f6d tegema,\" \u00fctles Garcia.",
		"tgt": "I'm more than happy to work at it,\" Garcia said."
	},
	{
		"src": "Lomachenko s\u00f5nas: \"Olen olnud parimate v\u00f5itlejate ootel ja Mikey on just seda.",
		"tgt": "Said Lomachenko: \"I've waited for the top fighters, and this is Mikey."
	},
	{
		"src": "Sellest tuleb hea v\u00f5itlus.\"",
		"tgt": "It will be a great fight.\""
	},
	{
		"src": "Millistest maailmanurkadest Eestisse kolitakse?",
		"tgt": "What corners of the world do people move to Estonia from?"
	},
	{
		"src": "Mullu pikendas ning v\u00e4ljastas politsei- ja piirivalveamet (PPA) rekordiliselt \u00fcle 13 000 elamisloa kolmandate riikide kodanikele, kes valdavalt on Eestisse reisinud t\u00f6\u00f6le, \u00f5ppima v\u00f5i pere juurde.",
		"tgt": "Last year, the Police and Border Guard Board (PPA) extended residence permits for a record more than 13,000 third-country nationals who have mainly travelled to Estonia to pursue work, studies or for family."
	},
	{
		"src": "Kui n\u00e4iteks mullu otsustati t\u00e4htajaline elamisluba v\u00e4ljastada 6702 v\u00e4lismaalasele, siis tunamullu oli see arv 4928.",
		"tgt": "For example, last year, it was decided to issue a temporary residence permit to 6,702 foreigners, but the year before last the number was 4,928."
	},
	{
		"src": "Ametkonnad ei oska \u00f6elda, kui palju sisser\u00e4ndajaid l\u00f5puks Eestisse p\u00fcsivalt j\u00e4\u00e4b, kuid sellist anal\u00fc\u00fcsi siseministeeriumis koostatakse.",
		"tgt": "Government offices can\u2019t say how many immigrants will end up staying in Estonia permanently, but the Ministry of the Interior is working on such an analysis."
	},
	{
		"src": "Kui k\u00fcmme aastat tagasi kolis Eestisse aastas ligi 500 ukrainlast, siis viimastel aastatel hakkab see arv 2000 l\u00e4hedale j\u00f5udma.",
		"tgt": "Whereas ten years ago, about 500 Ukrainians moved to Estonia, this number has been approaching 2,000 in recent years."
	},
	{
		"src": "Elamisloa taotlejate hulk suurenes h\u00fcppeliselt Ukraina kriisi ajal - 2014. aastal sai t\u00e4htajalise elamisloa 1087 inimest, aasta varem 675.",
		"tgt": "The number of residence permit applicants grew in leaps and bounds during the Ukrainian crisis \u2013 in 2014, 1,087 received a temporary residence permit, 675 in the year before that."
	},
	{
		"src": "Statistikaameti andmeil kasvabki Eestis k\u00f5ige rohkem Ukraina kodanike arv - mullu saabus Eestisse 850 Ukraina kodanikku enam kui lahkus.",
		"tgt": "According to Statistics Estonia, the number of Ukrainian citizens is growing the fastest in Estonia \u2013 last year, 850 more Ukrainian citizens arrived in Estonia than left."
	},
	{
		"src": "\"Ukraina kogukond on Eestis kogu aeg suur olnud ning keeruliste olude t\u00f5ttu riigis on loomulik, et t\u00f6\u00f6d ja \u00f5ppimise v\u00f5imalusi otsitakse riigist, kus kogukond ja paljudel ka pere juba ees\", nentis siseministeeriumi pressiesindaja Kristin Rammus.",
		"tgt": "\u201cThe Ukrainian community in Estonia has always been big and due to the complicated situation in the country, it\u2019s natural that people look for work and study possibilities in a country where there is a community and many have family members already ahead of them,\u201d said Ministry of the Interior press representative Kristin Rammus."
	},
	{
		"src": "Mullu ja tunamullu oli t\u00e4htajalise elamisloa saanud ukrainlaste hulk suurem isegi Venemaa kodanike arvust, ehkki k\u00fcmne aasta jooksul on kokku k\u00f5ige rohkem t\u00e4htajalisi elamislube v\u00e4ljastatud viimastele.",
		"tgt": "Last year and the year before last, the number of Ukrainians who have received a temporary residence permit was even greater than the number of Russian citizens, even though more the most temporary residence permits have been issued to the latter during the last ten years."
	},
	{
		"src": "Kui ukrainlased tulevad siia valdavalt t\u00f6\u00f6le, siis Venemaa kodanikud perer\u00e4nde p\u00e4rast.",
		"tgt": "While Ukrainians come here predominantly to work, Russian citizens come for family migration."
	},
	{
		"src": "\"Arvestades siinset ajaloolist vene kogukonda, on neil t\u00f5en\u00e4olisemalt ka k\u00f5ige suuremad perekondlikud sidemed Venemaal elavate inimestega\", \u00fctles Sisekaitseakadeemia r\u00e4ndeteadur Helina Maasing.",
		"tgt": "\u201cConsidering the historical Russian community here, this they have likely the closest family ties to people living in Russia,\u201d said Academy of Security Sciences migration researcher Helina Maasing."
	},
	{
		"src": "\"Kui vaadata, kuhu Eesti elamisloa saanud Venemaa kodanikud on elama siirdunud, siis Harjumaa j\u00e4rel on kohe Ida-Virumaa\", lisas ta ning t\u00f5i v\u00e4lja, et umbes 40 protsenti neist on abiellunud Euroopa Liidu kodanikuga.",
		"tgt": "\u201cIf we look at where Russian citizens who have received an Estonian residence permit have settled, Ida-Viru County comes right after Harju County,\u201d she added and noted that 40 per cent of them are married to EU citizens."
	},
	{
		"src": "Mullu sai t\u00e4htajalise elamisloa 1696 Venemaa kodanikku, mis on samuti rekordiline hulk.",
		"tgt": "Last year, 1,696 Russian citizens received a temporary residence permit, which is also a record number."
	},
	{
		"src": "Samal ajal elamisluba pikendada soovinud venelaste hulk hoopis v\u00e4henes.",
		"tgt": "The number of Russians who wished to extend residence permits decreased at the same time."
	},
	{
		"src": "\"H\u00fcpe on tingitud sellest, et elamisloa pikendamise asemel on taotletud uut elamisluba p\u00fcsivalt Eestisse asumiseks\", selgitas siseministeeriumi pressiesindaja Rammus, kelle s\u00f5nul on Vene kodanike huvi Eesti elamisloa vastu p\u00fcsinud aastaid pigem stabiilsena.",
		"tgt": "\u201cThe jump is because instead of extending residence permits, they have applied for a new residence permit for permanently settling in Estonia,\u201d said interior ministry press representative Rammus, who said interest among Russian citizens in the Estonian residence permit has tended to be stable for years."
	},
	{
		"src": "Uut elamisluba p\u00fcsivalt Eestisse asumiseks saavad siin v\u00e4hemalt kolm aastat elanud v\u00e4lismaalased taotleda eelmisest aastast.",
		"tgt": "As of last year, foreign nationals who have lived here at least three years can apply for a new residence permit for permanently settling in Estonia."
	},
	{
		"src": "Selle eesm\u00e4rk on soodustada kohanenud inimeste siiaj\u00e4\u00e4mist.",
		"tgt": "The aim is to encourage people who have adjusted to the local situation to stay here."
	},
	{
		"src": "Pikaajalise elaniku elamisluba eeldab aga n\u00e4iteks viit aastat.",
		"tgt": "The residence permit for long-term residents requires five years, for instance."
	},
	{
		"src": "Uue elamisloa p\u00e4rast on ilmselt v\u00e4henenud ka vana elamisloa pikendamine.",
		"tgt": "The new residence permit has probably resulted in decreased extensions of old residence permits."
	},
	{
		"src": "N\u00e4iteks mullu anti selline elamisluba 146 ukrainlasele, kes on siin v\u00e4hemalt kolm aastat t\u00f6\u00f6tanud.",
		"tgt": "For instance, last year such a residence permit was issued to 146 Ukrainians who had lived worked here for at least three years."
	},
	{
		"src": "N\u00fc\u00fcd saavad ukrainlased t\u00f6\u00f6d vahetada ja Eesti riik ei aja enam n\u00e4puga j\u00e4rge, kas palgakriteerium on t\u00e4idetud.",
		"tgt": "Now Ukrainians can change their employer and the Estonian state no longer keeps close tabs on whether the salary criterion is fulfilled."
	},
	{
		"src": "See elamisluba sai hoobilt populaarseks - taotlejateks mullu veel halli passi omanikud (1029), venelased (487), indialased (54) ja nigeerlased (36).",
		"tgt": "This residence permit became popular at one stroke \u2013 applicants last year also included grey passport holders (1,029), Russians (487), Indians (54) and Nigerians (36)."
	},
	{
		"src": "Kokku said Eestisse elama asumise eesm\u00e4rgil elamisloa 1968 inimest, nende seas veel n\u00e4iteks 23 ameeriklast, 12 egiptlast, 18 grusiini ja sama palju hiinlasi.",
		"tgt": "In total, 1,968 people received a residence permit for the purpose of settling in Estonia, also including 23 Americans, 12 Egyptians, 18 Georgians and just as many Chinese."
	},
	{
		"src": "T\u00e4navu esimese poolaastaga on selliste taotlejate koguhulk juba 1269.",
		"tgt": "In the first half-year of this year, the total number of such applicants has already reached 1,269."
	},
	{
		"src": "K\u00fcmne aastaga on \u00fcllatuslikult Nigeeriast saanud riik, mille kodanikud on \u00fched aktiivsemad Eesti elamisloa taotlejad.",
		"tgt": "In ten years, Nigeria has surprisingly become the country whose citizens are among the most active applicants for the Estonian residence permit."
	},
	{
		"src": "Kui 2007. aastal v\u00e4ljastati nigeerlastele kolm elamisluba, siis mullu 200.",
		"tgt": "Whereas in 2007, three residence permits were issued to Nigerians, last year the number was 200."
	},
	{
		"src": "Nigeeriast tullakse siinsetesse \u00fclikoolidesse \u00f5ppima.",
		"tgt": "People come from Nigeria to study at local universities."
	},
	{
		"src": "Veel on Eesti k\u00f5rgkoolid populaarsed n\u00e4iteks grusiinide, hiinlaste ja t\u00fcrklaste seas.",
		"tgt": "Estonian higher education institutions are also popular among Georgians, Chinese and Turks."
	},
	{
		"src": "India, Bangladeshi ja Nigeeria kodanike arv on t\u00f5usnud valdavalt t\u00e4nu \u00f5pper\u00e4ndele.",
		"tgt": "The number of citizens of India, Bangladesh and Nigeria has risen mainly due to study migration."
	},
	{
		"src": "Ka nende puhul kehtib reegel, et kus on kogukond ette tekkinud, sinna tuleb lihtsamalt teisi juurde\", lisas Rammus.",
		"tgt": "In their case as well, the rule is that where a community has taken shape ahead of them, others arrive more easily,\u201d added Rammus."
	},
	{
		"src": "K\u00fcmne aasta jooksul on kaks inimest Eestisse kolinud ka n\u00e4iteks P\u00f5hja-Koreast, sama palju Laosest ja Madagaskarilt.",
		"tgt": "In ten years, two people have also moved to Estonia from, North Korea, and just as many from Laos and Madagascar."
	},
	{
		"src": "K\u00fcmme inimest on siia tulnud Kuubalt, 231 L\u00f5una-Koreast, 40 Indoneesiast ja neli Uruguayst.",
		"tgt": "Ten people have come here from Cuba, 231 from South Korea, 40 from Indonesia and four from Uruguay."
	},
	{
		"src": "Kui aastas saab elamisloa umbes 6000 kolmanda riigi kodanikku, siis see on umbes 0,46 protsenti kogu rahvastikust.",
		"tgt": "In a given year, about 6,000 third-country citizens receive a residence permit, which is about 0.46 per cent of the population."
	},
	{
		"src": "Isegi kui arvata juurde Euroopa Liidu kodanikud, j\u00e4\u00e4b r\u00e4nne umbes protsendi juurde\", kommenteeris Maasing, et tegelikult on arvud v\u00e4ikesed.",
		"tgt": "Even if we include EU citizens in the total, migration will be around 1 per cent,\u201d said Maasing, noting that the numbers are actually small."
	},
	{
		"src": "Kokku r\u00e4ndas statistikaameti andmetel Eestisse mullu 14 822 inimest, siit v\u00e4lja aga 13 792.",
		"tgt": "In total, according to Statistics Estonia, 14,822 people immigrated to Estonia, and 13,792 emigrated."
	},
	{
		"src": "See t\u00e4hendab, et sisser\u00e4nne \u00fcletas teist aastat v\u00e4ljar\u00e4nnet.",
		"tgt": "That means that immigration outstripped emigration for a second year."
	},
	{
		"src": "Enamik v\u00e4lja- ja sissekolijatest on Eesti kodanikud, kuid rohkem on neid lahkujate seas.",
		"tgt": "Most immigrants and emigrants are Estonian citizens, but there are more of them among the ones leaving."
	},
	{
		"src": "Seet\u00f5ttu oli Eesti kodanike r\u00e4ndesaldo mullu 2000 inimesega miinuses.",
		"tgt": "For that reason, the migration balance for Estonian citizens was negative 2,000 last year."
	},
	{
		"src": "Eestlased r\u00e4ndavad eelk\u00f5ige Soome ja Eesti vahet.",
		"tgt": "Estonians migrate between Finland and Estonia the most."
	},
	{
		"src": "Mammu Couture'i printsessimood v\u00f5lub satside, tikandite ja t\u00fclliga",
		"tgt": "Mammu Couture princess fashion entices with frills, embroidery and tulle."
	},
	{
		"src": "P\u00f5hjatu ideedelaegas on Maria Tammeoru jaoks siiski ajalugu - vanad maalid ja kost\u00fc\u00fcmid: \"V\u00f5in tundide kaupa kusagil muuseumis unistada ja vanaaegseid varrukaid ja kraesid imetleda.",
		"tgt": "Nevertheless, history is a bottomless well of ideas for Maria Tammeoru \u2013 old paintings and costumes: \u201cI can sit in some museum for hours lost in reverie, just admiring old-fashioned sleeves and collars."
	},
	{
		"src": "Kui teed midagi kirega siis sa uurid ja \u00f5pid selle kohta juurde iga p\u00e4ev.",
		"tgt": "If you do something with passion, you study and learn from it every day."
	},
	{
		"src": "See on avastamisr\u00f5\u00f5m!",
		"tgt": "It\u2019s the joy of discovery!"
	},
	{
		"src": "Mammu Couture'i glamuurne maailm v\u00f5ib m\u00f5nele eluv\u00f5\u00f5ras n\u00e4ida, kuid disainer nii ei arva.",
		"tgt": "Mammu Couture\u2019s glamorous world may seem out of touch for some, but the designer doesn\u2019t think so."
	},
	{
		"src": "Sa ise otsustad, kui palju s\u00e4ra su elus on!",
		"tgt": "You yourself decide how much flair there is in your life!"
	},
	{
		"src": "Mul on s\u00f5branna, kel on terve saun t\u00e4is minu loodud haute couture'i kleite.",
		"tgt": "I have a girlfriend whose entire sauna is full of my haute couture dresses."
	},
	{
		"src": "Sest ega see tema s\u00fc\u00fc pole, et ta ei ela Hollywoodis ja ei k\u00e4i iga p\u00e4ev punasel vaibal, tema tahab ka neid k\u00f5ige ilusamaid kleite kanda ning kannabki!",
		"tgt": "It isn\u2019t her fault that she doesn\u2019t live in Hollywood and doesn\u2019t walk the red carpet every day; she wants to wear the prettiest dresses, and does wear them!"
	},
	{
		"src": "Sa saad ise elada oma elu eriliseks!",
		"tgt": "You can live your own life so it\u2019s special!"
	},
	{
		"src": "Moekunstnik ei tunnista l\u00f5het s\u00e4ravate s\u00fcndmuste ja halli argip\u00e4eva vahel.",
		"tgt": "The fashion artist doesn\u2019t acknowledge a rift between glamorous events and the grey everyday."
	},
	{
		"src": "Just see m\u00f5ttek\u00e4ik pani veerema plaani viia k\u00f5rgmood Eestis maakohtadesse, metsade ja p\u00f5ldude vahele, inimesteni, kelleni mood tihtipeale ei j\u00f5ua.",
		"tgt": "It was this idea that got the plan rolling to take haute couture to the countryside in Estonia, amidst fields and forests, people that fashion doesn\u2019t usually reach."
	},
	{
		"src": "Mammu kollektsiooni esitleti n\u00e4iteks V\u00f5rus, J\u00f5hvis ja P\u00e4rnu moealleel, kus 45 modelliga kuninglik defilee t\u00e4itis terve t\u00e4nava.",
		"tgt": "The Mammu collection was showcased in V\u00f5ru, in J\u00f5hvi and along the fashion street in P\u00e4rnu, where a regal column of 45 models filled the entire street."
	},
	{
		"src": "Tallinnas v\u00f5etakse sageli poos sisse, noogutatakse v\u00e4\u00e4rikalt, aga mujal on emotsioone rohkem - h\u00fc\u00fcavad braavo, t\u00f5usevad p\u00fcsti, tahavad sind k\u00e4ttpidi t\u00e4nada.",
		"tgt": "In Tallinn, often people strike a pose, give a distinguished nod, but elsewhere there\u2019s more emotions \u2013 cries of bravo!, standing ovations, people wanting to thank you physically."
	},
	{
		"src": "Suur osa publikust tuli niisama uudistama, aga n\u00fc\u00fcd on nad Mammu Couture'i f\u00e4nnid.",
		"tgt": "A large part of the audience just came out of curiosity, but they\u2019re now fans of Mammu Couture."
	},
	{
		"src": "Kui sa \u00fcletad inimeste ootused, on nad vaimustatud!",
		"tgt": "If you exceed people\u2019s expectations, they\u2019re thrilled!"
	},
	{
		"src": "Ja mulle meeldib see tunne, et olen oma moeloominguga justkui suvetuuril.",
		"tgt": "And I like the feeling that I\u2019m on a summer tour with my fashion creations."
	},
	{
		"src": "P\u00e4rnus oli meil 50 meetri pikkune punane vaip, terve t\u00e4nav kauneid kleite t\u00e4is, tundus, et neil ei tulegi l\u00f5ppu!",
		"tgt": "We had a 50-metre long red carpet in P\u00e4rnu, a whole street of beautiful dresses, it seemed they would never end!"
	},
	{
		"src": "Maria ei tunnista ka moetava, et loomingut peab esitlema supersale supermodell, tema toob meelsasti lavale tavalised naised.",
		"tgt": "Maria doesn\u2019t also accept the fashion custom that fashion designs have to be presented by a twiggy supermodel; she is happy to bring ordinary women on to the catwalk."
	},
	{
		"src": "Tihti kutsun lavale omaenda kliendid - nad on alati r\u00f5\u00f5muga tulnud.",
		"tgt": "I often invite my own clients to take the stage \u2013 they\u2019ve always accepted the offer gladly."
	},
	{
		"src": "See on ju nii kihvt kogemus, saad s\u00e4rada laval imeilusas kleidis!",
		"tgt": "It\u2019s such a cool experience, you can shine on stage in an incredibly beautiful dress!"
	},
	{
		"src": "Mul on nii kahju, et ma ise ei ole mitte kunagi oma etendust n\u00e4inud, alati olen ju lava taga, et anda lootusetu perfektsionistina asjadele viimane lihv.",
		"tgt": "I feel so sorry that I haven\u2019t ever seen my own shows, I\u2019m always behind the stage, perfectionistically giving things a final polish."
	},
	{
		"src": "Mu n\u00e4rv ei lubaks rahulikult saalist pealt vaadata.",
		"tgt": "I wouldn\u2019t have the nerve to just watch calmly from the audience."
	},
	{
		"src": "Maria ongi seda sorti moelooja, kes ei taha \u00fcksnes esindusrolli t\u00e4ita, vaid k\u00f5iges k\u00e4ttpidi sees olla.",
		"tgt": "Maria is the kind of fashion designer who doesn\u2019t want to solely fill a representative role \u2013 she wants to have her fingers in everything."
	},
	{
		"src": "Mul on stuudios oma \u00f5mblusmasin, enamiku kollektsioonist teostan ise.",
		"tgt": "I have a sewing machine in my studio, I execute most of the collection myself."
	},
	{
		"src": "Mulle meeldib kogu protsess, kus sa m\u00e4ngid detailidega, avastad.",
		"tgt": "I like the whole process, where you\u2019re playing with the details, making discoveries."
	},
	{
		"src": "Ma pole oma loomingust kunagi kaugel ja t\u00f6\u00f6d ma ei karda.",
		"tgt": "I\u2019m never far from my work and I\u2019m not afraid of work."
	},
	{
		"src": "Disainiga asi ei piirdu, ka stilistika, logistika, korraldamine, organiseerimine - k\u00f5ik peab \u00fche temperamentse naise p\u00e4eva \u00e4ra mahtuma.",
		"tgt": "It isn\u2019t restricted to design, stylistics, logistics, managing, organizing \u2013 a temperamental woman\u2019s day has to have room for all of it."
	},
	{
		"src": "Eks neid t\u00f6\u00f6tunde tuleb fanaatikutel ikka tohutult.",
		"tgt": "Fanatics do rack up an incredible amount of work hours."
	},
	{
		"src": "Ma ei oskagi \u00f6elda, millal mu t\u00f6\u00f6p\u00e4ev l\u00f5peb, minu jaoks on see lihtsalt p\u00e4ev t\u00e4is r\u00f5\u00f5mu!",
		"tgt": "I can\u2019t even say when my workday ends, for me it\u2019s just a day full of fun!"
	},
	{
		"src": "Mul on ikka v\u00e4ga vedanud - see on nagu lakkamatu \u00f5nneahel: mina teen midagi ilusat, inimene saab midagi ilusat ja veel omakorda komplimente.",
		"tgt": "I\u2019ve been very fortunate \u2013 it\u2019s like a unbroken circle of happiness: I make something beautiful, people get something beautiful, and then compliments on top of that."
	},
	{
		"src": "Mitu korda on \u00f6eldud, et mu kleitides on maagia - need panevad end printsessina tundma.",
		"tgt": "It\u2019s been said a number of times that there\u2019s magic in my dresses \u2013 they make me feel like a princess."
	},
	{
		"src": "K\u00fclluslikud t\u00fcllist satsiread, mis Maria talendi \u00fcle\u00f6\u00f6 kuulsaks tegid, on Mammu Couture signatuuriks j\u00e4\u00e4nud t\u00e4naseni.",
		"tgt": "The lavish tulle frills that made Maria\u2019s talent an overnight sensation, have remained the signature of Mammu Couture right up to the present."
	},
	{
		"src": "Martin M\u00fc\u00fcrsepp U18 poistest: eestlaste alagrupiturniiri relv p\u00f6\u00f6rati n\u00fc\u00fcd meie vastu",
		"tgt": "Martin M\u00fc\u00fcrsepp on U18 boys: the Estonian tournament\u2019s weapon now was turned against us"
	},
	{
		"src": "Kahju, muinasjutt sai otsa.",
		"tgt": "Too bad, the fairy-tale ended."
	},
	{
		"src": "Esimese asjana j\u00e4i silma, et me ei saanud oma lauda k\u00e4tte.",
		"tgt": "The first thing I noticed is that we didn\u2019t get rebounds."
	},
	{
		"src": "Ja kui lauas tuleb nii suur vahe sisse, pole midagi teha\", kommenteeris Eesti U18 korvpallipoiste 61:75 allaj\u00e4\u00e4mist Suurbritanniale meie ainus NBAs m\u00e4nginud korvpallur, BC Kalev/Cramo abitreener Martin M\u00fc\u00fcrsepp.",
		"tgt": "And when there\u2019s such a big difference in rebounding, there\u2019s nothing to be done,\u201d commented BC Kalev/Cramo assistant coach Martin M\u00fc\u00fcrsepp, the only Estonian to have played in the NBA, in commenting on the Estonian U18 boys\u2019 team\u2019s 75-61 loss to Great Britain."
	},
	{
		"src": "Vastased v\u00f5tsid r\u00fcndelauast 28 palli ja said selle t\u00f5ttu nii palju rohkem r\u00fcnnakuid.",
		"tgt": "The opponents grabbed 28 offensive rebounds and got more scoring chances because of that."
	},
	{
		"src": "Me polnud ka valmis nende agressiivseks kaitseks ega r\u00fcnnakuks, see l\u00f5i .",
		"tgt": "We weren\u2019t ready for their aggressive defence or offence."
	},
	{
		"src": "Paljud inglaste r\u00fcnnakud l\u00f5ppesid kolme kuni viie sekundiga, me ei suutnud kaitset \u00fcles ehitada.",
		"tgt": "Many of the English attacks ended in three to five seconds, we couldn\u2019t set up the defence."
	},
	{
		"src": "Kaitses j\u00f5udsid nad aga igal pool k\u00e4si vahel hoida, me ei saanud kombineerida.",
		"tgt": "They were able to get a hand in the way everywhere while on defence, and our playmaking was hampered."
	},
	{
		"src": "See l\u00f5i meeskonnal jalad alt.",
		"tgt": "That knocked us off our feet."
	},
	{
		"src": "Vastaste kodut\u00f6\u00f6 oli paremini tehtud.",
		"tgt": "Our opponents had done their homework better."
	},
	{
		"src": "M\u00fc\u00fcrsepa hinnangul pidanuks Eesti tegema rohkem taktikalisi vigu, et vastaste hoog eos maha v\u00f5tta.",
		"tgt": "M\u00fc\u00fcrsepp said Estonia should have committed more fouls to nip the opponents\u2019 momentum in the bud."
	},
	{
		"src": "Viimaselgi veerandil - meil oli null viga, kuid vastased juba mitu kiiret korvi saanud.",
		"tgt": "In the last quarter as well, we had zero fouls but the opponents had already scored a number of quick baskets."
	},
	{
		"src": "Atleetlikkus ja tihe pealek\u00e4imine, mis oli alagrupiturniiril meie relv, p\u00f6\u00f6rdus n\u00fc\u00fcd k\u00f5ik meie vastu.",
		"tgt": "Athleticism and hustle, which were our weapon in the tournament, now was turned against us."
	},
	{
		"src": "T\u00e4na polnud meil nende agressiivsuse vastu j\u00f5udu.",
		"tgt": "Today we were powerless against their aggressive play."
	},
	{
		"src": "M\u00fc\u00fcrsepp j\u00e4i oma hoolealusega Kalevis, Matthias Tassiga rahule.",
		"tgt": "M\u00fc\u00fcrsepp said he was satisfied with his charge on the Kalev squad, Matthias Tass."
	},
	{
		"src": "Turniiril \u00fcldiselt saab terve meeskonna kohta \u00f6elda h\u00e4id s\u00f5nu, t\u00e4naseni oldi \u00fchtne l\u00f6\u00f6girusikas.",
		"tgt": "At the tournament, generally good words can be said about the whole team, to this point we were a united strike force."
	},
	{
		"src": "Kahju, et n\u00f5nda agressiivse vastasega poldud juba varem kohtutud.",
		"tgt": "It\u2019s too bad that we hadn\u2019t met such aggressive opponents before"
	},
	{
		"src": "Tass on kogu aeg olnud enesekindel ja m\u00e4ngis t\u00e4nagi oma v\u00e4lja, kuid tundus, et ta oli v\u00e4sinud - ta on kandnud p\u00e4ris suurt koormat.",
		"tgt": "Tass has been self-confident the whole time and he had a strong outing today as well, but it seemed he was tired \u2013 he had been carrying a pretty heavy burden."
	},
	{
		"src": "Aga ta tegi m\u00f5ne t\u00e4itsa ilusa liigutuse, mida varem trennides n\u00e4inud olen\", lisas juhendaja.",
		"tgt": "But he made a couple nice moves that I\u2019ve seen before in practices,\u201d added the coach."
	},
	{
		"src": "Kohutavad numbrid: neidude korvpallikoondis viskas EM-turniiril kolme veerandiga v\u00e4hem kui 10 punkti...",
		"tgt": "Awful numbers: girls\u2019 basketball team held to under 10 points in three quarters at European championship tournament\u2026"
	},
	{
		"src": "U18 vanuseklassis ei k\u00e4i ainult noormeeste EMi B-divisjoni korvpalliturniir Tallinnas, neiud alustasid \u00fcleeile Dublinis.",
		"tgt": "Not only the young men\u2019s European championship division B basketball tournament is underway in U18 age class in Tallinn; the young women started yesterday in Dublin."
	},
	{
		"src": "Ning Eesti m\u00e4ng Poolaga kippus paraku k\u00fcll antirekordite valdkonda.",
		"tgt": "And Estonia\u2019s game with Poland tended unfortunately to be in the anti-record category."
	},
	{
		"src": "Eesti kaotas 25:65, kuid veel p\u00e4rast kolmandat veerandaega oli seis 9:49 ehk alles viimasel k\u00fcmnel minutil v\u00f5tsid vastased jala gaasipedaalilt ning too periood j\u00e4i viiki 16:16.",
		"tgt": "Estonia lost 65-25, but the score after three quarters was 49-9, meaning that only in the last ten minutes did the opponents take their foot off the gas and scoring in that period was even, 16-16."
	},
	{
		"src": "Nii esimesel kui ka teisel veerandil viskas Eesti 4, kolmandal 1 punkti...",
		"tgt": "Estonia scored 4 points in the first and second quarter and 1 point in the third\u2026"
	},
	{
		"src": "Seejuures tabasid eestlannad alguses kahe minutiga neljast esimesest viskest kaks t\u00fckki, edasi aga m\u00e4ngust 25 t\u00fckki m\u00f6\u00f6da, siis \u00fcks kolmene sisse ning seej\u00e4rel veel 21 viset m\u00f6\u00f6da...",
		"tgt": "The Estonians made two of the first four field goal attempts in two minutes, from there on, they missed 25 in a row, then a three-pointer went in, and then another 21 missed attempts\u2026"
	},
	{
		"src": "Ehk peaaegu poole tunni jooksul tabati 47 viskest \u00fcks.",
		"tgt": "In other words, they made one out of 47 shot attempts in nearly half an hour."
	},
	{
		"src": "Lisaks tuli 2 punkti neljast vabaviskest.",
		"tgt": "In addition, 2 points came from four free throws."
	},
	{
		"src": "Pallikaotusi oli selle ajaga m\u00f5istlik arv, 12.",
		"tgt": "The number of turnovers during that time was normal, 12."
	},
	{
		"src": "M\u00e4ngu l\u00f5puks oli Poola visketabavus 33 ja Eestil 13 protsenti (68/9).",
		"tgt": "By the end of the game, Poland was shooting 33% from the field; and Estonia, 13% (9 out of 68)."
	},
	{
		"src": "Eesti on alustanud kahe kaotusega, avap\u00e4eval tuli tunnistada Portugali 83:56 paremust.",
		"tgt": "Estonia started the tournament with two losses, having to concede to Portugal, 83-56, on the opening day."
	},
	{
		"src": "NATO laevad tulid Tallinnasse varusid t\u00e4iendama",
		"tgt": "NATO ships come to Tallinn to replenish stores"
	},
	{
		"src": "T\u00e4na saabus NATO 1. alaline miinit\u00f5rjegrupp n\u00e4dalavahetuseks Tallinnasse plaanilisele sadamavisiidile, et t\u00e4iendada laevade varusid ning valmistuda eelolevateks harjutusteks.",
		"tgt": "Today, NATO Standing Mine Countermeasures Group 1 arrived in Tallinn for a weekend port call to replenish ships\u2019 stores and prepare for an upcoming exercise."
	},
	{
		"src": "K\u00fclastuse k\u00e4igus laevad teevad ettevalmistusi merele naasimiseks ning annavad sealjuures meeskonnaliikmetele v\u00f5imaluse paarip\u00e4evaseks puhkuseks.",
		"tgt": "In the course of the visit, the ships will prepare for returning to sea and will give the crew members a chance for a couple days of shore leave."
	},
	{
		"src": "P\u00e4rast visiiti j\u00e4\u00e4vad NATO laevad Eesti vetesse, et viia l\u00e4bi mitmeid harjutusi ja olla valmis tulevasteks ajalooliste l\u00f5hkekehade otsimise operatsioonideks.",
		"tgt": "After the visit, NATO ships will remain in Estonian waters to carry out a number of exercises and to be prepared for future operations to search for historical ordnance."
	},
	{
		"src": "\"Eestlaste osalus NATO \u00fcksuses ja nende poolt l\u00e4biviidav koostegevus\u00f5pe kohalikes vetes ilmestab h\u00e4sti meie integreeritust liitlasj\u00f5ududega\", \u00fctles merev\u00e4e laevastiku \u00fclema \u00fclesannetes olev operatsiooni- ja planeerimisjaoskonna \u00fclem kaptenmajor Arto Reinmaa.",
		"tgt": "\u201cEstonians\u2019 participation in the NATO unit and the interoperability exercise in local waters typifies our integrated allied forces,\u201d said Capt. Maj. Arto Reinmaa, the operations and planning division commander in the capacity of commander of the naval fleet."
	},
	{
		"src": "Alates 29. juunist juhib NATO 1. alalist miinit\u00f5rjegruppi L\u00e4ti merev\u00e4elane kaptenleitnant Gvido Laudups, kes v\u00f5ttis Riias peetud tseremoonial grupi\u00fclema \u00fclesanded \u00fcle Eesti merev\u00e4eohvitserilt kaptenleitnant Johan-Elias Seljamaalt.",
		"tgt": "Starting 29 June, NATO Standing Mine Countermeasures Group 1 is headed by Latvian naval Capt. Lt. Gvido Laudups, who took over the functions of group commander from Estonian naval officer Capt. Lt. Johan Elias Seljamaa at a ceremony held in Riga."
	},
	{
		"src": "Grupi lipulaevaks on m\u00e4\u00e4ratud L\u00e4ti merev\u00e4e toetuslaev LVNS Virsaitis, millel tegutseb ka grupi juhtstaap.",
		"tgt": "The Latvian naval auxiliary LVNS Virsaitis has been made the flagship of the group, and the group\u2019s command staff also is based on board."
	},
	{
		"src": "Sel poolaastal kuulub rahvusvahelise \u00fcksuse koosseisu ka Eesti merev\u00e4e miinijahtija Sakala.",
		"tgt": "This half-year, the Estonian minesweeper Sakala is also part of the international unit."
	},
	{
		"src": "\u00dchena neljast NATO merelise v\u00e4ejuhatuse alluvuses olevast laevade grupist on NATO 1. alaline miinit\u00f5rjegrupp esmaste kiirreageerijate hulka kuuluv valmidus\u00fcksus, keda allianss v\u00f5ib viie p\u00e4eva jooksul saata erinevatesse maailma paikadesse.",
		"tgt": "As one of four groups of ships subordinate to the NATO naval command, Standing Mine Countermeasures Group 1 is a response unit that is among the primary rapid responders, which the alliance can deploy in various places around the world in five days."
	},
	{
		"src": "4. - 13. augustini muutuvad Pirita kloostri muistsed varemed taaskord paigaks, kus peetakse maha 13 aastat tagasi maestro Eri Klasi poolt ellu kutsutud Birgitta Festival.",
		"tgt": "From 4-13 August, the ancient ruins of Pirita Convent again turn into the venue for the Birgitta Festival started 13 years ago by maestro Eri Klas."
	},
	{
		"src": "T\u00e4navune Birgitta Festival saab Tallinna Filharmoonia kunstilise juhi Risto Joosti (36) s\u00f5nul olema kaunis, v\u00f5imas ja enneolematu.",
		"tgt": "This year\u2019s Birgitta Festival will be beautiful, powerful and unprecedented, according to the artistic director of Tallinn Philharmonic Risto Joost, 36."
	},
	{
		"src": "Risto Joost: Kuulajateni j\u00f5uavad ooperimaailma klassikasse kuuluvad \"Traviata\" ja \"Tosca\", balletilavastused lummavast \"Bolerost\" l\u00f5busa \"Karlssonini\" ning samuti ei puudu kavast omaproduktsioon, milleks on sel korral Joseph Haydni imelise oratooriumi \"Aastaajad\" lavastus sama rahvusvahelise loovmeeskonna poolt, kes 2015. aastal t\u00f5id Pirital lavale Haydni teisegi meistriteose \"Loomine\".",
		"tgt": "Risto Joost: Listeners will hear opera classics La Traviata and Tosca, see ballet performances from Bolero to \u201cKarlsson\u201d and there\u2019s even an in-production in the programme, which this time will be a performance of Joseph Haydn\u2019s wonderful oratorio The Seasons by the same international creative team that brought another Haydn masterpiece to the stage at Pirita in 2015, The Creation."
	},
	{
		"src": "Birgitta Festival on palju enamat, kui lihtsalt kontserdid ja teatrilavastused.",
		"tgt": "There is much more at Birgitta Festival than just concerts and theatre performances."
	},
	{
		"src": "See on suurem kui mistahes muusikateater oma tavap\u00e4rases vormis.",
		"tgt": "It is bigger than any other musical theatre in its conventional form."
	},
	{
		"src": "See on festival, mille lummus v\u00f5tab v\u00f5imust ja ei lasegi kunagi enam p\u00e4ris lahti.",
		"tgt": "It\u2019s a festival whose magic gets a hold on you and doesn\u2019t quite ever let go."
	},
	{
		"src": "Sest kogemus, mille kuulaja saab selles \u00fclevas ja salap\u00e4rases keskkonnas, paneb inimhinged helisema ning puudutab inimtajusid moel, mida kirjeldada pole v\u00f5imalik.",
		"tgt": "Because the experience that listeners get in this sublime and mysterious environment makes human spirits resonate and touches human senses in a way that can\u2019t be described."
	},
	{
		"src": "Risto, oled esimest aastat Birgitta Festivali kunstiline juht.",
		"tgt": "Risto, it is your first year as artistic director of the Birgitta Festival."
	},
	{
		"src": "Kas maestro Eri Klasi kingad pisut suurtena ei tundunud?",
		"tgt": "Don\u2019t maestro Eri Klas\u2019s shoes seem a bit big for you?"
	},
	{
		"src": "Loomulikult, aga kuna mul oli Eri Klasiga v\u00e4ga isiklik suhe, siis on sellest palju abi olnud.",
		"tgt": "Naturally but since I had a very personal relationship with Eri Klas, that has helped me greatly."
	},
	{
		"src": "Ta suunas mind l\u00e4bi terve minu \u00f5pilaskarj\u00e4\u00e4ri ja toetas ka dirigeerimiskarj\u00e4\u00e4ri alguses.",
		"tgt": "He guided me throughout my time as a student and also supported ma at the start of my conducting career."
	},
	{
		"src": "V\u00f5ib-olla just t\u00e4nu sellele on mul lihtsam tema t\u00f6\u00f6d j\u00e4tkata.",
		"tgt": "Maybe thanks to this it is easier for me to continue his work."
	},
	{
		"src": "Eri Klas on s\u00fcstinud Birgitta Festivali meeskonda nii palju headust ja loomulikult kandub see k\u00f5ik ka mulle \u00fcle.",
		"tgt": "Eri Klas has injected so much goodness into the Birgitta Festival team and naturally it all spreads to me as well."
	},
	{
		"src": "Suurep\u00e4rane oli liituda meeskonnaga, kes teab kuidas asjad t\u00e4pselt k\u00e4ivad.",
		"tgt": "It was great to join a team who knows exactly how things work."
	},
	{
		"src": "Just Eri Klasi suur s\u00fcda andis ka mulle j\u00f5udu Tallinna Filharmoonias Birgitta Festivaliga j\u00f5udsalt edasi minna.",
		"tgt": "It was Eri Klas\u2019s big heart that gave me energy to go ahead with Birgitta Festival in the Tallinn Philharmonic."
	},
	{
		"src": "Ja siin ma n\u00fc\u00fcd olen ja ma saan hakkama!",
		"tgt": "And here I am now, and I\u2019ll manage!"
	},
	{
		"src": "Mis v\u00f5iks publikut t\u00e4navusel festivalil erutada, mida erilist pakute?",
		"tgt": "What might excite the public at this year\u2019s festival, anything special being offered?"
	},
	{
		"src": "Meil on artiste Inglismaalt, L\u00e4tist, Leedust ja \u00fcllatusena tuleb esitlusele muuseas esimene ballett, mis kirjutatud Astrid Lindgreni jutustusele.",
		"tgt": "We have artists from England, Latvia, Lithuania and as a surprise the first ballet based on an Astrid Lindgren story will be performed."
	},
	{
		"src": "Selleks on \"Karlsson lendab\".",
		"tgt": "It\u2019s \u201cKarlsson Flies\u201d."
	},
	{
		"src": "Ja \u00fcks kurioosne n\u00fcanss selle juures on, et selle balleti autor on L\u00e4ti helilooja Juris Karlsons, kes ise avaldas soovi selle teose kirjutada.",
		"tgt": "And a curious twist is that the ballet is by Latvian composer Juris Karlsons and it was his idea to write it."
	},
	{
		"src": "Ilmselt on tal juba lapsest saati hinges elanud Karlssoni karakter.",
		"tgt": "The Karlsson-on-the-Roof character had been dwelling in his soul since he was a child, it appears."
	},
	{
		"src": "Risto, kuidas sa seda k\u00f5ike jaksad?",
		"tgt": "Risto, how do you find the energy for everything?"
	},
	{
		"src": "T\u00e4nu minu toetavale elukaaslasele kindlasti.",
		"tgt": "Thanks to my supportive partner, certainly."
	},
	{
		"src": "Selline t\u00f6\u00f6 vajab tugis\u00fcsteemi ja palju armastust ning seda on mul \u00f5nneks kuhjaga.",
		"tgt": "This kind of work needs a support system and much love and fortunately I have that in spades."
	},
	{
		"src": "Ja olen m\u00e4rganud, et minu isiklikud emotsioonid ei s\u00f5ltugi niipalju teistest inimestest, kuiv\u00f5rd minust endast ehk siis kuidas ma igale uuele p\u00e4evale vastu l\u00e4hen.",
		"tgt": "And I\u2019ve noticed that my personal emotions don\u2019t depend so much on other people, as on my own self \u2013 on how I set out to face each new day."
	},
	{
		"src": "Ja selline teadlik toonuse hoidmine, positiivsuse hoidmine ja tegelikult naeratamine iseendale hommikuti peeglisse, t\u00f5stis oluliselt minu \u00f5nneprotsenti.",
		"tgt": "And this sort of consciously maintaining one\u2019s tone, staying positive and actually smiling at yourself in the mirror in the morning significantly increased my happiness quotient."
	},
	{
		"src": "Eriti n\u00fc\u00fcd sel n\u00e4dalal, kui on k\u00f5ige olulisemad proovid, olen seda eriti agaralt praktiseerinud ja see toimib.",
		"tgt": "Especially this week, with the most important rehearsals, I have been avidly practising it and works."
	},
	{
		"src": "Endale naeratamine aktiviseerib aju ja t\u00f5stab toonust.",
		"tgt": "Smiling at yourself stimulates the brain and improves tone."
	},
	{
		"src": "See pole lihtsalt s\u00f5nak\u00f5lks.",
		"tgt": "It isn\u2019t just empty words."
	},
	{
		"src": "Arvan, et inimesed ei tea veel pooligi asju oma kehast, mida universum neile pakub, aga eks iga\u00fcks ise avastab seda tasapisi.",
		"tgt": "I think that people don\u2019t know half of the things about their body that the universe offers them, but I suppose everyone has to discover it little by little."
	},
	{
		"src": "Kohe, kohe on t\u00e4htis hetk k\u00e4es.",
		"tgt": "The big moment is about to come."
	},
	{
		"src": "On sul ka mingi rituaal enne dirigendi pulti astumist?",
		"tgt": "Do you have any ritual before the ascend the conductor\u2019s podium?"
	},
	{
		"src": "On ikka, riided tuleb \u00e4ra vahetada mugavamate vastu.",
		"tgt": "Sure \u2013 you have to change into more comfortable clothing."
	},
	{
		"src": "See on see v\u00e4ike hetk iseendale.",
		"tgt": "It\u2019s a little moment for myself."
	},
	{
		"src": "Aga \u00fcldiselt jah, mul pole v\u00f5imalust enne suurt esinemist puhata v\u00f5i v\u00e4ikest uinakut teha.",
		"tgt": "But in general, I don\u2019t have a chance to rest up or take a short nap before a big performance."
	},
	{
		"src": "Tegelikult mulle isegi meeldib inimestega aktiivselt suhelda, isegi enne dirigendipulti astumist.",
		"tgt": "Actually I like interacting actively with people, even before ascending the podium."
	},
	{
		"src": "Aga tulge k\u00f5ik Birgitta Festivalile, siin on mida avastada ka mitte eriti suurele ooperi ja balleti s\u00f5brale!",
		"tgt": "But everybody come out to the Birgitta Festival, there\u2019s plenty to discover here even for people who aren\u2019t big opera and ballet fans!"
	},
	{
		"src": "Vaata meeleolukat videot Risto Joostiga!",
		"tgt": "Watch the enjoyable video with Risto Joost!"
	},
	{
		"src": "Avaldati Rootsi as\u00fc\u00fclitaotlejate vanuse hindamise testide uued tulemused",
		"tgt": "New results of Sweden's asylum age assessment tests released"
	},
	{
		"src": "Rootsis tehti as\u00fc\u00fclitaotlejate seas test, mille k\u00e4igus hinnati nende vanust uudse l\u00e4henemisega meditsiiniliselt. Testi v\u00e4rskeimad tulemused n\u00e4itavad, et rohkem kui 80 protsenti testitutest hinnati vanemaks kui 18, aga sugugi mitte k\u00f5ik ei usu tulemuste t\u00e4psusesse.",
		"tgt": "The latest results of tests on asylum seekers in Sweden subjected to a new method of medically assessing their age show that over 80 percent tested were judged to be older than 18, but not everyone has faith in their accuracy."
	},
	{
		"src": "Rootsi riiklik kohtumeditsiini instituut (R\u00e4ttsmedicinalverket) alustas testidega selle aasta alguse poole.",
		"tgt": "Sweden's national Forensic Medicine Agency (R\u00e4ttsmedicinalverket) started carrying out the tests earlier year."
	},
	{
		"src": "Testid loodi vanuse t\u00e4psemaks hindamiseks as\u00fc\u00fcli taotlemise k\u00e4igus p\u00e4rast seda, kui Rootsi Migratsiooniametit (Migrationsverket) kritiseeriti selle eest, et neil ei ole \u00f5nnestunud mitmete v\u00e4idetavalt alaealiste pagulaste vanust \u00f5igesti m\u00e4\u00e4rata.",
		"tgt": "They are designed to make age assessment during the asylum process more accurate after the Swedish Migration Agency (Migrationsverket) was criticized for failings in assessing the correct age of some refugees claiming to be underage."
	},
	{
		"src": "Praeguseks on Migrationsverket saatnud testimisele 6880 juhtumit ja Kohtumeditsiini Instituut on vahemikus 2017. aasta m\u00e4rtsi keskpaigast kuni 31. juulini v\u00e4ljastanud kokku 2481 testi tulemused.",
		"tgt": "To date Migrationsverket has sent 6,880 cases to be tested, and the Forensic Medicine Agency has now released the results of a total of 2,481 tests from the period between mid March until July 31st, 2017."
	},
	{
		"src": "Kaheksak\u00fcmmend protsenti (2002) hinnati 18-aastaseks v\u00f5i vanemaks ja veel 25 juhtumi puhul hindas Kohtumeditsiini Instituut, et testitav \"v\u00f5ib olla 18-aastane v\u00f5i vanem\".",
		"tgt": "Eighty percent (2002) were judged to be 18 or over, while in a further 25 cases the Forensic Medicine Agency judged that the subject was \"possibly 18 or over.\""
	},
	{
		"src": "432 juhtumi puhul j\u00f5uti j\u00e4reldusele, et inimene on \"arvatavasti noorem kui 18\".",
		"tgt": "In 432 cases the conclusion was that the person is \"possibly under 18.\""
	},
	{
		"src": "Teste kasutatakse ainult juhul, kui inimese vanus on k\u00fcsim\u00e4rgi all.",
		"tgt": "The tests are only carried out in cases where the person's age is in question."
	},
	{
		"src": "Kohtumeditsiini Instituudis t\u00f6\u00f6tava Johan G\u00f6ranssoni s\u00f5nul on tulemused eelnevate kuude omadega v\u00f5rreldes j\u00e4rjepidevad.",
		"tgt": "According to Johan G\u00f6ransson from the Forensic Medicine Agency, the results are consistent with previous months."
	},
	{
		"src": "\"Me ei n\u00e4e eelmiste kuude statistikaga v\u00f5rreldes suurt erinevust, numbrid on \u00fcsna j\u00e4rjepidevad,\" \u00fctles ta ajalehele The Local.",
		"tgt": "\"We see no big difference in the statistics from previous months, the numbers are quite consistent,\" he told The Local."
	},
	{
		"src": "See, et suur osa juhtumitest hinnati vanemaks kui 18, ei t\u00e4henda ilmtingimata, et as\u00fc\u00fclitaotlejad on oma vanuse kohta valetanud.",
		"tgt": "The high proportion of cases judged to be over 18 does not necessarily mean that the asylum seeker lied about their age."
	},
	{
		"src": "Instituut v\u00e4ljastas mais 581 testi tulemused ja \u00fctles, et 442 juhul \"on viiteid sellele, et uuritav inimene on 18-aastane v\u00f5i vanem\".",
		"tgt": "In May, the agency released the results of 581 tests and said that there were 442 instances that \"suggest the person examined is 18 years or older.\""
	},
	{
		"src": "Aga kui ajaleht Svenska Dagbladet uuris nende 581 testi tulemusi, selgus, et 243 juhul oli inimene otse v\u00e4itnud, et saab sel aastal 18.",
		"tgt": "When newspaper Svenska Dagbladet investigated the 581 results released however it found that in 243 of the cases the person had openly stated that they turn 18 this year."
	},
	{
		"src": "Seda meditsiinilist vanuse hindamise meetodit, mille k\u00e4igus tehakse tarkusehammastest r\u00f6ntgenipildid ja p\u00f5lveliigestest MRT, misj\u00e4rel neid lastakse hambaarstidel ja radioloogidel anal\u00fc\u00fcsida, on m\u00f5nes ringkonnas kritiseeritud.",
		"tgt": "The method of medical age assessment, which consists of taking X-rays of wisdom teeth and MRI scans of knee joints, then having dentists and radiologists analyse them, has also been criticised in some quarters."
	},
	{
		"src": "\u00dcks skeptikutest on Karolinska Instituudi endokrinoloog Claude Marcus, kelle t\u00f6\u00f6\u00fclesannete hulka kuulub inimeste bioloogilise k\u00fcpsuse hindamine, et selgitada v\u00e4lja, kas nad l\u00e4bisid puberteedi tavap\u00e4rasest varem v\u00f5i hiljem.",
		"tgt": "One sceptic is Karolinska Institute endocrinologist Claude Marcus, whose work includes assessing the biological maturity of people to see if they went through puberty earlier or later than usual."
	},
	{
		"src": "\"Mul on olnud p\u00f5hjust selle \u00fcle m\u00f5elda ja ma ei arva, et praegu kasutatavat m\u00f5\u00f5tmisviisi peaks kasutama.",
		"tgt": "\"I've had reason to think about this, and I don't think the type of measurement being used should be."
	},
	{
		"src": "Bioloogilise vanuse m\u00e4\u00e4ramine sellisel viisil on v\u00e4ga ebakindel.",
		"tgt": "Judging biological age in this way is very uncertain."
	},
	{
		"src": "Kui me ei saa kindlalt \u00f6elda, siis me ei tohiks teha n\u00e4gu, et saame,\" \u00fctles ta ajalehele Metro.",
		"tgt": "If we can't say it for sure we shouldn't pretend that we can,\" he told newspaper Metro."
	},
	{
		"src": "Aga Johan G\u00f6ransson Kohtumeditsiini Instituudist kaitses testide t\u00e4psust: \"\u00dcldiselt v\u00f5ib \u00f6elda, et lapse ebat\u00e4pselt t\u00e4iskasvanuks lahterdamise risk on v\u00e4ike.",
		"tgt": "The Forensic Medicine Agency's G\u00f6ransson defended the accuracy of the tests however: \"In general you can say that the risk of inaccurately judging a child to be an adult is small."
	},
	{
		"src": "K\u00f5ige suurem ehk umbes 10% juures on risk juhul, kui inimene on natuke alla 18.\"",
		"tgt": "The biggest risk is if the person is just under 18, in which case it's around 10 percent.\""
	},
	{
		"src": "9 m\u00e4rki, et v\u00f5id sind petnud kallimale andestada.",
		"tgt": "9 signs you can forgive a partner who cheated on you."
	},
	{
		"src": "Su kallim reetis sind ja veetis \u00f6\u00f6 kellegi teisega.",
		"tgt": "Your partner betrayed you and spent the night with someone else."
	},
	{
		"src": "Sul on valus, sest teil on \u00fchiselt nii palju toredaid aegu ja meenutusi.",
		"tgt": "You feel hurt because you have so many shared experiences and memories."
	},
	{
		"src": "Tahaksid talle andestada, kuid kas on \u00f5ige aeg...",
		"tgt": "You want to forgive them, but is it the right time\u2026"
	},
	{
		"src": "Your Tango loetleb \u00fcheksa m\u00e4rki, mis n\u00e4itavad, et su kallim oma tegu kahetseb ja v\u00f5iksid talle andestada.",
		"tgt": "Your Tango provides nine signs that show that your partner is remorseful and you could forgive them."
	},
	{
		"src": "Su kallim n\u00e4ib m\u00f5istvat olukorra t\u00f5sidust ja n\u00e4eb selle lahendamiseks palju vaeva.",
		"tgt": "Your partner appears to realize the seriousness of the situation and is putting a lot of effort into resolving it."
	},
	{
		"src": "Su kallim tegeleb probleemiga, mis viis ta teise kaaslasega voodisse.",
		"tgt": "Your partner is dealing with the problem that led them to sleep with someone else."
	},
	{
		"src": "Su kallim ei ole enam kaitsepositsioonil.",
		"tgt": "Your partner isn\u2019t taking a defensive position any longer."
	},
	{
		"src": "Ta kahetseb siiralt ja v\u00f5tab vastutuste oma tegude eest.",
		"tgt": "They are sincerely remorseful and take responsibility for their actions."
	},
	{
		"src": "Ta ei \u00fcrita sind oma k\u00e4itumises s\u00fc\u00fcdistada.",
		"tgt": "They don\u2019t try to blame you for their actions."
	},
	{
		"src": "Ta n\u00f5ustub, et on teinud t\u00f5sise vea ja siiralt \u00fcritab olukorda parandada.",
		"tgt": "They agree that they made a serious mistake and sincerely tries to rectify the situation."
	},
	{
		"src": "Ta on t\u00e4helepanelik ja \u00fcritab sinuga meeldivalt suhelda.",
		"tgt": "They are attentive and tries to interact with you in a pleasant manner."
	},
	{
		"src": "Samas survesta ta sind kiirustades asjast \u00fcle saama.",
		"tgt": "They pressure you, urging you to try to get over it."
	},
	{
		"src": "Nad ei eita juhtunut ega \u00fcrita seda m\u00e4rkamatuks muuta.",
		"tgt": "They don\u2019t deny what happened and don\u2019t try to cover it up."
	},
	{
		"src": "Sul ja su kallimal on arusaam, miks truudusetus teie suhtes tekkis.",
		"tgt": "You and your partner have an understanding about what caused the infidelity."
	},
	{
		"src": "Te r\u00e4\u00e4gite sellest ja ka sellest, kuidas seda tulevikus v\u00e4ltida.",
		"tgt": "You talk about it and also about how to avoid it in future."
	},
	{
		"src": "\u00d5pite paremini suhtlema ja \u00fcksteise vajadusi hindama.",
		"tgt": "You learn to communicate better and appreciate each other\u2019s needs."
	},
	{
		"src": "Su kallima suhtumine ja teod on aidanud sul arendada endas kaastunnet tema eksimuse vastu.",
		"tgt": "Your partner\u2019s attitude and actions have helped you to develop empathy in regard to their actions."
	},
	{
		"src": "Su kallima p\u00fchendumine ja k\u00e4itumine on loonud aluse, et teie l\u00e4hedus hakkab taastuma.",
		"tgt": "Your partner\u2019s commitment and actions have laid a basis for restoring intimacy between you."
	},
	{
		"src": "Olete paarina teinud edusamme, et uskuda taas teie \u00fchtsusesse ja suhtesse.",
		"tgt": "As a couple, you have made progress to once again believing in your unity and your relationship."
	},
	{
		"src": "20aastane vasaraheitja Anna Maria Orel tegi Londoni MMil ilusa deb\u00fc\u00fcdi, saades 67.37ga tubli 18. koha.",
		"tgt": "The 20-year-old hammer thrower Anna Maria Orel made a nice debut at the London World Championships, finishing a well-deserved 18th with a mark of 67.37h"
	},
	{
		"src": "Orel oli MMi noorim naisvasaraheitja ning r\u00f5\u00f5msameelne naine kinnitas, et loodab tulevikus medalite eest v\u00f5idelda.",
		"tgt": "Orel was the youngest women\u2019s hammer thrower at the worlds and the cheerful woman affirmed that she hopes to be in the medal hunt in future."
	},
	{
		"src": "V\u00f5istlus l\u00e4ks h\u00e4sti ja sain hea kogemuse.",
		"tgt": "The competition went well and I gained a good experience."
	},
	{
		"src": "Esimese katsega (64.80) tegin kohe oma keskmise tulemuse \u00e4ra, teisel (62.80) riskisin liiga palju ja kolmandal (67.37) suutsin pea selge hoida\", \u00fctles Orel p\u00e4rast v\u00f5istlust.",
		"tgt": "On my first attempt (64.80) I got my average result right away, on the second (62.80) I risked too much and on the third (67.37) I managed to stay clear in the head,\u201d said Orel after the event."
	},
	{
		"src": "Otsisin oma heidet ja mul on v\u00e4ga hea meel, et leidsin selle.",
		"tgt": "I looked for my throw and I was very glad that I found it."
	},
	{
		"src": "Anna Maria Oreli MMi deb\u00fc\u00fct l\u00f5ppes tubli 18. kohaga.",
		"tgt": "Anna Maria Orel\u2019s world championship debut culminated in a solid 18th place."
	},
	{
		"src": "Vihmasadu Orelit ei seganud, sest treenib ta ju talv l\u00e4bi TT\u00dc staadionil.",
		"tgt": "The rain didn\u2019t bother Orel, because she trained all winter long at the TUT stadium."
	},
	{
		"src": "\"Olen karastatud\", \u00fctles ta v\u00e4ikese muigega.",
		"tgt": "\u201cI\u2019ve been toughened up,\u201d she says with a bit of a grin."
	},
	{
		"src": "Londoni ol\u00fcmpiastaadionil oli peaaegu t\u00e4ismaja jagu rahvast, kas Orel tajus inimesi enda \u00fcmber v\u00f5i suutis end v\u00e4lja l\u00fclitada?",
		"tgt": "The London Olympic stadium was nearly packed, did Orel sense the people around her or was she able to disengage?"
	},
	{
		"src": "Tajusin, aga positiivses m\u00f5ttes.",
		"tgt": "I did sense them, but in a positive sense."
	},
	{
		"src": "K\u00f5ik \u00fctlevad, et see annab juurde - nii ongi!",
		"tgt": "Everybody says that it gives you something."
	},
	{
		"src": "Kui ise v\u00f5istled, siis saab seda kogeda.",
		"tgt": "It\u2019s something you can experience when you\u2019re competing."
	},
	{
		"src": "Orel kinnitas, et j\u00e4\u00e4b MMi deb\u00fc\u00fcdiga rahule ning teda ootab veel palju h\u00e4id v\u00f5istlusi: \"Tulin siia t\u00e4navuse hooaja 32. ehk viimase tulemusega, l\u00f5petasin 18. kohal.",
		"tgt": "Orel confirmed that she was satisfied with her World Championships debut and that many good competitions lay ahead for her: \u201cI came here with the 32nd or last place result, and I finished in 18th place."
	},
	{
		"src": "See on v\u00e4ga korralik tulemus.",
		"tgt": "That was a very decent result."
	},
	{
		"src": "Olen 20aastane ja MMil - see on ainus, mis loeb.",
		"tgt": "I\u2019m 20 and the World Championships \u2013 that\u2019s the only one that counts."
	},
	{
		"src": "V\u00f5tan kaasa hea kogemuse ja m\u00f5nel p\u00e4eval tahan v\u00f5istelda juba medalite nimel.",
		"tgt": "I will come away with a good experience and someday I\u2019ll be wanting to compete for medals."
	},
	{
		"src": "L\u00e4\u00e4ne-Virgina kuberner teatas parteivahetusest",
		"tgt": "West Virginia governor announces he's switching parties"
	},
	{
		"src": "L\u00e4\u00e4ne-Virginia demokraadist kuberner Jim Justice teatas neljap\u00e4eva \u00f5htul kogunemisel koos president Trumpiga, et ta vahetab parteid.",
		"tgt": "The Democratic governor of West Virginia, Jim Justice, announced Thursday night at a rally with President Trump that he's switching parties."
	},
	{
		"src": "\"Meeldigu see v\u00f5i mitte, aga demokraadid k\u00f5ndisid minu juurest minema,\" \u00fctles kuberner Justice.",
		"tgt": "\"Like it or not like it, the Democrats walked away from me,\" Gov. Justice said."
	},
	{
		"src": "\"T\u00e4na ma \u00fctlen teile, olles rohkelt palvetanud ja j\u00e4rele m\u00f5elnud... t\u00e4na ma \u00fctlen teile, l\u00e4\u00e4nevirginialastele, et ma ei saa teid demokraatliku kubernerina enam aidata.\"",
		"tgt": "\"Today I will tell you with lots of prayers and lots of thinking ... today I will tell you as West Virginians, I can't help you anymore being a Democratic governor.\""
	},
	{
		"src": "Kogunemisel vallandusid r\u00f5\u00f5muh\u00f5isked.",
		"tgt": "The rally erupted in cheers."
	},
	{
		"src": "\"Seega saab minust homme vabariiklane,\" lisas Justice.",
		"tgt": "\"So tomorrow, I will be changing my registration to Republican,\" Justice added."
	},
	{
		"src": "\"Treenerina \u00fctleksin teile, et aeg on m\u00e4ngida teist m\u00e4ngu.\"",
		"tgt": "\"As a coach, I would tell you it's time to run another play.\""
	},
	{
		"src": "Trump oli lubanud varem L\u00e4\u00e4ne-Virginia kogunemisel suurt teadaannet.",
		"tgt": "Mr. Trump promised earlier a big announcement at the West Virginia rally."
	},
	{
		"src": "Trump v\u00f5itis L\u00e4\u00e4ne-Virginias 42 punktiga ja Justice ei toetanud demokraatide kandidaati Hillary Clintonit.",
		"tgt": "Mr. Trump won West Virginia by 42 points, and Justice did not endorse the Democratic nominee, Hillary Clinton."
	},
	{
		"src": "Justice, kes on Forbesi andmetel osariigi ainus miljard\u00e4r, osutus valituks aastal 2016.",
		"tgt": "Justice, who is the only billionaire in the state, according to Forbes, was elected in 2016."
	},
	{
		"src": "Forbes m\u00e4rgib, et talle kuuluvad kivis\u00f6ekaevandused viies osariigis ning kivis\u00f6e\u00e4ri p\u00e4ris ta oma isalt.",
		"tgt": "Forbes notes that he owns coal mines in five states, having inherited a coal business from his father."
	},
	{
		"src": "Tema v\u00e4\u00e4rtus on ligikaudu 1,59 miljardit dollarit.",
		"tgt": "He's worth about $1.59 billion."
	},
	{
		"src": "Samal ajal avaldas vabariiklaste rahvuskomitee (RNC) neljap\u00e4eva \u00f5htul teadaande, et \"kuberner Justice'i parteivahetus on j\u00e4rjekordne l\u00f6\u00f6k demokraatlikule parteile, mis pigem takistaks riigi j\u00e4lle paremaks muutmist kui t\u00f6\u00f6taks selle nimel\".",
		"tgt": "Meanwhile, the Republican National Committee released a statement Thursday night saying \"Governor Justice's party switch is another blow to a Democratic Party that would rather obstruct than work to make our country great again.\""
	},
	{
		"src": "\"K\u00f5igest 15 kubernerikohta ja kontroll k\u00f5ige madalama arvu osariikide \u00fcle ajaloos - kuberner Justice'i teadaanne on lihtsalt k\u00f5ige hiljutisem \u00e4ra\u00fctlemine parteile, mis on otsast l\u00f5puni juhitu ega suuda leida positiivset ning \u00fchendavat s\u00f5numit,\" \u00fctles RNC esinaine Ronna McDaniel avalduses CBS Newsile.",
		"tgt": "\"With only 15 governorships and control of the fewest state legislatures in history, Governor Justice's announcement is just the latest rejection of a party that is leaderless from top to bottom and unable to find a positive, unifying message,\" RNC chairwoman Ronna McDaniel said in a statement to CBS News."
	},
	{
		"src": "Pole vast \u00fcllatus, et kus on palju rahvast, seal on ka palju vigastatuid.",
		"tgt": "It\u2019s no surprise now that where there\u2019s large crowds, there\u2019s also more injured."
	},
	{
		"src": "Weekendil meditsiinitelgis ametis olev Urmet \u00fctles eile \u00d5htulehele, et plaastreid on nad pidanud p\u00e4ris palju v\u00e4lja jagama.",
		"tgt": "Urmet, working in the medicine tent at Weekend, told \u00d5htuleht yesterday that they have had to dispense quite a few bandages."
	},
	{
		"src": "Villid ja marrastused on p\u00f5hilised, v\u00e4lja v\u00e4\u00e4namised ja kerged kukkumised.",
		"tgt": "Blisters and abrasions are the main ones, sprains and mild falls."
	},
	{
		"src": "Loomulikult ka pea-, selja- ja jalavalud.",
		"tgt": "Naturally, headaches, backaches and leg pain."
	},
	{
		"src": "Urmeti s\u00f5nul tulevad k\u00fclastajad festivalile valede jalan\u00f5udega ja nii probleemid tulevad.",
		"tgt": "Urmet says patrons come to the festival with the wrong footwear and that causes problems."
	},
	{
		"src": "Meedikud on pidanud abistama ka paari suurema vigastusega k\u00fclastajaid - on olnud m\u00f5ned paanikahood ja ka \u00fcks jalaluumurd.",
		"tgt": "Medics have had to assist a couple guests with more serious injuries \u2013 one had a panic attack and one had a broken leg."
	},
	{
		"src": "Samuti oleme teinud \u00f5mblemisi, kui inimene on k\u00e4e v\u00f5i s\u00f5rme puruks teinud.",
		"tgt": "We have also had to apply stitches where someone has cut their hand or finger."
	},
	{
		"src": "V\u00e4iksemad \u00f5mblused teeme siin \u00e4ra, suuremad saadame haiglasse.",
		"tgt": "We do minor stitches here, bigger ones we send them to hospital."
	},
	{
		"src": "Vaata videost, kas pidulised meedikutelt pohmelli raviks valuvaigistit ka k\u00fcsivad.",
		"tgt": "Watch the video whether festivalgoers also ask medics for pain relievers for hangovers."
	},
	{
		"src": "Coe kiitis venelaste ausat vabandust dopinguskandaali p\u00e4rast",
		"tgt": "Coe praises 'candid' Russian apology for doping scandal"
	},
	{
		"src": "Kergej\u00f5ustiku rahvusvaheline ninamees Sebastian Coe kiitis tema s\u00f5nade j\u00e4rgi \"Venemaa neljap\u00e4evast ausat vabandust\" dopinguskandaali p\u00e4rast, aga kordas, et praegu pole aeg riiki sporti tagasi lubada.",
		"tgt": "Global athletics boss Sebastian Coe praised what he described as a candid apology from Russia over a doping scandal on Thursday but reiterated it was not the moment for the country to be readmitted to the sport."
	},
	{
		"src": "Venemaa kergej\u00f5ustiku ninamees Dmitry Shylakhtin \u00fctles kergej\u00f5ustiku maailmameistriv\u00f5istluste eel\u00f5htul toimunud IAAF-i kongressil, et tema riigile kehtestatud v\u00f5istluskeeld on \u00f5ige ja tal on kindel eesm\u00e4rk dopingu vastu v\u00f5idelda.",
		"tgt": "Russia's athletics boss Dmitry Shylakhtin told an IAAF Congress, held on the eve of the World Athletics Championships, that his country's ban from the sport was correct and that he was determined to fight doping."
	},
	{
		"src": "Ta palus vabandust \"k\u00f5ikidelt kergej\u00f5ustiklastelt, kelle k\u00e4est on v\u00f5istlustel kuld- ja h\u00f5bemedalid \u00e4ra napsatud\".",
		"tgt": "He said he was sorry to \"all athletes who have had gold and silver medals snatched from them at competitions.\""
	},
	{
		"src": "Tema kommentaaridele vaatamata h\u00e4\u00e4letas IAAF-i kongress selle poolt, et j\u00e4tta j\u00f5usse v\u00f5istluskeeld, mis kehtestati 2015. aasta novembris p\u00e4rast seda, kui Maailma Antidopingu Agentuuri (WADA) raport leidis asit\u00f5endeid riigi toetatud dopingu kohta Venemaal.",
		"tgt": "Despite his comments, the IAAF Congress voted in favor of maintaining the ban, imposed in November 2015 after a World Anti-Doping Agency (WADA) report found evidence of state-sponsored doping in Russia."
	},
	{
		"src": "\"Minu arvates oli t\u00e4na tegu v\u00e4ga ausa vastusega, v\u00e4ga ausa esitlusega,\" \u00fctles IAAF-i president Coe ajakirjanikele.",
		"tgt": "\"I thought it was a very candid response today, a very candid presentation,\" IAAF president Coe told reporters."
	},
	{
		"src": "\"Terve n\u00f5ukogu ja kogu kongress olid rahul, et Venemaa alaliit tunnistas ka ise, et neil on olnud \u00fcsna keerulised ajad ja nad teevad alaliidu \u00fcmberkorraldamiseks k\u00f5ik v\u00f5imaliku.\"",
		"tgt": "\"The whole Council and the whole Congress was pleased ... that the Russian federation recognized themselves that they have been through some pretty torrid times and are doing everything possible to make sure the federation is reengineered.\""
	},
	{
		"src": "Coe s\u00f5nul oli tal lisaks hea meel, et Venemaa aktsepteeris enda ennistamise kriteeriumeid.",
		"tgt": "Coe said he was also \"pleased\" that Russia accepted the criteria for its reintroduction."
	},
	{
		"src": "\"Usun, et t\u00e4na oli v\u00e4ga konstruktiivne p\u00e4ev ja toimub edasiminek, aga kongress toetab t\u00f6\u00f6r\u00fchma ettepanekut, et praegu pole \u00f5ige aeg Venemaa tagasiv\u00f5tmiseks,\" \u00fctles Coe.",
		"tgt": "\"I think it was a very constructive day and I think progress is being made, but the Congress supports the recommendations of the task force that this was not the moment to reinstate Russia,\" said Coe."
	},
	{
		"src": "\"Peame tegema paari j\u00e4rgmise kuu jooksul k\u00f5ik v\u00f5imaliku, et olukord normaliseerida.",
		"tgt": "\"We need to do everything over the next few months to normalize this situation."
	},
	{
		"src": "Oleme l\u00e4htunud alati p\u00f5him\u00f5ttest, et tahame puhtad sportlased rikutud s\u00fcsteemist eraldada,\" lisas ta.",
		"tgt": "The guiding principle has always been that we wanted to separate the clean athletes from the tainted system,\" he added"
	},
	{
		"src": "\u00dcheksateist Venemaa kergej\u00f5ustiklast, kes vastavad IAAF-i rangetele kriteeriumitele, v\u00f5istlevad reedel Londonis algavatel kergej\u00f5ustiku maailmameistriv\u00f5istlustel neutraalsete sportlastena.",
		"tgt": "Nineteen Russian athletes will be competing as neutrals at the World Athletics Championships which start in London on Friday, having met strict IAAF criteria."
	},
	{
		"src": "IAAF-i t\u00f6\u00f6r\u00fchma juht Rune Andersen \u00fctles esmasp\u00e4eval, et Venemaa ei vasta veel mitmele ennistamise kriteeriumile.",
		"tgt": "The head of the IAAF's Task Force, Rune Andersen, said on Monday that Russia had yet to meet several of the criteria for reinstatement."
	},
	{
		"src": "P\u00e4rast IAAF-i n\u00f5ukogule tehtud ettekannet lausus ta Londonis ajakirjanikele, et dopingukontroll on endiselt ebapiisav ja keelu saanud treenerid tegutsevad ikka veel vabalt.",
		"tgt": "Drug-testing was still insufficient and banned coaches were still operating freely, he told reporters in London after a presentation to the IAAF Council."
	},
	{
		"src": "Elektriautode revolutsioon muudab oluliselt metallide n\u00f5udlust.",
		"tgt": "The electric car revolution is transforming demand for metals"
	},
	{
		"src": "Kes on v\u00f5itjad ja kaotajad?",
		"tgt": "Who are the winners and losers?"
	},
	{
		"src": "V\u00e4he sellest, et elektriautode revolutsioon muudab oluliselt k\u00f5ike k\u00fctuseturust kuni infrastruktuurini, loob see ka metalliturul uued v\u00f5itjad ja kaotajad.",
		"tgt": "If it wasn\u2019t enough that the electric car revolution is transforming everything from the fuel market to infrastructure, it is also creating new winners and losers on the metals market."
	},
	{
		"src": "Kuigi kaevandusgigandid nagu Glencore saavad \u00f6elda, et \u00fchest kohast nad v\u00f5idavad ja teisest kaotavad, siis v\u00e4iksemad kaevandusfirmasid see ei aita.",
		"tgt": "Although mining giants such as Glencore can say that they are winning in one area and losing in another, this is of no use to smaller mining companies."
	},
	{
		"src": "Praegu teenib Glencore kivis\u00f6elt ja naftalt, kuid edaspidi elektriautode ajastul kasvab koobalti, liitiumi, vase, alumiiniumi ja niklin\u00f5udlus.",
		"tgt": "Glencore currently makes money on coal and oil, but in future, the demand for cobalt, lithium, copper, aluminium and nickel will grow in the electric car age."
	},
	{
		"src": "Sel aastal on elektriautode leviku osas panuseid t\u00f5stnud \u00dchendkuningriigi, Prantsusmaa ja Norra valitsuste otsused, kes lubavad l\u00e4hiaastak\u00fcmnetel keelustada fossiilsed k\u00fctuseid kasutavate uute autode m\u00fc\u00fcgi.",
		"tgt": "This year, decision by the governments of the United Kingdom, France and Norway have raised the stakes with regard to the spread of electric cars, as they promise to prohibit the sale of fossil fuel powered cars in the decades ahead."
	},
	{
		"src": "Sestap on juba Volvo teadanud, et nad plaanivad loobuda sisep\u00f5lemismootorist ning Tesla toob turule odavama Model 3 elektriauto.",
		"tgt": "That\u2019s why Volvo has already announced that they plan to phase out internal combustion engines and Tesla will be introducing a cheaper Model 3 electric car."
	},
	{
		"src": "Bloomberg New Energy Finance prognooside kohaselt m\u00fc\u00fcakse juba kahe aastak\u00fcmne jooksul elektriautosid rohkem kui naftast toodetud k\u00fctuseid kasutavaid autosid.",
		"tgt": "According to Bloomberg New Energy Finance, in the next two decades more electric cars will be sold than cars that use petroleum-derived fuels."
	},
	{
		"src": "\"M\u00f5nede metallide osas muudab see k\u00f5ike\", \u00fctles Capital Economicsi tooraineanal\u00fc\u00fctik Simona Gambranini Bloombergile.",
		"tgt": "\u201cIt will change everything with regard to some metals,\u201d Capital Economics commodities analyst Simona Gambranini told Bloomberg."
	},
	{
		"src": "Oleme juba n\u00e4inud suurt m\u00f5ju sellistele metallide nagu koobalt ja liitium, mille n\u00f5udlus on aastaid kasvanud.",
		"tgt": "We have already seen a great impact on such metals as cobalt and lithium whose demand has grown for years."
	},
	{
		"src": "Elektriautodes on umbes kolm korda rohkem vaske kui tavaautos, teatas Glencore.",
		"tgt": "Electric cars have about three times more copper than conventional cars,\u201d said Glencore."
	},
	{
		"src": "Veel rohkem vaske on tarvis laadimisjaamades, mist\u00f5ttu Exane BNP Paribasi hinnangul suurendab see 2025. aastaks vase n\u00f5udlust umbes viis protsenti.",
		"tgt": "There is even more copper in charging stations, which is why Exane BNP Paribas believes it will increase copper demand by about five per cent by 2025."
	},
	{
		"src": "Elektriautode akude n\u00f5udluse kasv t\u00e4hendab t\u00e4iendavat liitiumi, koobalti, grafiidi ja mangaanin\u00f5udlust.",
		"tgt": "The increase in demand for electric car batteries will mean additional demand for lithium, cobalt, graphite and manganese."
	},
	{
		"src": "Glencore saab kasvavast elektriautode trendist tulu vase hinnat\u00f5usult ja sellelt, et on maailma suurim koobaltitootja, prognoosis Jefferies Group.",
		"tgt": "Glencore will derive income from the growing electric car trend from the rise in copper prices, and the fact that it is the world\u2019s biggest cobalt producer, the Jefferies Group has forecasted."
	},
	{
		"src": "Selle maaklerfirma hinnangul on teisteks elektriautode v\u00f5iduk\u00e4igust v\u00f5itjateks Freeport-McMoRan ja First Quantum Minerals.",
		"tgt": "This brokerage believes that Freeport-McMoRan and First Quantum Minerals will be other winners from the ascendancy of electric cars."
	},
	{
		"src": "Turg reageerib juba muutuvale trendile.",
		"tgt": "The market is already responding to the changing trend."
	},
	{
		"src": "T\u00e4navu on Londoni metallib\u00f6rsil koobalt kallinenud 70 protsenti.",
		"tgt": "This year, cobalt has already risen 70 per cent in price on the London Metal Exchange."
	},
	{
		"src": "Mullune hinnat\u00f5us oli 37 protsenti.",
		"tgt": "Last year\u2019s price rise was 37 per cent."
	},
	{
		"src": "Ka vask on t\u00e4navu kallinenud 14 protsenti, peaasjalikult majanduskasvu t\u00f5ttu.",
		"tgt": "Copper, too, is up 14 per cent this year, mainly due to economic growth."
	},
	{
		"src": "Glencore'i aktsia t\u00f5usis Londonis 20 protsenti, olles hinnat\u00f5usult \u00fcletanud rivaale Rio Tinto Groupi, BHP Billitoni ja Anglo Americani.",
		"tgt": "Glencore shares rose 20 per cent in London, outstripping rivals Rio Tinto Group, BHP Billiton and Anglo American in its increase."
	},
	{
		"src": "Kaotajate poolel on pliiga tegelevad ettev\u00f5tted nagu Recyclex ja Campine, kes peavad kohanduma uue ajastuga.",
		"tgt": "On the loser\u2019s side, there companies engaged in lead, like Recyclex and Campine, which have to adapt to the new era."
	},
	{
		"src": "Plii p\u00f5hiline l\u00f5ppkasutus on bensiini- ja diiselmootoriga autode startereid vooluga varustavad akud.",
		"tgt": "The main end use of lead is in batteries that provide current to the starters of petrol and diesel cars."
	},
	{
		"src": "Elektriautod kasutavad liitiumioonakusid.",
		"tgt": "Electric cars use lithium ion batteries."
	},
	{
		"src": "\"See on t\u00f5sine risk pliin\u00f5udlusele v\u00e4lja arvatud juhul kui leitakse sellele muu otstarve, millega saaks \u00fcletada n\u00f5udluse langust\", \u00fctles Bank of America Merrill Lynchi metallituru anal\u00fc\u00fcsijuht Michael Widmer.",
		"tgt": "\u201cThis is a serious risk to lead demand, unless some other purpose is found for it, that would exceed the decline in demand,\u201d said Bank of America Merrill Lynch\u2019s head of metal market analysis, Michael Widmer."
	},
	{
		"src": "Plii hinnaliikumise n\u00e4ol pole veel lahtirulluva trendi m\u00f5ju m\u00e4rgata.",
		"tgt": "The effect of the unfurling trend isn\u2019t showing up yet in lead prices."
	},
	{
		"src": "Plii on t\u00e4navu kallinenud 17 protsenti, kusjuures see on Londonis peamiste t\u00f6\u00f6stusmetallide seas hinnat\u00f5usult parim metall.",
		"tgt": "Lead has increased in price by 17 per cent this year, being the biggest gainer among industrial metals in London."
	},
	{
		"src": "Investorid n\u00e4evad probleeme metallile alles kaugel tulevikus.",
		"tgt": "Investors see problems for the metal only in the distant future."
	},
	{
		"src": "\"Ma ei ole kindel, et pliile on see nii halb, sest odav nafta hoiab tavaautod konkurentsis\", \u00fctles metallimaaklerfirma Triland Metalsi m\u00fc\u00fcgijuht Herwig Schmidt.",
		"tgt": "\u201cI\u2019m not sure that it will be so bad for lead, because cheap oil will keep conventional cars competition,\u201d said Herwig Schmidt, the sales director of the metal brokerage Triland Metals."
	},
	{
		"src": "Kui plii n\u00f5udlus kukub, toimub see aeglaselt.",
		"tgt": "If lead demand falls, it will happen slowly."
	},
	{
		"src": "V\u00f5ib olla juhtub see nii umbes k\u00fcmne aasta p\u00e4rast.",
		"tgt": "Perhaps it will happen in about ten years\u2019 time."
	},
	{
		"src": "Seniks aga t\u00e4hendavad karmimad heitgaaside normid, et kasvab h\u00fcbriidautode n\u00f5udlus, mis s\u00f5ltuvad sagedasel mootorite k\u00e4ivitamisel arenenud pliip\u00f5histest akudest, hindab rahvusvaheline plii ja tsingi uurimisorganisatsioon.",
		"tgt": "For now, the stricter emissions standards mean growing demand for hybrid cars that depend on advanced lead-based batteries for frequent engine starts, in the estimation of an international lead and zinc research organization."
	},
	{
		"src": "Kergmetallid nagu alumiinium asendavad terast, kuna kergem auto saab v\u00e4hema elektriga s\u00f5ita kaugemale.",
		"tgt": "Light metals such as aluminium will replace steel, as a lighter car can drive further on less electricity."
	},
	{
		"src": "Sellega on seletatav juba 2013-2016 aastani t\u00e4iendav 1,6 miljoni tonnine alumiinimumin\u00f5udlus.",
		"tgt": "The additional 1.6 million tonne aluminium demand in the years 2013-2016 can already be attributed to this."
	},
	{
		"src": "See moodustab 2,7 protsenti alumiiniumi maailma kogutoodangust.",
		"tgt": "This makes up 2.7 per cent of the total world aluminium production."
	},
	{
		"src": "T\u00f5en\u00e4oliselt see trend s\u00fcveneb, \u00fctles Widmer.",
		"tgt": "The trend will likely deepen, says Widmer."
	},
	{
		"src": "Alumiinium on t\u00e4navu kallinenud 13 protsenti, kuna kasvav n\u00f5udlus autotootjate poolt on viinud turu defitsiiti.",
		"tgt": "Aluminium has increased in price by 13 per cent this year, as growing demand from auto makers has led to a market deficit."
	},
	{
		"src": "Terasetootjad ei maga.",
		"tgt": "Steel producers not asleep."
	},
	{
		"src": "AK Steel Holding teeb koost\u00f6\u00f6d General Motorsiga, et kasutada nanotehnoloogiat imekergete autokerede tootmiseks.",
		"tgt": "AK Steel Holding is partnered with General Motors for using nanotechnology for manufacturing incredibly light car bodies."
	},
	{
		"src": "Ka ArcelorMittal ja Tata Steel Europe p\u00fc\u00fcavad arendada v\u00e4lja kergemat sulamit terast, et seista vastu alumiinimumile.",
		"tgt": "ArcelorMittal and Tata Steel Europe are also trying to develop lighter steel alloys to compete with aluminium."
	},
	{
		"src": "\"\u00dclitugev teras peaks olema vastus sellele arengule\", \u00fctles Exane BNP Paribasi anal\u00fc\u00fctik Sylvain Brunet.",
		"tgt": "\u201cUltrastrong steel should be the answer to this development,\u201d said Exane BNP Paribas analyst Sylvain Brunet."
	},
	{
		"src": "Euroopas on n\u00e4ha m\u00f5ningast edu.",
		"tgt": "Some success can be seen in Europe."
	},
	{
		"src": "Naftaajastu l\u00f5pp v\u00f5ib tuua ka kannatusi plaatinale.",
		"tgt": "The end of the oil era can lead to tribulations for platinum as well."
	},
	{
		"src": "Mullu kulus umbes pool sellest v\u00e4\u00e4rismetallist diiselmootoriga autode katal\u00fcsaatoriteks, teatas metallirafineerija Johnson Matthey.",
		"tgt": "Last year, about half of this precious metal was used for catalytic converters in diesel cars,\u201d said metal refiner Johnson Matthey."
	},
	{
		"src": "\"Paljudel praegu suure n\u00f5udlusega toorainetel nagu nafta ja plaatina ei pruugi tulevikus suurt n\u00f5udlust olla\", \u00fctles Natixise tooraineanal\u00fc\u00fctik Bernard Dahdah.",
		"tgt": "\u201cMany commodities in high demand such as oil and platinum may not necessarily have high demand in future,\u201d said commodities analyst for Natixis, Bernard Dahdah."
	},
	{
		"src": "See ei t\u00e4henda, et toorained tervikuna muutuvad v\u00e4hem t\u00e4htsaks, kuid nende t\u00e4htsus muutub 15 aasta jooksul.",
		"tgt": "This doesn\u2019t mean that commodities as a whole will become less important but their importance will change over the next 15 years."
	},
	{
		"src": "Plaatinatootjad usuvad j\u00e4tkuvat n\u00f5udlust diiselh\u00fcbriidautode jaoks.",
		"tgt": "Platinum producers believe there will be continuing demand for diesel hybrid cars."
	},
	{
		"src": "Uncore'i juht Marc Grynberg \u00fctles, et 2025. aastal m\u00fc\u00fcakse j\u00e4tkuvalt t\u00e4iselektriautodest rohkem h\u00fcbriidautosid.",
		"tgt": "Uncore CEO Marc Grynberg said that in 2025, sales of hybrid cars will still exceed that of fully electric cars."
	},
	{
		"src": "Plaatinatootjate suur lootus 10 aasta perspektiivis on Toyota Motori ja Hyundai Motosi arendatud vesinikelemendil p\u00f5hinevatel autodel, mis s\u00f5ltuvad plaatinast, et toota vesinikust elektrit.",
		"tgt": "Platinum producers\u2019 big hope in the 10-year perspective rests with the hydrogen element based cars developed by Toyota Motor and Hyundai, which depend on platinum for producing electricity from hydrogen."
	},
	{
		"src": "Seni ei ole see tehnoloogia siiski veel \u00e4riliselt end \u00f5igustanud.",
		"tgt": "To this point, the technology has not proved its worth commercially."
	},
	{
		"src": "\"Diisel n\u00e4ib olevat selge kaotaja teel elektriautode poole\", \u00fctles Exane BNP Paribasist Brunet.",
		"tgt": "\u201cDiesel appears to be the clear loser on the way to electric cars,\u201d said Brunet from Exane BNP Paribas."
	},
	{
		"src": "Saksa autotootjad said juulis suure tagasil\u00f6\u00f6gi osaliseks, kuna Stuttgarti kohus keelas diisli kasutamise Mercedes-Benzi ja Porsche kodulinnas.",
		"tgt": "In July, German auto makers experience d a big setback as a Stuttgart court forbade the use of diesel in the home city of Mercedes-Benz and Porsche."
	},
	{
		"src": "Kuidas jalgpalli rahanduseeskirjad m\u00f5jutavad Neymari \u00fcleminekut Pariisi",
		"tgt": "How soccer's financial rules impact Neymar's move to Paris"
	},
	{
		"src": "Eeskirjad, mille eesm\u00e4rk on ennetada Euroopa jalgpalliklubide ohjeldamatut kulutamist, ei takista Neymari maailmarekordilist \u00fcleminekut Hispaania jalgpalliklubist Barcelona Prantsusmaa klubisse Paris-Saint Germain.",
		"tgt": "Rules aimed at preventing unfettered spending by European soccer clubs will not disrupt Neymar's world-record transfer from Spain's Barcelona to France's Paris-Saint Germain."
	},
	{
		"src": "Mis tahes tagaj\u00e4rjed UEFA-lt, juhtorganilt, mis valitseb Euroopa m\u00e4ngu ja mille v\u00f5imuses on keelata meeskondadel prestii\u017esel Meistrite Liiga turniiril osalemist, ootavad Paris Saint-Germaini alles ees.",
		"tgt": "Any consequences will come further down the line for Paris Saint-Germain from UEFA, the governing body overseeing the European game which has the power to ban teams from the prestigious Champions League tournament."
	},
	{
		"src": "UEFA 2011. aastal kehtestatud ausa m\u00e4ngu finantseeskirjad (FFP) t\u00e4hendavad, et PSG peab millalgi t\u00f5endama, et Neymari \u00fcleminekut rahastati ilma tohutu kahjumita.",
		"tgt": "Financial Fair Play rules launched by UEFA in 2011 mean that PSG will eventually have to show that Neymar's transfer was funded without incurring huge losses."
	},
	{
		"src": "Barcelonale maksti 222 miljonit eurot (262 miljonit dollarit) ainu\u00fcksi selle eest, et brasiillane tema lepingust v\u00e4lja osta, ja Neymari palk hakkab ulatuma k\u00fcmnete miljonite dollariteni aastas.",
		"tgt": "Barcelona has been paid 222 million euros ($262 million) just to buy the Brazilian out of his contract and Neymar will command a salary that will run to tens of millions of dollars a year."
	},
	{
		"src": "Siin on m\u00f5ned Neymari Prantsusmaa klubisse siirdumise rahalised aspektid.",
		"tgt": "Here are some of the financial aspects of Neymar's move to France."
	},
	{
		"src": "PSG-l on kahtlemata v\u00f5imalik Neymari v\u00e4rbamiseks ja oma t\u00e4htederohkesse rivistusse lisamiseks selline raha v\u00e4lja k\u00e4ia, arvestades, et meeskonda rahastab Katari energiarikkurist valitsev perekond.",
		"tgt": "PSG can certainly stump up the cash to sign Neymar and add him to a galaxy of other stars, given the team's funding from the energy-rich ruling family of Qatar."
	},
	{
		"src": "Klubidel on lubatud m\u00e4ngijate v\u00e4rbamiseks rohkelt kulutada, kuid nad peavad tasakaalustama seda \u00f5iguslike sissetulekuallikatega, mis v\u00f5imaldavad neil jalgpalli\u00e4ris omadega v\u00e4lja tulla.",
		"tgt": "Clubs are allowed to spend heavily on acquiring players but they have to counterbalance that with legitimate sources of income, allowing them to approach break-even on their football-related business."
	},
	{
		"src": "FFP-le pani aluse Michel Platini p\u00e4rast seda, kui ta valiti 2007. aastal UEFA presidendiks.",
		"tgt": "FFP was conceived by Michel Platini after his election as UEFA president in 2007."
	},
	{
		"src": "See endine prantsuse m\u00e4ngija uskus, et klubid, kes langevad edu otsinguil suurtesse v\u00f5lgadesse, tegelevad tegelikult petmisega ja riskivad laostumisega, kui pangad v\u00f5i omanikud peaksid toetamisest loobuma.",
		"tgt": "The former France player believed that clubs who ran up huge debts in their pursuit of success were effectively cheating and risking ruin if banks or owners withdrew their support."
	},
	{
		"src": "Alates 2011. aastast keskendub FFP klubide v\u00f5lgade asemel nende kaotuste j\u00e4lgimisele.",
		"tgt": "In 2011, FFP shifted from focusing on clubs' debts to monitoring their losses instead."
	},
	{
		"src": "See muudatus t\u00e4hendab, et \u00e4rimudelit, mida Roman Abramovich kasutas esmalt 2003. aastal Chelsea's - osta potentsiaaliga klubi ja seej\u00e4rel teha suuri kulutusi, et meeskonda paremaks muuta ja \u00fcleilmset kaubam\u00e4rki luua - on raskem rakendada.",
		"tgt": "The change meant that the business model Roman Abramovich initially used at Chelsea in 2003 - buy a club with potential, and then spend heavily to improve the squad and build a global brand - become a tougher proposition."
	},
	{
		"src": "FFP praeguse kolmeaastase hindamisperioodi v\u00e4ltel, mis kestab kuni 2018. aastani, v\u00f5ivad klubid kanda kuni 30 miljoni euro suuruseid kahjusid.",
		"tgt": "During the current three-year FFP assessment period that runs through 2018, clubs can incur losses of 30 million euros."
	},
	{
		"src": "Ja hoolimata sellest, et Platini t\u00f5rjuti 2015. aastal h\u00e4bistatult presidendiametist, on tema UEFA j\u00e4reltulija Aleksander Ceferin p\u00fchendunud endiselt \u00fcleliigse kulutamise takistamisele.",
		"tgt": "And despite Platini being ousted in disgrace from the presidency in 2015, his UEFA successor Aleksander Ceferin is still committed to deterring excessive spending."
	},
	{
		"src": "\"FFP ei ole kindlasti surnud ja me j\u00e4tkame kahtlemata edaspidi nende eeskirjade tugevdamist,\" \u00fctles eelmine n\u00e4dal The Associated Pressile Andrea Traverso, kes on UEFA-s FFP j\u00e4relevaataja.",
		"tgt": "\"Certainly FFP is not dead and we will, for sure, reinforce the rules going forward,\" Andrea Traverso, who oversees FFP at UEFA, told The Associated Press last week."
	},
	{
		"src": "Kuigi PSG tasus Neymari \u00fcleostmisklausli eest \u00fche tervikv\u00e4ljamaksena, on neil v\u00f5imalik jaotada see summa raamatupidamise eesm\u00e4rgil kogu lepingu kehtivusaja v\u00e4ltel osadeks.",
		"tgt": "Although PSG will have paid Neymar's buyout clause in one lump sum, it can spread the amount for accounting purposes over the length of his contract."
	},
	{
		"src": "Neymar s\u00f5lmis viieaastase lepingu, mist\u00f5ttu on v\u00f5imalik n\u00e4idata \u00fcleminekutasu j\u00e4rgmise viie aasta jooksul aasta l\u00f5ikes 44,4 miljoni euro suuruse summana.",
		"tgt": "Neymar has signed a five-year deal, so the transfer fee could be shown as a 44.4 million-euro cost in the annual accounts for the next five years."
	},
	{
		"src": "FFP sanktsioonide esimese laine puhul 2014. aastal sai PSG koos Abu Dhabile kuuluva Manchester Cityga kaela k\u00f5ige r\u00e4ngemad karistused.",
		"tgt": "The first wave of FFP sanctions in 2014 saw PSG, along with Abu Dhabi-owned Manchester City, hit with the heaviest sanctions."
	},
	{
		"src": "PSG-le m\u00e4\u00e4rati 60 miljoni euro (sel hetkel 82 miljoni dollari) suurune trahv, mida v\u00e4hendati hiljem 20 miljonile eurole, ja klubilt n\u00f5uti Meistrite Liiga meeskonna piiramist 2014-2015. aasta hooajal 21 m\u00e4ngijale tavap\u00e4rase 25 asemel.",
		"tgt": "PSG was handed a fine of 60 million euros (then $82 million) - that was later reduced to 20 million euros - and ordered to limit its Champions League squads to 21 players for the 2014-15 season instead of the normal 25."
	},
	{
		"src": "UEFA otsib klubisid, kes v\u00f5ivad proovida kavaldada \u00fcle reguleerivaid finantsasutusi, puhudes oma sissetulekuid \u00fcles klubi omanikega seotud ettev\u00f5tete kaudu.",
		"tgt": "UEFA is on the lookout for clubs who might try to outwit its financial regulators by inflating their income through companies linked to a club's owners."
	},
	{
		"src": "Katari ettev\u00f5te v\u00f5ib k\u00fcll PSG-d sponsoreerida, aga kui sponsorluse v\u00e4\u00e4rtust peetakse standardseid turum\u00e4\u00e4rasid \u00fcletavaks, ei lubaks UEFA seda ametliku sissetulekuna arvestada.",
		"tgt": "While a Qatari company could sponsor PSG, if the value of the sponsorship was deemed to exceed standard market rates UEFA would not allow it to count as legitimate income."
	},
	{
		"src": "Nii juhtus 2014. aastal, kui UEFA otsustas, et Qatar Tourism Authority PSG toetuse v\u00e4\u00e4rtus oli \u00fclespuhutud.",
		"tgt": "That is what happened in 2014 when UEFA ruled that the value of the Qatar Tourism Authority sponsorship of PSG was inflated."
	},
	{
		"src": "On r\u00e4\u00e4gitud, et teatud osa Neymari PSG teenistusest v\u00f5ib tulla 2022. aasta maailmameistriv\u00f5istluste korralduskomitee maksete kaudu Katarist.",
		"tgt": "It has been reported that part of Neymar's PSG earnings could come via payments from the 2022 World Cup organizing committee in Qatar."
	},
	{
		"src": "Kuid PSG ja Katar 2022 eitavad, et Neymarist v\u00f5iks saada maailmameistriv\u00f5istluste saadik, ja v\u00e4idavad, et UEFA reguleerivad asutused suudaksid sellise man\u00f6\u00f6vri h\u00f5lpsalt paljastada.",
		"tgt": "But PSG and Qatar 2022 have denied that Neymar will become a World Cup ambassador and such a maneuver would be easy for UEFA's regulators to expose."
	},
	{
		"src": "PSG-le varem m\u00e4\u00e4ratud karistused t\u00e4hendavad, et UEFA on veelgi valvsam seoses mis tahes p\u00fc\u00fcdlustega reegleid eirata.",
		"tgt": "Past sanctions slapped on PSG means that UEFA will be even more watchful of any attempt to circumvent the rules."
	},
	{
		"src": "Olukorraga tuttavad inimesed s\u00f5nasid neljap\u00e4eval, et UEFA ei ole PSG-ga Neymari \u00fcleminekut ennetavalt arutanud.",
		"tgt": "UEFA has not been in pre-emptive discussions with PSG about Neymar's transfer, people familiar with the situation said Thursday."
	},
	{
		"src": "Nad r\u00e4\u00e4kisid The Associated Pressiga tingimusel, et tagatakse nende anon\u00fc\u00fcmsus, kuna neil ei ole lubatud PSG olukorda arutada.",
		"tgt": "They spoke to The Associated Press on condition of anonymity as they were not authorized to discuss the PSG situation."
	},
	{
		"src": "Viimati avaldatud aruanded n\u00e4itavad, et PSG teenis 2015-2016. aasta hooajal rohkem kui 10 miljonit eurot kasumit ligikaudu 542,4 miljoni euro suuruse k\u00e4ibe juures.",
		"tgt": "The last published accounts show that PSG made a profit of more than 10 million euros in 2015-16 on a turnover of 542.4 million euros."
	},
	{
		"src": "Viimase finantsaasta andmeid ei ole veel avaldatud.",
		"tgt": "Accounts for the last financial year are yet to be published."
	},
	{
		"src": "PSG loodab, et Neymari saabumine m\u00f5jub h\u00e4sti sponsorlustehingutele, kaubastamisele ja s\u00e4rgim\u00fc\u00fcgile.",
		"tgt": "PSG expects Neymar's arrival to be a boon for sponsorship deals, merchandising and jersey sales."
	},
	{
		"src": "Klubi ootab seoses lepingu s\u00f5lmimisega k\u00e4ibe v\u00e4hemalt 30 protsendi suurust kasvu.",
		"tgt": "The club expects turnover would grow by at least 30 percent on the back of the signing."
	},
	{
		"src": "Hispaania liiga, olles selgelt \u00e4rritunud \u00fche suurima jalgpallit\u00e4he lahkumisest, p\u00fc\u00fcdis Neymari \u00fcleminekut takistada, v\u00e4ites, et PSG rikub sellega FFP-d.",
		"tgt": "Clearly irritated to see one of soccer's biggest players leaving, the Spanish league tried to stymie Neymar's move, claiming that PSG will be breaching FFP."
	},
	{
		"src": "\"See on selge \"rahalise dopingu\" juhtum klubi ja riigiga,\" s\u00f5nas La Liga president Javier Tebas Hispaania ajalehele AS, viidates sellele, et PSG kuulub peamiselt Katarile.",
		"tgt": "\"It is a clear case of 'financial doping', with the club and the state,\" La Liga President Javier Tebas told Spanish newspaper AS, referring to Qatar's ultimate ownership of PSG."
	},
	{
		"src": "Arsenali m\u00e4ned\u017eer Arsene Wenger, kelle klubi kuulub Ameerika spordimagnaadile, jagab La Liga hoiakut, et riik rahastab klubi.",
		"tgt": "Arsenal manager Arsene Wenger, whose club is owned by an American sports tycoon, shares La Liga's reservations about a state funding a club."
	},
	{
		"src": "\"See on omandi\u00f5iguste tagaj\u00e4rg ja see on viimase 15 aasta jooksul t\u00e4ielikult kogu jalgpallimaastikku muutnud,\" s\u00f5nas Wenger neljap\u00e4eval.",
		"tgt": "\"It is the consequence of the ownerships and that has completely changed the whole landscape of football in the last 15 years,\" Wenger said Thursday."
	},
	{
		"src": "\"Kui klubi kuulub riigile, on k\u00f5ik v\u00f5imalik.",
		"tgt": "\"Once a country owns a club, everything is possible."
	},
	{
		"src": "V\u00e4ga raske on ausa m\u00e4ngu finantseeskirju austada, kuna riigil v\u00f5ivad olla teised viisid v\u00f5i teised huvid, et selline suur m\u00e4ngija riiki esindaks.\"",
		"tgt": "It becomes very difficult to respect the Financial Fair Play because you can have different ways or different interests for a country to have such a big player to represent a country.\""
	},
	{
		"src": "Norra odavlennufirmal Norwegian on kena traditsioon panna lennukikiilule nende pilte, kes on omas valdkonnas piire nihutanud ja olnud teistele inspiratsiooniks, kirjutab trip.ee",
		"tgt": "Norway\u2019s low-cost carrier Norwegian has a nice tradition of emblazoning their plane rudders with pictures of those who have shifted boundaries in their field and been an inspiration to others, writes trip.ee"
	},
	{
		"src": "Koos Norwegiani tegutsemisgeograafia laienemisega on laienenud ka lennukikiilul koha v\u00e4lja teeninud inimeste ring.",
		"tgt": "Along with the expansion of Norwegian\u2019s operating geography, the range of individuals who have earned a spot on the rudder has also expanded."
	},
	{
		"src": "V\u00e4ljavalitud persoonide seas on n\u00e4iteks Benjamin Franklin, Greta Garbo (pildil) ja Miguel de Cervantes.",
		"tgt": "Among the selected persons are Benjamin Franklin, Greta Garbo (pictured) and Miguel de Cervantes."
	},
	{
		"src": "L\u00e4hiajal hakkab aga \u00fcht lennukit kaunistama Queeni legendaarse laulja Freddie Mercury portree.",
		"tgt": "In the near future, a portrait of legendary Queen singer Freddie Mercury will adorn one plane."
	},
	{
		"src": "T\u00e4na 50 aastat tagasi: orkaanim\u00f5\u00f5tu torm Eestis, mis rebis majadelt katused ja aknad.",
		"tgt": "Fifty years ago today: a storm of hurricane magnitude in Estonia, which tore roofs and windows off houses"
	},
	{
		"src": "Sajandi tormiks nimetatud orkaan, mis m\u00f6llas 6. ja 7. augustil tekitas suuri kahjustusi eelk\u00f5ige L\u00e4\u00e4nemaale, Harjumaale ja Raplamaale.",
		"tgt": "The hurricane, called the storm of the century, which raged on 6 and 7 August, caused major damage above all in L\u00e4\u00e4ne County, Harju County and Rapla County."
	},
	{
		"src": "Loode-Eestis oli nende p\u00e4evade kestel tuule kiiruseks \u00fcle 30 m/s.",
		"tgt": "The wind speed in northwestern Estonia on those days was over 30 m/s."
	},
	{
		"src": "Mu vanamees jooksis aias \u00fche kaarduva puu juurest teise juurde ja katsus k\u00e4tega neid toetada.",
		"tgt": "My husband ran through the garden from one arching tree to the next trying to support them by hand."
	},
	{
		"src": "K\u00f5ik oli pime ja ragises, nagu maailmal\u00f5pp.",
		"tgt": "It was all dark with a rumbling sound, like the end of the world."
	},
	{
		"src": "Taamal lendasid juba majadelt katused, meenutas 2002. aastal vanaproua Linda Kurova Haapsalust ajakirjale Eesti Loodus antud intervjuus.",
		"tgt": "Roofs were already flying off the houses yonder, recalled an older woman, Linda Kurova of Haapsalu, in an interview with the magazine Eesti Loodus in 2002."
	},
	{
		"src": "Linda abikaasa n\u00e4gi, kuidas enda istutatud aed kokku varises.",
		"tgt": "Linda\u2019s husband watched the orchard she\u2019d planted blow down."
	},
	{
		"src": "Aga mis sa ikka puid k\u00e4tega toetad, kus sa sellise tormi vastu saad?",
		"tgt": "But why try to support trees with your arms, what power do you have against such a storm?"
	},
	{
		"src": "Meri tuli akna alla, akendest pritsis vesi sisse\", r\u00e4\u00e4kis Haapsalus Kalda t\u00e4naval elanud proua Linda toona.",
		"tgt": "The storm surge came up to the window, water sprayed in through the windows,\u201d said Ms. Linda, who lived on Kalda Street in Haapsalu back then."
	},
	{
		"src": "Seda, et teed olid puid t\u00e4is ja raudteejaama perrooni katus oli lennanud 20-30 meetri kaugusele, n\u00e4gi Linda enamiku haapsalulaste sarnaselt alles j\u00e4rgmisel hommikul.",
		"tgt": "Like most Haapsalu residents, only the following morning did Linda see how the roads were full of trees and the roof of the railway station platform had flown 20-30 metres away"
	},
	{
		"src": "Kohalike s\u00f5nul olid Paralepa taga puud loogus maas, m\u00f5ned t\u00e4iesti pikali, m\u00f5ned pooleks.",
		"tgt": "Locals said trees behind Paralepa were bowed over so that they were touching the ground, some were completely felled, some snapped in two."
	},
	{
		"src": "K\u00f5ik n\u00e4gi v\u00e4lja v\u00e4ga masendav, torm k\u00e4is ilusatest vanadest puudest ragina ja praginaga l\u00e4bi nagu s\u00f5da.",
		"tgt": "Everything looked really horrible, the storm had ravaged the beautiful old trees much as a war might have done."
	},
	{
		"src": "L\u00e4\u00e4ne-Virumaa ei saanud 1967. aasta augustitormis v\u00f5rreldes L\u00e4\u00e4ne-Eestiga eriti r\u00e4ngalt kannatada, kuid kahjud olid sealgi suured, kirjutas Virumaa Teataja 2007. aastal.",
		"tgt": "Compared to L\u00e4\u00e4ne County, L\u00e4\u00e4ne-Viru County did not sustain particularly severe damage compared to the August storm of 1967, but the losses were high there, too, Virumaa Teataja reported in 2007."
	},
	{
		"src": "Haapsalu Lossipark ja Padise park p\u00fchiti maamunalt, kuid ka meie kandi pargid said tugevalt kannatada.",
		"tgt": "Haapsalu castle park and Padise park were wiped off the face of the earth, but parks in our area also sustained heavy damage."
	},
	{
		"src": "Tallinnas m\u00f5\u00f5deti tuule kiiruseks kuni 35 meetrit sekundis ehk umbes 130 kilomeetrit tunnis.",
		"tgt": "In Tallinn, the wind speed was measured at as much as 35 metres per second \u2013 in other words, about 130 kilometres per hour."
	},
	{
		"src": "Tallinnas Meriv\u00e4ljal oli 6.augusti \u00f5htul \u00fcks pisike plikatirts h\u00fc\u00fcdnud: \"Ema, ema!",
		"tgt": "In the Meriv\u00e4lja part of Tallinn, on 6 August, one tiny slip of a girl was said to have shouted: \u201cMother, mother!"
	},
	{
		"src": "Kanad on \u00f5hus ja ei saa enam alla!\"\", kirjutas Virumaa Teataja.",
		"tgt": "The chickens are in the air and can\u2019t come down anymore,\u201d Virumaa Teataja reported."
	},
	{
		"src": "Viljandimaal asuv P\u00f5lli m\u00f5isa hoone h\u00e4vis tormi ajal niiv\u00f5rd, et see otsustati hiljem lammutada.",
		"tgt": "The P\u00f5lli Manor building in Viljandi County was so badly damaged by the storm that it was decided later to raze it."
	},
	{
		"src": "Augustitormile ei pidanud vastu T\u00fcri suusah\u00fcppem\u00e4e konstruktsioonid, mida hiljem enam ei taastatud.",
		"tgt": "Nor did the T\u00fcri ski jump structures survive the August storm; they were not restored later."
	},
	{
		"src": "Ajaleht Punane T\u00e4ht kirjutas 12. augustil 1967. aastal, et linnade ja asulate koristamine mahalangenud puudest ja nende okstest edeneb aeglaselt, ning elanikud v\u00f5iksid koristust\u00f6\u00f6del kaasa l\u00fc\u00fca.",
		"tgt": "The newspaper Punane T\u00e4ht wrote on 12 August 1967 that cleaning up the cities and towns of fallen trees and branches was going slowly, and residents should pitch in in the cleanup work."
	},
	{
		"src": "Tormis said k\u00f5vasti kannatada ka viljap\u00f5llud, ja ajaleht teatas, et \"parteialgorganisatsioonid peavad olema nii korrastust\u00f6\u00f6del kui ka viljakoristusel innustajaiks ja suunajaiks\".",
		"tgt": "Orchards also suffered severely in the storm and the newspaper reported that \u201cparty organizations must provide inspiration and guidance in both the cleanup and the grain harvest\u201d."
	},
	{
		"src": "Orkaanidest saab r\u00e4\u00e4kida juhul, kui keskmine tuule kiirus \u00fcletab 32,7 m/s.",
		"tgt": "A hurricane is when the average wind speed exceeds 32.7 m/s."
	},
	{
		"src": "Puhangulise tuule rekord Eestis p\u00fcsib 2. novembrist 1969. aastat, mil Ruhnul m\u00f5\u00f5deti tuule kiiruseks 48 m/s.",
		"tgt": "The record for strongest wind gust in Estonia has stood since 2 November 1969, when wind at a speed of 48 m/s was measured on Ruhnu Island."
	},
	{
		"src": "Vaindloo saarel purunes m\u00f5\u00f5teriist, seega ei saanud seal m\u00f5\u00f5detud tugeva tuule kiirust t\u00e4pselt registreerida.",
		"tgt": "The measurement device on Vaindloo Island broke, and thus the precise speed of the strong wind could not be recorded there."
	},
	{
		"src": "Puhaste supelrandade saladus: \u00f6ised koristust\u00f6\u00f6d ja kehv rannailm",
		"tgt": "The secret of clean beaches: nightly cleanup and poor beach weather"
	},
	{
		"src": "K\u00fclmemad suveilmad t\u00e4hendavad ka v\u00e4iksemat koristusvaeva Tallinna supelrandades.",
		"tgt": "The cooler summer weather means less of a need for cleaning on Tallinn\u2019s beaches."
	},
	{
		"src": "\"Kui on ilma, siis on inimesed rannas, ja kui pole, siis pole ka inimesi\", t\u00f5deb ranna koristaja.",
		"tgt": "\u201cIf the weather is good, there are people at the beach, and if it isn\u2019t there are no people,\u201d says beach cleaning person."
	},
	{
		"src": "P\u00f5hja-Tallinna Stroomi rannas kisendavad kajakad.",
		"tgt": "Seagulls shriek at Stroomi Beach in North-Tallinn."
	},
	{
		"src": "Neile pakuvad meloodilist konkurentsi madalatel p\u00f6\u00f6retel p\u00f5risev traktor, mis plaa\u017eile triipe maha k\u00fcnnab.",
		"tgt": "They get some melodic competition from a tractor rumbling in low gear, which is ploughing stripes into the strand."
	},
	{
		"src": "Tegelikult s\u00f5elub viimane seitsme sentimeetri s\u00fcgavuselt liiva l\u00e4bi, korjates sellest v\u00e4lja mereprahti ja inimeste maha j\u00e4etud risu: pudelikorke, sigaretikonisid ja muud.",
		"tgt": "Actually, it is sifting through the top seven centimetres of sand to collect sea debris and rubbish left by people: bottle caps, cigarette butts and other things."
	},
	{
		"src": "Inimesed tulevad ikka randa, olenemata sellest, kas vesi on soe v\u00f5i mitte.",
		"tgt": "People still come to the beach regardless of whether the water is warm or not."
	},
	{
		"src": "Kui on ilus ilm, siis on inimesed rannas, ja kui pole, siis pole ka inimesi\", \u00fctleb osa\u00fchingu Haabersti Haldus ranna koristust\u00f6\u00f6de juhataja Aleksandr Usov.",
		"tgt": "If it\u2019s nice weather, people are at the beach, and if it isn\u2019t, there are no people,\u201d says Aleksandr Usov, the head of cleaning operations for the private company Haabersti Haldus."
	},
	{
		"src": "Kell on 6.30 ja rannas k\u00e4ib kibe koristust\u00f6\u00f6, sest kell kaheksa peab plats olema inimestele korras.",
		"tgt": "It\u2019s 6:30am and clean-up on the beach is in top gear because by eight, he expanse must be in order for the people."
	},
	{
		"src": "Usov on t\u00f6\u00f6postil juba kella neljast.",
		"tgt": "Usov has been on duty since four o\u2019clock."
	},
	{
		"src": "Peale Stroomi hoiab ta silma peal veel Pirita, Harku j\u00e4rve, Kakum\u00e4e ja Paljasaare Pikakari rannal.",
		"tgt": "Besides Stroomi, he also watches over Pirita, Harku Lake, Kakum\u00e4e and Paljassaare Pikakari beach."
	},
	{
		"src": "Pr\u00fcgikogused on v\u00e4henenud.",
		"tgt": "The amounts of rubbish have decreased."
	},
	{
		"src": "Aastaid tagasi oli seda palju rohkem.",
		"tgt": "Years ago, there was a lot more of it."
	},
	{
		"src": "Inimesed oskavad n\u00fc\u00fcd juba hinnata seda, mida nende heaks tehakse\", r\u00e4\u00e4gib Usov, kes on randu koristanud 15 aastat.",
		"tgt": "People are now able to appreciate the good things doe for them,\u201d says Usov, who has been cleaning beaches for 15 years."
	},
	{
		"src": "Enne oli nii, et kui midagi uut sai p\u00fcsti pandud, siis oli see juba j\u00e4rgmine p\u00e4ev katki.",
		"tgt": "In the past, if something new was erected, it was broken the next day."
	},
	{
		"src": "N\u00fc\u00fcd juba hoitakse seda, mis rannas on.",
		"tgt": "Now better care is taken of the things at the beach."
	},
	{
		"src": "Puhta ranna hind",
		"tgt": "The price of a clean beach"
	},
	{
		"src": "\u00dcks suuremaid t\u00f6id Eesti randades on kaldale uhutud merepr\u00fcgi ehk adru koristamine.",
		"tgt": "One of the biggest jobs at Estonian beaches is cleaning up the marine debris that washes ashore \u2013 the algae."
	},
	{
		"src": "N\u00e4iteks Pirita rannas tuleb seda rannahooaja peale \u00e4ra vedada 400 000 tonni.",
		"tgt": "For instance, at Pirita beach, 400,000 tonnes has to be hauled away each beach season."
	},
	{
		"src": "\"See on uskumatu kogus\", m\u00e4rgib Usov.",
		"tgt": "\u201cThat\u2019s an unbelievable amount,\u201d notes Usov."
	},
	{
		"src": "Teise suure kategooria moodustab olmepr\u00fcgi ehk k\u00f5ik see, mille inimesed endast maha j\u00e4tavad.",
		"tgt": "Another major category is ordinary waste \u2013 everything that people leave behind."
	},
	{
		"src": "Poolteisekilomeetrisel Stroomi rannaribal on kaheksa suurt pr\u00fcgikonteinerit, mida on vaja kolm korda n\u00e4dalas t\u00fchjendada.",
		"tgt": "The 1.5-km-long Stroomi beach strand has eight large dumpsters that need to be emptied three times a week."
	},
	{
		"src": "Nii palju tekib pr\u00fcgi.",
		"tgt": "That is how much waste is generated."
	},
	{
		"src": "Siiski, k\u00fclmemad suveilmad on t\u00e4hendanud seda, et pr\u00fcgi on viiendiku v\u00f5rra v\u00e4hem kui muidu.",
		"tgt": "Still, the cooler summer weather has meant that there is one-fifth less waste than otherwise."
	},
	{
		"src": "Kolmanda liigi moodustavad mahaj\u00e4etud asjad.",
		"tgt": "A third category is things left behind."
	},
	{
		"src": "Enamasti on need lastelelud.",
		"tgt": "Most of them are children\u2019s toys."
	},
	{
		"src": "Seekordse saagina on Usov liiva seest v\u00e4lja k\u00fchveldanud k\u00fcmmekond mudelautot.",
		"tgt": "As today\u2019s haul, Usov has shovelled around 10 model cars out of the sand."
	},
	{
		"src": "Need j\u00e4\u00e4vad omanikke ootama randa viivale puitteele.",
		"tgt": "They will be placed on the wooden boardwalk leading to the beach, to await their owners."
	},
	{
		"src": "\"Tavaliselt tuleb neid rohkem v\u00e4lja, aga see on normaalne saak\". Usov juba teab, et varsti leiab ta need uuesti liiva seest.",
		"tgt": "\u201cUsually more of them emerge, but this is a normal yield.\u201d Usov already knows that soon he will find them in the sand again."
	},
	{
		"src": "Lapsed tulevad randa ja v\u00f5tavad m\u00e4nguasjad, et need uuesti liiva sisse uputada.",
		"tgt": "Kids come to the beach and take the toys so they can bury them in the sand again."
	},
	{
		"src": "Pr\u00fcgi kistakse laiali",
		"tgt": "Rubbish is spread around"
	},
	{
		"src": "Haabersti haldusteenuste esindaja Erika Scholler m\u00f6\u00f6nab, et traktori s\u00f5elumist\u00f6\u00f6d h\u00e4irivad kohalikke.",
		"tgt": "Haabersti management services representative Erika Scholler says that the tractor sifting work is a nuisance for locals."
	},
	{
		"src": "M\u00fcra, mis kestab \u00f6\u00f6tundidest varahommikuni, segab naabruses elavate inimeste und.",
		"tgt": "The noise, which lasts from the night hours to early morning, disturbs the sleep of the people living in the neighbourhood."
	},
	{
		"src": "P\u00e4eval on see t\u00f6\u00f6 aga v\u00f5imatu.",
		"tgt": "During the day, the work would be impossible."
	},
	{
		"src": "\u00dches kuus tuleb rand kaks korda l\u00e4bi s\u00f5eluda.",
		"tgt": "In one month, the beach has to be sifted twice."
	},
	{
		"src": "\"Kui me seda ei tee, siis linnaosa trahvib meid\", m\u00e4rgib Scholler.",
		"tgt": "\u201cIf we don\u2019t do it, the city district will fine us,\u201d says Scholler."
	},
	{
		"src": "Kuid eesm\u00e4rk on sarnaselt Pirita, Pikakari ja P\u00e4rnuga saada ka Stroomi rand rahvusvahelise sinilipu kvaliteedim\u00e4rgi alla.",
		"tgt": "But the goal is to get an international blue flag for Stroomi, similarly to Pirita, Pikakari and P\u00e4rnu."
	},
	{
		"src": "\"V\u00f5rreldes Euroopaga on Eestis palju rohkem t\u00f6\u00f6d, et rannad oleksid hooldatud\", \u00fctleb Scholler.",
		"tgt": "\u201cCompared to the rest of Europe, there is a lot more work in Estonia to keep the beaches maintained,\u201d says Scholler."
	},
	{
		"src": "Meil on rohkem adru ja kive ning raskem liiva s\u00f5eluda.",
		"tgt": "We have more seaweed and stones and it is harder to sift through the sand."
	},
	{
		"src": "K\u00fcll aga on meie randades v\u00e4hem pr\u00fcgi kui mujal Euroopas.",
		"tgt": "But we have less trash on our beaches than elsewhere in Europe."
	},
	{
		"src": "Kuuldes, et rannas k\u00f5neldakse pr\u00fcgist, astub Stroomi ranna l\u00e4histel elav Martin sundimatult ajakirjaniku ja koristust\u00f6\u00f6tajate vestlusringi, tuues esile ranna praegused kitsaskohad.",
		"tgt": "Upon hearing talk of trash on the beach, Martin, who lives near Stroomi Beach, joins the conversation between the journalist and cleaning workers, noting the current problem areas for the beach."
	},
	{
		"src": "Hommikuti on igal pool r\u00f5ve pilt.",
		"tgt": "In the morning, it\u2019s a disgusting scene everywhere."
	},
	{
		"src": "Probleem on lindude ja pudelikorjajatega, kes on pr\u00fcgikotid pahupidi t\u00f5mmanud\", teatab Martin.",
		"tgt": "The problem is with the birds and bottle collectors, who have turned the trash bags upside down,\u201d says Martin."
	},
	{
		"src": "Kuigi on raske eeldada, et inimesed suudavad oma seniseid k\u00e4itumisharjumusi muuta, siis Martin loodab, et linnavalitsus v\u00f5tab midagi ette pr\u00fcgikastidega ning paneb neile n\u00e4iteks kaaned peale, takistamaks v\u00e4hemalt lindudel seal uudistamas k\u00e4imas.",
		"tgt": "Although it is a difficult proposition to get people to change their behavioural habits, Martin says he hopes the city government will do something about the waste receptacles and perhaps install lids to keep the birds from poking around there."
	},
	{
		"src": "\u00dcldiselt on Martin siiski Stroomi ranna arenguga rahul.",
		"tgt": "In general, Martin is satisfied with the development of Stroomi Beach."
	},
	{
		"src": "On n\u00e4ha, et linn hoolitseb selle eest.",
		"tgt": "It can be seen that the city is caring for it."
	},
	{
		"src": "Lastev\u00e4ljakute, valgustatud ja v\u00e4rskelt asfalteeritud teedega on see muutunud meeldivamaks.",
		"tgt": "The playgrounds, illuminated and freshly asphalted paths have made it more pleasant."
	},
	{
		"src": "Kunagi oli nii, et rulluiskudel sai vaid \u00fchel teel s\u00f5ita\", m\u00e4rgib Martin.",
		"tgt": "Once upon a time, you could roller-skate only on one path,\u201d says Martin."
	},
	{
		"src": "Aardek\u00fcti leiud Stroomis: m\u00fcndid, ainult m\u00fcndid",
		"tgt": "Treasures found at Stroomi: coins, only coins"
	},
	{
		"src": "Hommikust m\u00f5\u00f5naperioodi on tulnud \u00e4ra kasutama 40aastane Dimitri, kes aardek\u00fctina kammib metallidetektoriga ranna\u00e4\u00e4rt.",
		"tgt": "Forty-year-old Dmitri has come to take advantage of the morning lull, combing the beach fringe with a metal detector as a treasure hunter."
	},
	{
		"src": "Ta ei usu, et t\u00e4na ega ka tulevikus midagi hinnalist leiab.",
		"tgt": "He doesn\u2019t think that he will find anything valuable today or in future."
	},
	{
		"src": "Merejumalad ei ole selleks piisavalt helded.",
		"tgt": "The gods of the sea are not that generous."
	},
	{
		"src": "\"Olen aasta sellega tegelenud ja pole seni midagi v\u00e4\u00e4rtuslikku leidnud\", teatab Dmitri.",
		"tgt": "\u201cI\u2019ve been doing it for a year and I haven\u2019t found anything valuable yet,\u201d Dmitri says."
	},
	{
		"src": "Hobiaardek\u00fctina on Dmitri aardekotis m\u00f5ned eurom\u00fcndid, pudelikorgid ja ka ohtlikud naelad, mis hiljem pr\u00fcgikasti viskab.",
		"tgt": "As an amateur treasure hunter, Dmitri has in his treasure pouch a few euro coins, bottle caps and dangerous nails, which he later throws into the waste bin."
	},
	{
		"src": "Tavaliselt on ikka m\u00fcndid.",
		"tgt": "Usually it\u2019s coins."
	},
	{
		"src": "\"Kulda, s\u00f5rmuseid ja muud s\u00e4\u00e4rast tavaliselt ei ole\", nendib aardek\u00fctt.",
		"tgt": "\u201cThere usually isn\u2019t any gold, rings and suchlike,\u201d the treasure hunter says."
	},
	{
		"src": "Bank of England hoiab intressim\u00e4\u00e4rasid 0,25% juures",
		"tgt": "Bank of England to keep interest rates at 0.25%"
	},
	{
		"src": "Bank of Englandilt oodatakse teadet, et intressim\u00e4\u00e4rad j\u00e4\u00e4vad endisele tasemele, kuna j\u00f5uetu majanduskasv ja inflatsiooni leevenemine on pehmendanud spekulatsioone seoses t\u00f5usuga.",
		"tgt": "The Bank of England is expected to announce later that interest rates will remain unchanged after lacklustre economic growth and easing inflation dampened speculation over a hike."
	},
	{
		"src": "Bank of England on hoiatanud, et majanduskasv p\u00fcsib loiuna, kuna leibkondade pitsitavad sissetulekud on pannud intressim\u00e4\u00e4rad ootele.",
		"tgt": "The Bank of England has warned economic growth will remain \"sluggish\" as it kept interest rates on hold amid a tightening squeeze on family incomes."
	},
	{
		"src": "Panga rahapoliitikakomitee (MPC) poliitikakujundajad h\u00e4\u00e4letasid 6:2 m\u00e4\u00e4rade 0,25% juures hoidmise poolt ja v\u00e4hem liikmeid n\u00f5uab sel kuul t\u00f5usu, kuna aeglane majanduskasv on n\u00f5rgestanud tuge t\u00f5usule.",
		"tgt": "Policymakers on the Bank's Monetary Policy Committee (MPC) voted 6-2 to keep rates at 0.25%, with fewer members this month calling for a rise as lacklustre economic growth has weakened support for a hike."
	},
	{
		"src": "Oma kvartaalses inflatsiooniraportis k\u00e4rpis pank 2017. aasta kasvuprognoosi 1,7% peale ja 2018. aasta oma 1,6% peale ning hoiatas, et surve leibkondade sissetulekutele p\u00fcsib, kuna s\u00fcgisel oodatakse endiselt inflatsiooni t\u00f5usmist 3% l\u00e4hedale.",
		"tgt": "In its quarterly inflation report, the Bank cut its forecasts for growth to 1.7% in 2017 and 1.6% in 2018 and cautioned the squeeze on household incomes would continue, with inflation still expected to surge close to 3% in the autumn."
	},
	{
		"src": "Samas andis pank ka m\u00e4rku, et m\u00e4\u00e4rade kasv on j\u00e4rgmise paari aasta jooksul Brexitist tingitud inflatsiooni ohjeldamiseks tarvilik ja finantsturgudel v\u00f5ib olla vajalik laenukulude ootusp\u00e4rasest k\u00f5rgem t\u00f5us.",
		"tgt": "But it signalled rate hikes will be needed over the next few years to rein in Brexit-fuelled inflation and said borrowing costs may need to rise by more than expected in financial markets."
	},
	{
		"src": "Liikmed h\u00e4\u00e4letasid ka aasta tagasi Brexiti tagaj\u00e4rjel k\u00e4iku lastud majandust turgutava mammutpaketi osalise tagasiv\u00f5tmise poolt.",
		"tgt": "Members also voted to withdraw part of the mammoth economy-boosting package unleashed a year ago in the aftermath of Brexit."
	},
	{
		"src": "Pank l\u00f5petab veebruaris t\u00e4htajalise rahastusskeemi, mis pakub pankadele odavat rahastust, kuigi \u00fctles, et n\u00fc\u00fcd on selle skeemi raames oodata 15 miljardi naela v\u00f5rra suuremat pakkumist, milleks on 115 miljardit naela.",
		"tgt": "It will call time on the Term Funding Scheme to offer cheap-finance to banks from next February, although it said it was now expected to offer \u00a315 billion more under the scheme - at \u00a3115 billion."
	},
	{
		"src": "M\u00e4\u00e4ra suhtes langetatud otsuse protokollides \u00fctleb pank: \"MPC keskprognoosis j\u00e4\u00e4b sisemajanduse koguprodukt (SKP) l\u00e4hitulevikus j\u00f5uetuks, kuna leibkondade reaalsete sissetulekute raske olukord avaldab ka edaspidi tarbimisele m\u00f5ju.\"",
		"tgt": "In minutes of the rates decision, the Bank said: \"In the MPC's central forecast, gross domestic product (GDP) remains sluggish in the near-term as the squeeze on households' real incomes continues to weigh on consumption.\""
	},
	{
		"src": "M\u00e4\u00e4rade kohta korrati, et inflatsiooni leevendamiseks on vajalik \"rahanduspoliitika m\u00f5ningane pingule t\u00f5mbamine\" ja seda \"m\u00f5nev\u00f5rra suuremas\" ulatuses, kui turgudel on oodatud.",
		"tgt": "On rates, it reiterated that \"some tightening of monetary policy\" would be needed to cool inflation and by a \"somewhat greater\" extent than markets expect."
	},
	{
		"src": "B\u00f6rs ennustab praegu esimest t\u00f5usu j\u00e4rgmise aasta kolmandas kvartalis ja teist t\u00f5usu aastal 2020.",
		"tgt": "Markets are currently forecasting the first rise in the third quarter of next year and another in 2020."
	},
	{
		"src": "Kuid pank r\u00f5hutas, et igasugused h\u00fcpped on astmelised ja piiratud.",
		"tgt": "But the Bank stressed that any hikes would be \"gradual\" and \"limited.\""
	},
	{
		"src": "Panga v\u00e4hendatud kasvuprognoosid selleks ja j\u00e4rgmiseks aastaks on v\u00f5rreldavad maikuu prognoosidega 1,9% ja 1,7%.",
		"tgt": "The Bank's downgraded growth forecasts for this year and next compare with the 1.9% and 1.7% predicted in May."
	},
	{
		"src": "2018. aasta 1,8-protsendilise kasvu prognoos j\u00e4i p\u00fcsima.",
		"tgt": "It maintained its forecast for growth of 1.8% in 2018."
	},
	{
		"src": "P\u00e4rast seda uudist langes naela kurss dollari ja euro suhtes.",
		"tgt": "Sterling fell against the dollar and the euro following the news."
	},
	{
		"src": "Nael langes 0,5% 1,31 USA dollarini ja 0,4% 1,11 euroni.",
		"tgt": "The pound was 0.5% down at 1.31 US dollars and fell 0.4% to 1.11 euros."
	},
	{
		"src": "Otsus muudatusi mitte teha on tingitud hiljutistest pettumust valmistavatest kasvun\u00e4itajatest, mis on summutanud kasvavaid lootusi seoses t\u00f5usuga \u0096 SKP t\u00f5usis teises kvartalis eelmise kolme kuu 0,2% pealt 0,3% peale.",
		"tgt": "The no-change decision comes after recent disappointing growth figures have dampened mounting expectations of a hike, with GDP edging up to 0.3% in the second quarter from 0.2% in the previous three months."
	},
	{
		"src": "Pank \u00fctleb, et kasv p\u00fcsib kolmandas kvartalis t\u00f5en\u00e4oliselt 0,3% juures, kuigi aasta l\u00f5pus hakkab see veidi hoogu koguma.",
		"tgt": "Growth is likely to remain at 0.3% in the third quarter, although it will start to pick up slightly at the end of the year, according to the Bank."
	},
	{
		"src": "Panga v\u00e4rskeim inflatsiooniraport andis t\u00f5usva inflatsiooni ja armetu palgat\u00f5usu k\u00e4es kannatavatele leibkondadele r\u00f5\u00f5mustamiseks v\u00e4he p\u00f5hjust, \u00f6eldes, et olukord l\u00e4heb enne paranemist veel natuke halvemaks.",
		"tgt": "Its latest inflation report offered little cheer for households being hit by soaring inflation and paltry pay rises as it said the squeeze will get worse before it gets better."
	},
	{
		"src": "Lisati, et rahapoliitikaga ei saa hoida \u00e4ra j\u00e4rgmisel paaril aastal sissetulekuid tabavat l\u00f6\u00f6ki, aga kolmeaastase prognoosi l\u00f5pu poole oodatakse palkade m\u00e4rgatavat taastumist.",
		"tgt": "It added that monetary policy \"cannot prevent\" the hit to incomes over the next few years, but expects wages will recover \"significantly\" towards the end of its three-year forecast."
	},
	{
		"src": "N\u00f5rga naela t\u00f5ttu ergutab majandust ka kasvav n\u00f5udlus Briti toodangu j\u00e4rele, mis h\u00fcvitab osaliselt tarbijate v\u00e4iksemaid kulutusi.",
		"tgt": "The economy is also set for a boost from surging demand for British goods thanks to the weak pound, which will offset some of the lower consumer spending."
	},
	{
		"src": "Otsus tuleb aasta p\u00e4rast seda, kui m\u00e4\u00e4rad viidi m\u00f6\u00f6dunud augustis 0,25% peale p\u00e4rast \u0161okeerivat EL-i referendumit, mis p\u00f5hjustas naela \u00e4kilise n\u00f5rgenemise.",
		"tgt": "The decision comes a year after rates were cut to 0.25% last August following the shock EU referendum vote, which sent the pound slumping."
	},
	{
		"src": "Panga hinnangul kulub t\u00f5en\u00e4oliselt neli aastat, et hindadele ja majandusele t\u00e4ielikult elu sisse puhuda.",
		"tgt": "The Bank estimates it will likely take four years to fully feed through to prices and the economy."
	},
	{
		"src": "Enne panga viimast otsust oli tunda kasvavat n\u00f5udlust m\u00e4\u00e4ra t\u00f5stmise j\u00e4rele, kuna inflatsioon oli suurendanud survet kitsikuses leibkondadele; juulis n\u00f5udsid kolm poliitikakujundajat m\u00e4\u00e4ra t\u00f5stmist 0,5% peale.",
		"tgt": "Prior to the Bank's latest rates verdict, there had been growing clamour for a rate rise as inflation ramped up pressure on hard-pressed households, with three policymakers calling for an increase to 0.5% in July."
	},
	{
		"src": "Inflatsioon langes eelmisel kuul 2,6% peale, v\u00f5rreldes juuni 2,9%-ga, kuigi panga s\u00f5nutsi oli see ootusp\u00e4rane ja j\u00e4rgmistel kuudel ootab taas ees t\u00f5us.",
		"tgt": "Inflation eased back to 2.6% last month from 2.9% in June, although the Bank said this was expected and will pick up once again over the coming months."
	},
	{
		"src": "Pank \u00fctles, et liigne kasv v\u00f5rreldes 2-protsendilise eesm\u00e4rgiga oli tingitud t\u00e4ielikult n\u00f5rgast naelast.",
		"tgt": "The Bank said the overshoot relative to its 2% target was \"entirely\" down to the weak pound."
	},
	{
		"src": "Coreco h\u00fcpoteegimaaklerite juht Andrew Montlake \u00fctles: \"Vahetuskursside hiljutist langust arvestades tundub, et h\u00fcpoteegiturg muutub taas aina konkurentsiv\u00f5imelisemaks, kuna laenuandjad ihkavad t\u00f6\u00f6d ja loodavad l\u00f5petada aasta positiivselt.",
		"tgt": "Andrew Montlake, director at Coreco Mortgage Brokers, said: \"Given the recent fall in swap rates, the mortgage market looks set to become ever more competitive once more as lenders clamour for business and look to end the year in positive fashion."
	},
	{
		"src": "B\u00f6rs n\u00e4ib eriti soodne neile, kelle kehtivad tehingud hakkavad l\u00f5pule j\u00f5udma, kuna refinantseerimine, sageli teenustasuta ja madala m\u00e4\u00e4raga, on muutunud \u00fcha populaarsemaks.\"",
		"tgt": "The market looks particularly good for those who may be coming to the end of their existing deals as re-mortgages, many with fee-free options as well as low rates, become ever more popular.\""
	},
	{
		"src": "NHS on kirjutamas 10 000 inimesele v\u00e4lja vastuolu tekitanud HIV ravimit",
		"tgt": "NHS to prescribe controversial HIV drug to 10,000"
	},
	{
		"src": "Patsientidel on alates septembrist juurdep\u00e4\u00e4s \"transformatiivsele\" HIV-d ennetavale ravile p\u00e4rast \u00fclemkohtus maha peetud lahingut selle \u00fcle, kas NHS peaks ravimit rahastama.",
		"tgt": "Patients will be able to access a 'transformative' HIV prevention treatment from September following a High Court battle over funding the drug on the NHS."
	},
	{
		"src": "NHS England teatas, et riiklik tervishoid teeb n\u00fc\u00fcd algse kolmeaastase kliinilise katse v\u00e4ltel hinnanguliselt 10 000 inimesele k\u00e4ttesaadavaks kokkupuute-eelse prof\u00fclaktika (PrEP) - tableti, mida manustatakse enne vahekorda ja mis on n\u00e4idanud k\u00f5rge riskiga inimeste puhul nakatumisohu v\u00e4henemist ligikaudu 86% v\u00f5rra.",
		"tgt": "NHS England announced that pre-exposure prophylaxis (PrEP), a pill taken before sex which has been shown to reduce the risk of infection in high-risk individuals by around 86 per cent, will now be provided by the health service through an initial three-year trial to an estimated 10,000 people."
	},
	{
		"src": "NHS n\u00f5ustus rahastama kliinilist katset p\u00e4rast seda, kui apellatsioonikohus toetas \u00fclemkohtu eelmise aasta otsust, mille kohaselt on NHS v\u00f5imeline PrEP-i eest maksma, hoolimata asutuse enda v\u00e4idetest, et ravimit peaksid rahastama hoopis kohalikud omavalitsused.",
		"tgt": "It agreed to fund the trial after the Court of Appeal upheld a High Court ruling last year, which said the NHS had the power to pay for PrEP despite its claims that local authorities should fund it."
	},
	{
		"src": "NHS Englandi tegevjuhataja Simon Stevens tervitas seda neljap\u00e4eval avalikustatud k\u00e4iku kui \"uut ulatuslikku sekkumist\", samal ajal kui riiklik aidsifond (NAT) kirjeldas seda \"p\u00f6\u00f6rdelise hetkena\".",
		"tgt": "The move announced on Thursday was hailed as a 'major new intervention' by NHS England chief executive Simon Stevens while the National Aids Trust (NAT) described it as a 'pivotal moment'."
	},
	{
		"src": "Seksuaaltervise kliinikud Londonis, Brightonis, Manchesteris, Liverpoolis ja Sheffieldis on esimeste hulgas, kes hakkavad inimesi registreerima. Oktoobris lisandub veelgi kliinikuid, enne kui programm 2018. aasta aprilliks Inglismaal k\u00f5ikjal juurutatakse.",
		"tgt": "Sexual health clinics in London, Brighton, Manchester, Liverpool and Sheffield will be among the first to start enrolling people, with more clinics joining in October before full implementation across England by April 2018."
	},
	{
		"src": "Kokkupuute-eelne prof\u00fclaktika (PrEP) on HIV ravimite kuur, mida v\u00f5etakse enne vahekorda, et v\u00e4hendada HIV-sse nakatumise ohtu.",
		"tgt": "Pre-exposure prophylaxis (PrEP) is a course of HIV drugs taken before sex to reduce the risk of getting HIV."
	},
	{
		"src": "Kliiniliste katsete tulemused n\u00e4itavad, et PrEP v\u00e4hendab m\u00e4rgatavalt HIV edasikandumist nakatumisohuga inimeste hulgas.",
		"tgt": "Trials have shown PrEP significantly reduces HIV transmission among those at-risk of infection."
	},
	{
		"src": "PrEP-i v\u00f5tmine enne vahekorda t\u00e4hendab, et inimese kehas on piisaval hulgal teatud ravimeid, mis takistavad HIV-sse nakatumist.",
		"tgt": "Taking PrEP before sex means there is just enough of certain drugs in a person's body to prevent an HIV infection taking hold."
	},
	{
		"src": "Selliseid ravimeid v\u00f5ib v\u00f5tta iga p\u00e4ev v\u00f5i hiljemalt kaks tundi enne vahekorda.",
		"tgt": "Such drugs can be taken every day or as soon as two hours before having sex."
	},
	{
		"src": "Raviks sobilike kandidaatide hulka kuuluvad homo- v\u00f5i biseksuaalsed mehed, transsoolised inimesed ja inimesed, kelle partnerid on HIV-sse nakatunud ega saa ravi.",
		"tgt": "Those eligible for the treatment include gay or bisexual men, transgender people and those with HIV-positive partners who are not successfully receiving treatment."
	},
	{
		"src": "Kliinikud tuvastavad sobilikud inimesed, kes on n\u00f5us kliinilises katses osalema, sh mehed, naised, transsoolised inimesed ja need, kelle HIV-d p\u00f5dev partner ei saa antiretroviirusravi.",
		"tgt": "Clinics will identify eligible participants who consent to the trial, including men, women, transgender people, and individuals who have a partner whose HIV status is not known to be controlled by anti-retroviral treatment."
	},
	{
		"src": "Inimesed, kes elavad Inglismaal ja on valinud endale seal perearsti, saavad programmis osalevas kohalikus seksuaaltervise kliinikus samuti oma osalemissoovi registreerida.",
		"tgt": "People living and registered with a GP in England will also be able to enrol for potential participation at their local participating sexual health clinic."
	},
	{
		"src": "Programm maksab 10 miljonit naela ja NHS England allkirjastas lepingu, et saada ravimid sel n\u00e4dalal p\u00e4rast rahvusvahelist hankemenetlust k\u00e4tte.",
		"tgt": "The programme will cost \u00a310 million and NHS England signed a contract to source the drugs this week following an international competitive procurement."
	},
	{
		"src": "Kliinilise katse eesm\u00e4rk on hinnata PrEP-i tegelikku potentsiaali, kogudes kliinilisi t\u00f5endeid selle kohta, kellele ravim m\u00f5eldud on ning kuidas seda suures pildis tarbitakse ja rakendatakse.",
		"tgt": "The trial is designed to assess the full potential of PrEP by gathering clinical evidence on how it is targeted, taken up, and implemented on a large scale."
	},
	{
		"src": "Stevens \u00fctles: \"See uus ulatuslik sekkumine peaks t\u00e4iendama ja v\u00f5imendama laiaulatuslikku ja aina edukamat HIV leviku vastast v\u00f5itlust.",
		"tgt": "Mr Stevens said: 'This major new intervention should complement and supercharge the wide-ranging and increasingly successful effort to prevent HIV."
	},
	{
		"src": "See on j\u00e4rjekordne verstapost rohkem kui kolme aastak\u00fcmne pikkuses v\u00f5itluses inimkonna \u00fche suurima terviseprobleemiga.\"",
		"tgt": "It's another milestone in more than three decades' worth of progress in tackling one of humanity's major health challenges.'"
	},
	{
		"src": "Deborah Gold, NAT-i tegevjuhataja, \u00fctles: \"See on p\u00f6\u00f6rdeline hetk HIV-vastases v\u00f5itluses.",
		"tgt": "Deborah Gold, chief executive at NAT (National Aids Trust), said: 'This is a pivotal moment in the fight against HIV."
	},
	{
		"src": "PrEP, kui seda sihitakse korrektselt neile, kes seda vajavad ja kuuluvad riskigruppi, pakub v\u00f5imalust muuta Inglismaa HIV-epideemiat.",
		"tgt": "PrEP, if targeted properly at those in need and at risk, offers the possibility of transforming the English HIV epidemic."
	},
	{
		"src": "Alates septembrist on suure HIV-riskiga inimestel Inglismaal selle NHS-i rahastatud kliinilise katse kaudu juurdep\u00e4\u00e4s v\u00f5imsale uuele t\u00f6\u00f6riistale, mis on individuaalselt hallatav ega s\u00f5ltu l\u00e4bir\u00e4\u00e4kimistest partneriga, parandades seel\u00e4bi paljusid elusid.",
		"tgt": "From September, people at high risk of HIV will have access via this NHS-funded trial in England to an empowering new tool that is truly individually controlled and not subject to negotiation with a partner, leading to the improvement of many, many lives."
	},
	{
		"src": "Me tervitame seda teadaannet soojalt.\"",
		"tgt": "We warmly welcome this announcement.'"
	},
	{
		"src": "Terrence Higginsi fondi tegevjuht Ian Green \u00fctles: \"N\u00fc\u00fcd on esmat\u00e4htis tagada, et kliiniline katse \u00fcle riigi kiirelt k\u00e4ima l\u00fckataks ja et mitte \u00fckski HIV riskir\u00fchma kuuluja ei j\u00e4\u00e4ks k\u00f5rvale.",
		"tgt": "Ian Green, chief executive of the Terrence Higgins Trust, said: 'The priority must now be to make sure that the trial is rolled out speedily across the country, and that no-one at risk of HIV is left behind."
	},
	{
		"src": "N\u00fc\u00fcd, mil PrEP-i kliinilise katse ravim on hangitud, oleme teel sinnapoole, et kaitsta rohkem kui 10 000 inimest, kellel on oht HIV-sse nakatuda.",
		"tgt": "Now that the PrEP trial drug has been procured, we're well on the way to protecting over 10,000 people at risk of HIV.'"
	},
	{
		"src": "Rahvatervise variminister Sharon Hodgson \u00fctles: \"PrEP-i kliinilise katse algus on v\u00e4ga teretulnud ja k\u00f5vasti hilinenud p\u00e4rast kuudepikkusi viivitusi ja valitsuse jalgade lohistamist.",
		"tgt": "Shadow public health minister Sharon Hodgson said: 'The start of the PrEP trial is welcome and long overdue after months of delays and heel-dragging by the Government."
	},
	{
		"src": "T\u00f5endid n\u00e4itavad, kui suuri muutusi v\u00f5ib see ravim tuua HIV ennetamist\u00f6\u00f6se ja selle elumuutva nakkuse leviku l\u00f5petamisse.",
		"tgt": "The evidence shows just how transformative this drug can be as part of our approach to HIV prevention and ending the transmission of this life-changing infection."
	},
	{
		"src": "See kliiniline katse viib meid sammu v\u00f5rra l\u00e4hemale PrEP-i eeliste t\u00e4ielikule m\u00f5istmisele.",
		"tgt": "This trial will take us one step closer to fully understanding the benefits of PrEP."
	},
	{
		"src": "N\u00fc\u00fcd on t\u00e4htis, et kliiniline katse v\u00f5etaks \u00fcle riigi v\u00f5imalikult kiiresti kasutusele, et kaitsta inimesi, kellel on kokkupuude HIV-ga, ja viia meid sammukese v\u00f5rra l\u00e4hemale HIV leviku peatamisele \u00fchiskonnas.\"",
		"tgt": "Now it is important that this trial is rolled out as quickly as possible across the country to protect individuals who are exposed to HIV and help take us one step closer to ending the spread of HIV in society.'"
	},
	{
		"src": "Elektri hind t\u00f5usis Eestis 12%, L\u00e4tis ja Leedus aga langes.",
		"tgt": "The price of electricity rose 12% in Estonian, while it dropped in Latvia and Lithuania."
	},
	{
		"src": "Juulikuus v\u00e4henes elektri j\u00e4rgmise p\u00e4eva b\u00f6rsihinna erinevus Eesti ning L\u00e4ti ja Leedu hinnapiirkondade vahel 1,94 euroni, v\u00f5rreldes 7,71 euroga t\u00e4navu juunis, teatas Elering.",
		"tgt": "In July, the difference in the next-day exchange process of power in the Estonia and Latvia and Lithuania bidding area decrease to 1.94 euros, compared to 7.71 euros this June, Elering announced."
	},
	{
		"src": "Hinnaerinevuse peamiseks p\u00f5hjuseks on Leedu-Rootsi \u00fchenduse rikked.",
		"tgt": "The main reason for the price difference was faults in the Lithuania-Sweden connection."
	},
	{
		"src": "Eestis kujunes elektri keskmiseks b\u00f6rsihinnaks eelmisel kuul 34,33 eurot megavatt-tunnist ja hind kerkis juuniga v\u00f5rreldes 12 protsenti.",
		"tgt": "In Estonia, the average power exchange price of electricity last month shaped up to be 34.33 euros per megawatt-hour and the price rose by 12% compared to June."
	},
	{
		"src": "L\u00e4tis ja Leedus langes hind viie protsendi v\u00f5rra 36,27 euroni megavatt-tunnist.",
		"tgt": "In Latvia and Lithuania, the price fell by five per cent to 36.27 euros per megawatt-hour."
	},
	{
		"src": "Soomes oli hind 34,17 eurot ja elektrib\u00f6rsi Nord Pool s\u00fcsteemihind oli samas 26,37 eurot megavatt-tunni kohta.",
		"tgt": "In Finland, the price was 34.17 euros and the system price on Nord Pool power exchange was 26.37 euros per megawatt-hour."
	},
	{
		"src": "Hinnad t\u00f5usid vastavalt 12 ja seitse protsenti.",
		"tgt": "Prices rose 12 and seven per cent, respectively."
	},
	{
		"src": "Eesti ja Soome vahel liikus elekter 75 protsendil eelmise kuu tundidest Eesti suunal ja 16 protsendil tundidest Eestist Soome.",
		"tgt": "Between Estonia and Finland, electricity flowed to Estonia in 75% of the hours last month and from Estonia to Finland in 16% of the hours."
	},
	{
		"src": "\u00dclej\u00e4\u00e4nud \u00fcheksal protsendil tundidest kahe riigi vahel j\u00e4rgmise p\u00e4eva tehinguid ei toimunud.",
		"tgt": "During the remaining nine per cent of the hours, no next-day transactions took place between the two countries."
	},
	{
		"src": "Eesti ja L\u00e4ti vahel liikus elekter 99 protsendil ajast Eestist L\u00e4tti ja 73 protsendil tundidest oli kasutuses kogu \u00fclekandev\u00f5imsus.",
		"tgt": "Between Estonia and Latvia, electricity flowed from Estonia to Latvia 99% of the time and during 73% of the hours, the entire transmission capacity was in use."
	},
	{
		"src": "Juuli viimasel kauplemisp\u00e4eval toimunud tehingute j\u00e4rgi Nasdaq OMX turul v\u00f5ib augustis elektri b\u00f6rsihinnaks kujuneda ligikaudu 34 ja septembris 37 eurot megavatt-tunnist.",
		"tgt": "According to the transactions executed on the last trading day in July on the Nasdaq OMX market, the power exchange price electricity may end up being around 34 and in September 37 euros per megawatt-hour."
	},
	{
		"src": "Elektri tootmishinda m\u00f5jutava s\u00fcsinikdioksiidi hind kerkis eelmisel kuul ning tehingud toimusid hinnaga 5,04-5,47 eurot tonni kohta.",
		"tgt": "The price of carbon dioxide, which impacts the power generation price, rose last month and transactions were conducted at a price of 5.04 to 5.47 euros per tonne."
	},
	{
		"src": "K\u00f5rgelu elamine - poolkorrus ja nutikad disaininipid on muutnud selle v\u00e4ikse Earls Courti korteri ruumikaks koduks",
		"tgt": "Living the high life: mezzanine floor and clever design tricks have transformed this small Earls Court flat into a spacious home"
	},
	{
		"src": "Joanne Leigh, endine pankur, kes on kirglik kinnisvarauuendaja, vahetas oma suure Knightsbridge'i kodu 2014. aastal Earls Courti korteri vastu.",
		"tgt": "Joanne Leigh, a former banker with a passion for doing up property, downsized from a large home in Knightsbridge to an Earls Court apartment in 2014."
	},
	{
		"src": "See asub Queen Anne Terrace'i esimesel korrusel ning see, et Joanne ei ole oma kotte kokku pakkinud ja korterit edasi m\u00fc\u00fcnud, on austusavaldus uuele disainile.",
		"tgt": "It is on the first floor of a smart Queen Anne terrace - and it is a testament to the new design that Joanne hasn't packed her bags and sold on."
	},
	{
		"src": "\"Enne seda elasin koos endise elukaaslasega Knightsbridge'is palju suuremal pinnal,\" s\u00f5nas Joanne.",
		"tgt": "\"Before this, I was living with my ex in Knightsbridge in a much bigger space,\" Joanne says."
	},
	{
		"src": "\"Otsisin midagi, mis oleks minu pakutava hinna eest samav\u00e4\u00e4rne.",
		"tgt": "\"I was looking for something that was comparable for my price."
	},
	{
		"src": "Mulle n\u00e4idati seda Earls Courti korterit ja sellel olid samasugused k\u00f5rged laed.",
		"tgt": "I was shown this apartment in Earls Court and it had the same high ceilings."
	},
	{
		"src": "Ma armusin sellesse ja tegin samal p\u00e4eval pakkumise.\"",
		"tgt": "I fell in love with it and put an offer in that day.\""
	},
	{
		"src": "Alates esimesest k\u00fclastusest on see 93-ruutmeetrine korter l\u00e4binud t\u00e4ieliku uuenduskuuri.",
		"tgt": "Since the first viewing, the 1,000sq ft flat has had a complete overhaul."
	},
	{
		"src": "Alguses oli see \u00fche magamistoa ja keeruka paigutusega korter - magamistuppa j\u00f5udmiseks tuli k\u00f5ndida l\u00e4bi k\u00f6\u00f6gi. Joanne soovis lisada hoiuruumi ja poolkorruse, et kasutada \u00e4ra k\u00f5rgeid lagesid.",
		"tgt": "Originally a one-bedroom property with a convoluted layout - you had to walk through the kitchen to get to the bedroom - Joanne wanted to add storage space and a mezzanine to make the most of the generous ceiling height."
	},
	{
		"src": "\"Ma soovisin k\u00f5rgeid lagesid, suuri aknaid, palju valgust.",
		"tgt": "\"I wanted high ceilings, big windows, lots of light."
	},
	{
		"src": "Need olid mu n\u00f5udmised,\" \u00fctles ta.",
		"tgt": "That was my requirement,\" she says."
	},
	{
		"src": "Ta palkas Erfan Azadi Notting Hillis tegutsevast arhitektuuri- ja disainistuudiost Duck & Shed, et kasutada \u00e4ra 3,8 m k\u00f5rguseid lagesid ja luua kodu, mis ei oleks lihtsalt arendusobjekt, vaid koht, kus Joanne saaks elada.",
		"tgt": "To this end, she employed Erfan Azadi of Notting Hill-based architecture and design studio Duck & Shed to exploit the 12.5ft ceilings and create a home that wasn't only a development but a place for Joanne to live."
	},
	{
		"src": "Lagi ei olnud piisavalt k\u00f5rge, et lisada kaks ruumi \u00fcksteise peale, seega oli arhitektuuriline v\u00e4ljakutse luua poolkorrus, kus saaks p\u00fcsti seista.",
		"tgt": "The ceiling wasn't quite tall enough to add two spaces on top of each other so the architectural challenge was to create a mezzanine that you could stand up in."
	},
	{
		"src": "Erfan pidi l\u00e4henema asjale loominguliselt.",
		"tgt": "Erfan had to think creatively to resolve the brief."
	},
	{
		"src": "\"Metallkonstruktsioon on \u00fcsna keerukas,\" selgitab ta.",
		"tgt": "\"The steelwork is quite complicated,\" he explains."
	},
	{
		"src": "\"Pidime ruumid \u00fcmber korraldama, nii et need paikneksid \u00fcksteise peal, ilma et peaks kummarduma.",
		"tgt": "\"We had to arrange the spaces so that they stacked on top of each other without needing to hunch down."
	},
	{
		"src": "Tegemist ei olnud lihtsalt platvormi ehitamisega, vaid kasutasime teraskonstruktsiooni, et nii \u00fclemise kui ka alumise ruumi k\u00f5rgus oleks \u00f5ige.\"",
		"tgt": "It wasn't just building a simple platform, but cranking the steels so that they were at the right height for the function above or below.\""
	},
	{
		"src": "See asetus v\u00f5imaldas Erfanil tekitada ruumis \u00fcksteise peale kaks t\u00e4isk\u00f5rgusega tuba koos rohkelt dramaatiliste elementidega.",
		"tgt": "This arrangement allowed Erfan to get two full-height rooms on top of each other in the space - with lots of added drama."
	},
	{
		"src": "Poolkorruselt avaneb vanaaegsest vaskse valgusega Retrouviuse aknast vaade all asuvale glamuursele eluruumile.",
		"tgt": "For the mezzanine, a vintage copper light window from Retrouvius looks down over the glamorous living area below."
	},
	{
		"src": "Peegelpinnaga kuldne m\u00f6\u00f6bel, h\u00f5bedased detailid ja retroh\u00f5nguline Serge Mouille' valgusti r\u00f5hutavad ruumi stiili.",
		"tgt": "Mirrored gold furniture, silver accents and vintage Serge Mouille lighting all set the style for the scheme."
	},
	{
		"src": "Peeglite kasutamine m\u00e4ngib rolli teatraalsuse, ruumikuse ja valgusk\u00fcllasuse lisamisel.",
		"tgt": "The use of mirrors plays a part in adding theatre, space and light."
	},
	{
		"src": "L\u00fchikese koridori m\u00f5lemasse otsa on lisatud peeglid, et see tunduks pikem.",
		"tgt": "A short corridor is mirrored at both ends to make it appear longer."
	},
	{
		"src": "K\u00f6\u00f6gis j\u00e4tab peegliga tagasein teise tuppa avaneva akna mulje.",
		"tgt": "In the kitchen, the mirrored splashback feels like a window to another room."
	},
	{
		"src": "Sissek\u00e4igu juures pakub peegelkapp hoiukohta k\u00f5igile Joanne'i s\u00f6\u00f6giriistadele ja klaasn\u00f5udele.",
		"tgt": "At the entrance, mirrored units provide storage for all Joanne's cutlery and glassware."
	},
	{
		"src": "Elutoale lisab v\u00f5lu v\u00f5imalus k\u00f6\u00f6giosa sulgeda, kui seda ei kasutata, tekitades kujutluse glamuursemast ruumist.",
		"tgt": "Giving the perception of a more glamorous space, the beauty of the living room is being able to close off the kitchen when it's not in use."
	},
	{
		"src": "Kokkuklapitavad k\u00f6\u00f6gid ei ole midagi uut.",
		"tgt": "Foldaway kitchens are nothing new."
	},
	{
		"src": "Selle k\u00f6\u00f6gi juures on aga unikaalne asjaolu, et tegemist on garaa\u017ei t\u00fc\u00fcpi \u00fclest\u00f5stetava uksega.",
		"tgt": "What's unique about this one is that it's a garage-style lift-up door."
	},
	{
		"src": "\"Sellesse l\u00e4ks pisut projekteerimisvaeva,\" selgitab Erfan terastugevdusega spoonitud MDF-ist ust.",
		"tgt": "\"A bit of engineering went into that,\" explains Erfan of the steel-reinforced, veneered MDF door."
	},
	{
		"src": "\"Sellel on vastukaal, mist\u00f5ttu see liugleb v\u00e4ga lihtsalt, kui see \u00fcles l\u00fckata.\"",
		"tgt": "\"It's counter-weighted so that when you push the door up, it glides really easily.\""
	},
	{
		"src": "T\u00e4nu ruumi ja hoiuruumi nutikale kasutamisele on Joanne'il n\u00fc\u00fcd 16 lisaruutmeetrit, t\u00e4iendav magamistuba ning parem korteriplaan.",
		"tgt": "Thanks to clever use of space and storage, Joanne gained an additional 16sq m, an extra bedroom and an improved layout."
	},
	{
		"src": "\"L\u00f5ppude l\u00f5puks on p\u00f5randapind see, mida sa m\u00fc\u00fcd - v\u00f5i see, mis annab kinnisvarale v\u00e4\u00e4rtuse,\" s\u00f5nab Erfan.",
		"tgt": "\"At the end of the day, floor space is what you are going to sell - or how your property is valued,\" Erfan says."
	},
	{
		"src": "\"Kinnisvaramaakler astub aegunud vormis tuppa ja teeb arvutusi, tuginedes p\u00f5randa pindalale.\"",
		"tgt": "\"In a rudimentary form, a real estate agent will walk in and do a calculation based on floor size.\""
	},
	{
		"src": "Siin on nad suutnud p\u00f5randapinda suurendada, kasutades seejuures kvaliteetseid materjale, mis lisavad ruumile luksuslikkust.",
		"tgt": "Here they have managed to increase the floor space while using quality materials that give the space its luxurious edge."
	},
	{
		"src": "\"Materjalid on need, mida sa puudutad ja mis aitavad seel\u00e4bi koduga emotsionaalse sideme tekitada,\" \u00fctleb Erfan.",
		"tgt": "\"The materials are the things that you touch and therefore help to create an emotional bond in a home,\" says Erfan."
	},
	{
		"src": "\"Sa ei armu seinas olevasse elektrikaabeldusse.",
		"tgt": "\"You don't fall in love with the electrical feeds in the walls."
	},
	{
		"src": "See on t\u00e4htis, kuid ei pane s\u00fcdame keeli helisema.\"",
		"tgt": "These are important but they don't pull the heart strings.\""
	},
	{
		"src": "See n\u00e4itab, et hea disain ja suurendatud pindala aitavad teha \u00fcsna tavalisest korterist midagi h\u00e4mmastavat.",
		"tgt": "It goes to show that through good design and increased square metreage, a flat can turn from something standard into something quite amazing."
	},
	{
		"src": "Tegelikult v\u00f5ivad need lausa tekitada soovi mitte lahkuda, nagu juhtus Joanne'iga.",
		"tgt": "In fact, like Joanne, you may choose not to leave."
	},
	{
		"src": "Peategelane Dane Jensen on Chicago pilvel\u00f5hkujas tegutsev pearahak\u00fctt, kes v\u00f5istleb kolleegiga ametik\u00f5rgenduse p\u00e4rast.",
		"tgt": "The lead character Dane Jensen is a head hunter working in a Chicago skyscraper who is competing with co-workers for a promotion."
	},
	{
		"src": "Ei loe muu kui teenitud rahasumma, mille k\u00f5rval ununeb igasugune eetika.",
		"tgt": "The only thing that matters for him is how much he earns, and all ethical considerations fall by the wayside."
	},
	{
		"src": "Oma naist ja kolme last n\u00e4eb mees vaid varahommikul ja hilis\u00f5htul.",
		"tgt": "He sees his wife and three kids only early in the morning and late at night."
	},
	{
		"src": "Filmi esimeses pooles taban ennast m\u00f5ttelt, et see on ju \"Kaardimaja\" \u00e4rimaailma versioon - isegi Kevin Spacey ja Gerard Butleri k\u00f5nemaneer on sarnane.",
		"tgt": "In the first half of the film, it occurs to me that it is a business-world version of House of Cards \u2013 Kevin Spacey and Gerard Butler even have a similar manner of speaking."
	},
	{
		"src": "Mida film edasi, seda v\u00e4hemaks kaadrimajalikku elementi aga j\u00e4\u00e4b ja filmitegijate moraliseeriv kavatsus hakkab aina enam v\u00e4lja paistma.",
		"tgt": "As the film wears on, the less of the House-of-Cards element there is and the moralistic intentions of the film-makers start becoming more evident."
	},
	{
		"src": "Elumuutvaks kogemuseks saab peategelasele poja haigestumine v\u00e4hki.",
		"tgt": "A life-changing experience is when the lead character\u2019s son is diagnosed with cancer."
	},
	{
		"src": "N\u00fc\u00fcd tuleb teha valik t\u00f6\u00f6- ja pereelu vahel.",
		"tgt": "Now he has to make a choice between work and family life."
	},
	{
		"src": "Arhitektiametist unistav poeg paneb isa jalutusk\u00e4ikudel Chicago suurte hoonete juurde m\u00f5tlema t\u00f5eliselt oluliste asjade peale nagu usk, headus, armastus..., puudutamata ei j\u00e4\u00e4 isegi kaksiktornide katastroof.",
		"tgt": "On walks to the Chicago\u2019s towering buildings, his son, who dreams of an architect\u2019s profession, makes his father think about what really matters, like faith, goodness, love\u2026even the Twin Towers attack is not neglected."
	},
	{
		"src": "P\u00e4rast kolmandat stseeni, kus poeg isa silmi avab, tekib tunne, et filmitegijad on l\u00e4htunud eesm\u00e4rgist publik kindlasti nutma saada, sest isegi k\u00f5ige kalgima s\u00fcdamega vaataja ei suuda pisaraid tagasi hoida armsa v\u00e4hihaige poisi kannatusi n\u00e4hes.",
		"tgt": "After the third scene, where the son opens his father\u2019s eyes, one gets a feeling that the film-makers have set out to make a tearjerker, because even the hardest heart in the audience won\u2019t be able to hold back the tears upon seeing the adorable cancer-stricken boy\u2019s suffering."
	},
	{
		"src": "Kui poeg koomasse langeb ja tema olukord pea lootusetu n\u00e4ib, saab isa l\u00f5plikult aru oma t\u00f6\u00f6 moraalitusest ja teeb heateo t\u00f6\u00f6d otsivale vanale mehele.",
		"tgt": "When the son falls into a coma and his case seems nearly hopeless, the father finally realizes the amorality of his work and does a good deed for an old man who is looking for a job."
	},
	{
		"src": "N\u00fc\u00fcd vean m\u00f5ttes iseendaga kihla - kui filmil on happy end, siis premeerin oma l\u00e4bin\u00e4gelikkust p\u00e4rast filmi kohviga, kui aga eksin, siis v\u00f5ib stsenaristi v\u00e4hemalt \u00fche \u00fcllatuse eest kiita.",
		"tgt": "Now I have a bet I make with myself \u2013 if a film has a happy ending, I reward myself with a coffee after the movie, but if I\u2019m wrong, then at least the screenwriter can be praised for a surprise."
	},
	{
		"src": "Hetkeks tekib kahtlus, et j\u00e4\u00e4ngi kohvist ilma - siis, kui abikaasa helistab Dane'ile haiglast ja mees tormab aegluubis m\u00f6\u00f6da koridori palati poole.",
		"tgt": "For a second, it seems I will go coffee-less \u2013 when his spouse calls Dane from the hospital and he runs toward the hospital room down the hallway in slow motion."
	},
	{
		"src": "Poeg on aga hoopiski imeliselt tervenenud, ja kuigi tema isa on just t\u00f6\u00f6 kaotanud, osutub seegi positiivseks, sest n\u00fc\u00fcd on ju aega tegeleda perega.",
		"tgt": "The son has made a miraculous recovery, however, and although his father has just lost his job, that, too, proves positive, for now he has time to spend with his family."
	},
	{
		"src": "Mina saan ka ennast h\u00e4sti tunda - oskan Ameerika draama l\u00f5ppu juba p\u00e4ris h\u00e4sti ennustada!",
		"tgt": "It\u2019s a feel-good moment for me, too \u2013 I\u2019m getting pretty good at predicting the endings of American dramas!"
	},
	{
		"src": "T\u00f5ele au andes on film h\u00e4sti konstrueeritud, k\u00f5ik selleks vajalikud elemendid on olemas.",
		"tgt": "Truth be told, the film is very well constructed, all the requisite elements are there."
	},
	{
		"src": "Saab nutta, saab naerda, n\u00e4itlejad on head ja moraal ilus: raha ei ole elus k\u00f5ige t\u00e4htsam.",
		"tgt": "Laughter, tears, the actors are good, and there\u2019s a good moral to the story: money\u2019s not the most important thing in life."
	},
	{
		"src": "K\u00fcllap toob see film h\u00e4sti sisse.",
		"tgt": "The film will no doubt do well at the box office."
	},
	{
		"src": "Trumpi uus personali\u00fclem plaanib piirata presidendi meediatarbimist.",
		"tgt": "Trump's new chief of staff plans to restrict the president's media diet."
	},
	{
		"src": "Teised on \u00fcritanud ja eba\u00f5nnestunud.",
		"tgt": "Others have tried and failed."
	},
	{
		"src": "V\u00f5ib-olla saab John F. Kelly sellega ka p\u00e4riselt hakkama.",
		"tgt": "Maybe John F. Kelly can actually do it."
	},
	{
		"src": "Sel juhul oleks ta esimene.",
		"tgt": "If so, he will be the first."
	},
	{
		"src": "Politico kirjutab, et Valge Maja uus personali\u00fclem plaanib piirata president Trumpini j\u00f5udvat teabevoogu, sealhulgas uudiseid, lootuses, et see hoiab \u00fclemust tasasemas vees.",
		"tgt": "Politico reports that the new White House chief of staff plans to restrict the flow of information to President Trump - including news media reports - in the hope of keeping the boss on a more even keel."
	},
	{
		"src": "Siin on katkend reporter Josh Dawseylt:",
		"tgt": "Here's a bit from reporter Josh Dawsey:"
	},
	{
		"src": "\"Kui Valge Maja uus personali\u00fclem John F. Kelly oma esimesel t\u00f6\u00f6p\u00e4eval k\u00f5rgete ametnikega kokku sai, t\u00f5i ta v\u00e4lja v\u00f5tmeprobleemi president Donald Trumpi Valges Majas, mille ta plaanis lahendada \u0096 halva teabe j\u00f5udmine presidendi k\u00e4tesse.",
		"tgt": "\"When new White House Chief of Staff John F. Kelly huddled with senior staff on his first day at work, he outlined a key problem in President Donald Trump's White House that he planned to fix: bad information getting into the president's hands."
	},
	{
		"src": "Kelly \u00fctles ametnikele, et teave peab liikuma l\u00e4bi tema, kas siis paberil v\u00f5i koosolekutel, sest president teeks paremaid otsuseid, kui talle jagataks head teavet.\"",
		"tgt": "Kelly told the staff that information needed to flow through him - whether on paper or in briefings - because the president would make better decisions if given good information.\""
	},
	{
		"src": "Kelly diagnoos tundub t\u00e4iesti loogiline, aga ka teised on seda \u00fcritanud ja neil on Trumpi taltsutamine tema meediatarbimise j\u00e4lgimisega eba\u00f5nnestunud.",
		"tgt": "Kelly's diagnosis makes perfect sense, but others have tried and failed to tame Trump by monitoring his media diet."
	},
	{
		"src": "President Trumpi suhe televisiooniga ulatub aastak\u00fcmnete taha ja ka n\u00fc\u00fcd, mil ta on Valges Majas, pole tema telerivaatamisharjumused kuhugi kadunud.",
		"tgt": "President Trump's relationship with television goes back decades - and now that he's in the White House, his TV-watching habit is still going strong."
	},
	{
		"src": "\"Kui kandidaat Trump oli ebaausa meediakajastuse p\u00e4rast pahane, tasus talle n\u00e4idata, et teda kajastati m\u00f5jutatavates v\u00e4ljaannetes ka ausalt,\" \u00fctles endine kampaanian\u00f5unik Sam Nunberg veebruaris Politicole.",
		"tgt": "\"If candidate Trump was upset about unfair coverage, it was productive to show him that he was getting fair coverage from outlets that were persuadable,\" Sam Nunberg, a former campaign adviser, told Politico in February."
	},
	{
		"src": "Politico Tara Palmeri kirjutas tol ajal, et \"kuue endise kampaaniat\u00f6\u00f6taja s\u00f5nul on Trumpi Twitteri-harjumuste ohjamise v\u00f5tmeks see, kui tagada, et ta isiklik meediatarbimine sisaldab stabiilselt ka kiidulaulu\".",
		"tgt": "Politico's Tara Palmeri wrote at the time that \"the key to keeping Trump's Twitter habit under control, according to six former campaign officials, is to ensure that his personal media consumption includes a steady stream of praise.\""
	},
	{
		"src": "Hea k\u00fcll.",
		"tgt": "Okay."
	},
	{
		"src": "Aga m\u00f5te, et Trumpi Twitteri kasutamise harjumused on kunagi \"kontrolli all olnud\", on naeruv\u00e4\u00e4rne.",
		"tgt": "But the idea that Trump's Twitter habit has ever been \"under control\" is laughable."
	},
	{
		"src": "V\u00f5ib-olla teavad need kampaaniat\u00f6\u00f6tajad midagi, mida \u00fclej\u00e4\u00e4nud meist ei tea \u0096 et Trumpi s\u00e4utsud oleksid ilma nende sekkumisteta veelgi s\u00fctitavamad olnud.",
		"tgt": "Maybe these campaign officials know something the rest of us don't - that Trump's tweets would have been even more inflammatory if not for their interventions."
	},
	{
		"src": "Me ei saa arvatavasti kunagi teada s\u00e4utsude kohta, mida Trump ei postitanud.",
		"tgt": "We'll probably never know about tweets that Trump didn't send."
	},
	{
		"src": "Kui ta abilised suutsid ta kas v\u00f5i paar korda pahandustest p\u00e4\u00e4sta, olid nende ponnistused seda v\u00e4\u00e4rt.",
		"tgt": "If his staffers managed to him out of trouble even a few times, then their efforts were worthwhile."
	},
	{
		"src": "Aga mitte keegi ei ole suutnud takistada Trumpi j\u00e4rjepidevalt poleemikat tekitamast.",
		"tgt": "But no one has been able to consistently prevent Trump from stirring up controversy."
	},
	{
		"src": "Osa probleemist seisneb selles, et omavahel v\u00f5istlevatest klikkidest koosnevas Valges Majas \u00fcritavad inimesed eranditult iseenda huvisid edendada, edastades Trumpile materjali, mis toetab nende maailmavaateid, aga ei pruugi alati usaldusv\u00e4\u00e4rne olla.",
		"tgt": "Part of the problem is that in a White House composed of competing factions, people invariably try to advance their agendas by presenting Trump with material - which may or may not be reliable - that promotes their worldviews."
	},
	{
		"src": "Kogu loo kulgu kajastav Politico kirjutas maikuus n\u00f5unike kalduvusest s\u00f6\u00f6ta presidendile ette strateegiliselt k\u00fcsitava v\u00e4\u00e4rtusega teavet.",
		"tgt": "Politico - all over this story - reported in May on advisers' penchants for strategically feeding dubious information to the president."
	},
	{
		"src": "\u00dcks n\u00e4idetest, mida kirjeldab reporter Shane Goldmacher, on j\u00e4rgmine:",
		"tgt": "This was one example, described by reporter Shane Goldmacher:"
	},
	{
		"src": "\"Praegused ja endised Trumpi alluvad \u00fctlevad, et Trump v\u00f5ib reageerida negatiivsele pressile, eriti kahjustava m\u00f5juga infoleketele, plahvatuslikult, v\u00f5ttes kinnisideeks nende l\u00e4hteallika v\u00e4ljaselgitamise.",
		"tgt": "\"Current and former Trump officials say Trump can react volcanically to negative press clips, especially those with damaging leaks, becoming engrossed in finding out where they originated."
	},
	{
		"src": "Nii juhtus ka veebruari l\u00f5pus, kui keegi andis kahjur\u00f5\u00f5msalt presidendile prinditud koopia internetiprovokaatorile Charles C. Johnsonile kuuluva veebilehe GotNews.com artiklist, mis s\u00fc\u00fcdistas personali\u00fclema aset\u00e4itjat Katie Walshi selles, et ta olevat Valge Maja \"mitmete infolekete allikas\".",
		"tgt": "That is what happened in late February when someone mischievously gave the president a printed copy of an article from GotNews.com, the website of Internet provocateur Charles C. Johnson, which accused deputy chief of staff Katie Walsh of being 'the source behind a bunch of leaks' in the White House."
	},
	{
		"src": "Pole vahet, et Johnson on m\u00f5nitamise t\u00f5ttu Twitterist j\u00e4\u00e4davalt blokeeritud v\u00f5i et ta ei pakkunud mingeid konkreetseid asit\u00f5endeid v\u00f5i et ta on ka minevikus vales\u00fc\u00fcdistusi esitanud ja neid tagasi v\u00f5tnud.",
		"tgt": "No matter that Johnson had been permanently banned from Twitter for harassment or that he offered no concrete evidence or that he had lobbed false accusations in the past and recanted them."
	},
	{
		"src": "Trump luges artiklit ja hakkas alluvatelt Walshi kohta p\u00e4rima.\"",
		"tgt": "Trump read the article and began asking staff about Walsh.\""
	},
	{
		"src": "Goldmacher lisas, et tolleaegne personali\u00fclem Reince Priebus ja Valge Maja kantselei juht Rob Porter \"on \u00fcritanud kehtestada s\u00fcsteemi Trumpini j\u00f5udvate dokumentide haldamiseks ja dokumenteerimiseks\".",
		"tgt": "Goldmacher added that then-chief of staff Reince Priebus and White House staff secretary Rob Porter \"have tried to implement a system to manage and document the paperwork Trump receives.\""
	},
	{
		"src": "Kuidas see \u00f5nnestus?",
		"tgt": "How'd that work out?"
	},
	{
		"src": "Kelly \u00fcritab kolm kuud hiljem t\u00e4pselt sama teha.",
		"tgt": "Kelly is trying to do the same thing, three months later."
	},
	{
		"src": "V\u00f5ib-olla osutub ta Priebusist t\u00f5husamaks juhiks, aga Trump on endiselt impulsiivne ja tema abilised v\u00f5istlevad endiselt m\u00f5ju nimel.",
		"tgt": "Perhaps he will prove a more effective manager than Priebus, but Trump is still his impulsive self, and his aides are still vying for influence."
	},
	{
		"src": "Need muutumatud tegurid muudavad Kelly missiooni v\u00e4ga raskeks.",
		"tgt": "Those immutable factors will make Kelly's mission very difficult."
	},
	{
		"src": "V\u00e4lismaalt pealinna tulnud t\u00e4navamuusikud ei kibele esinemiseks luba hankima.",
		"tgt": "Foreign street musicians in Tallinn not itching to obtain busking permit."
	},
	{
		"src": "Tallinna kesklinnas k\u00e4ib palju v\u00e4lismaalasi musitseerimas.",
		"tgt": "Many foreigners busk in the city centre of Tallinn."
	},
	{
		"src": "Need, kellega \u00d5htuleht jutule sai, tunnistasid, et m\u00e4ngivad vanalinnas ilma linnavalitsuse loata.",
		"tgt": "The ones \u00d5htuleht spoke to said admitted they were busking in the Old Town without the city government permit."
	},
	{
		"src": "Esimesena leidsime Viru v\u00e4ravate l\u00e4hedalt kolm t\u00e4navamuusikut, kes olid endaga sama palju koeri kaasa v\u00f5tnud.",
		"tgt": "First, we found three street musicians near the Viru gates. They had just as many dogs with them."
	},
	{
		"src": "Oli selgelt n\u00e4ha, et rastapatside ja l\u00f5hkiste riietega muusikud olid seljakotir\u00e4ndurid, kellele kuluks \u00fcks du\u0161\u0161 marjaks \u00e4ra.",
		"tgt": "It could be clearly see that the dreadlocked musicians wearing ripped clothing were backpacker vagabonds who would really benefit from a shower."
	},
	{
		"src": "V\u00e4limusest hoolimata m\u00e4ngis seltskonna ainus naine akordionil l\u00f5busa r\u00fctmiga lugu, samal ajal kui \u00fcks mees tema k\u00f5rval kolme palliga \u017eongleeris ja m\u00f6\u00f6dujaid l\u00e4hemale kutsus.",
		"tgt": "In spite of their appearance, the only woman in the group played a tune with a jolly rhythm on the accordion, while one of the men juggled three balls and beckoned to passersby."
	},
	{
		"src": "Kolmas mees oli nende k\u00f5rval \u00fchele seljakotile istunud ja suitsetas s\u00fcdamerahus ise valmis keeratud pl\u00e4ru.",
		"tgt": "The third man next to them was sitting on a backpack and calmly smoking a hand-rolled cigarette."
	},
	{
		"src": "Nende kolm koera ei lasknud end m\u00f6\u00f6duvast rahvast h\u00e4irida.",
		"tgt": "Their three dogs were unfazed by the passersby."
	},
	{
		"src": "Akordioni m\u00e4nginud Noemi ja pallidega \u017eongleerinud Bob r\u00e4\u00e4kisid, et musitseerivad t\u00e4navatel nii l\u00f5bu kui ka raha p\u00e4rast.",
		"tgt": "Noemi, the one playing the accordion, and Bob the juggler said that they busked for fun as well as for the money."
	},
	{
		"src": "Seltskonna esinemise eesm\u00e4rk oli koguda piletiraha sama p\u00e4eva \u00f5htul Soomesse s\u00f5itva laevale.",
		"tgt": "They were trying to raise enough money to buy tickets for a ship sailing to Finland the same evening."
	},
	{
		"src": "K\u00fcsimuse peale, kas nad vanalinnas musitseerimise jaoks linnalt luba k\u00fcsisid, raputasid Noemi ja Bob pead.",
		"tgt": "Asked whether they applied for a permit for busking in the Old Town, Noemi and Bob shook their heads."
	},
	{
		"src": "Esiteks, me ei teadnud.",
		"tgt": "First of all, we didn\u2019t know."
	},
	{
		"src": "Teiseks, me ei p\u00fcsi kunagi \u00fches linnas rohkem kui p\u00e4eva v\u00f5i paar ja enamasti antakse lubasid kuuks ajaks v\u00f5i midagi sellist.",
		"tgt": "Secondly, we\u2019re never in one city for longer than a day or two and generally permits are handed out for a month or the like."
	},
	{
		"src": "Selle eest ei ole m\u00f5tet maksta\", seletas Bob.",
		"tgt": "There\u2019s no point in paying for that,\u201d said Bob."
	},
	{
		"src": "Kui me umbes 20 minutit hiljem uuesti Viru v\u00e4ravate juurde sattusime, n\u00e4gime, et kaks naist on muusikute juures ja ajavad neid minema.",
		"tgt": "When we found ourselves by the Viru gates once again about 20 minutes later, we saw that two women had approached the musicians and were telling them to move along."
	},
	{
		"src": "Seltskond kolis seljakottide ja koertega Viru keskuse ristmiku juurde \u00f5nne katsuma.",
		"tgt": "The group with backpacks and dogs moved on to the Viru Keskus crossing to try their luck."
	},
	{
		"src": "Viru t\u00e4naval esinesid ka kolm poola noormeest, kellest \u00fcks m\u00e4ngis viiulit, teine klarnetit ja kolmas oli lausa elektroonilise klaveri kaasa vedanud.",
		"tgt": "Three young Polish men were also busking on Viru Street, one of whom was playing the violin, another the clarinet and a third had even hauled out an electronic piano."
	},
	{
		"src": "\"Me oleme siin, et inimestele meelelahutust pakkuda, et levitada muusikat ja r\u00f5\u00f5mu ning selleks, et k\u00fctuse ja elamise jaoks raha teenida\", seletas trio pianist Mivosh.",
		"tgt": "\u201cWe\u2019re here to offer people entertainment, to spread music and joy and to make money for gas and living expenses,\u201d explained Mivosh, the pianist."
	},
	{
		"src": "Mivoshi s\u00f5nul on nad teadlikud sellest, et esinemiseks peab linnavalitsuse luba olema.",
		"tgt": "Mivosh said they were aware they had to apply for a permit from city government."
	},
	{
		"src": "\"Loomulikult meil ei ole seda\", \u00fctles ta naljatades.",
		"tgt": "\u201cOf course we don\u2019t have that,\u201d he said in a light-hearted manner."
	},
	{
		"src": "Aga me loodame, et kui inimesed naudivad meie muusikat, siis ei ole mingit probleemi.",
		"tgt": "But we hope that if people enjoy our music, then there won\u2019t be a problem."
	},
	{
		"src": "Loomulikult, kui politsei tuleb, siis me l\u00e4heme mujale, aga proovima peab\", lisas ta.",
		"tgt": "Naturally, if the police come, we will go elsewhere, but we have to try,\u201d he added."
	},
	{
		"src": "Eesti Pank ostis euroala keskpankade avaliku sektori varaostuprogrammi raames juulikuus 149 miljoni euro eest v\u00f5lakirju, keskpanga v\u00f5lakirjaportfell kasvas kokku 4,36 miljardi euroni.",
		"tgt": "In July, Bank of Estonia bought 149 million euros in bonds as part of the central banks\u2019 government asset programme, and the central bank\u2019s bond portfolio grew to a total of 4.36 billion euros."
	},
	{
		"src": "Keskpank detailsemat infot ostude kohta ei avalda.",
		"tgt": "The central bank is not releasing more details on the purchases."
	},
	{
		"src": "Eesti panga president Hardo Hansson on varem riigikogu liikmete arup\u00e4rimisele vastates selgitanud, et euros\u00fcsteemi keskpankade varaostukava h\u00f5lmab kolme erinevat ostuprogrammi: finantssektori kaetud v\u00f5lakirjad (covered bonds), varaga tagatud v\u00f5lakirjad (ABS) ja avaliku sektori v\u00f5lakirjad (PSPP).",
		"tgt": "Bank of Estonia President Ardo Hansson had previously explained in response to an interpellation from MPs that Eurozone central banks\u2019 asset purchase programme encompasses three different buying programmes: covered bonds, asset backed securities (ABS) and public sector purchase programme (PSPP)."
	},
	{
		"src": "Keskpank ostab turult kokku v\u00f5lakirju, et innustada v\u00f5lakirju m\u00fc\u00fcnud investoreid raha mujale investeerima.",
		"tgt": "The central bank buys up bonds on the market, to encourage the investors who sold the bonds to invest money elsewhere."
	},
	{
		"src": "Ostude m\u00f5jul langeb madalama riskiga varade tootlus ning see motiveerib investoreid suuremaid riske v\u00f5tma.",
		"tgt": "As an effect of the purchases the yield of low-risk assets decreases, and this motivates investors to take bigger risks."
	},
	{
		"src": "\u00dcldjuhul ostab avaliku sektori v\u00f5lakirjaostuprogrammi raames iga keskpank oma riigi valitsuse v\u00f5lakirju, teiste riikide v\u00f5lakirju ei osteta.",
		"tgt": "In general, in the context of the public sector bond purchase programme, each central bank buys its own government bonds, other countries\u2019 bonds are not purchased."
	},
	{
		"src": "Kuna Eesti riik v\u00f5lakirju emiteerinud ei ole, siis teeb Eesti Pank neile eraldatud mahu piires nn asendusoste.",
		"tgt": "As the Estonian state has not issued bonds, the Bank of Estonia executes what are called substitute purchases in the amount allocated to it."
	},
	{
		"src": "Asendusoste teevad ka keskpangad nendes riikides, kus ostukavale vastavate v\u00f5lakirjade pakkumine on piiratud.",
		"tgt": "Central banks also make substitute purchases in countries with a limited supply of the bonds conforming to the purchase programme."
	},
	{
		"src": "Eesti Pank ostab Hanssoni kinnitusel \u00fcldjuhul Euroopa institutsioonide v\u00f5lakirju, n\u00e4iteks Euroopa Finantsstabiilsuse Fondi ning Euroopa Investeerimispanga v\u00f5lakirju.",
		"tgt": "Hansson said Bank of Estonia generally buys the bonds of European institutions, such as the bonds of the EFSF and the EIB."
	},
	{
		"src": "Eesti Pank ostab varaostuprogrammi raames v\u00f5lakirju alates 2015. aasta m\u00e4rtsist.",
		"tgt": "The Bank of Estonia has been purchased bonds as part of the asset purchase programme since March 2015."
	},
	{
		"src": "Vahepeal soetati ka Eleringi v\u00f5lakirju, kuid 2016. aasta juunist Eesti Pank enam Eleringi v\u00f5lakirju ei osta.",
		"tgt": "In the interim, Elering bonds were purchased, but as of June 2016, the Bank of Estonia no longer buys Elering bonds."
	},
	{
		"src": "Euroala keskpankade nimel ostab alates juunist nii Eleringi kui ka Eesti Energia v\u00f5lakirju Soome keskpank.",
		"tgt": "The Finnish central bank buys both Elering and Eesti Energia bonds on behalf of the Eurozone\u2019s central banks."
	},
	{
		"src": "R\u00e4ndurid eiravad kraavi ning naasevad \"miljon\u00e4ride rajooni\"",
		"tgt": "Travellers negotiate trench, return to 'Millionaire's row'"
	},
	{
		"src": "M\u00f5ned West Midlandsi j\u00f5ukaimad koduomanikud on sattunud taas raevukasse vastasseisu otsusekindlate r\u00e4nduritega, kes on eiranud volikogu kaevatud kraavi, et v\u00f5ita tagasi nende villadest eemale j\u00e4\u00e4v v\u00e4li.",
		"tgt": "Some of the West Midlands' wealthiest homeowners are again at loggerheads with determined travellers who have negotiated a council-dug trench to reclaim a field outside their mansions."
	},
	{
		"src": "R\u00e4ndurid on parkinud oma 20 haagissuvilat v\u00e4ljale j\u00f5uka \"miljon\u00e4ride rajooniks\" ristitud Solihulli t\u00e4nava l\u00e4histel.",
		"tgt": "The travellers have parked their 20 caravans in a field outside a prosperous street of Solihull dubbed 'millionaire's row'."
	},
	{
		"src": "Nad on naasnud koos hobuste, laste ja veoautode armeega p\u00e4rast seda, kui nad alles mais sealt v\u00e4lja l\u00f6\u00f6di, laskmata end segada kraavist, mille kaevas nende sissetungi takistamiseks volikogu.",
		"tgt": "Bringing horses, babies and an army of vans, they have returned after being kicked out only in May, undeterred by a moat dug by the council to prevent their incursions."
	},
	{
		"src": "Taktiline r\u00fchm leidis kaitsepiirdes n\u00f5rga koha, pigistades oma s\u00f5idukid l\u00e4bi t\u00f5kestamata j\u00e4\u00e4nud osast, mis oli j\u00e4etud jalgteeks.",
		"tgt": "The tactful group found a gap in the defences, squeezing their vehicles though a section left unbarricaded to accommodate a pathway."
	},
	{
		"src": "Maruvihased elanikud on kirunud Solihulli volikogu, \u00f6eldes, et volikogu on \"probleemiga tegelemisel kasutu\".",
		"tgt": "Furious residents have savaged Solihull Council saying it was 'useless at dealing with the problem'."
	},
	{
		"src": "\u00dcks anon\u00fc\u00fcmne elanik s\u00f5nas: \"Nad kolisid sinna esmasp\u00e4eva \u00f5htul p\u00e4rast nende v\u00e4ljat\u00f5rjumist Bentley Heathist, kus nad loopisid m\u00f6\u00f6dujaid kividega.",
		"tgt": "One anonymous resident said: 'They moved there on Monday night after being moved on from Bentley Heath where they were throwing rocks at passers by."
	},
	{
		"src": "Volikogu tuleb h\u00e4bistada, et nad tegutsema hakkaksid, sest nad on probleemiga tegelemises kasutud.",
		"tgt": "The council needs to be shamed into action as they are useless at dealing with the problem."
	},
	{
		"src": "R\u00e4ndurid olid seal mais, nad ajati minema ja n\u00fc\u00fcd nad on j\u00e4lle tagasi.",
		"tgt": "The travellers were there in May, were moved on and now they are back again."
	},
	{
		"src": "Neid tuli eile \u00f5htul juurde, t\u00e4na t\u00f5en\u00e4oliselt veel rohkemgi.\"",
		"tgt": "More arrived last night, probably even more today.'"
	},
	{
		"src": "Ta lisas: \"Birminghami volikogu teab, kuidas selliste asjadega tegeleda, hankides oma parkide kaitsmiseks pikad t\u00f5kendid.",
		"tgt": "She added: 'Birmingham council knows how to deal with this by getting long injunctions to protect their parks."
	},
	{
		"src": "Ma elan Streetsbrooki teel ja ma ei ole rahul, et pean j\u00e4tkama volikogumaksu tasumist, kui volikogu ei suuda isegi sellist asja takistada.\"",
		"tgt": "I live on Streetsbrook road and I'm not happy to continue paying my council tax when the council can't even stop this.'"
	},
	{
		"src": "\u00dcks kohalik elanik, kes soovis samuti anon\u00fc\u00fcmseks j\u00e4\u00e4da, \u00fctles: \"See on naeruv\u00e4\u00e4rne. Alles n\u00e4gime, kuidas viimased neist r\u00e4nduritest lahkusid, ja juba on toimumas uus pealetung.",
		"tgt": "One local resident who did not wish to be named said: 'It is ridiculous, we have only just seen the last round of these travellers leaving, only to be blighted by another round."
	},
	{
		"src": "Seekord on arv kasvanud ja rohumaal on isegi hobust m\u00e4letsemas n\u00e4htud.\"",
		"tgt": "The numbers have increased this time and a horse has even been seen grazing on the parkland.'"
	},
	{
		"src": "Solihulli volikogu esindaja lausus: \"Oleme teadlikud, et Streetsbrooki tee l\u00e4histel oleval maal on lubamatu laagriplats, ja teeme koost\u00f6\u00f6d Solihulli politseiga. Rakendame vajalikke \u00f5igusmeetmeid, et nad v\u00f5imalikult kiiresti liikuma saada.",
		"tgt": "A spokeswoman for Solihull Council said: 'We are aware of an unauthorised encampment on land off Streetsbrook Road and working alongside Solihull Police, we are undertaking the necessary legal actions to move them on as quickly as possible."
	},
	{
		"src": "T\u00f5endite kogumisel on v\u00e4ga suureks abiks, kui v\u00f5imalikult paljud kohalikud elanikud teatavad mis tahes antisotsiaalsest v\u00f5i kriminaalsest k\u00e4itumisest politseile, helistades numbril 101.",
		"tgt": "To support our evidence gathering it is very important that as many local residents as possible report any anti-social or criminal behaviour to the police by calling 101."
	},
	{
		"src": "See aitab olukorrast kohtu jaoks pildi luua, kui me juhtumit neile esitleme.\"",
		"tgt": "This helps build a picture of the situation for the court to consider when we present our case to them.'"
	},
	{
		"src": "Weekend festivali k\u00fclastab k\u00f5igi teiste seas ka kultuuriminister Indrek Saar, kel on hea meel, et Eestisse on suudetud tuua t\u00f5elised maailma tippnimed.",
		"tgt": "Culture Minister Indrek Saar is one of the attendees at the Weekend Festival and says he is glad that true world headliners are playing in Estonia."
	},
	{
		"src": "K\u00fcsimusele, miks on Weekend festival eestlaste jaoks niiv\u00f5rd oluline, vastab Saar, et seda tuleks k\u00fcsida k\u00f5igilt neilt, kes festivali kolm p\u00e4eva jutti t\u00e4iel rinnal naudivad.",
		"tgt": "In response to the question of why the weekend festival is so important for Estonians, he said that the question should be asked of all those who are enjoying every aspect of the festival for three days in a row."
	},
	{
		"src": "K\u00fcll aga t\u00f5deb ta, et P\u00e4rnusse on kohale tulnud t\u00f5elised oma ala tegijad.",
		"tgt": "But he does admit the true top calibre performers have arrived in P\u00e4rnu."
	},
	{
		"src": "\"Vaadates seda artistide taset, mida on suudetud Eestisse tuua, siis et tuuakse koju k\u00e4tte selle muusika\u017eanri absoluutsed tippnimed - seda tihti meie kandis ei juhtu\", r\u00e4\u00e4gib kultuuriminister.",
		"tgt": "\u201cLooking at the level of artists that they\u2019ve managed to bring to Estonia, these are the absolute top names in the musical genre \u2013 that doesn\u2019t often happen in these parts,\u201d says the minister of culture."
	},
	{
		"src": "Millised festivalil esinevad artistid aga Saart ennast k\u00f5ige enam k\u00f5netavad?",
		"tgt": "Which of the artists performing at the festival resonate with Saar most?"
	},
	{
		"src": "Ma pean end suhteliselt vanainimeseks ja minusuguste vanainimeste jaoks on kindlasti \u00fcks k\u00f5ige enam kogetud artist Armin van Buuren, kes eile \u00f5htul \u00fcles astus.",
		"tgt": "I consider myself a fairly old person and for older folks like myself one of the artists we\u2019ve had the most experience with is Armin van Buuren, who took the stage yesterday evening."
	},
	{
		"src": "Tema plaadikeerutuse j\u00e4rgi on ju k\u00f5ik meist mingil hetkel ka ise jalga keerutanud\", s\u00f5nab ta.",
		"tgt": "All of us have taken a spin on the dance floor to his record spinning,\u201d he says."
	},
	{
		"src": "K\u00fcll aga toob ta veel v\u00e4lja mitmeid nimesid, n\u00e4iteks Chainsmokers'i, Deadmau5, Knifeparty.",
		"tgt": "He also cites a number of other names, such as Chainsmokers, Deadmau5 and Knifeparty."
	},
	{
		"src": "Loomulikult ka meie oma Eesti tegijad: alustades NO\u00cbP'ist ja neid v\u00f5ib lugeda terve rea.",
		"tgt": "Naturally, our own Estonian acts, too \u2013 starting with NO\u00cbP to a wide range of others."
	},
	{
		"src": "Tegelikkuses see tuntud nimede kontsentratsioon on v\u00e4ga suur\", \u00fctleb ta.",
		"tgt": "Actually, the concentration of well-known names is very high,\u201d he says."
	},
	{
		"src": "Vaata pikemalt \u00d5htulehe videost!",
		"tgt": "Watch the full \u00d5htuleht video!"
	},
	{
		"src": "Audi uuendab autotootjaid tabanud kriitika keskel kuni 850 000 diisels\u00f5idukit",
		"tgt": "Audi to Modify Up to 850,000 Diesel Vehicles as Carmakers Face Backlash"
	},
	{
		"src": "P\u00e4ev enne Audi teadaannet \u00fctles BMW, et pakub tarkvarat\u00e4iendust enam kui 350 000 s\u00f5idukile.",
		"tgt": "A day before Audi's announcement, BMW said it would offer to upgrade the software in more than 350,000 vehicles."
	},
	{
		"src": "BMW esimehe s\u00f5nul usub ettev\u00f5te, et \"on olemas arukamaid variante kui s\u00f5idupiirangud\", viidates Euroopa linnadele, sealhulgas BMW kodulinnale M\u00fcnchenile, mis on kaalunud diisels\u00f5idukite keelustamist v\u00f5i piiramist.",
		"tgt": "The BMW chairman said the company believed \"there are more intelligent options than driving restrictions,\" referring to the European cities - including Munich, where BMW is based - that have considered banning or restricting diesel vehicles."
	},
	{
		"src": "Daimler teatas teisip\u00e4eval, et uuendab diiselmootorite heitgaaside v\u00e4hendamiseks kolme miljonit Mercedese s\u00f5idukit Euroopas.",
		"tgt": "Daimler announced on Tuesday that it would modify three million Mercedes vehicles in Europe to reduce their diesel emissions."
	},
	{
		"src": "\u00dckski ettev\u00f5te ei kirjeldanud neid toiminguid tagasikutsumisena.",
		"tgt": "None of the companies described the moves as recalls."
	},
	{
		"src": "Euroopa autotootjad on reklaaminud Euroopas ja Ameerika \u00dchendriikides innukalt diisels\u00f5idukite kasutamist, et aidata j\u00e4rgida s\u00fcsinikdioksiidi heitkogustele kehtestatud m\u00e4\u00e4ruseid.",
		"tgt": "European carmakers have heavily promoted the use of diesel vehicles in Europe and the United States to help meet rules on carbon dioxide emissions."
	},
	{
		"src": "Ent diiselmootoritest eralduvat l\u00e4mmastikoksiidi peetakse kantserogeeniks ja see v\u00f5ib p\u00f5hjustada astmat.",
		"tgt": "But the nitrogen oxides that diesel engines emit are considered carcinogens, and can cause asthma."
	},
	{
		"src": "\u00dchtlasi suureneb autot\u00f6\u00f6stusettev\u00f5tete jaoks diisels\u00f5idukite \u00f5hku paisatavate heitgaaside neutraliseerimiseks paigaldatava varustuse maksumus, muutes autode hinna konkurentsiv\u00f5imelisena hoidmise raskeks.",
		"tgt": "The cost to automotive companies of installing equipment to neutralize the fumes emitted by diesel vehicles is also increasing, making it difficult to keep the price of the cars competitive."
	},
	{
		"src": "Samal ajal kui Saksa autotootjad on p\u00f5hjaliku uurimise all, s\u00fc\u00fcdistatakse ka liidukantsler Angela Merkeli valitsust v\u00f5imsate autotootjate hellitamises ja probleemile viitavate m\u00e4rkide eiramises.",
		"tgt": "As German automakers face scrutiny, the government of Chancellor Angela Merkel has also been accused of coddling the powerful car companies and of ignoring signs of the problem."
	},
	{
		"src": "Ettev\u00f5tted \u00fcritavad v\u00e4ltida Volkswageni vigade kordamist, kes vaikis maha nii-\u00f6elda petuseadmete kasutamise, mis v\u00f5imaldasid kohandada heitgaaside n\u00e4idu auto testimise ajaks regulatsioonidele vastavaks, aga t\u00f5mbusid tavalistes s\u00f5iduoludes tagasi.",
		"tgt": "The companies are trying to avoid repeating the mistakes of Volkswagen, which covered up its use of so-called defeat devices that could adjust emissions to comply with regulations when a car was being tested, but ease back in normal driving conditions."
	},
	{
		"src": "Mitmele Volkswageni juhile on esitatud Ameerika \u00dchendriikides s\u00fc\u00fcdistus ja teised on m\u00f5lemal pool Atlandi ookeani uurimise all.",
		"tgt": "Several Volkswagen executives have been charged in the United States, and others are under investigation on both sides of the Atlantic."
	},
	{
		"src": "Eelmisel kuul vahistati Saksamaal Audi mootoriarenduse osakonna termod\u00fcnaamika all\u00fcksuse endine juhataja.",
		"tgt": "Last month, the former head of thermodynamics at Audi's engine development department was arrested in Germany."
	},
	{
		"src": "Endine juhataja Zaccheo Giovanni Pamio on itaallane ja pole seega v\u00e4ljaandmise eest kaitstud ning v\u00f5ib minna kohtu alla Ameerika \u00dchendriikides.",
		"tgt": "The former manager, Zaccheo Giovanni Pamio, is Italian, and therefore is not protected from extradition and could face trial in the United States."
	},
	{
		"src": "Selle aasta alguses t\u00f5mmati Audi Saksamaal Volkswagenit puudutavasse kriminaaluurimisse, kui ametiv\u00f5imud s\u00fc\u00fcdistasid Audit s\u00fcsteemi paigaldamises, et hiilida k\u00f5rvale Euroopa heitgaasikoguste n\u00f5uetest, laiendades sellega juurdlust, mis oli keskendunud varem Ameerika \u00dchendriikidele.",
		"tgt": "Early this year, Audi was swept up into a German criminal investigation involving Volkswagen after the authorities accused Audi of installing a system to evade emissions rules in Europe, broadening an inquiry that had focused on the United States."
	},
	{
		"src": "Audi kaasamine uurimisse v\u00f5ib olla Volkswagenile suur hoop \u0096 luksusautode tootja genereerib ebaproportsionaalselt suure osa Volkswageni kasumist.",
		"tgt": "The inclusion of Audi in the investigation could weigh heavily on Volkswagen: The luxury carmaker accounts for a disproportionate share of Volkswagen's profit."
	},
	{
		"src": "Eesti koolidele soetatakse 20 000 euro eest Euroopa Liidu lippe.",
		"tgt": "European Union flags will be purchased for Estonian schools for 20,000 euros."
	},
	{
		"src": "Haridusministeerium kavatseb Eesti koolidele 1. septembriks osta eesistumise \u00e4ram\u00e4rkimiseks Euroopa Liidu lippe.",
		"tgt": "The Ministry of Education plans to buy European flags for Estonian schools by 1 September to mark the Estonian Presidency of the Council of the European Union."
	},
	{
		"src": "Kokku saavad m\u00f5\u00f5tudega 105x158 sentimeetrit Euroopa Liidu lipu 570 haridusasutust.",
		"tgt": "A total of 570 educational institutions will receive European Union flags measuring 105 x 158 cm."
	},
	{
		"src": "Lipud on ette n\u00e4htud eksponeerimiseks siseruumides, need peavad olema teostatud kvaliteetses tr\u00fckitehnikas siseruumides ka tunnelkinnitusega, vahendab ERRi uudisportaal.",
		"tgt": "The flags are intended for displaying; they must be executed in quality printing technique with tunnel fastening, ERR News reports."
	},
	{
		"src": "Lipuvarda sildil on tekst: \"Kingitus Eesti koolidele Eesti Euroopa Liidu N\u00f5ukogu esimese eesistumise \u00e4ram\u00e4rkimiseks.",
		"tgt": "The flagpole label bears a text: \u201cGift to Estonian schools for recognizing the first Estonian presidency of the Council of the European Union."
	},
	{
		"src": "570 lipu eeldatav maksumus on haridusministeeriumi hinnagul 20 000 eurot ehk \u00fcks lipp l\u00e4heb maksma 35 eurot.",
		"tgt": "The estimated cost of the 570 flags is put by the Ministry of Education at \u20ac20,000. In other words, one flag costs \u20ac35."
	},
	{
		"src": "Ajakirjaniku m\u00f5rv r\u00f5hutab kasvavat ohuolukorda Mehhikos",
		"tgt": "A journalist's murder underscores growing threat in Mexico"
	},
	{
		"src": "N\u00e4dalalehe Riodoce t\u00f6\u00f6tajad kogunevad tavaliselt kolmap\u00e4eviti, et vaadata \u00fcle plaanid Sinaloa osariigi k\u00f5ige hiljutisema kaose kajastamiseks, mida k\u00fclvavad organiseeritud kuritegevus, korrumpeerunud ametnikud ja lakkamatud narkos\u00f5jad.",
		"tgt": "The staff of the weekly newspaper Riodoce normally meets on Wednesdays to review their plans for coverage of the most recent mayhem wrought in Sinaloa state by organized crime, corrupt officials and ceaseless drug wars."
	},
	{
		"src": "Aga t\u00e4na on nad kogunenud isikliku trag\u00f6\u00f6dia varjus arutama enda turvalisust.",
		"tgt": "But on this day, in the shadow of their own tragedy, they've come together to talk about security."
	},
	{
		"src": "Neile \u00f6eldakse, et t\u00e4htis on oma rutiine muuta.",
		"tgt": "It's important to change their routines, they are told."
	},
	{
		"src": "Kaks vanemajakirjanikku arutavad, kumb tundub ohutum: kas tuua lapsed endaga kontorisse, mis oli 2009. aastal granaadir\u00fcnnaku sihtm\u00e4rgiks, v\u00f5i j\u00e4tta nad koju.",
		"tgt": "Two senior journalists discuss what feels safer: to take their children with them to the office, which was the target of a grenade attack in 2009, or to leave them at home."
	},
	{
		"src": "Turvaeksperdid on kirjutanud ruumi eesotsas asuvale tahvlile kolm s\u00f5na: \"vaenlased\", \"neutraalsed\", \"liitlased\".",
		"tgt": "Security experts have written three words on a blackboard at the front of the room: adversaries, neutrals, allies."
	},
	{
		"src": "Nad paluvad reporteritel igasse veergu nimesid pakkuda \u0096 t\u00f5endeid pole vaja, piisab muljetest ja sisetundest.",
		"tgt": "They ask the reporters to suggest names for each column - no proof is needed, perceptions and gut feelings are enough."
	},
	{
		"src": "Valitsuse v\u00f5i kartellide palgal olemises kahtlustatakse uimastikaubitsejaid, poliitikuid, \u00e4rimehi ja ajakirjanikke \u0096 terve nimekiri pahalasi, kes teevad Mehhikos valitseva kaose kajastamise ohtlikuks.",
		"tgt": "There are drug-traffickers, politicians, businesspeople, journalists suspected of being on the payroll of the government or the cartels, a catalog of villains who make the job of covering Mexico's chaos perilous."
	},
	{
		"src": "V\u00e4givallast ei ole hinget\u00f5mbepausi ning mida rohkem surnukehasid \u00fcle riigi kokku kuhjub, seda suurema osa nendest moodustavad ajakirjanikud \u0096 Ajakirjanike Kaitse Komitee andmetel on neid alates president Enrique Pena Nieto ametisse vannutamisest 2012. aasta detsembris v\u00e4hemalt 25. 589 ajakirjanikku on p\u00e4rast r\u00fcnnakuid ja \u00e4hvardusi riikliku kaitse all ning selle aasta jooksul on saanud siiani surma v\u00e4hemalt seitse ajakirjanikku seitsmes osariigis.",
		"tgt": "There is no respite from the violence, and as bodies pile up across the country, more and more of them are journalists: at least 25 since President Enrique Pena Nieto took office in December 2012, according to the Committee to Protect Journalists; 589 under federal protection after attacks and threats; and so far this year, at least seven dead in seven states."
	},
	{
		"src": "Viimaste hukkunute hulka kuulub nende toimetaja ja inspiratsiooniallikas, Riodoce kaasasutaja Javier Valdez Cardenas.",
		"tgt": "Among the latest is their editor and inspiration, Riodoce co-founder Javier Valdez Cardenas."
	},
	{
		"src": "\"Suurim viga on elada Mehhikos ja olla ajakirjanik,\" kirjutas Valdez \u00fches oma paljudest narkov\u00e4givalda k\u00e4sitlevatest raamatutest.",
		"tgt": "\"The greatest error is to live in Mexico and to be a journalist,\" Valdez wrote in one of his many books on narco-violence."
	},
	{
		"src": "Tema puudumine annab s\u00fcgavalt tunda, kuigi tema kohalolu v\u00f5ib tajuda k\u00f5ikjal \u0096 Riodoce hoone fassaadil ripub suur pilt keskmist s\u00f5rme n\u00e4itavast Valdezist koos kirjaga \"\u00d5iglus\" ning kaks 30ndates reporterit, Aaron Ibarra ja Miriam Ramirez, kannavad T-s\u00e4rke, millel on kujutatud tema naeratavat prillidega n\u00e4gu v\u00f5i talle iseloomulikku panamak\u00fcbarat.",
		"tgt": "His absence is felt deeply, although his presence is everywhere - a large photo of Valdez displaying his middle finger, with the word \"Justice,\" hangs on the facade of the Riodoce building; two reporters on their 30s, Aaron Ibarra and Miriam Ramirez, wear T-shirts that display his smiling, bespectacled face or his trademark Panama hat."
	},
	{
		"src": "Koosolek toimub v\u00e4hem kui kaks kuud p\u00e4rast ta surma. Reporterid arutavad \u00fchist traumat, oma \u00f5udusunen\u00e4gusid, unetust, paranoiat.",
		"tgt": "The workshop takes place less than two months after his death; the reporters discuss their shared trauma, their nightmares, insomnia, paranoia."
	},
	{
		"src": "Kuigi 2010. aastal loodi ajakirjanike juhtumite k\u00e4sitlemiseks eraldi riigiprokuratuur, on Ajakirjanike Kaitse Komitee andmeil v\u00f5etud kohtulikule vastutusele vaid kaks juhtumit.",
		"tgt": "Although a special federal prosecutor's office was established in 2010 to handle the journalists' cases, it has only prosecuted two, according to the Committee to Protect Journalists."
	},
	{
		"src": "Nagu enamiku iga-aastaste uimastikaubanduse ja organiseeritud kuritegevusega seotud m\u00f5rvade puhul, mille arv ulatub tuhandetesse, j\u00f5uavad ka ajakirjanike tapjad harva kohtu ette.",
		"tgt": "As with most of the thousands of murders tied to drug trafficking and organized crime each year, the killers of journalists are rarely brought to justice."
	},
	{
		"src": "Riodoce toimetuses j\u00e4tkatakse Sinaloas valitseva v\u00e4givalla kajastamist, kuigi nende s\u00fcdamed on murtud ja maastik on n\u00fc\u00fcd veelgi ohtlikum.",
		"tgt": "At Riodoce, they persist in covering the violence of Sinaloa, though they are heartbroken, though the terrain is more treacherous now."
	},
	{
		"src": "Ilma m\u00f5rvarite andmete ja \u00f5igluseta pole turvalisust k\u00e4sitlevast koosolekust Ibarra s\u00f5nul palju kasu.",
		"tgt": "Without information on the killers, without justice, the meeting to discuss security, says Ibarra, is of little use."
	},
	{
		"src": "\"V\u00e4ga tobe on oma aega siin koosolekul raisata,\" \u00fctleb ta.",
		"tgt": "\"It's very foolish to waste my time in this workshop,\" he says."
	},
	{
		"src": "\"Seni, kuni p\u00f5hjus pole teada, umbusaldad k\u00f5iki.\"",
		"tgt": "\"As long as we don't know why, you distrust everyone.\""
	},
	{
		"src": "Valdez lahkus osariigi pealinnas Culiacanis asuvast Riodoce kontorist 15. mai hommikul.",
		"tgt": "On the morning of May 15, Valdez left the Riodoce office in the state capital of Culiacan."
	},
	{
		"src": "Tal \u00f5nnestus s\u00f5ita vaid paar kvartalit, enne kui kaks meest ta punase Toyota Corolla peatasid. Ta sunniti autost v\u00e4ljuma ja teda tulistati 12 korda. Seda eeldatavasti ajalehe nime p\u00e4rast, mis t\u00e4hendab t\u00f5lgitult \"kaheteistk\u00fcmnendat j\u00f5ge\".",
		"tgt": "He managed to drive just a couple blocks before his red Toyota Corolla was stopped by two men; he was forced out of his car and shot 12 times, presumably for the name of the paper - which translates as Twelfth River."
	},
	{
		"src": "Relvastatud mees s\u00f5itis Valdezi autos minema ja tegi sellega l\u00e4heduses avarii.",
		"tgt": "The gunman drove away in his car and crashed it nearby."
	},
	{
		"src": "Valdez oli 50 aastat vana.",
		"tgt": "Valdez was 50 years old."
	},
	{
		"src": "Temast j\u00e4id maha naine ja kaks t\u00e4iskasvanud last.",
		"tgt": "He left a wife and two adult children."
	},
	{
		"src": "Kuulujutud levivad Culiacanis vabalt.",
		"tgt": "Rumors tend to fly freely in Culiacan."
	},
	{
		"src": "Ent Valdezi teemal valitseb peaasjalikult vaid vaikus.",
		"tgt": "But on the subject of Valdez, there's practically nothing but silence."
	},
	{
		"src": "Alates Guzmani vahistamisest eelmisel aastal ja Ameerika \u00dchendriikidele v\u00e4ljaandmisest jaanuaris on Sinaloa olnud riigi \u00fcks k\u00f5ige verisemaid lahinguv\u00e4lju, sest rivaalitsevad klikid v\u00f5itlevad v\u00f5imuvaakumi t\u00e4itmise p\u00e4rast.",
		"tgt": "Since Guzman's arrest last year and extradition to the United States in January, Sinaloa has been one of the country's bloodiest battlegrounds as rival factions fight to fill the vacuum."
	},
	{
		"src": "Pole vahet, et Sinaloa t\u00e4navatel lastakse iga p\u00e4ev m\u00f5ni inimene v\u00f5i lausa mitu maha v\u00f5i et surnuaed kubiseb k\u00fclluslikult kaunistatud kahekordsetest narkokuningate mausoleumidest, mis on suuremad kui paljude elavate kodud.",
		"tgt": "Never mind that someone or several people are shot dead in the street every day in Sinaloa, or that the cemetery is filled with ornate, two-story mausoleums for drug kings, larger than many homes for the living."
	},
	{
		"src": "Unustagem hetkeks, et rahuaeg viitab sellele, kui v\u00e4\u00e4rtuslike sadamate ja Ameerika \u00dchendriikidesse viivate uimastimarsruutidega mere\u00e4\u00e4rset osariiki juhib ainult \u00fcks kartell.",
		"tgt": "Forget for a minute that a state of \"calm\" is when just one cartel is in control of the coastal state with its valuable ports and drug-trafficking routes to the United States."
	},
	{
		"src": "Vaatamata k\u00f5igele sellele ja asjaolule, et Valdez oli oma t\u00f6\u00f6ga kaasnevatest ohtudest l\u00e4binisti teadlik, tunneb Riodoce kaasasutaja ja juhataja Ismail Bojorquez (60) tohutuid s\u00fc\u00fcmepiinu, et ta ei suutnud oma s\u00f5pra kaitsta.",
		"tgt": "Despite that, and the fact that Valdez was intimately aware of the perils of his work, Ismail Bojorquez, 60, a co-founder and director of Riodoce, is wracked with guilt for failing to protect his friend."
	},
	{
		"src": "Ta usub, et tapmist soodustasid kaks viga.",
		"tgt": "He believes two errors contributed to the killing."
	},
	{
		"src": "Esimene neist oli Guzmani poegadega konkureeriva ja s\u00f5jajalal oleva kartelli kliki ninamehe Damaso Lopeziga tehtud intervjuu avaldamine veebruaris.",
		"tgt": "First there was the publication in February of an interview with Damaso Lopez, a leader of one of the rival cartel factions at war with Guzman's sons."
	},
	{
		"src": "See kirjat\u00fckk v\u00f5is poegi vihastada \u0096 kahtlustatavad j\u00f5uguliikmed ostsid k\u00f5ik v\u00e4ljaande koopiad \u00e4ra kohe, kui need ajalehekioskitesse j\u00f5udsid.",
		"tgt": "The piece may have angered the sons; suspected gang members bought up every copy of the edition as soon as they were delivered to newsstands."
	},
	{
		"src": "Teine viga oli see, et Valdezi ei sunnitud tema enda turvalisuse nimel riigist lahkuma p\u00e4rast seda, kui toimus haarang \u00fches teises sama lugu kajastanud ajalehetoimetuses.",
		"tgt": "The second mistake was not forcing Valdez to leave the country for his own safety after the seizure of another newspaper that carried the same story."
	},
	{
		"src": "Valdez oli legend nii Mehhikos kui ka v\u00e4lismaal ning tema tapmist n\u00e4hakse kui p\u00f6\u00f6rdepunkti ajakirjanike vastu suunatud v\u00e4givallas Mehhikos.",
		"tgt": "Valdez was a legend in Mexico and abroad, and his killing is seen as a milestone in Mexican violence against journalists."
	},
	{
		"src": "Ta oli nii kaua elus p\u00fcsinud, et tema s\u00f5brad ja kolleegid eeldasid, et ta on alatiseks olemas.",
		"tgt": "He'd survived for so long, his friends and colleagues assumed he'd always be there."
	},
	{
		"src": "Ta t\u00f6\u00f6tas 2003. aastal ajalehe Noroeste juures veteranreporterina, kui ta liitus viie kolleegiga, et luua Riodoce, m\u00fc\u00fces 50-dollarilisi osakuid.",
		"tgt": "He was a veteran reporter for Noroeste in 2003 when he joined five colleagues in creating Riodoce, selling $50 shares."
	},
	{
		"src": "Bojorquez \u00fctles, et Sinaloas \"oli v\u00f5imatu ajakirjandusega ilma narkoprobleemi puutumata tegeleda\".",
		"tgt": "In Sinaloa, \"it was impossible to do journalism without touching the narco issue,\" said Bojorquez."
	},
	{
		"src": "Ajaleht kogus ajapikku oma julgete ja ausate kajastustega tuntust ning m\u00fc\u00fck ja reklaam kasvasid.",
		"tgt": "Over time the paper earned a reputation for brave and honest coverage, and sales and advertising increased."
	},
	{
		"src": "Reporteritele meeldis avaldada j\u00f5ulisi uurimusi ilma tsensuuri kartmata ja lugejaid lummas tr\u00fckis, millest nad said lugeda lugusid, mida keegi teine ei julgenud kajastada.",
		"tgt": "Reporters loved being able to publish hard-hitting investigations without fear of censorship, and readers were fascinated by a publication where they could read stories nobody else dared to cover."
	},
	{
		"src": "Kaheksa aastat p\u00e4rast Riodoce asutamist v\u00f5itis ajaleht oma Ladina-Ameerika kajastuste eest prestii\u017ese Maria Moors Caboti auhinna.",
		"tgt": "Eight years after Riodoce was founded, it won the prestigious Maria Moors Cabot award for coverage in Latin America."
	},
	{
		"src": "Samal aastal v\u00f5itis Valdez Ajakirjanike Kaitse Komitee (AKK) rahvusvahelise ajakirjandusvabaduse auhinna oma julguse eest j\u00e4rgneda Mehhiko narkoloole k\u00f5ikjale, kuhu see viib.",
		"tgt": "That same year, Valdez won the International Press Freedom Award of the Committee to Protect Journalists for his courage in pursuing the Mexican drug story wherever it led."
	},
	{
		"src": "Ta tunnistas avameelselt, et kartis.",
		"tgt": "He freely acknowledged that he was frightened."
	},
	{
		"src": "\"Tahan edasi elada,\" \u00fctles ta AKK auhinda vastu v\u00f5ttes.",
		"tgt": "\"I want to carry on living,\" he said at the time of the CPJ award."
	},
	{
		"src": "Eelmisel oktoobril \u00fctles ta telekanalile Rompeviento TV antud intervjuus, et uimastikaubandus on Sinaloas eluviis.",
		"tgt": "Drug trafficking in Sinaloa \"is a way of life,\" he said last October, in an interview with Rompeviento TV."
	},
	{
		"src": "\"Pead v\u00f5tma omaks \u00fclesande, mis ajakirjanikuametiga kaasneb \u0096 teine v\u00f5imalus on lolli m\u00e4ngida.",
		"tgt": "\"You have to assume the task that falls to you as a journalist - either that or you play dumb."
	},
	{
		"src": "Ma ei taha, et minult k\u00fcsitaks, et mida ma nii paljude surmadega silmitsi seistes tegin v\u00f5i miks ma ei r\u00e4\u00e4kinud, mis toimub.\"",
		"tgt": "I don't want to be asked, 'What were you doing in the face of so much death ... why didn't you say what was going on?'\""
	},
	{
		"src": "Riodoce kollektiiv igatseb Valdezi, naljameest, kes ropendas nagu madrus, s\u00f5pra, kes jagas lahkelt embusi ja n\u00f5uandeid, \u00f5petajat, kes teadis, kuidas ellu j\u00e4\u00e4da.",
		"tgt": "The Riodoce staff misses Valdez, the jokester who swore like a longshoreman, the friend generous with hugs and advice, a teacher who knew how to survive."
	},
	{
		"src": "Nad toetusid tema rutiinile.",
		"tgt": "They relied on his routine."
	},
	{
		"src": "Ta kandis alati oma k\u00fcbarat.",
		"tgt": "He would always wear his hat."
	},
	{
		"src": "Ta l\u00e4ks kontorist \u00fcle tee asuvasse El Guayabo baari ja istus alati samas lauas.",
		"tgt": "He would go to El Guayabo, the bar across from the office, and would always sit at the same table."
	},
	{
		"src": "N\u00fc\u00fcd nad k\u00fcsivad, kas tema rutiiniarmastus sai talle saatuslikuks.",
		"tgt": "Now, they ask: Was his love of routine his downfall?"
	},
	{
		"src": "Ta surm on pannud ka neid ennast kahtlema, kuidas oma t\u00f6\u00f6d k\u00f5ige paremini teha ja elus p\u00fcsida.",
		"tgt": "His death also has forced them to question their own assumptions about how best to do their jobs and stay alive."
	},
	{
		"src": "\"Neile ei meeldi, kui j\u00e4ndad nende naiste, nende laste, nende seaduslike \u00e4ride, nende salajaste maandumisplatsidega, mida kasutatakse narkootikumide transportimiseks.\"",
		"tgt": "\"They don't like it if you mess with their women, their children, their clean businesses, their clandestine airstrips\" used to move drugs."
	},
	{
		"src": "\"Neid asju ei tohtinud puutuda,\" \u00fctles Bojorquez.",
		"tgt": "\"Those things were off-limits,\" said Bojorquez."
	},
	{
		"src": "Tulemuseks on isegi parimatel aegadel tugev enesetsensuur ja enesealalhoid.",
		"tgt": "The result is, even in the best of times, a high-level of self-censorship and self-preservation."
	},
	{
		"src": "Oma instinktide usaldamine.",
		"tgt": "Trusting one's instincts."
	},
	{
		"src": "Kui asi l\u00f5hnab kahtlaselt, hoia eemale.",
		"tgt": "If it smells wrong, stay away."
	},
	{
		"src": "Riodoce toimetaja Andres Villarreali s\u00f5nul on probleem selles, et \"l\u00f5hnataju saab petta... ja nii juhtuski see asi Javieriga\".",
		"tgt": "The trouble, said Riodoce editor Andres Villarreal, is that \"smell is a sense that can be fooled ... and then the thing with Javier happened.\""
	},
	{
		"src": "Tema ja teised \u00fctlevad, et Sinaloas ei kehti enam vanad reeglid, t\u00e4pselt nagu need ei kehti Tamaulipasis, Veracruzis, Guerreros ega muudes osariikides, mis on koduks tulusate smugeldamismarsruutide, n\u00f5rkade institutsioonide ja korrumpeerunud riigiametnike m\u00fcrgisele kooslusele.",
		"tgt": "The old rules, he and others say, no longer apply in Sinaloa - just as they don't in Tamaulipas, Veracruz, Guerrero and other states that are home to a toxic mix of lucrative smuggling routes, weak institutions and corrupt government officials."
	},
	{
		"src": "Maastik muutub pidevalt.",
		"tgt": "The landscape constantly shifts."
	},
	{
		"src": "Ruumis, kus Riodoce t\u00f6\u00f6tajad turvakoolituse jaoks kokku said, ei olnud j\u00e4rsku enam mobiiltelefonid lubatud; m\u00f5ned p\u00e4evad enne seda paljastati, et ainult valitsustele m\u00fc\u00fcdavat nuhkvara oli kasutatud Mehhikos ajakirjanike ja aktivistide j\u00e4lgimiseks.",
		"tgt": "In the room where Riodoce staff met for security training, suddenly no cellphones were allowed; days before, it was revealed that spyware sold exclusively to governments had been used to monitor journalists and activists in Mexico."
	},
	{
		"src": "Maja ees otsisid kaks politseinikku puu varjus leevendust 40-kraadisest kuumusest.",
		"tgt": "Outside, two police officers sought relief from the 104-degree (40 Celsius) heat in the shade of a tree."
	},
	{
		"src": "Valitsus m\u00e4\u00e4ras nad valvama Riodoce kontorit, mis asub neljakorruselises hoones Culiacani keskklassi naabruskonnas.",
		"tgt": "They were assigned by the state government to guard Riodoce's offices, housed in a four-story building in a middle-class neighborhood of Culiacan."
	},
	{
		"src": "M\u00f5ned reporterid m\u00f5tisklesid poolnaljatades, kas need politseinikud kuuluvad nende 50 protsendi politseinike hulka, kelle kuberner ise on ebausaldusv\u00e4\u00e4rseks tembeldanud.",
		"tgt": "Half-jokingly, some of the reporters wondered whether these officers are among the 50 percent of cops whom the governor himself has said are not trustworthy."
	},
	{
		"src": "Mitu kuud on m\u00f6\u00f6dunud ajast, mil reporterid on s\u00f5itnud m\u00e4gistesse maakohtadesse, kus kontroll on de facto narkoj\u00f5ukude k\u00e4es.",
		"tgt": "It has been months since the reporters have gone into the mountainous countryside, where the drug gangs are in de facto control."
	},
	{
		"src": "Riodoce selle n\u00e4dala v\u00e4ljaanne k\u00e4sitles kolme p\u00f5hilugu.",
		"tgt": "For this week's edition Riodoce was looking at three main stories."
	},
	{
		"src": "\u00dcks neist oli endise poksilegendi Julio Cesar Chavezi venna m\u00f5rv Sinaloas.",
		"tgt": "There was the killing of former boxing great Julio Cesar Chavez's brother in Sinaloa."
	},
	{
		"src": "Lisaks oli neil paljastav lugu valitsuse rahade kulutamisest kuberneri kodulinnale.",
		"tgt": "They also had an expose on government spending concentrated in the governor's hometown."
	},
	{
		"src": "Ja prokur\u00f6ri kabinetist kvartali kaugusel asuvast Culiacani \u00fchest k\u00f5ige kallimast restoranist r\u00f6\u00f6viti grupp inimesi.",
		"tgt": "And there was a group kidnapping in one of Culiacan's most expensive restaurants, a block from the prosecutor's office."
	},
	{
		"src": "Polnud mingit ametlikku teadaannet selle kohta, kes r\u00f6\u00f6viti v\u00f5i kuidas see juhtus, seega tuli olla ettevaatlik, kui oli aeg kirjutada seda, mida k\u00f5ik linnas teavad \u0096 restoran on nii uimastikauplejate kui ka ametiv\u00f5imude meelispaik.",
		"tgt": "There was no official word on who was abducted or how it happened, so caution set in when it came time to write what everyone in the city knows: that the restaurant is a favorite of both drug traffickers and authorities."
	},
	{
		"src": "Reporter sai avalikest dokumentidest teada, et restoran on registreeritud poliitiku nimele, kes kuulub v\u00f5imul olevasse Institutsioonilisse Revolutsiooniparteisse (IRP), mis domineeris k\u00f5iki poliitika tasandeid peaaegu kogu eelmise sajandi v\u00e4ltel.",
		"tgt": "A reporter learned from public records that the restaurant was registered under the name of a politician belonging to the ruling Institutional Revolution Party, or PRI, which dominated all levels of politics for nearly all of the last century."
	},
	{
		"src": "Viimasel ajal on mitut IRP kuberneri s\u00fc\u00fcdistatud laialdase kajastusega kohtuasjade raames korruptsioonis.",
		"tgt": "Recently several PRI governors have been accused of corruption in high-profile cases."
	},
	{
		"src": "Villarreal palus reporteril kirjutada eelnevatest intsidentidest samas paigas, kaasa arvatud sellest, kuidas h\u00fc\u00fcdnime El Chapo kandva Guzmani poeg p\u00e4\u00e4ses s\u00f5jav\u00e4ereidist.",
		"tgt": "Villarreal asked the reporter to write about prior incidents in that locale, including one in which a son of \"El Chapo\" Guzman escaped a military raid."
	},
	{
		"src": "K\u00f5igest m\u00f5ni kuu varem oleksid lugejad otsinud Valdezi kolumni, et saada inimr\u00f6\u00f6vi kohta teavet parimatelt allikatelt.",
		"tgt": "Just months before, readers would have looked to Valdez's column for the best-sourced information about the kidnapping."
	},
	{
		"src": "\"Varem oleksime me juba teadnud, mis juhtus,\" \u00fctles 46-aastane Villarreal, kelle kleenuke kehaehitus on teeninud talle h\u00fc\u00fcdnime El Flaco.",
		"tgt": "\"Before, we would have already known what happened,\" said Villarreal, 46, nicknamed \"El Flaco\" for his slender build."
	},
	{
		"src": "\"N\u00fc\u00fcd on k\u00f5ik suhtluskanalid meie allikatega katkenud.\"",
		"tgt": "\"Now all channels of communication with our sources have been broken.\""
	},
	{
		"src": "Valdezi kontorist on saanud hoiuruum siltidele ja kleebistele, mis protestivad ajakirjanike tapmise vastu, ja toimetuse t\u00f6\u00f6tajatest on saanud miski, mida nad ei osanud kunagi oodata \u0096 aktivistid pressi nimel.",
		"tgt": "Valdez's office has been repurposed as a storage room for signs and stickers protesting journalist killings, as staff have become something they never expected to be: activists on behalf of the press."
	},
	{
		"src": "Reporter Miriam Ramirez haaras paar silti ja suundus j\u00e4rgmisel hommikul kohaliku prokur\u00f6ri kabineti juurde meeleavaldusele j\u00e4rjekordse ajakirjaniku p\u00e4rast.",
		"tgt": "Reporter Miriam Ramirez grabbed a few of the signs and headed out the next morning for a demonstration at the local prosecutor's office over yet another journalist."
	},
	{
		"src": "Salvador Adame kadus l\u00e4\u00e4nepoolses Michoacani osariigis kolm p\u00e4eva p\u00e4rast Valdezi tapmist.",
		"tgt": "Salvador Adame disappeared in the western state of Michoacan three days after Valdez was killed."
	},
	{
		"src": "Leitud on p\u00f5lenud surnukeha ja ametnike s\u00f5nul kuulub see DNA-testide p\u00f5hjal talle.",
		"tgt": "A burned body has been discovered and officials say it is his, based on DNA tests."
	},
	{
		"src": "Ajakirjanikud on \u00fcle kogu riigi h\u00e4\u00e4lekamaks muutunud ning kritseldavad organiseeritud protestina k\u00f5nniteedele ja hoonetele fraasi \"SOS press\".",
		"tgt": "Nationwide, journalists have become more vocal, scrawling \"SOS Press\" on sidewalks and buildings in organized protests."
	},
	{
		"src": "Sellel p\u00e4eval on juhataja Bojorquez \u00e4ra Washingtonis, \u00fcritades koguda Valdezi juhtumis \u00f5igluse jalule seadmiseks rahvusvahelist toetust.",
		"tgt": "On this day, the director Bojorquez is away in Washington, trying to rally international support for justice in the Valdez case."
	},
	{
		"src": "P\u00e4ev p\u00e4rast Valdezi surma Sinaloa kuberneriga kohtudes s\u00fc\u00fcdistas Ramirez ametiv\u00f5ime ajakirjanike j\u00e4rele nuhkimises ja nende tapmises t\u00f5e r\u00e4\u00e4kimise t\u00f5ttu.",
		"tgt": "At a meeting with the governor of Sinaloa the day after Valdez was killed, Ramirez accused authorities of spying on journalists and having them killed for telling the truth."
	},
	{
		"src": "P\u00e4rast seda palus ta, et ta suunataks valitsuse tegevuse kajastamiselt mujale, muretsedes, et viha on ta objektiivsust m\u00f5jutanud.",
		"tgt": "She has since asked to be reassigned from covering the government, concerned that her anger has hurt her objectivity."
	},
	{
		"src": "Valdez oli korduvalt \u00f6elnud, et Mehhiko ajakirjanikud on organiseeritud kuritegevuse, kaass\u00fc\u00fcdlastest riigiametnike ja \u00fcksk\u00f5ikse \u00fchiskonna poolt \"sisse piiratud\".",
		"tgt": "Valdez had repeatedly said that journalists in Mexico are \"surrounded\" by organized crime, complicit government officials and an indifferent society."
	},
	{
		"src": "Oma viimases raamatus \"Narkoajakirjandus\" kirjutas ta, et reportereid ei tapa ainult narkoj\u00f5ugud, vaid seda tehakse ka poliitikute ja julgeolekuj\u00f5udude k\u00e4sul, kes on organiseeritud kuritegevusega mestis.",
		"tgt": "In his last book, \"Narco-journalism,\" he wrote that reporters are being killed not just by drug gangs but on the order of politicians and security forces in cahoots with organized crime."
	},
	{
		"src": "Meediakanalite j\u00e4relevalver\u00fchm Articulo 19 omistas eelmisel aastal enam kui poole ajakirjanike r\u00fcndamistest politseile ja riigiametnikele.",
		"tgt": "The media watchdog group Articulo 19 attributed more than half of attacks on journalists last year to police and public officials."
	},
	{
		"src": "\"Mehhikos sa sured, sest sind tahetakse vaikima panna,\" \u00fctles Ramirez.",
		"tgt": "\"In Mexico you die because they want to shut you up,\" Ramirez said."
	},
	{
		"src": "M\u00f5rvad m\u00f5juvad ilmselgelt verdtarretavalt.",
		"tgt": "Clearly, the murders have a chilling effect."
	},
	{
		"src": "Keegi ei unusta blogija Maria Elizabeth Maciase surma p\u00f5hjapoolses piiriosariigis Tamaulipasis kuus aastat tagasi.",
		"tgt": "No one forgets the death six years ago of blogger Maria Elizabeth Macias in the northern border state of Tamaulipas."
	},
	{
		"src": "Ta surnukeha leiti koos kirjaga, millele oli arvatavasti kirjutanud alla kartell Los Zetas: \"Ma olen siin oma reportaa\u017eide p\u00e4rast.\"",
		"tgt": "Her body was found along with a note purportedly signed by the Zetas cartel: \"Here I am because of my reports.\""
	},
	{
		"src": "Tema maharaiutud pea k\u00f5rval lebasid arvutiklaviatuur ja k\u00f5rvaklapid.",
		"tgt": "A computer keyboard and headphones lay next to her severed head."
	},
	{
		"src": "M\u00f5ned v\u00e4ljaanded on otsustanud oma uksed sulgeda, n\u00e4iteks ajaleht El Norte p\u00f5hjapoolses piiriosariigis Chihuahuas p\u00e4rast nende korrespondendi Miroslava Breachi tapmist m\u00e4rtsikuus.",
		"tgt": "Some outlets have opted to close, such as the newspaper El Norte, in the northern border state of Chihuahua, after the killing of correspondent Miroslava Breach in March."
	},
	{
		"src": "Teised lasevad edasi nii, nagu tegi ajaleht El Manana de Nuevo Laredo p\u00e4rast nende juhataja m\u00f5rva 2004. aastal.",
		"tgt": "Others keep going, as El Manana of Nuevo Laredo did following the killing of its director in 2004."
	},
	{
		"src": "2010. aastal k\u00f5netas ajaleht Diario de Ciudad Juarez narkokartelle avalikult esikaanel asuva juhtkirjaga \"Mida te meist tahate?\".",
		"tgt": "In 2010, Diario de Ciudad Juarez addressed the drug cartels publicly with a front-page editorial titled, \"What do you want from us?\""
	},
	{
		"src": "M\u00f5ned ajakirjanikud on koduosariikidest v\u00f5i isegi riigist pagenud.",
		"tgt": "Some journalists have fled their home states or even the country."
	},
	{
		"src": "Tegu on n\u00e4rves\u00f6\u00f6va otsusega.",
		"tgt": "It's a wrenching decision."
	},
	{
		"src": "Eksiilis on raske t\u00f6\u00f6d leida ja nad peavad endiselt t\u00e4navaid piidlema, et ohtusid v\u00e4ltida.",
		"tgt": "It's hard to find work in exile, and they still scan the streets, looking for danger."
	},
	{
		"src": "Ja m\u00f5nikord aetakse neid taga, nagu juhtus arvatavasti fotograafi Ruben Espinosaga, kes m\u00f5rvati koos nelja naisterahvaga 2015. aastal \u00fches Mexico korteris kolm kuud p\u00e4rast Veracruzist pagemist.",
		"tgt": "And sometimes, they are hunted down, as apparently was photographer Ruben Espinosa, who was murdered in 2015 along with four women in a Mexico City apartment three months after fleeing Veracruz."
	},
	{
		"src": "Need, kes j\u00e4\u00e4vad paigale ja j\u00e4tkavad t\u00f6\u00f6d, peavad iga p\u00e4ev riskantsete otsuste \u00fcmber tantsima.",
		"tgt": "For those who stay behind and continue the work, it's a daily dance of high-risk decisions."
	},
	{
		"src": "Ibarra, kes soovis kunagi luuletajaks saada, tunnistab, et narko\u00e4ri kajastamine hirmutab teda.",
		"tgt": "Ibarra - who once wanted to be a poet - admits that covering the drug trade scares him."
	},
	{
		"src": "\"Mehhiko on teel p\u00f5rgusse ja sellep\u00e4rast ma reporteriks hakkasingi,\" \u00fctles ta.",
		"tgt": "\"Mexico is going to hell, and that's why I became a reporter,\" he said."
	},
	{
		"src": "\u00dche hiljutise reede kesk\u00f6\u00f6l, mil v\u00e4rskeim number oli juba lukku l\u00f6\u00f6dud, istusid Riodoce toimetajad kontori ees k\u00f5nniteel ja r\u00fc\u00fcpasid \u00f5lut, kui j\u00e4rsku hakkasid k\u00f5igi telefonid vibreerima.",
		"tgt": "At midnight on a recent Friday, with the latest issue already put to bed, Riodoce editors sat on the sidewalk outside the office, drinking beer, when all at once, their phones began to buzz."
	},
	{
		"src": "Ranna\u00e4\u00e4rses kuurortlinnas Mazatlanis oli rivaalitsevate j\u00f5ukude ja julgeolekuj\u00f5udude vahel toimunud tulevahetustes hukkunud kinnitatud andmetel 19 inimest.",
		"tgt": "A series of shootouts involving gang rivals and security forces near the beach resort city of Mazatlan had left 19 confirmed dead."
	},
	{
		"src": "S\u00f5da eskaleerus j\u00e4tkuvalt, nagu lubasid ka mitmed piirkonnast leitud kartellide j\u00e4etud s\u00f5numid.",
		"tgt": "The war continued to escalate, as was promised by a series of cartel messages discovered in the area."
	},
	{
		"src": "Sealtsamast k\u00f5nnitee servalt panid reporterid uudise mobiiltelefoni kasutades Riodoce veebisaidile \u00fcles.",
		"tgt": "From the curb, via cellphone, they put the news up on Riodoce's website."
	},
	{
		"src": "J\u00e4rgmise p\u00e4eva esikaas vajas muutmist.",
		"tgt": "The front page would have to be changed the next day."
	},
	{
		"src": "Sireenid huilgasid m\u00f6\u00f6da \u0096 j\u00e4rjekordne tulevahetus piirkonnas.",
		"tgt": "Sirens wailed nearby - another shootout in the area."
	},
	{
		"src": "Bojorquez piilus valves olevate politseinike poole, et n\u00e4ha, kas nad on valvsad.",
		"tgt": "Bojorquez glanced over at the police officers standing guard to see if they were alert."
	},
	{
		"src": "Kui nad kartsidki, ei n\u00e4idanud nad seda v\u00e4hemasti v\u00e4lja.",
		"tgt": "If they were at all afraid, they didn't show it."
	},
	{
		"src": "Ajalehe langenud asutaja massiivse portree all, millel tema keskmine s\u00f5rm on n\u00e4ha kogu Sinaloale, toimetasid Riodoce t\u00f6\u00f6tajad tema j\u00e4lgedes.",
		"tgt": "Beneath the massive portrait of their newspaper's fallen founder, his middle finger displayed for all of Sinaloa to see, the staff of Riodoce was following in his footsteps."
	},
	{
		"src": "\"Kuidas saaks \u00fcldse sulgemisele m\u00f5elda,\" \u00fctles Bojorquez, \"kui samal p\u00e4eval, mil Javier tapeti, palus praktikant, et saadaksin ta t\u00e4navatele reportaa\u017ei tegema?\"",
		"tgt": "\"How can you even think of closing,\" Bojorquez said, \"when the same day Javier was killed the intern asked me to send her out to report on the street?\""
	},
	{
		"src": "Dinosaurus kasutas vaenlaste v\u00e4ltimiseks kaitsev\u00e4rvust",
		"tgt": "Dinosaur used camouflage to evade its enemies"
	},
	{
		"src": "Esmapilgul tundub see nagu kuju, kuigi \u00fcsna hirmutav.",
		"tgt": "At first glance, it looks like a statue albeit a terrifying one."
	},
	{
		"src": "Teadlased on avalikustanud n\u00fc\u00fcdseks esimesed leiud seoses kanada kaevuri avastatud uskumatu ninasarvikusuuruse olevusega, mis on niiv\u00f5rd h\u00e4sti s\u00e4ilinud, et asjatundjad on kirjeldanud seda kui \"dinosauruste Mona Lisat\".",
		"tgt": "Now researchers have revealed the first findings from the incredible rhino-sized creature found by a Canadian miner were so well preserved experts have described it as 'the Mona Lisa of dinosaurs'."
	},
	{
		"src": "See on lausa nii h\u00e4sti s\u00e4ilinud, et oli isegi v\u00f5imalik tuvastada, et tema soomustega kaetud nahk oli punakaspruuni v\u00e4rvi ja tema minevik oli olnud m\u00f5nev\u00f5rra \"keerukas\".",
		"tgt": "It was so well preserved, they were even able to determine the colour of its scaly skin was a reddish brown - and say it had something of a 'troubled past'."
	},
	{
		"src": "Ajakirjas Current Biology avaldatud reportaa\u017e kirjeldas olevust kui \"k\u00f5ige paremini s\u00e4ilinud soomusdinosaurust, mis on kunagi leitud\" ja kui \"\u00fcht parimat dinosauruseisendit kogu maailmas\".",
		"tgt": "The report in the journal Current Biology described it as 'the best-preserved armored dinosaur ever found, and one of the best dinosaur specimens in the world.'"
	},
	{
		"src": "Fossiili puhul on tegemist uue nodosauruse liigiga, mis elas kriidiajastu keskel, 110-112 miljonit aastat tagasi.",
		"tgt": "The fossil is a newfound species of nodosaur, which lived midway through the Cretaceous period, between 110 million and 112 million years ago."
	},
	{
		"src": "Selle uskumatult hea s\u00e4ilimine rabas teadureid, kes kirjeldavad seda \"t\u00f5eliselt m\u00e4rkimisv\u00e4\u00e4rsena\".",
		"tgt": "It's incredible well preserved state has stunned researchers, who describe it as 'truly remarkable'"
	},
	{
		"src": "See soomustega kaetud taimetoitlane on ajakirja National Geographic andmetel k\u00f5ige paremini s\u00e4ilinud seda t\u00fc\u00fcpi fossiil, mis on kunagi leitud.",
		"tgt": "The armoured plant-eater is the best preserved fossil of its kind ever found, according to reports in National Geographic."
	},
	{
		"src": "Selle leidis 21. m\u00e4rtsil 2011 Shawn Funk, kui ta kaevandas Suncor Milleniumi kaevanduses Fort McMurray l\u00e4hedal P\u00f5hja-Albertas Kanadas.",
		"tgt": "It was found by Shawn Funk, when he was digging at the Suncor Millenium Mine near Fort McMurray in northern Alberta, Canada, on March 21, 2011."
	},
	{
		"src": "Ta tabas midagi, mis ei meenutanud \u00fcmbritsevat kivi, ja otsustas l\u00e4hemalt uurida.",
		"tgt": "He hit something which seemed out of place from the surrounding rock, and decided to take a closer look."
	},
	{
		"src": "Avastatud fossiil saadeti Royal Tyrrelli paleontoloogiamuuseumi.",
		"tgt": "The fossil he uncovered was sent to the Royal Tyrrell Museum of Paleontology."
	},
	{
		"src": "J\u00e4rgmised kuus aastat t\u00f6\u00f6tati selle kallal, et loom 2500-naelasest (1100-kilosest) maat\u00fckist v\u00e4lja kaevata.",
		"tgt": "They spent the next six years working on uncovering the beast within the 2,500-pound (1,100 kg) lump of earth."
	},
	{
		"src": "P\u00e4rast kogu seda r\u00e4nka vaeva on l\u00f5pptulemus n\u00fc\u00fcd l\u00f5puks avalikkuse ette toomiseks valmis.",
		"tgt": "After all that hard work, the finished result is now ready to be unveiled."
	},
	{
		"src": "\"Kui pisut silmi kissitada, v\u00f5ib peaaegu uskuda, et ta magab,\" \u00fctles juhtiv autor Caleb Brown, teadur Royal Tyrrelli muuseumis, kus olevust eksponeeritakse.",
		"tgt": "'If you just squint your eyes a bit, you could almost believe it was sleeping,' said lead author Caleb Brown, a scientist at the Royal Tyrrell Museum where the creature is on display."
	},
	{
		"src": "\"See l\u00e4heb teadusajalukku \u00fche k\u00f5ige kaunima ja k\u00f5ige paremini s\u00e4ilinud dinosauruseisendina - dinosauruste Mona Lisana.\"",
		"tgt": "'It will go down in science history as one of the most beautiful and best preserved dinosaur specimens - the Mona Lisa of dinosaurs.'"
	},
	{
		"src": "Ta nahka uurides leidsid teadurid, et seda taimes\u00f6\u00f6jat, kes on k\u00fcll kaetud soomustega ja meenutab k\u00f5ndivat tanki, ohustasid t\u00f5en\u00e4oliselt m\u00e4rkimisv\u00e4\u00e4rselt lihatoidulised dinosaurused.",
		"tgt": "By studying its skin, researchers found that this plant-eater, though covered in armor and resembling a walking tank, likely faced a significant threat from meat-eating dinosaurs."
	},
	{
		"src": "See rohkete soomustega dinosaurus kasutas punast ja valget kaitsev\u00e4rvust, et peita end kiskjate eest, ning rakendas varjumistehnikat, mida nimetatakse vastuvarjutuseks ja mida kasutavad \u00fchtlasi paljud t\u00e4nap\u00e4eva loomad.",
		"tgt": "The heavily armoured dinosaur used red and white camouflage to hide from predators, and employed a shielding technique known as counter-shading, which is also used by many modern-day animals."
	},
	{
		"src": "See v\u00f5imaldas asjatundjate s\u00f5nul dinosaurusel paremini \u00fcmbrusesse sulanduda ja vaenlasi v\u00e4ltida, kuna suuremad dinosaurused pidasid talle t\u00f5en\u00e4oliselt jahti.",
		"tgt": "This would have allowed it to better blend into its surroundings and evade its enemies, experts say, suggesting it was preyed on by larger dinosaurs."
	},
	{
		"src": "See 110 miljoni aasta vanune nodosauruste perekonda kuuluv olevus j\u00f5udis esimest korda uudistesse mais ja on n\u00fc\u00fcd k\u00fclastatav Royal Tyrrelli paleontoloogiamuuseumis.",
		"tgt": "The 110-million-year-old creature, part of the nodosaur family, first hit headlines in May and is now on view at the Royal Tyrrell Museum of Palaeontology."
	},
	{
		"src": "Teadurid on n\u00fc\u00fcdseks olevust uurinud ja andsid sellele nime Borealopelta markmitchelli muuseumi laborandi Mark Mitchelli j\u00e4rgi, kes kuulus meeskonda, mis kulutas looma vaevan\u00f5udvaks paljastamiseks rohkem kui 7000 tundi.",
		"tgt": "Researchers have now studied and named the beast Borealopelta markmitchelli after museum technician Mark Mitchell, one of a team who spent more than 7,000 hours painstakingly uncovering it."
	},
	{
		"src": "T\u00e4nu isendi h\u00e4mmastavalt heale s\u00e4ilimisele oli dr Mitchellil ja rahvusvahelisel teadlaste meeskonnal v\u00f5imalik dokumenteerida soomuste kuju ja suurus looma kehal.",
		"tgt": "The amazing preservation of the specimen made it possible for Dr Mitchell and an international team of scientists to document the pattern and shape of scales and armour across its body."
	},
	{
		"src": "Nad avastasid vastuvarjutuse - loomariigis levinud kaitsemeetodi, mis t\u00e4hendab, et olevuse pealmine pool oli tumedam kui alumine.",
		"tgt": "They discovered countershading, a common method of defence in the animal kingdom, which means the top of the creature was darker than its underside."
	},
	{
		"src": "Kuigi vastuvarjutus on levinud, tulevad leiud \u00fcllatusena, kuna Borealopelta on m\u00e4rksa suurem kui t\u00e4nap\u00e4eval elavad vastuvarjutusega loomad.",
		"tgt": "Although countershading is common, the findings come as surprise because Borealopelta's size far exceeds that of countershaded animals alive today."
	},
	{
		"src": "See vihjab, et dinosaurust jahtisid piisavalt aktiivselt teised lihas\u00f6\u00f6jatest dinosaurused, et evolutsioon eelistas elluj\u00e4\u00e4mistaktikana vastasseisu asemel varjumist.",
		"tgt": "It suggests the dinosaur was hunted by enough pressure meat-eating dinosaurs that evolution favoured concealment over confrontation as a means of survival."
	},
	{
		"src": "Kuid enamik t\u00e4nap\u00e4evaseid vastuvarjutust kasutavaid loomi - nt hirved, sebrad v\u00f5i armadillid - on saagina palju v\u00e4iksemad ja haavatavamad, mis viitab, et nodosaurus pidi elluj\u00e4\u00e4miseks t\u00f5eliselt vaeva n\u00e4gema.",
		"tgt": "But most contemporary animals that have countershading -- think deer, zebras or armadillos -- are much smaller and more vulnerable as prey, signaling that this nodosaur faced a real struggle to survive."
	},
	{
		"src": "\"Tohutult suure ja rohkete soomustega kaetud dinosauruse j\u00f5uline jahtimine n\u00e4itab, kui ohtlikud v\u00f5isid kriidiajastu dinosaurustest r\u00f6\u00f6vloomad olla,\" \u00fctles Brown.",
		"tgt": "'Strong predation on a massive, heavily-armored dinosaur illustrates just how dangerous the dinosaur predators of the Cretaceous must have been,' said Brown."
	},
	{
		"src": "Soomuste orgaaniliste \u00fchendite keemiline anal\u00fc\u00fcs paljastas \u00fchtlasi, et dinosauruse nahk oli punakaspruun.",
		"tgt": "Chemical analysis of organic compounds in its scales also reveal that the dinosaur's skin would have been reddish brown."
	},
	{
		"src": "Teadlased j\u00e4tkavad looma uurimist, et saada vihjeid selle elu kohta, sh selle soolestiku s\u00e4ilinud sisu, et selgitada v\u00e4lja, mida loom oma viimaseks eineks s\u00f5i.",
		"tgt": "Scientists are continuing to study the animal for clues about its life, including its preserved gut contents to find out what it ate for its last meal."
	},
	{
		"src": "Nad usuvad, et dinosaurus kukkus surres j\u00f5kke, j\u00f5udes seel\u00e4bi vooluga merre, kus ta vajus selg ees ookeanip\u00f5hja.",
		"tgt": "They believe that when the dinosaur died, it fell into a river and was swept out to sea, where it sank on its back to the ocean floor."
	},
	{
		"src": "Sel ajal oli Albertas sama soe kui praegu L\u00f5una-Floridas ning j\u00f5ed ja ookeanid ulatusid t\u00f5en\u00e4oliselt palju kaugemale sisemaale kui praegu.",
		"tgt": "At that time, Alberta was as warm as south Florida is today, and rivers and oceans likely spread far further inland than they do now."
	},
	{
		"src": "\"See nodosaurus on t\u00f5eliselt m\u00e4rkimisv\u00e4\u00e4rne, kuna ta on t\u00e4ielikult kaetud s\u00e4ilinud soomuselise nahaga, samas on ta j\u00e4\u00e4nud ka kolmem\u00f5\u00f5tmeliseks, s\u00e4ilitades looma algse kuju,\" s\u00f5nas Brown.",
		"tgt": "'This nodosaur is truly remarkable in that it is completely covered in preserved scaly skin, yet is also preserved in three dimensions, retaining the original shape of the animal,' said Brown."
	},
	{
		"src": "\"Selle tulemusel n\u00e4eb loom t\u00e4nap\u00e4eval v\u00e4lja peaaegu samasugune kui kriidiajastul.",
		"tgt": "'The result is that the animal looks almost the same today as it did back in the Early Cretaceous."
	},
	{
		"src": "Selle rekonstrueerimiseks ei pea v\u00e4ga palju kujutlusv\u00f5imet kasutama - piisab lihtsalt silmade kissitamisest ja tundubki, et ta justkui magaks.\"",
		"tgt": "You don't need to use much imagination to reconstruct it; if you just squint your eyes a bit, you could almost believe it was sleeping.'"
	},
	{
		"src": "Kriidiajastu oli aeg, mil Maal uitasid tohutud kahel jalal liikuvad lihas\u00f6\u00f6jatest dinosaurused - teropoodid.",
		"tgt": "The Cretaceous was a time when giant theropods, meat-eating dinosaurs that stood on two legs, roamed the Earth."
	},
	{
		"src": "Kuigi nende k\u00f5igi kuningas Tyrannosaurus rex elas miljoneid aastaid hiljem kui Borealopelta, v\u00f5isid seda soomustatud dinosaurust jahtida m\u00f5ned tema hirmu\u00e4ratavad eelk\u00e4ijad.",
		"tgt": "Although the king of them all, Tyrannosaurus rex, lived millions of years after Borealopelta, the armoured dinosaur may have been hunted by some of its formidable ancestors."
	},
	{
		"src": "Nende hulka kuulub Acrocanthosaurus, 38 jalga (11,5 meetrit) pikk ja kuus tonni kaaluv koletis.",
		"tgt": "They include Acrocanthosaurus, a 38ft (11.5m) long monster weighing six tonnes."
	},
	{
		"src": "Teadlased, kelle hiljutised leiud on avaldatud ajakirjas Current Biology, usuvad, et Borealopelta uhuti p\u00e4rast surma merre ja see mumifitseerus mudas.",
		"tgt": "The scientists, whose latest findings appear in the journal Current Biology, believe Borealopelta was washed out to sea after it died and mummified in mud."
	},
	{
		"src": "Olevuse avastas 21. m\u00e4rtsil 2011 Shawn Funk, kui ta kaevandas Milleniumi kaevanduses Fort McMurray l\u00e4hedal P\u00f5hja-Albertas Kanadas.",
		"tgt": "The creature was found by Shawn Funk, when he was digging at the Millenium Mine near Fort McMurray in northern Alberta, Canada, on March 21, 2011."
	},
	{
		"src": "Muuseumi s\u00f5nul on see k\u00f5ige paremini s\u00e4ilinud soomusdinosaurus maailmas, sh nahk ja soomused, ning see on terviklik koonust kuni puusadeni.",
		"tgt": "According to the museum, it is the best preserved armoured dinosaur in the world, including skin and armour, and is complete from the snout to hips."
	},
	{
		"src": "Need olevused olid keskmiselt 18 jalga (viis meetrit) pikad ja kaalusid kuni 3000 naela (1300 kg).",
		"tgt": "The creatures were around 18 feet (five metres) long on average, and weighted up to 3,000 pounds (1,300 kg)."
	},
	{
		"src": "Selle \u00f5lgadest tungis v\u00e4lja kaks 20 tolli pikkust ora.",
		"tgt": "It featured two 20-inch-long spikes which protruded from its shoulders."
	},
	{
		"src": "Teadlased usuvad, et see soomustega kaetud taimes\u00f6\u00f6ja seikles l\u00e4bi praeguse L\u00e4\u00e4ne-Kanada, kuni \u00fcle ujutatud j\u00f5gi selle avamerre uhtus.",
		"tgt": "The researchers believe that the this armored plant-eater lumbered through what is now western Canada, until a flooded river swept it into open sea."
	},
	{
		"src": "Kuid dinosauruse merealune matmiskoht aitas s\u00e4ilitada oivaliselt detailselt selle soomused.",
		"tgt": "But the dinosaur's undersea burial preserved its armor in exquisite detail."
	},
	{
		"src": "Selle konkreetse isendi kivistunud j\u00e4\u00e4nused on niiv\u00f5rd h\u00e4sti s\u00e4ilinud, et m\u00fcgarlikke soomusplaate piki dinosauruse pealuud katavad endiselt nahaj\u00e4\u00e4nused.",
		"tgt": "The fossilised remains of this particular specimen are so well preserved that remnants of skin still cover bumpy armour plates along the dinosaur's skull."
	},
	{
		"src": "Nagu kirjutas Michael Greshko ajakirjas National Geographic: \"Selline s\u00e4ilivuse aste on sama haruldane kui lotov\u00f5it.",
		"tgt": "As Michael Greshko wrote for National Geographic, such level of preservation 'is a rare as winning the lottery."
	},
	{
		"src": "Mida rohkem ma seda vaatan, seda uskumatum see tundub.",
		"tgt": "The more I look at it, the more mind-boggling it becomes."
	},
	{
		"src": "Kivistunud nahaj\u00e4\u00e4nused katavad endiselt looma koljul paiknevaid m\u00fcgarlikke soomusplaate.",
		"tgt": "Fossilized remnants of skin still cover the bumpy armor plates dotting the animal's skull."
	},
	{
		"src": "Parem esijalg lebab tema k\u00f5rval ning viis varvast on sirutatud \u00fclespoole.",
		"tgt": "Its right forefoot lies by its side, its five digits splayed upward."
	},
	{
		"src": "Mul on v\u00f5imalik tema tallal olevaid soomuseid loendada.\"",
		"tgt": "I can count the scales on its sole.'"
	},
	{
		"src": "Kuidas \u00fcks aktivist leidis vastuse k\u00fcsimusele \"Kelle t\u00e4navad?\"",
		"tgt": "How one activist came to learn the answer to the question: 'Whose Streets?'"
	},
	{
		"src": "9. augustil 2014 sai Brittany Ferrell t\u00e4ieliku \u0161oki.",
		"tgt": "On Aug. 9, 2014, Brittany Ferrell was shaken to her core."
	},
	{
		"src": "K\u00f5igest p\u00e4ev p\u00e4rast New Yorki reisimist istus see St. Louisi elanik Airbnb kaudu renditud toas voodil, sirvides telefonis Facebooki.",
		"tgt": "Just a day after arriving in New York City on a trip, the St. Louis native sat on the bed of an Airbnb she was renting, scrolling through Facebook on her phone."
	},
	{
		"src": "Ta sattus peale oma kunagise koolikaaslase postitusele.",
		"tgt": "She stumbled upon a post from someone from high school."
	},
	{
		"src": "Seal oli kirjas: \"Politsei tappis just 18-aastase nooruki ja ta lebab siiani t\u00e4naval.\"",
		"tgt": "\"The police just killed an 18 year old kid and he's still laying in the street,\" it read."
	},
	{
		"src": "Ta oli segaduses, miks keegi teine ei olnud seda teavet tema voogu postitanud, mist\u00f5ttu ta sulges Facebooki ja avas Twitteri.",
		"tgt": "Confused, noticing no one else on her feed had posted the information, she closed Facebook and opened Twitter."
	},
	{
		"src": "Pidemega @TheePharoah kasutaja postitusi oli korduvalt tema ajajoonel edasi jagatud.",
		"tgt": "A user with the handle @TheePharoah was being constantly retweeted onto her timeline."
	},
	{
		"src": "St. Louisi piirkonnast p\u00e4rit r\u00e4ppar edastas reaalajas s\u00e4utse Michael Browni, relvastamata 18-aastase mustanahalise noormehe surma kohta, kelle tappis Fergusonis Missouris valge politseinik.",
		"tgt": "The St. Louis-area rapper was live-tweeting the death of Michael Brown, an unarmed black 18-year-old killed by a white police officer in Ferguson, Mo."
	},
	{
		"src": "Ta postitas pildi Browni elutust kehast, mis lebas t\u00e4naval, j\u00e4\u00e4des sinna neljaks tunniks.",
		"tgt": "He posted a picture of Brown's lifeless body stretched out in the street, where it would stay for four hours."
	},
	{
		"src": "\"See on hullumeelne,\" m\u00f5tles Ferrell endamisi.",
		"tgt": "\"This is wild,\" Ferrell thought to herself."
	},
	{
		"src": "Kuid surm ei olnud tema ega ta kogukonna jaoks midagi uut.",
		"tgt": "But death was nothing new for her and her community."
	},
	{
		"src": "Ta pani oma telefoni \u00e4ra, kuid n\u00e4gi hiljem \u00f5htul uuesti s\u00e4utse, mis teatasid seekord inimeste kogunemisest Canfield Drive'il.",
		"tgt": "She put down her phone only to return later that evening to tweets about people gathering on Canfield Drive."
	},
	{
		"src": "Jagati fotosid politseilindist ja karjuvatest inimestest ning mehest, kes v\u00e4itis end olevat Browni isa ja hoidis silti kirjaga \"Fergusoni politsei tappis just mu relvastamata poja!\".",
		"tgt": "There were photos of police tape and people yelling, and of a guy claiming to be Brown's father holding a sign that read, \"Ferguson police just killed my unarmed son!\""
	},
	{
		"src": "Ta vaatas reaalajas voogu, kus politseinik seisis haukuva koeraga protestijate grupi ees.",
		"tgt": "She watched a live feed where a police officer stood in front of a group of protesters with a barking dog."
	},
	{
		"src": "Teises videos vinnastas \u00fcks teine politseinik tema s\u00f5nul p\u00fcssi ja karjus: \"Ma tapan teid k\u00f5iki... loomad.\"",
		"tgt": "In another video, a different cop, she said, cocked his rifle and screamed, \"I'll kill all you ... animals.\""
	},
	{
		"src": "Ferrellile meenub, kuidas ta tabas end m\u00f5ttelt: \"See on ebatavaline.\"",
		"tgt": "\"'This is not usual,'\" Ferrell recalled saying."
	},
	{
		"src": "\"\"See ei ole sedalaadi m\u00f5rv, millega me oleme harjunud ja mida me v\u00f5iksime nimetada t\u00fc\u00fcpiliseks.\"",
		"tgt": "\"'This isn't the type of murder that we've become used to and can call typical.'"
	},
	{
		"src": "Tundsin sel hetkel hirmujudinaid.",
		"tgt": "In that moment I felt chills."
	},
	{
		"src": "Ma olin vihane ja nutsin.\"",
		"tgt": "I was angry and crying.\""
	},
	{
		"src": "Ta broneeris tagasilennu ja s\u00f5itis j\u00e4rgmisel p\u00e4eval koju.",
		"tgt": "She booked a return flight and went home the next day."
	},
	{
		"src": "Olles kell 23 maandunud, l\u00e4ks ta isa juurde oma kuueaastasele t\u00fctrele j\u00e4rele ja otsustas, et nad s\u00f5idavad j\u00e4rgmisel hommikul kahekesi Fergusoni.",
		"tgt": "After landing at 11 p.m., she picked up her 6-year-old daughter from her dad's house and decided the two of them would head to Ferguson the next morning."
	},
	{
		"src": "See, mis Ferrelli ja Fergusoniga j\u00e4rgmisel kolmel aastal toimus, on keskne teema uues dokumentaalfilmis \"Whose Streets?\" (\"Kelle t\u00e4navad?\"), mis esilinastub kinodes 11. augustil.",
		"tgt": "What happened, to Ferrell and to Ferguson in the following almost three years is the subject of a new documentary, \"Whose Streets?,\" in theaters Aug. 11."
	},
	{
		"src": "See on lugu elluj\u00e4\u00e4misest ja protestist, armastusest ja kaotusest, tugevusest ja sitkusest nende inimeste vaatevinklist, kes elavad selles kogukonnas ja kes t\u00e4itsid vastuseid n\u00f5udes t\u00e4navad.",
		"tgt": "It's a tale of survival and protest, love and loss, strength and resilience from the vantage point of the people who live in the community and packed the streets demanding answers."
	},
	{
		"src": "Kui Ferrell koos t\u00fctrega - kellel oli seljas lilleline kleit ja peas sellega sobiv kroon - Fergusoni poole s\u00f5itis, vestlesid nad taas teemal, mis oli neil enne seda hommikut korduvalt varem jutuks tulnud - mustanahaliste kogemustest ja elutingimustest.",
		"tgt": "As Ferrell drove to Ferguson with her daughter, who was wearing a floral dress and matching crown, the two revisited a conversation they'd had countless times before that morning \"about the black experience and black condition.\""
	},
	{
		"src": "\"Kas m\u00e4letad, kui ma \u00f5petasin sulle, kuidas must kogukond pidi oma \u00f5iguste eest v\u00f5itlema?\" meenutab ta ennast k\u00fcsimas.",
		"tgt": "\"You remember how I taught you about when black people had to fight for what they believed in?\" she recalled saying."
	},
	{
		"src": "\"Me s\u00f5idame praegu Fergusoni, sest politsei tappis 18-aastase poisi ja see ei ole \u00f5ige.\"",
		"tgt": "\"We're going to Ferguson right now because the police killed an 18-year-old boy and it wasn't right."
	},
	{
		"src": "\"Ma ei saanud teda mitte kaasa v\u00f5tta,\" \u00fctles Ferrell hiljem.",
		"tgt": "I couldn't not take her,\" Ferrell said later."
	},
	{
		"src": "\"See, mis praegu toimub, on... minevikus toimunu kulminatsioon.",
		"tgt": "\"This happening today is a culmination of ... that has happened in the past."
	},
	{
		"src": "Ta peab seda teadma ja n\u00e4gema ning selle keskel kasvama.",
		"tgt": "She needs to know it and see it and be raised in it."
	},
	{
		"src": "Ta peab \u00f5ppima aktivismi ja organiseerimise kohta ning tundma samas ka mustanahaliste kogemuste ja elutingimuste erinevaid kihte ning seda, mida me peame tegema, et saada vabaks ja ennast vabastada.",
		"tgt": "She needs to be well developed in the area of not just activism and organizing but knowing the different layers of the black experience and the black condition and what we must do to get free, to free ourselves."
	},
	{
		"src": "Isegi kui mul \u00f5nnestub teda kasvatada nii, et ta ei koge isiklikult jultunud rassismi, ei erine ta m\u00f5nest teisest mustanahalisest t\u00fctarlapsest.",
		"tgt": "Even if I'm fortunate enough to provide her an experience where she doesn't personally experience blatant racism, she is no different than the next black woman-child."
	},
	{
		"src": "Tunnen, et teeksin talle karuteene, kui kaitseksin teda selle maailma eest.\"",
		"tgt": "I feel like I would be doing her a disservice to shield her from that.\""
	},
	{
		"src": "Esimene peatus, mille nad Fergusoni j\u00f5udes tegid, oli South Florissanti teel - politseijaoskonnast \u00fcle tee j\u00e4\u00e4vas paigas, millest oli saanud teatud laadi laagriplats, kus aktivistid ootasid uudiseid politseinik Darren Wilsoni kohta, kellele ei esitatudki l\u00f5puks s\u00fc\u00fcdistust.",
		"tgt": "The first stop when they arrived in Ferguson was on South Florissant Road, a site across from the police department that became a campground of sorts as the activists awaited word of Officer Darren Wilson's eventual non-indictment."
	},
	{
		"src": "Seal \u00fchendasid Ferrell ja tema t\u00fctar j\u00f5ud kohaliku \u00e4riomanikuga, kes valmistas l\u00f5unaeineid.",
		"tgt": "There Ferrell and her daughter linked up with a local business owner who was making sack lunches."
	},
	{
		"src": "Nad panid toidukotte kokku ja aitasid neid protestijatele jagada.",
		"tgt": "They prepared bags and helped pass them out to protesters."
	},
	{
		"src": "Ferrelli jaoks hakkas aeglaselt v\u00f5tma kuju uut t\u00fc\u00fcpi aktivism.",
		"tgt": "Slowly, a new type of activism began to take shape for Ferrell."
	},
	{
		"src": "\"Minu aktivism muutus t\u00e4ielikult p\u00e4rast 9. augustit,\" \u00fctles ta, m\u00e4rkides, et kui ta oli Missouri-St. Louisi \u00fclikoolis \u00fcli\u00f5pilane, oli ta V\u00e4hemustest \u00d5endus\u00f5pilaste Liidu president ning keskendus toidu\u00f5iglusele ja tervisega seotud ebav\u00f5rdsustele mustanahaliste kogukondades.",
		"tgt": "\"My activism completely transformed after Aug. 9,\" she said, noting that while an undergrad at the University of Missouri-St. Louis, she was president of the Minority Student Nurses Assn. and focused on food justice and health disparities in black communities."
	},
	{
		"src": "\"Mul ei olnud mingit organiseerimiskogemust.",
		"tgt": "\"I had no experience in organizing."
	},
	{
		"src": "See k\u00f5ik lihtsalt laabus.\"",
		"tgt": "It all just came.\""
	},
	{
		"src": "N\u00e4dalaid hiljem kohtus Ferrell \u00f5htuse meeleavalduse ajal \u00fche filmi kaasre\u017eiss\u00f6\u00f6ri Sabaah Folayaniga.",
		"tgt": "Weeks later, Ferrell met Sabaah Folayan, one of the film's co-directors, during an evening demonstration."
	},
	{
		"src": "Folayan \u00fctles, et tema ja filmioperaator Lucas Alvarado-Farrar tahtsid lihtsalt toimuvat dokumenteerida.",
		"tgt": "Folayan said she and her director of photography Lucas Alvarado-Farrar \"just wanted to document\" what was happening."
	},
	{
		"src": "Ferrelli p\u00e4he kerkis k\u00fcsimus: \"Kas te p\u00fc\u00fcate toimuvat dokumenteerida v\u00f5i leida lugu, mida saab \u00e4ra kasutada?\"",
		"tgt": "A question came to Ferrell's mind: \"Do you want to document or are you trying to find a story that you can exploit?\""
	},
	{
		"src": "Taoline skeptitsism oli tingitud lugematust arvust juhtumitest, kus inimesed - tihtipeale valgenahalised - tulevad kogukonda ja p\u00fc\u00fcavad selle valust ja vastupidavusest kasu l\u00f5igata.",
		"tgt": "That skepticism was informed by countless instances of people - often white - coming into a community to profit off its pain and resilience."
	},
	{
		"src": "Folayan selgitas hiljutises intervjuus: \"Olime kuulnud, et Fergusonis s\u00fcndinud ja kasvanud inimeste h\u00e4\u00e4lt ei v\u00f5eta kuulda ja me soovisime teha seda teisiti.\"",
		"tgt": "As Folayan explained in a recent interview, \"We had heard that people who are born and raised in Ferguson were not having their voices centered, and we wanted to do it differently.\""
	},
	{
		"src": "Folayan oli juba l\u00f6\u00f6nud k\u00e4ed kaasre\u017eiss\u00f6\u00f6ri Damon Davisega, piirkonna kunstnikuga, kes oli tuntud aktivismi poolest seoses surmam\u00f5istetud vangidega.",
		"tgt": "Folayan had already linked up with co-director Damon Davis, an area artist known for his activism around death row inmates."
	},
	{
		"src": "Tema kaasatus muutis projekti k\u00f6itvaks Ferrelli ja veel kuue teise kohaliku jaoks, keda filmi \"Whose Streets?\" meeskond p\u00e4rast Browni tulistamist aastaid j\u00e4lgis.",
		"tgt": "His involvement endeared Ferrell to the project, along with six other locals the \"Whose Streets?\" team followed in the years after Brown's shooting."
	},
	{
		"src": "\"Selles dokumentaalfilmis ei r\u00e4\u00e4gi keegi meie eest ega meiega, vaid k\u00f5neleme meie ise,\" \u00fctles Davis.",
		"tgt": "\"This documentary is not somebody speaking for us or speaking to us, it's us speaking,\" Davis said."
	},
	{
		"src": "\"Minu jaoks oli t\u00e4htis, kuidas neid inimesi kujutatakse, kuna nii kujutatakse ka mind.\"",
		"tgt": "\"That was the main thing for me, how these people will be represented, because that's how I will be represented.\""
	},
	{
		"src": "Kuigi eesm\u00e4rk polnud keskenduda Ferrelli kogemusele - taheti n\u00e4idata, et liikumine ei seisne \"lunastajast juhis, vaid kogukonna kokkutulemises\", nagu s\u00f5nas Folayan -, kujunes temast filmi k\u00f5ige avatum osaline.",
		"tgt": "While the goal wasn't to focus on Ferrell's experience - in an effort to show that the movement is \"not about a messiah leader but a community coming together,\" Folayan said - she proved to be the most open of the film's participants."
	},
	{
		"src": "Selle tulemusena dokumenteerib \"Whose Streets?\" \u00fcllatavalt isiklikke aspekte Ferrelli elust, nagu armumine ja oma naisega abiellumine.",
		"tgt": "As a result, \"Whose Streets?\" documents surprisingly personal aspects of Ferrell's life, like falling in love and marrying her wife."
	},
	{
		"src": "\"Ma tundsin, nagu oleksin alasti,\" \u00fctles Ferrell, naerdes esimese korra \u00fcle, mil ta valmis linateost n\u00e4gi.",
		"tgt": "\"I felt like I was naked,\" said Ferrell, laughing about the first time she saw the finished product."
	},
	{
		"src": "\"Aga ma m\u00f5istsin, et selle t\u00f6\u00f6 tegemise ja mustanahaliste inimeste inimlikustamisega peab kaasnema teatud haavatavus.\"",
		"tgt": "\"But I understood that with doing this work and humanizing black folks, there has to be a level of vulnerability.\""
	},
	{
		"src": "Veelgi enam, Ferrelli lugu r\u00f5hutab ja seab uuesti keskmesse mustanahalise homoseksuaalse naise rolli laiemas Black Lives Matteri liikumises.",
		"tgt": "Moreover, Ferrell's story reiterates and re-centers the role of black queer women in the broader Black Lives Matter movement."
	},
	{
		"src": "Kaks liikumise kolmest algatajast, kes m\u00f5tlesid sotsiaalmeedias 2012. aastal mustanahalise teismelise Trayvon Martini tapmise j\u00e4rel v\u00e4lja teemaviite #BlackLivesMatter, on homoseksuaalsed.",
		"tgt": "Two of the movement's three founders - who coined #BlackLivesMatter on social media in the aftermath of the 2012 killing of black teen Trayvon Martin - identify as queer."
	},
	{
		"src": "\"Juhtivas rollis mustanahalised homoseksuaalsed naised on liikumist \u00fcle\u00fcldiselt alal hoidnud,\" s\u00f5nas Ferrell, \"ja seda just seet\u00f5ttu, et peame pidevalt mitmel rindel v\u00f5itlema.",
		"tgt": "\"Black queer women in leadership has sustained the movement overall,\" said Ferrell, \"and that's because we're constantly at battle on multiple fronts."
	},
	{
		"src": "Mustanahalised homoseksuaalsed naised peavad kogu seda koormat kandma.\"",
		"tgt": "Black queer women have to bear the brunt of it all.\""
	},
	{
		"src": "Folayan n\u00f5ustus, m\u00e4rkides, et \"liikumist hoiavad t\u00f5epoolest elus mustanahalised naised ja paljud neist on mustanahalised homoseksuaalsed naised\".",
		"tgt": "Folayan agreed noting that \"the movement is really upheld by black women and a lot of queer black women.\""
	},
	{
		"src": "Ta v\u00e4idab samas, et \"tegemist ei ole mingisuguse v\u00f5rdsete v\u00f5imaluste loomise t\u00fc\u00fcpi asjaga\" - Ferrelli ei valitud filmi keskpunktiks tema identiteedi t\u00f5ttu.",
		"tgt": "She insists, however, that \"this is not some affirmative action type of thing\" where Ferrell was chosen as the film's heart because of her identities."
	},
	{
		"src": "\"Ta oli inimene, kellest \u00f5hkas \u00f5iget energiat,\" \u00fctles ta.",
		"tgt": "\"She was the person who was galvanizing this energy,\" she said."
	},
	{
		"src": "\"Aga see ei ole kokkusattumus, et ta otse rindejoonel paiknes, sest mustanahalise homoseksuaalse naisena sellistes s\u00f5lmpunktides elades on palju kaalul.",
		"tgt": "\"It's not a coincidence though she was on the front lines, because living life at those intersections as a black queer woman, you have so much on the line."
	},
	{
		"src": "Tema energiat on v\u00f5imalik l\u00e4bi ekraani tajuda.\"",
		"tgt": "You can feel her energy through the screen.\""
	},
	{
		"src": "Samal ajal on uudistekaamerad Fergusonist ammu kadunud, kuid rassilised sidemed kogukonna ja politsei vahel on endiselt haprad.",
		"tgt": "Meanwhile, back in Ferguson, the news cameras are long gone but fraught racial ties between the community and police persist."
	},
	{
		"src": "Ferrellile meeleavalduse ajal maantee blokeerimise eest m\u00e4\u00e4ratud tingimisi karistus kestab veel 2,5 aastat.",
		"tgt": "Ferrell is on probation for 2\u00bd more years for blocking a highway during a demonstration."
	},
	{
		"src": "Ta kirjeldab sotsiaalpoliitilist \u00f5hustikku piirkonnas, mida ta kutsub koduks, lihtsalt \"tohuvabohuks\".",
		"tgt": "She describes the socio-political atmosphere of the area she calls home simply: \"A mess.\""
	},
	{
		"src": "Sellegipoolest peab ta endiselt t\u00e4htsaks mantrat, mille ta on s\u00f6\u00f6vitanud m\u00e4llu alates ajast, mil ta tervelt kolm aastat tagasi Fergusoni t\u00e4navatele l\u00e4ks.",
		"tgt": "Still, she clings to a chant she's committed to memory since taking to Ferguson's streets a full three years ago."
	},
	{
		"src": "\"Meie kohustus on v\u00f5idelda oma vabaduse eest.",
		"tgt": "\"It is our duty to fight for our freedom."
	},
	{
		"src": "Meie kohustus on v\u00f5ita.",
		"tgt": "It is our duty to win."
	},
	{
		"src": "Me peame \u00fcksteist armastama ja toetama.",
		"tgt": "We must love and support each other."
	},
	{
		"src": "Meil ei ole kaotada midagi peale meie ahelate.\"",
		"tgt": "We have nothing to lose but our chains.\""
	},
	{
		"src": "7 nippi, kuidas p\u00e4rast Weekendi pidu pohmellist \u00fcle saada",
		"tgt": "7 tips for getting over the Weekend Festival hangover"
	},
	{
		"src": "M\u00f5ned kangemad mehepojad leiavad p\u00e4rast napsurohket pidu k\u00fcll, et millest h\u00e4da, sellest ka abi.",
		"tgt": "After a party with lots of drinking, a certain tougher breed of people find themselves thinking the hair of the dog that bit them might be a good idea."
	},
	{
		"src": "V\u00f5i l\u00e4htuvad \u00fctlusest \"v\u00e4ldi pohmelli, p\u00fcsi purjus\".",
		"tgt": "Or they follow the maxim \u201cavoid a hangover, stay drunk.\u201d"
	},
	{
		"src": "Aga see on vaid v\u00e4ltimatu edasil\u00fckkamine ja tervisele korralik p\u00f5nts.",
		"tgt": "But this is just putting off the inevitable and is quite a blow to one\u2019s health."
	},
	{
		"src": "Mida sa saad teha, et p\u00e4rast t\u00e4nast ja homset Weekendi tralli - v\u00f5i muud pidu - end hommikul paremini tunda ja pohmellist v\u00f5imalikult valutult \u00fcle saada?",
		"tgt": "What can you do to feel better in the morning after today and tomorrow\u2019s Weekend festival or other party and get over a hangover as painlessly as possible?"
	},
	{
		"src": "Joo vett.",
		"tgt": "Drink water."
	},
	{
		"src": "Alkoholile alla ja peale, p\u00e4rast suurt pidu hommikul ... v\u00f5i v\u00f5imalusel isegi alkoholi asemel.",
		"tgt": "Before and after alcohol, after the big party in the morning\u2026or even instead of alcohol."
	},
	{
		"src": "Kuna keha kaotab alkoholi tarvitades palju vedelikku, siis tuleb see kuidagi tagasi saada.",
		"tgt": "Because the body loses lots of fluid when consuming alcohol, it has to be replenished."
	},
	{
		"src": "Koos veega uhutakse kehast v\u00e4lja ka mineraalained ja sestap on hea juua mineraalvett.",
		"tgt": "Along with the water, minerals are also flushed out of the body, and so it is good to drink mineral water."
	},
	{
		"src": "Kuna napsutamise j\u00e4rgselt on magu sageli \u00e4rritunud, siis on eriti hea, kui too on mullivaba v\u00f5i vaid kergelt gaseeritud.",
		"tgt": "The stomach lining is often irritated after tippling, so still water or lightly carbonated water is especially good."
	},
	{
		"src": "Mine jalutama.",
		"tgt": "Take a walk."
	},
	{
		"src": "Kindlasti ei maksaks pohmelliga suunduda vanaema juurde puid l\u00f5hkuma - see v\u00f5ib osutuda saatuslikuks valeotsuseks.",
		"tgt": "Certainly it wouldn\u2019t be wise to go split wood at grandma\u2019s \u2013 that could be a fateful miscue."
	},
	{
		"src": "Aga kerge jalutusk\u00e4ik aitab kehal j\u00e4lle meelde tuletada, mis tunne on elus olla.",
		"tgt": "But a light walk helps the body remember what it feels like to be alive."
	},
	{
		"src": "Telgis lamamine ja pohmaka v\u00e4ljamagamine on aegan\u00f5udvam tervekssaamise viis.",
		"tgt": "Lying in a tent and sleeping off a hangover is a more time-consuming way of recovering."
	},
	{
		"src": "Anna kehale energiat tagasi tasapisi ja ettevaatlikult.",
		"tgt": "Give your body back its energy little by little, carefully."
	},
	{
		"src": "Kui oled eilsest \u00fclejoomisest niigi oksele hakkamas, ei tasu kindlasti \u00fcritada makku laadida suurt rasvast praadi.",
		"tgt": "If you\u2019re already experiencing nausea because of yesterday\u2019s overindulgence, it isn\u2019t a good idea to burden your liver with a big fatty meal."
	},
	{
		"src": "Alusta n\u00e4iteks v\u00e4rskest mahlast, milles sisalduvad puuviljasuhkrud su keha vaikselt turgutama asuvad.",
		"tgt": "Start with fresh juice, containing fruit sugars that will start giving your body sustenance quietly."
	},
	{
		"src": "Kui l\u00f5una paiku tervis juba kannatab, siis v\u00f5iksid proovida n\u00e4iteks puljongit.",
		"tgt": "If your health is doing poorly around lunch, try some bouillon for example."
	},
	{
		"src": "Ja veidi hiljem juba seljankat.",
		"tgt": "And solyanka meat soup a bit later already."
	},
	{
		"src": "V\u00e4ldi kohvi.",
		"tgt": "Avoid coffee."
	},
	{
		"src": "See diureetikum vabastab su keha viimsestki veest.",
		"tgt": "This diuretic will rob your body of the last liquid."
	},
	{
		"src": "Nagu juba \u00f6eldud: vesi ja mahl on su s\u00f5brad.",
		"tgt": "As already said, water and juice are your friends."
	},
	{
		"src": "\u00c4ra panusta valuvaigistitele.",
		"tgt": "Don\u2019t count on pain relievers."
	},
	{
		"src": "Kui v\u00f5tad \u00f5htul pohmelli ennetamiseks valuvaigistit, siis peab su maks tegelema lisaks alkoholile ka paratsetamooli v\u00f5i ibuprofeeniga ja kaotab nii j\u00f5udlust.",
		"tgt": "If you take a pain reliever in the evening to avoid hangover, your liver has to deal with the acetaminophen or ibuprofen in addition to the alcohol and will lose strength."
	},
	{
		"src": "Nii rikud oma maksa veelgi enam ja edaspidi on pohmakad hullemadki.",
		"tgt": "You will do even more damage to your liver and your hangovers will be worse in future."
	},
	{
		"src": "Lisaks ei p\u00fcsi valuvaigisti nagunii kehas kuigi kaua.",
		"tgt": "In addition, pain relievers don\u2019t stay in your body all that long."
	},
	{
		"src": "Kui v\u00f5tad hommikul valuvaigistit, siis \u00e4ra tee seda t\u00e4itsa t\u00fchja k\u00f5huga - see \u00e4rritab su niigi r\u00e4situd magu.",
		"tgt": "If you take a pain reliever in the morning, don\u2019t take it on an empty stomach \u2013 it will irritate your already inflamed stomach."
	},
	{
		"src": "V\u00f5i kui partnerit pole v\u00f5tta, siis saa iseendaga h\u00e4sti l\u00e4bi.",
		"tgt": "Or if you don\u2019t have a partner, you can get along well with yourself."
	},
	{
		"src": "M\u00f5jub umbes samamoodi nagu jalutamine, aga jalutades ei saa orgasmi.",
		"tgt": "It has about the same effect was a walk, except you don\u2019t orgasm on a walk."
	},
	{
		"src": "V\u00e4ldi aga liiga aktiivset tempot ja p\u00f6\u00f6raseid poose - pohmelli ajal peaks f\u00fc\u00fcsiline pingutus olema m\u00f5\u00f5dukas.",
		"tgt": "Avoid a too active pace and wild positions \u2013 physical exertion should be moderate during a hangover."
	},
	{
		"src": "Tee nalja.",
		"tgt": "Use humour."
	},
	{
		"src": "Aja s\u00f5prade-kaaskannatajatega lolli juttu, tee lihtsaid tobedusi ja naera s\u00f5bralikult nii iseenda kui teiste (kannatuste) \u00fcle.",
		"tgt": "Talk foolish talk with your friends and co-sufferers, do stupid things and laugh in a friendly manner about your own and others\u2019 (sufferings)."
	},
	{
		"src": "Nali ja naer ei pruugi pohmakat \u00e4ra ajada, aga kindlasti on nende abil j\u00e4reln\u00e4htusid l\u00f5busam taluda.",
		"tgt": "Humour and laughter may not drive a hangover away but it certainly makes it easier to tolerate the aftereffects."
	},
	{
		"src": "\u00dckskord l\u00e4heb pohmell \u00fcle niikuinii!",
		"tgt": "At some point, every hangover will go away."
	},
	{
		"src": "Northwesterni professorit ja Oxfordi \u00dclikooli t\u00f6\u00f6tajat otsitakse taga kahtlustatavatena m\u00f5rvas",
		"tgt": "Northwestern Professor and Oxford University Employee Wanted for Homicide"
	},
	{
		"src": "Politsei s\u00f5nul otsitakse \u00fcleriigiliselt taga Northwesterni \u00dclikooli professorit ja Oxfordi \u00dclikooli t\u00f6\u00f6tajat, kellest on saanud kahtlusalused p\u00e4rast surmavate pussitamishaavadega meesterahva surnukeha leidmist \u00fchest Chicago luksuskorterist.",
		"tgt": "A nationwide manhunt is underway for a Northwestern University professor and an Oxford University employee who are wanted as suspects after a man was found fatally stabbed inside a luxury Chicago apartment, police said."
	},
	{
		"src": "Cooki maakonna kohtudokumentide kohaselt anti esmasp\u00e4eval v\u00e4lja ilma kautsjoniv\u00f5imaluseta vahistamisk\u00e4sud 42-aastase Wyndham Lathemi ja 56-aastase Andrew Warreni arreteerimiseks s\u00fc\u00fcdistatuna esimese astme m\u00f5rvas nende v\u00e4idetava seotuse t\u00f5ttu Trenton H. James Cornell-Duranleau surmaga.",
		"tgt": "On Monday, first-degree murder warrants without bail were issued for Wyndham Lathem, 42, and Andrew Warren, 56, for their alleged involvement in the death of Trenton H. James Cornell-Duranleau, Cook County court records show."
	},
	{
		"src": "Dokumentide andmetel suri 26-aastane Cornell-Duranleau p\u00e4rast korduvat pussitamist.",
		"tgt": "The documents say Cornell-Duranleau, 26, died after being stabbed multiple times."
	},
	{
		"src": "Hoiatuse kohaselt, mille Chicago politseijaoskond kogukonnale v\u00e4ljastas, avastati surnukeha 27. juulil.",
		"tgt": "A community alert released by the Chicago Police Department says the body was discovered on July 27."
	},
	{
		"src": "Politseinikud said telefonik\u00f5ne ja leidsid Grand Plaza kortermajja saabudes eest ohvri, kelle kehal oli mitu torkehaava.",
		"tgt": "Officers received a call and arrived at the Grand Plaza Apartments and found the victim with several lacerations on his body."
	},
	{
		"src": "Ametnike s\u00f5nul tunnistati Cornell-Duranleau s\u00fcndmuskohal surnuks ja uurijad k\u00e4sitlevad pussitamist m\u00f5rvana, samal ajal kui politsei otsib aktiivselt kahte kahtlusalust.",
		"tgt": "Cornell-Duranleau was pronounced dead on the scene and detectives are investigating the stabbing as a homicide while police actively search for the two suspects, officials said."
	},
	{
		"src": "Lathem on t\u00f6\u00f6tanud alates 2007. aastast Northwesterni \u00dclikoolis mikrobioloogia ja immunoloogia kaasprofessorina.",
		"tgt": "Lathem has been an associate professor of microbiology and immunology at Northwestern University since 2007."
	},
	{
		"src": "\u00dclikooli avalike suhete asepresident Alan K. Cubbage \u00fctles e-kirjana saadetud avalduses, et Lathem on n\u00fc\u00fcd t\u00f6\u00f6lt ajutiselt k\u00f5rvaldatud ja tal on keelatud Northwesterni \u00dclikooli linnakutesse siseneda.",
		"tgt": "Alan K. Cubbage, the vice president for university relations, said in an emailed statement that Lathem is now on administrative leave and has been banned from entering Northwestern University campuses."
	},
	{
		"src": "\"Tegu on n\u00fc\u00fcd p\u00e4devate ametiv\u00f5imude uuritava kriminaalasjaga ning Northwesterni \u00dclikool teeb uurijatega koost\u00f6\u00f6d,\" \u00fctles Cubbage.",
		"tgt": "\"This is now a criminal matter under investigation by the appropriate authorities, and Northwestern University is cooperating in that investigation,\" Cubbage said."
	},
	{
		"src": "Warren on Oxfordi \u00dclikooli finantsosakonnas vanemassistent.",
		"tgt": "Warren is a senior treasury assistant at Oxford University."
	},
	{
		"src": "\u00dclikooli ja Somerville'i kolled\u017ei esindaja \u00fctles e-kirjana edastatud avalduses: \"Oleme olnud \u00fchenduses Suurbritannia politseiga ja valmis USA uurimisasutusi igal v\u00f5imalikul viisil aitama.\"",
		"tgt": "A spokesperson for the university and Somerville College said in an emailed statement that, \"We have been in contact with the police in the UK and are ready to help the US investigating authorities in any way they need.\""
	},
	{
		"src": "Lisaks oli avalduses kirjas, et Warreni kolleegid on \u0161okeeritud ja soovivad, et ta ennast v\u00e4lja annaks.",
		"tgt": "The statement added that Warren's colleagues were shocked and want him to turn himself in."
	},
	{
		"src": "Chicago politseijaoskonna kommunikatsiooniosakonna juhataja Anthony Guglielmi soovitab kahtlusalustel tungivalt ennast v\u00f5imudele \u00fcles anda.",
		"tgt": "Chief Communications Officer of the Chicago Police Department Anthony Guglielmi said he strongly encourages the suspects to surrender to authorities."
	},
	{
		"src": "\"Politseil on aimu, kus nad viibivad, aga tegeleme t\u00e4pse asukoha m\u00e4\u00e4ratlemisega \u00fcha intensiivsemalt,\" \u00fctles Guglielmi.",
		"tgt": "\"Police have an idea of their whereabouts but our efforts to locate that are intensifying,\" Guglielmi said."
	},
	{
		"src": "Guglielmi s\u00f5nul aitavad kahtlusaluseid otsida nii kohalikud, piirkondlikud kui ka riiklikud ametiv\u00f5imud.",
		"tgt": "Guglielmi said local, regional and national authorities are helping find the suspects."
	},
	{
		"src": "Guglielmi \u00fctles, et politsei sai telefonik\u00f5ne Grand Plaza kortermaja haldurilt, kes oli saanud just kr\u00fcptilise vihje, et korteris nr 1008 on midagi toimunud.",
		"tgt": "Guglielmi said police received a call from the Grand Plaza building manager who had just received a cryptic tip that said something had occurred in apartment 1008."
	},
	{
		"src": "Politsei kirjelduste kohaselt oli tegu v\u00f5ika vaatepildiga.",
		"tgt": "Police described the scene as very gruesome."
	},
	{
		"src": "Guglielmi v\u00e4itel pole selge, kas s\u00fcndmus ise toimus samuti 27. juulil.",
		"tgt": "Guglielmi said it is unclear if the incident also occurred on July 27."
	},
	{
		"src": "Ta \u00fctles, et turvakaamerad kinnitavad Lathemi ja Warreni viibimist hoones.",
		"tgt": "Lathem and Warren were confirmed to be at the building by security cameras, he said."
	},
	{
		"src": "\"Usume, et professor Lathamil ja ohvril oli suhe,\" lisas Guglielmi.",
		"tgt": "\"We believe Professor Latham and the victim had a relationship,\" Guglielmi said."
	},
	{
		"src": "Grand Plaza juhtkond saatis elanikele kirja: \"Politsei t\u00f6\u00f6tab praegu s\u00fcndmuste kronoloogia ja ohvri tausta v\u00e4ljaselgitamisega ning uurib erinevaid motiive, kaasa arvatud v\u00f5imalust, et tegu oli perekonnat\u00fcliga.\"",
		"tgt": "The management team at Grand Plaza released a statement to residents saying, \"Police are currently working on the timeline and background of the victim and are exploring a variety of motives, including a possible domestic incident.\""
	},
	{
		"src": "Idufirmad, mis aitavad teie ettev\u00f5ttel v\u00e4ltida j\u00e4rgmiseks Uberiks saamist",
		"tgt": "The start-ups that will help your company avoid becoming the next Uber"
	},
	{
		"src": "Amy Errett soovis m\u00f5\u00f5ta oma e-kaubanduse idufirmas t\u00f6\u00f6tajate rahulolu, kuid k\u00fcsitlused olid tulutud.",
		"tgt": "Amy Errett wanted to gauge employee happiness at her e-commerce start-up, but surveys weren't working."
	},
	{
		"src": "Vastused olid tihtipeale ebam\u00e4\u00e4rased, kasutud v\u00f5i, veelgi hullem, eksitavad.",
		"tgt": "Responses were often vague, unhelpful or, worse, deceitful."
	},
	{
		"src": "Ja isegi kui ta lubas tagada anon\u00fc\u00fcmsuse, ei usaldanud m\u00f5ned t\u00f6\u00f6tajad seda protsessi.",
		"tgt": "And even if she promised anonymity, some workers didn't trust the process."
	},
	{
		"src": "\"See s\u00fcsteem lihtsalt polnud j\u00e4rjekindel ja objektiivne,\" s\u00f5nas Errett, kes juhib 75 t\u00f6\u00f6tajaga San Franciscos tegutsevat juuksehooldustooteid m\u00fc\u00fcvat e-kaubanduse ettev\u00f5tet Madison Reed.",
		"tgt": "\"It just never had consistency and objectivity,\" said Errett, who runs the 75-person San Francisco e-commerce hair care company Madison Reed."
	},
	{
		"src": "Niisiis kutsus ta appi v\u00e4lised isikud.",
		"tgt": "So she called in outsiders for help."
	},
	{
		"src": "T\u00e4rkamas on uut t\u00fc\u00fcpi inimressurssidega tegelevad idufirmad, mis aitavad ettev\u00f5tetel v\u00e4lja selgitada, mida nende t\u00f6\u00f6tajad tunnevad.",
		"tgt": "A new breed of human resources start-ups is cropping up to help companies figure out how their employees feel."
	},
	{
		"src": "Arendades ja litsentsides tarkvara, mille kindel eesm\u00e4rk on m\u00f5\u00f5ta t\u00f6\u00f6tajate kaasatust, v\u00f5imaldavad nad ettev\u00f5tetel teha \u00e4kk-k\u00fcsitlusi, v\u00f5tta sihile kindlaid meeskondi ja demograafilisi r\u00fchmasid, pakkuda t\u00f6\u00f6tajatele anon\u00fc\u00fcmsust ja kaebuste esitamise kuuma liini ning m\u00f5ningatel juhtudel lubada keelekandjatel minna m\u00f6\u00f6da C-taseme juhtidest ja p\u00f6\u00f6rduda otse juhatuse poole.",
		"tgt": "By building and licensing software that has the specific purpose of measuring employee engagement, they allow companies to do snap polls, target specific teams and demographic groups, offer employees anonymity and complaint hotlines, and in some cases allow whistle-blowers to bypass C-suite executives and go straight to the board of directors."
	},
	{
		"src": "\"N\u00fc\u00fcd on olemas sellised t\u00f6\u00f6riistad nagu Strava ja Fitbit, mis on m\u00f5eldud tervise j\u00e4lgimiseks, aga kus on Fitbit teie ettev\u00f5ttele?\" k\u00fcsis Jim Barnett, kaasasutaja ja tegevjuht Redwood City idufirmas Glint, mille tarkvaralisi anal\u00fc\u00fctikat\u00f6\u00f6riistu kasutavad ettev\u00f5tted t\u00f6\u00f6tajate kaasatuse m\u00f5\u00f5tmiseks.",
		"tgt": "\"You've now got tools such as Strava and Fitbit for tracking your health, but where's the Fitbit for your company?\" said Jim Barnett, co-founder and chief executive of Redwood City start-up Glint, whose software analytics tools are used by companies to measure employee engagement."
	},
	{
		"src": "Erretti s\u00f5nul on ta saanud kolme aasta jooksul, mil ta on Glinti kasutanud, palju parema \u00fclevaate sellest, mida ta t\u00f6\u00f6tajad m\u00f5tlevad ja tunnevad.",
		"tgt": "Errett said she gained more insight into what her employees were thinking and feeling in three years using Glint."
	},
	{
		"src": "Lisaks \u00e4kkuuringutele ja kindlatele meeskondadele suunatud k\u00fcsitlustele pakub see ettev\u00f5tte soojuskaarti, mis annab \u00fclevaate sellest, millistes osakondades on k\u00f5ige rohkem kaebusi ja millistel juhtidel on madalaim toetus, v\u00f5imaldades tal selgitada v\u00e4lja p\u00f5hjused.",
		"tgt": "In addition to the snap surveys and polls of specific teams, it offers a heat map of the company showing at a glance which units have the most complaints and which managers have low approval scores - allowing her to drill down on why."
	},
	{
		"src": "Ettev\u00f5tted on hakanud m\u00f5istma, et nad peavad p\u00fcsima kursis oma t\u00f6\u00f6kultuuriga, et mitte muutuda j\u00e4rgmiseks Uberiks, mis on olnud m\u00e4ssitud skandaalidesse alates sellest, kui endine t\u00f6\u00f6taja avaldas blogipostituse, mis kirjeldas ahistavat keskkonda, kus karistati neid, kes julgesid s\u00f5na v\u00f5tta.",
		"tgt": "Companies are coming to realize they must stay on top of their workplace culture, lest they become the next Uber, which has been enmeshed in scandal since a former employee published a blog post describing an environment of harassment where those who spoke out were punished."
	},
	{
		"src": "Selliste idufirmade nagu Glint jaoks on \u00fclevaate omamise soov tulus \u00e4riv\u00f5imalus.",
		"tgt": "For start-ups such as Glint, this desire for oversight is a lucrative business opportunity."
	},
	{
		"src": "\u00dclemaailmne juhtimis-, reguleerimis- ja vastavusvaldkond v\u00f5ib olla vastavalt finantstehnoloogia statistika veebisaidi Let's Talk Payments andmetele 2020. aastaks v\u00e4\u00e4rt rohkem kui 118,7 miljardit dollarit.",
		"tgt": "The global governance, regulation and compliance industry could be worth more than $118.7 billion by 2020, according to finance tech insights website Let's Talk Payments."
	},
	{
		"src": "Denveris Colorados tegutsev idufirma Convercent, mis aitab ettev\u00f5tetel ennetada ja tuvastada sobimatut k\u00e4itumist, t\u00e4heldas sel aastal Uberi kahtlase reputatsiooni taustal huvi ja aktiivsuse kasvu.",
		"tgt": "Denver, Colo., start-up Convercent, which helps companies prevent and detect bad behavior, saw an uptick in interest and activity earlier this year amid Uber's fall into disrepute."
	},
	{
		"src": "Convercentil on peaaegu 600 klienti, nende hulgas Airbnb, Microsoft ja Tesla.",
		"tgt": "Convercent has nearly 600 clients, including Airbnb, Microsoft, and Tesla."
	},
	{
		"src": "Uber registreeris ennast hiljuti kliendiks.",
		"tgt": "Uber recently signed up as a client."
	},
	{
		"src": "Nagu Glintki, laseb Convercent ettev\u00f5tetel saata kohandatud impulssk\u00fcsitlusi, koguda reaalajas konfidentsiaalseid vastuseid ja vaadata soojuskaarte probleemsetest valdkondadest.",
		"tgt": "Like Glint, Convercent lets companies send customized \"pulse\" surveys, gather confidential responses in real time, and view heat maps of its problem areas."
	},
	{
		"src": "See pakub \u00fchtlasi anon\u00fc\u00fcmset s\u00f5numsideliini, mis v\u00f5imaldab t\u00f6\u00f6tajatel sobimatust k\u00e4itumisest teada anda.",
		"tgt": "It also offers an anonymous texting hotline that lets employees report bad behavior."
	},
	{
		"src": "Ja kui asjasse puutub tegevjuht, l\u00e4hevad kaebused otse juhatusele.",
		"tgt": "And if the chief executive is implicated, complaints go straight to the board of directors."
	},
	{
		"src": "\"Avalik arvamus on anastanud reguleerivad asutused,\" \u00fctles Convercenti asutaja ja tegevjuht Patrick Quinlan.",
		"tgt": "\"The court of public opinion has usurped regulators,\" said Patrick Quinlan, the founder and chief executive of Convercent."
	},
	{
		"src": "Quinlan s\u00f5nas, et kui leitakse, et ettev\u00f5te kohtleb oma t\u00f6\u00f6tajaid halvasti v\u00f5i k\u00e4itub ebaeetiliselt, v\u00f5ib ettev\u00f5te seista silmitsi t\u00f5siste tagaj\u00e4rgedega, nagu tarbijate boikotid, t\u00f6\u00f6tajate lahkumine ja kohtuasjad, isegi siis, kui reguleerivad asutused ei sekku.",
		"tgt": "If a company is found to treat its employees poorly or behave unethically, even if regulators don't step in, it can face costly consequences from consumer boycotts, employee attrition and lawsuits, Quinlan said."
	},
	{
		"src": "Ruby Tuesday, restoranikett, millel on rohkem kui 25 000 t\u00f6\u00f6tajat 500 tegevuskohas, on kasutanud Convercenti rohkem kui aasta, et tagada t\u00f6\u00f6tajate teadlikkus eeskirjadest ja toimingutest ning pakkuda h\u00f5lpsat viisi korporatsiooni peakorteriga suhtlemiseks.",
		"tgt": "Ruby Tuesday, the restaurant chain with more than 25,000 employees across 500 locations, has used Convercent for more than a year to ensure employees are aware of policies and procedures and offer an easy way to reach its corporate headquarters."
	},
	{
		"src": "Kui t\u00f6\u00f6taja tahtis varem probleemist teatada, pidi ta leidma korporatsiooni peakorteri telefoninumbri v\u00f5i meiliaadressi, esitama ametliku kaebuse ning lootma, et seda v\u00f5etakse t\u00f5siselt.",
		"tgt": "Previously, if an employee wanted to report a problem, he or she had to find a phone number or email for corporate headquarters, lodge a formal complaint, and hope it was taken seriously."
	},
	{
		"src": "See oli tihtipeale heidutav ja ebamugav protsess, \u00fctles Ruby Tuesday \u00fcldn\u00f5unik James Vitrano, kelle s\u00f5nul ei olnud t\u00f6\u00f6tajate kaebuste j\u00e4lgimiseks head viisi.",
		"tgt": "It was often an intimidating and uncomfortable experience, said James Vitrano, Ruby Tuesday's general counsel, who said there was no good way of tracking employee complaints."
	},
	{
		"src": "N\u00fc\u00fcd, mil ettev\u00f5te kasutab Convercenti, on aga v\u00f5imalik probleeme, nagu diskrimineerimine, ahistamine v\u00f5i ebaausad palgapraktikad, mis ei j\u00f5udnud varem juhtideni, kes tegutsesid teistes linnades v\u00f5i osariikides asuvates kontorites, kiiremini tuvastada ja nendega tegeleda.",
		"tgt": "Now that the company is using Convercent, though, problems that were previously hidden from executives who sat in offices cities or states away - such as discrimination, harassment or unfair wage practices - can be more quickly identified and addressed."
	},
	{
		"src": "\"Mul on v\u00f5imalik p\u00e4\u00e4seda l\u00e4hemale t\u00f6\u00f6tajate holistlikule 360-kraadisele kogemusele,\" s\u00f5nas Vitrano, kes juhib Ruby Tuesday riskihaldusr\u00fchma.",
		"tgt": "\"I can get closer to that holistic, 360-degree view into the employment experience,\" said Vitrano, who oversees Ruby Tuesday's risk management group."
	},
	{
		"src": "\"Ja me kaitseme oma osanikke kohtuvaidluste eest t\u00f6\u00f6tajatega.\"",
		"tgt": "\"And we're protecting our shareholders from employment litigation.\""
	},
	{
		"src": "Quinlan \u00fctles, et ettev\u00f5tted hakkasid eetilist k\u00e4itumist, v\u00e4\u00e4rtusi ja t\u00f6\u00f6tajate kaasatust v\u00f5tma palju t\u00f5sisemalt 2002. aastal ehk p\u00e4rast seda, kui audiitorfirma Arthur Andersen kukkus eetiliste rikkumiste t\u00f5ttu seoses Enroni skandaaliga kokku.",
		"tgt": "Companies started taking ethics, values and employee engagement more seriously in 2002 after accounting firm Arthur Andersen collapsed because of ethical violations from the Enron scandal, Quinlan said."
	},
	{
		"src": "Kuid alles siis, kui \"sotsiaalmeedia sai k\u00fcpseks\", m\u00f5istsid ettev\u00f5tted, et nad ei saa takistada oma musta pesu avalikult veebis pesemist.",
		"tgt": "But it wasn't until \"social media came into its own\" that companies realized they couldn't stop their dirty laundry from going viral online."
	},
	{
		"src": "\"Enne tehnoloogia kasutamist eetilise k\u00e4itumise j\u00e4lgimiseks kasutasid inimesed strateegiana lootust,\" \u00fctles ta.",
		"tgt": "\"Prior to using technology to monitor ethics, people used hope as a strategy,\" he said."
	},
	{
		"src": "Nii Glint kui ka Convercent pakuvad oma tarkvara teenusena, v\u00f5ttes ettev\u00f5tetelt perioodilist tasu oma toodete kasutamise eest.",
		"tgt": "Both Glint and Convercent offer their software as a service, charging companies recurring fees to use their products."
	},
	{
		"src": "See on \u00e4rimudel ja v\u00f5imalus, millel on riskikapitali investorite heakskiit, kes on olnud toeks m\u00f5lemale idufirmale.",
		"tgt": "It's a business model and opportunity that has the approval of venture capital investors, who have propped up both start-ups."
	},
	{
		"src": "Convercenti rahastasid veebruaris 10 miljoni dollari ulatuses sellised firmad nagu Sapphire Ventures ja Tola Capital, t\u00f5stes sellega kogutud kapitali v\u00e4\u00e4rtuseks 47 miljonit dollarit.",
		"tgt": "Convercent raised $10 million in funding in February from firms such as Sapphire Ventures and Tola Capital, bringing its total capital raised to $47 million."
	},
	{
		"src": "Glinti investeeris novembris 10 miljonit dollarit Bessemer Venture Partners, suurendades ettev\u00f5tte kogurahastust 60 miljoni dollarini.",
		"tgt": "Glint secured $10 million in November from Bessemer Venture Partners, bringing its total funding to $60 million."
	},
	{
		"src": "Sellised investeeringud ei tule \u00fcllatusena, kui v\u00f5tta arvesse ettev\u00f5tete, kultuuri ja riskikapitali omavahelist seotust.",
		"tgt": "These investments hardly come as a surprise, given the interconnected nature of companies, culture and venture capital."
	},
	{
		"src": "Aina rohkem uuringuid n\u00e4itab, et t\u00e4nap\u00e4evased t\u00f6\u00f6tajad ootavad t\u00f6\u00f6kohalt enamat kui varem.",
		"tgt": "There's a growing body of research showing today's employees expect more from their workplaces than before."
	},
	{
		"src": "Konkurentsirohketel turgudel, nagu Silicon Valley, on k\u00f5rged palgad ja huvitavad projektid pelgalt laual olevad panused.",
		"tgt": "In competitive markets such as Silicon Valley, high salaries and interesting projects are merely table stakes."
	},
	{
		"src": "T\u00f6\u00f6tajad tahavad tunda, et neid aktsepteeritakse ja v\u00e4\u00e4rtustatakse ning et nad p\u00fchendavad oma aega ettev\u00f5ttele, millel on positiivne missioon.",
		"tgt": "Employees want to feel that they're accepted and valued and that they're giving their time to a company with a positive mission."
	},
	{
		"src": "\"Kui inimesed on ettev\u00f5ttes \u00f5nnelikud, tunnevad, et neid kuulatakse ja et t\u00f6\u00f6, mida nad teevad, on rahuldust pakkuv, on nad rohkem p\u00fchendunud ettev\u00f5tte edu tagamisele,\" \u00fctles Nina McQueen, kes on \u00fcldise kasu ja t\u00f6\u00f6tajate kogemusega tegeleva osakonna asepresident LinkedInis, mis kasutab nii Convercenti kui ka Glinti.",
		"tgt": "\"When people are happy to be at a company, feel their voices are heard, and that the work they are doing is rewarding, they are more committed to making that company successful,\" said Nina McQueen, vice president of global benefits and employee experience at LinkedIn, which uses both Convercent and Glint."
	},
	{
		"src": "Investorid teenivad tulu, kui nende portfelli kuuluvatel ettev\u00f5tetel l\u00e4heb h\u00e4sti; ettev\u00f5tetel l\u00e4heb h\u00e4sti, kui t\u00f6\u00f6tajad on p\u00fchendunud ja kaasatud.",
		"tgt": "Investors achieve returns when their portfolio companies do well; companies do well when employees are committed and engaged."
	},
	{
		"src": "Kui kolmanda poole anal\u00fc\u00fctikat\u00f6\u00f6riistad lubavad suurendada t\u00f6\u00f6tajate p\u00fchendumust ja kaasatust, siis pole ime, et need toetust leiavad.",
		"tgt": "If third-party analytics tools promise to increase employee commitment and engagement, it's no wonder they're finding backing."
	},
	{
		"src": "Andmete omamine t\u00f6\u00f6tajate kaasatuse kohta on t\u00f6\u00f6kultuuri asjatundjate s\u00f5nul t\u00e4htis.",
		"tgt": "Having data on employee engagement is important, according to workplace culture experts."
	},
	{
		"src": "Kuid need andmed on kasutud, kui ettev\u00f5tte j\u00e4relvaatajad nendega midagi peale ei hakka.",
		"tgt": "But the data are useless unless a company's custodians take action."
	},
	{
		"src": "Tegelikult v\u00f5ib see, kui ettev\u00f5te k\u00fcsib oma t\u00f6\u00f6tajatelt tagasisidet, tekitada ootusi, et ees ootavad muutused.",
		"tgt": "In fact, if a company asks employees for their feedback, it can set an expectation that change is on the way."
	},
	{
		"src": "Ja kui muutused ei toimu piisavalt kiiresti v\u00f5i \u00fcldse mitte, v\u00f5ib see p\u00f5hjustada pettumust ja v\u00e4hendada t\u00f6\u00f6tajate kaasatust.",
		"tgt": "And if change doesn't come fast enough, or at all, it can breed disappointment and make employees disengaged."
	},
	{
		"src": "\"Kui k\u00fcsite 4000 ettepanekut, peate olema valmis 4000 vestluseks,\" \u00fctles konsultatsiooni- ja \u00e4rihaldusettev\u00f5tte Kotter International president Russell Raath, kes on n\u00e4inud, kuidas ettev\u00f5tted teevad vea sellega, et toetuvad liiga palju andmete kogumisele.",
		"tgt": "\"If you're going to ask for 4,000 suggestions, you need to be prepared to have 4,000 conversations,\" said Russell Raath, president of consulting at business management firm Kotter International, who has seen companies make the mistake of relying too much on data collection."
	},
	{
		"src": "\"Sest kui asju ei viida l\u00f5puni, siis t\u00f6\u00f6tajad m\u00f5tlevad: \"Kas te tegelikult v\u00f5tsite mind kuulda?",
		"tgt": "\"Because if you don't follow through, employees will wonder, 'Did you really hear me?"
	},
	{
		"src": "Kas te hoolite?",
		"tgt": "Do you care?"
	},
	{
		"src": "Ja kui teie ei hooli, siis miks peaksin mina hoolima?\" \"",
		"tgt": "And if you don't care, why should I care?' \""
	},
	{
		"src": "Erretti s\u00f5nul on Madison Reedil, kes korraldab t\u00f6\u00f6tajate seas n\u00fc\u00fcd kord kuus uuringuid, olnud v\u00f5imalik rakendada meetmeid samal p\u00e4eval, kui probleemist on Glinti kaudu teatatud.",
		"tgt": "Madison Reed, which now does monthly employee surveys, has been able to take action the same day a problem is reported on Glint, according to Errett."
	},
	{
		"src": "Ning p\u00e4rast otsuste tegemise kiiruses ja suhtluse kvaliteedis pettunud t\u00f6\u00f6tajatelt tagasiside saamist oli tal v\u00f5imalik ettev\u00f5ttes mitu meeskonda \u00fcmber korraldada ja pakkuda probleemidega tegelemiseks kommunikatsioonikoolitust.",
		"tgt": "And, after gathering feedback from employees frustrated by the speed of decision-making and the quality of communication, she was able to reorganize several teams within the company and add communication training to address the issues."
	},
	{
		"src": "Ruby Tuesdays kogutakse aga uusi andmeid t\u00f6\u00f6tajate kohta ja loodetakse, et pikas perspektiivis toob see endaga kaasa t\u00f6\u00f6tajate pikemaajalise p\u00fchendumise t\u00f6\u00f6stusharus, mis on tuntud oma suure t\u00f6\u00f6j\u00f5u voolavuse poolest.",
		"tgt": "Over at Ruby Tuesday, the company is getting new insight on its employees, and it's hoping that in the long run, this will convert to better retention of workers in an industry known for high turnover."
	},
	{
		"src": "\"Kui sa ei ole p\u00fchendunud l\u00e4bipaistvuse tagamisele, siis sa kaotad inimesed,\" \u00fctles Vitrano.",
		"tgt": "\"If you're not committed to creating a culture of transparency, you're going to lose people,\" Vitrano said."
	},
	{
		"src": "\"Ja kui sa kaotad inimesed, siis sa kaotad kliendid.",
		"tgt": "\"And if you lose people, you're going to lose customers."
	},
	{
		"src": "Ja kui sa kaotad kliendid, siis sa kaotad ettev\u00f5tted.\"",
		"tgt": "And when you lose customers, you're going to lose companies.\""
	},
	{
		"src": "Euroala s\u00e4rav t\u00e4ht on Baltikum: sissetulekud kasvavad kiiresti",
		"tgt": "Baltics are a shining star of the Eurozone: incomes growing fast"
	},
	{
		"src": "Kuigi 2008. aasta kriisis ja kaubandusprobleemid Venemaaga on avaldanud Baltikumile m\u00f5ju, on kolm Balti riiki kiiresti l\u00e4henemas L\u00e4\u00e4ne-Euroopa rikaste maade sissetulekute poole, kirjutab Bloomberg viidates Euroopa Keskpanga raportile.",
		"tgt": "Although the 2008 crisis and trade problems with Russia have had an impact on the Baltics, the three Baltic states are quickly approaching the affluent countries of Western Europe in terms of income, Bloomberg wrote, citing a report from the European Central Bank."
	},
	{
		"src": "Keskpanga andmetel on alates 1999. aastast majanduse kogutoodang inimese kohta Eestis, L\u00e4tis ja Leedus \u00fcletanud ootuseid.",
		"tgt": "According to the ECB, starting in 1999, the per capital GDP in Estonia, Latvia and Lithuania has exceeded expectations."
	},
	{
		"src": "Edu taga on madal v\u00f5lakoormus, kiiresti paranevad institutsioonid ning \u00e4ri- ja vabaturus\u00f5bralik poliitika.",
		"tgt": "Low debt burden, rapidly improving institution and pro-business and pro-free-market policies are responsible for the success."
	},
	{
		"src": "\"Balti riigid \u00fches Slovakkiaga on v\u00e4heste euroala maade seas, kus reaal-SKP inimese kohta ostuj\u00f5ult on oluliselt l\u00e4henenud EL keskmisele\", teatas keskpank.",
		"tgt": "\u201cThe Baltic states along with Slovakia are among the few Eurozone countries where the real per capital gross domestic product measured in purchasing power parity has grown significantly closer to the EU average,\u201d the ECB said."
	},
	{
		"src": "Kuigi eesm\u00e4rk on selline, et majanduse kogutoodang inimese kohta v\u00f5rdsustuks rikkama L\u00e4\u00e4ne-Euroopaga, moodustas 2015. aastal Balti majanduste kogutoodang inimese kohta k\u00f5igest 2/3 15 riigi keskmisest, kes kuulusid Euroopa Liitu enne 2004. aasta laienemisringi.",
		"tgt": "Although the objective is for per capita gross domestic product to become equal to the wealthier Western Europe, in 2015 per capital gross domestic product in the Baltic economies was just 2/3 of the average among the 15 countries that were members of the European Union before the 2004 enlargement round."
	},
	{
		"src": "Madalad palgad on viinud baltlasi otsima paremat palka v\u00e4lismaalt.",
		"tgt": "Low wages have led Balts to look for better pay abroad."
	},
	{
		"src": "Kuigi Euroopa keskpank n\u00e4eb Baltimaid positiivses valguses ning ka majandus kasvab t\u00e4navu, ei ole kohalikud elanikud sugugi entusiastlikud.",
		"tgt": "Although the European Central Bank sees the Baltics in a positive light and the economy is growing this year as well, local residents are far from enthusiastic."
	},
	{
		"src": "V\u00e4rskeima Eurobarometeri uuringu kohaselt hindas vaid veerand L\u00e4ti ja Leedu elanikest, et nende majandustel l\u00e4heb v\u00e4ga h\u00e4sti v\u00f5i pigem h\u00e4sti.",
		"tgt": "According to the latest Eurobarometer survey, only one-quarter of Latvian and Lithuanian residents felt that their economies were doing well or fairly well."
	},
	{
		"src": "T\u0161ehhis ja Poolas arvas seda oma maade majanduste kohta veidi v\u00e4hem kui pool k\u00fcsitletutest.",
		"tgt": "Slightly under half of respondents in the Czech Republic and Poland thought the same."
	},
	{
		"src": "NCAA otsus t\u00fchistada kaks korda p\u00e4evas toimuvad trennid muudab Bruinsi p\u00e4evad pikaks",
		"tgt": "The NCAA's elimination of two-a-day practices makes for a long day for the Bruins"
	},
	{
		"src": "Kell on peaaegu 23, kui trobikond UCLA jalgpallureid peatub vestlemiseks meeskonna \u00fclikoolilinnakus asuva uue harjutusv\u00e4ljaku servas.",
		"tgt": "It's pushing 11 p.m. as a throng of UCLA football players linger to chat on one side of the team's new on-campus practice fields."
	},
	{
		"src": "M\u00f5ni neist on koorinud seljast s\u00e4rgi, paljastades oma treeningulaagri esimese p\u00e4eva pingutustest higise selja.",
		"tgt": "Some have peeled off their jersey tops, revealing backs slick with sweat from the toil of the first day of training camp."
	},
	{
		"src": "Suure osa jaoks meeskonnast pakuvad need j\u00f5udeminutid keskp\u00e4evast pausi.",
		"tgt": "For a good chunk of the team, these idle minutes constitute a midday break."
	},
	{
		"src": "Suvistel kursustel osalevad m\u00e4ngijad suunduvad p\u00e4rast kolmetunnist trenni tagasi \u00fchiselamusse l\u00f5pueksamiteks \u00f5ppima, enne kui naasevad j\u00e4rgmisel hommikul kell 6.30 koosolekuteks Wassermani jalgpallikeskusesse.",
		"tgt": "Players enrolled in summer classes will head back to their dorms after the three-hour practice to study for final exams before returning to the Wasserman Football Center for meetings at 6:30 the following morning."
	},
	{
		"src": "\"J\u00e4rgmised kolm p\u00e4eva on nende jaoks t\u00f5eline katsumus,\" \u00fctles Bruinsi treener Jim Mora veidi enne seda, kui esmasp\u00e4evast sai teisip\u00e4ev.",
		"tgt": "\"This is a grind for these guys the next three days,\" Bruins coach Jim Mora said not long before Monday turned into Tuesday."
	},
	{
		"src": "NCAA otsus t\u00fchistada m\u00e4ngijate koormuse v\u00e4hendamiseks kaks korda p\u00e4evas toimuvad trennid, on tegelikult nende p\u00e4evad pikemaks muutnud - v\u00e4hemalt kuni l\u00f5pueksamitega \u00fchele poole saamiseni reedel.",
		"tgt": "The NCAA's elimination of two-a-day practices, designed to lighten the load on players, has actually lengthened their days - at least until finals end Friday."
	},
	{
		"src": "Sel p\u00f5hjusel olid UCLA kolm esimest treeningut ajastatud algama kell 19.15, et sobituda m\u00e4ngijate niigi tihedasse ajakavasse.",
		"tgt": "That's why UCLA's first three practices were scheduled to begin at 7:15 p.m. to accommodate players' already crammed schedules."
	},
	{
		"src": "\u00dcleminek kahelt treeningult p\u00e4evas t\u00e4hendab rohkem \u00fche trenniga p\u00e4evasid - Bruinsi treeningulaagri algus t\u00f5steti v\u00f5rreldes eelmise hooajaga peaaegu n\u00e4dala jagu ettepoole ja esimest korda Mora kuue Westwoodi hooaja jooksul toimuvad treeningud suviste kursuste ajal.",
		"tgt": "The trade-off from no two-a-days is more one-a-days, the Bruins pushing up the start of camp nearly a week from last season and holding practices during summer school for the first time during Mora's six seasons in Westwood."
	},
	{
		"src": "Neil on kuni 20. augustini kavas 18 trenni, enne kui algab ametlik ettevalmistus septembris toimuvaks avam\u00e4nguks Texas A&M-i vastu.",
		"tgt": "They are scheduled to hold 18 practices through Aug. 20 before beginning formal game preparations for their opener against Texas A&M on Sept."
	},
	{
		"src": "Mora s\u00f5nul on ta NCAA eeskirjamuutuse poolt, kuigi see lisab m\u00e4ngijate tihedatesse graafikutesse veel \u00fche p\u00e4evakorrapunkti.",
		"tgt": "Mora said he supported the NCAA's rule change even if it did add another item to players' busy itineraries."
	},
	{
		"src": "\"Neil on kolmel v\u00f5i neljal p\u00e4eval tohutu koormus ja see on t\u00f5sine v\u00e4ljakutse,\" \u00fctles Mora.",
		"tgt": "\"We're putting this enormous load on them for three or four days and it's very challenging,\" Mora said."
	},
	{
		"src": "\"Ja nad murravad end sellest katsumusest l\u00e4bi; nad pingutavad, nad on toredad noored.",
		"tgt": "\"And they've just pushed through it; they grind, they're great kids."
	},
	{
		"src": "Ma usun, et kui saabub laup\u00e4ev ja meil on rohkem aega, on see t\u00f5eliselt m\u00f5nus.\"",
		"tgt": "I think once we get to Saturday and we'll have more time, it will really be great.\""
	},
	{
		"src": "Kui laager on l\u00f5ppenud, muudab UCLA treeningud suletuks, mis ei ole aga sugugi lihtne \u00fclesanne, arvestades selget vaadet nende v\u00e4ljakutele l\u00e4hedalasuvalt parkimisplatsilt ja k\u00f5rvalseisvast Luskini keskusest, k\u00f5rgema klassi hotellist, mis on juba saanud pihta v\u00e4ravaposti \u00fcmbritsevast kaitsev\u00f5rgust m\u00f6\u00f6da p\u00e4\u00e4senud jalgpallidega.",
		"tgt": "UCLA will close its practices once camp is finished, no easy task given the clear sight lines of its fields from an adjacent parking lot and the adjoining Luskin Center, an upscale hotel that has already been pelted with footballs that cleared a protective net behind a goalpost."
	},
	{
		"src": "Alates sellest n\u00e4dalavahetusest h\u00f5ivavad hotelli Bruinsi m\u00e4ngijad, kuid Mora tunnistas, et probleeme v\u00f5ib tekkida vabade tubadega hooaja v\u00e4ltel.",
		"tgt": "Bruins players are scheduled to occupy the hotel beginning this weekend, but Mora acknowledged that there could be an issue once those rooms are vacant during the season."
	},
	{
		"src": "\"Rakendame turvameetmeid,\" \u00fctles Mora.",
		"tgt": "\"We will have security,\" Mora said."
	},
	{
		"src": "\"See on t\u00f5eline murekoht ja ei ole sugugi liialdatud arvata, et inimesed v\u00f5ivad \u00fc\u00fcrida toa ja sealt treeningut filmida.",
		"tgt": "\"That is a real concern and it's not far-fetched to think that people can rent a room and sit up there and videotape a practice."
	},
	{
		"src": "Kui sul on salvestus treeningust, v\u00f5ib sellega p\u00e4ris hea tehingu teha.",
		"tgt": "If you have videotape of a practice, it's a pretty good deal."
	},
	{
		"src": "Aga me kasutame seal ja 8. parkimisplatsil turvameeskonda.",
		"tgt": "But we'll have security there and we'll have security up in Parking Lot 8."
	},
	{
		"src": "Anname endast olemasolevat kasutades parima.",
		"tgt": "We'll do the best we can with what we got."
	},
	{
		"src": "Ma p\u00fc\u00fcan selle p\u00e4rast mitte eriti muretseda.",
		"tgt": "I'm not going to worry too much about it."
	},
	{
		"src": "Meil on plaan paigas.\"",
		"tgt": "We have a plan in place.\""
	},
	{
		"src": "K\u00e4ttemaksuks Keskerakonnale s\u00fcndinud Savisaare-Ivanova valimisliit, Reformierakonnast v\u00e4ljaheidetud Kristiina Ojulandi ja EKREst lahkuma sunnitud Maria Kaljuste j\u00f5udude \u00fchendamisel loodud Meie Tallinn ja parteilastele kohta k\u00e4tte n\u00e4idata lootev \u00e4rimeeste valimisliit Tegus Tallinn - n\u00e4ib, et parteipoliitikas k\u00f5rvetada saanute algatusel loodud valimisliite osaleb t\u00e4navu kohalikel valimistel v\u00e4hemalt sama palju kui erakondi.",
		"tgt": "The Savisaar-Ivanova election coalition conceived as revenge against the Centre Party, the Meie Tallinn coalition founded by Reform Party outcast Kristiina Ojuland and EKRE outcast Maria Kaljuste, and the Tegus Tallinn coalition of businessmen hoping to show party members their place \u2013 it appears that there will be just as many election coalitions, created at the initiative of those who have got their fingers burned in partisan politics, participating in this year\u2019s local elections as there will be political parties."
	},
	{
		"src": "Tibusid loetakse aga s\u00fcgisel, ja v\u00f5tmek\u00fcsimuseks saab, kas neile k\u00f5igile jagub piisavalt pettunud valijaid.",
		"tgt": "But the chickens will be counted in the autumn and the key question will be whether there will be enough disillusioned voters for them all."
	},
	{
		"src": "Kes j\u00e4\u00e4b Savisaarega?",
		"tgt": "Who will stick with Savisaar?"
	},
	{
		"src": "Kui v\u00e4ikseks on kahanenud Edgar Savisaare toetajaskond, v\u00f5ib aimata tema valimisliidu auks korraldatud \u00fcritustest.",
		"tgt": "The dwindling of his base can be seen in the events organized for the owner of his election coalition."
	},
	{
		"src": "\u00dcks riigikogu liige, m\u00f5ned endised ja praegused keskerakondlased ja palju tundmatuid n\u00e4gusid - kas selline saabki olema valimisliidu koosseis?",
		"tgt": "One MP, some former and current Centre Party members and many unknown faces \u2013 will this really be the makeup of the election coalition?"
	},
	{
		"src": "Ning kas p\u00f5hjust, miks Tallinnas kandideerimisest hoiavad k\u00f5rvale m\u00f5ned Savisaare truud poolehoidjad ja s\u00f5bradki, v\u00f5ib otsida sellest, et \u00e4rapanijate \"Savisaare nimekiri\", mille eesotsas on korruptandid ja korruptsioonikuritegudes kahtlustatavad, on saamas tegelikkuseks?",
		"tgt": "And might the reason that some of Savisaar\u2019s loyal adherents are refraining from running as candidates in Tallinn be found in the fact that the so-called \u201cSavisaar list\u201d led by the corrupt and those suspected of corruption crimes is becoming a reality?"
	},
	{
		"src": "Linnaosavalitsuse katusel filmitud muusikavideo venekeelsele poplaulule, milles osaleb Lasnam\u00e4e linnaosa vanem; ja igas m\u00f5ttes algeline arvutim\u00e4ng, milles peategelane peaminister J\u00fcri Ratas peab rattal s\u00f5ites v\u00e4ltima teele sattunud lompe ja oravaid - kas niimoodi p\u00fc\u00fcab Keskerakond esimest korda valimiskastide juurde lubatavate 16- ja 17aastaste valijate h\u00e4\u00e4li?",
		"tgt": "A music video filmed on the roof of the city district government with a Russian language pop song, featuring an appearance by the Lasnam\u00e4e district\u2019s mayor; and a very primitive computer game in which the main character Prime Minister J\u00fcri Ratas has to ride a bike down a street avoiding puddles and squirrels along his way \u2013 is that how the Centre Party will try to get the votes of 16- and 17-year-olds allowed to vote for the first time?"
	},
	{
		"src": "J\u00e4\u00e4me ootama, milline on teistegi erakondade ettekujutus noortep\u00e4rasest valimiskampaaniast.",
		"tgt": "We will have to wait to see what other parties imagine a youthful election campaign to be."
	},
	{
		"src": "Kui Kanal 2 v\u00f5i TV3 vaatajale vaatab alates augusti algusest meelelahutussaate asemel vastu must ruut, j\u00e4\u00e4b kaks valikut: leppida, et edaspidi n\u00e4eb vabalevis ainult ETV, ETV2, ETV+, Tallinna TV ja ingliskeelset France24 kanaleid v\u00f5i loovutada iga kuu k\u00fcmnekas m\u00f5nele teleoperaatorile.",
		"tgt": "Whereas instead of entertainment programming, viewers of Kanal 2 or TV3 see only a blank screen starting in early August, there are two choices: to accept that in the future, we will see only ETV, ETV2, ETV+, Tallinn TV and the English-language France24 channels on free-to-air TV, or pay 10 euros to some TV operator each month."
	},
	{
		"src": "On arvatavasti ka neid, kes algul reklaamivaba telekogemuse \u00fcle avalikult r\u00f5\u00f5mustavad, ent l\u00f5puks siiski - olgugi et vastumeelselt - telepildi ja reklaamide eest maksavad.",
		"tgt": "There are presumably those who will initially cheer the commercial-free TV experience, yet ultimately \u2013 even if reluctantly \u2013 pay for TV programming and commercials."
	},
	{
		"src": "K\u00f5rvulukustav muusika, l\u00e4rmakas rahvas ja t\u00e4navatele j\u00e4etud r\u00e4mps on pea iga suurema muusikafestivali ebameeldivad k\u00f5rvaln\u00e4htused.",
		"tgt": "Ear-splitting music, loud crowds and trash left on the street \u2013 these are the adverse effects of nearly every larger music festival."
	},
	{
		"src": "Kui ise melust osa saada ei taha, tasub aga kodus pea valutamise asemel kodumaad avastama minna - ja magamiskoht kopsaka summa eest festivalik\u00fclalistele j\u00e4tta.",
		"tgt": "If one doesn\u2019t want to partake of the revelry oneself, instead of getting hung up about it, it would be worth going off to discover Estonia \u2013 and rent out a bed to a festivalgoer for a small fortune."
	},
	{
		"src": "Washington muudab rohelise kaardi reegleid",
		"tgt": "Washington Changes the Green Card Rules"
	},
	{
		"src": "Meediav\u00e4ljaanded tsiteerivad president Donald Trumpi, kelle s\u00f5nul on kavas uus USA immigratsiooniplaan, mis muudab rohelise kaardi reegleid.",
		"tgt": "There is going to be new US immigration plan to modify Green Card rules, President Donald Trump said, quoted by the media."
	},
	{
		"src": "Plaan n\u00e4eb ette seaduslike immigrantide arvu v\u00e4hendamist 50 000 inimesele aastas, rangemaid reegleid ajutiste t\u00f6\u00f6viisade hankimisel ja piiranguid seoses perekondliku suunitlusega viisadega.",
		"tgt": "It envisages reducing legal immigrants to 50,000 per year, stricter rules for obtaining temporary work visas and restrictions on family-oriented visas."
	},
	{
		"src": "Uued reeglid on pakkunud v\u00e4lja vabariiklased ja president toetab neid.",
		"tgt": "The new rules are proposed by the Republicans and are supported by the president."
	},
	{
		"src": "Seaduseeln\u00f5u l\u00e4heb kongressi kahes kojas arutamisele.",
		"tgt": "The draft law is due to be discussed in the two chambers of Congress."
	},
	{
		"src": "\"See seadus v\u00e4hendab vaesust, t\u00f5stab palkasid ja s\u00e4\u00e4stab miljardeid dollareid maksumaksjate raha, kuna muudab viisi, kuidas USA teiste riikide kodanikele rohelisi kaarte v\u00e4ljastab.",
		"tgt": "\"This law will reduce poverty, raise wages and save billions of dollars for taxpayers, and will do this by changing the way the US issues Green Cards to citizens from other countries."
	},
	{
		"src": "Seadus v\u00e4hendab ahelr\u00e4nnet ja hakkab asendama praegust programmi.",
		"tgt": "The law will reduce chain migration and replace the current scheme."
	},
	{
		"src": "Uus taotlemisprotsess annab eelise kandidaatidele, kes r\u00e4\u00e4givad inglise keelt ning kellel on rahalised vahendid enda toetamiseks ja oskused, mis tulevad meie majandusele kasuks,\" lausus Trump Ameerika \u00dchendriikide meediav\u00e4ljaannete s\u00f5nul.",
		"tgt": "This new application process will benefit candidates who speak English, have financial resources to support themselves and show skills that will benefit our economy,\" said Trump, quoted by the American media."
	},
	{
		"src": "Siberi seto noored kolivad linna, pension\u00e4rid tagasi maale.",
		"tgt": "Young Setos in Siberia are moving to town, pensioners back to the countryside."
	},
	{
		"src": "Jevsejevi Anatoli j\u00e4tkab kunagiste Maana j\u00f5e \u00e4\u00e4rsete kuulsate seto kullakaevurite traditsiooni.",
		"tgt": "Anatoli Yevseyev is continuing the tradition of the famous Seto goldminers along the river Mana."
	},
	{
		"src": "Ta t\u00f6\u00f6tab kodust 140 kilomeetri kaugusel Maana lisaj\u00f5e Kuvai \u00e4\u00e4res kullaartellis autojuhina.",
		"tgt": "He works 140 km away from home along the Kuvai, a tributary of the Mana, as a driver for a gold mining collective."
	},
	{
		"src": "See on karm t\u00f6\u00f6: kaks kuud j\u00e4rjest ilma puhkep\u00e4evadeta 12 tundi t\u00f6\u00f6d ja siis ainult k\u00fcmme p\u00e4eva kodus ning j\u00e4lle tagasi.",
		"tgt": "It\u2019s a hard job: 12 hours of work for two months straight without a day off and then only 10 days at home and back again."
	},
	{
		"src": "Artellis t\u00f6\u00f6tatud kolme aasta jooksul on Anatoli seejuures kulda n\u00e4inud vaid \u00fcks kord.",
		"tgt": "During the three years that he\u2019s worked for the collective, Anatoly has seen gold only once."
	},
	{
		"src": "\"Seal on k\u00f5va kord: sisse minnes kontrollitakse p\u00f5hjalikult, et viina kaasa ei tooks, ning v\u00e4lja minnes, et kulda kaasa ei v\u00f5taks\", r\u00e4\u00e4gib Anatoli.",
		"tgt": "\u201cThe rules are strict there: when you enter they check you thoroughly that you don\u2019t bring any vodka in and when you leave make sure that you don\u2019t take any gold with you,\u201d says Anatoli."
	},
	{
		"src": "Mare Piho vestlemas Haida k\u00fclas kohaliku seto Jaaniga, kes on talle palju r\u00e4\u00e4kinud oma perekonna m\u00e4lestustest Siberis.",
		"tgt": "Mare Piho talking to a local Seto, Jan, in Haida village, who has told her a lot about his family\u2019s memories in Siberia."
	},
	{
		"src": "Siberi setode veel s\u00e4ilinud arhailine kultuur hakkab m\u00f5jutama ka kodu-setosid, sest see on lihtsalt nii vapustav, arvab k\u00f5ige p\u00f5hjalikumalt kaugeid setosid uurinud Piho Mare.",
		"tgt": "The archaic culture of the Siberian settlers, which still survives, is starting to have an effect on the settlers back at home too, because it\u2019s just so amazing, says Mare Piho, who has studied the distant Setos most thoroughly."
	},
	{
		"src": "Tema esimesest uurimisreisist Siberisse m\u00f6\u00f6dub t\u00e4navu 30 aastat.",
		"tgt": "This year marks 30 years since her first research trip to Siberia."
	},
	{
		"src": "Selle aja jooksul on ta seal k\u00e4inud 14 korda ja elanud seal kokku \u00fche aasta.",
		"tgt": "Since that time, she has been there 14 times and lived there for a total of one year."
	},
	{
		"src": "Kui palju setusid ikkagi r\u00e4ndas v\u00e4lja Siberisse 19. sajandi l\u00f5pus ja 20. sajandi alguses, et saada siin maad?",
		"tgt": "How many Setos migrated from Siberia at the end of the 19th century and beginning of the 20th century to get land here?"
	},
	{
		"src": "See on lahendamata k\u00fcsimus.",
		"tgt": "That\u2019s an unsettled question."
	},
	{
		"src": "Mina v\u00e4idan, et 8000.",
		"tgt": "I say 8,000."
	},
	{
		"src": "Ma arvestasin selle v\u00e4lja Siberi seto meeste juttude j\u00e4rgi, kes on ise ka m\u00f5elnud sellest.",
		"tgt": "I arrived at this number based on stories told by Siberian Seto men who have also thought about this."
	},
	{
		"src": "T\u00e4pselt on raske \u00f6elda, sest tollal v\u00f5is \u00fches r\u00fchmas tulla kuni 30 inimest, kuid pass anti ainult mehele.",
		"tgt": "It\u2019s hard to say exactly, because back then as many as 30 people could arrive in one group but passports were only given to men."
	},
	{
		"src": "Pass anti ainult \u00fchele, kuid temaga olid lapsed, \u00f5ed jt naissugulased.",
		"tgt": "The passport was only given to one individual but there were children, sisters and other female relatives with them."
	},
	{
		"src": "Vaadake, kui suur oli see territoorium siin!",
		"tgt": "Look how big this territory here was!"
	},
	{
		"src": "See oli mitmeid kordi suurem ajaloolisest Setomaast.",
		"tgt": "It several times bigger than historical Setomaa."
	},
	{
		"src": "Seda oli ju vaja harida, hallata mingil moel.",
		"tgt": "All that had to be cultivated and managed in some way."
	},
	{
		"src": "Setod tulid siia kui talupojad, aga nende elu muutus, sest siin sattusid nad piirkondadesse, mis ei olnud seotud ainult p\u00f5llumajandusega, vaid ka j\u00f5ega (palgiparvetamine), kullakaevandustega, t\u00f6\u00f6stusega.",
		"tgt": "The Setos came here as peasants, but their life changed, because they found themselves in regions that weren\u2019t tied only to agriculture but also to the river (log barges), gold-mining, industry."
	},
	{
		"src": "N\u00e4iteks Uus-Petseris l\u00e4ksid paljud setod hiljem t\u00f6\u00f6le salastatud linna Krasnojarsk-45 (sinna ehitas n\u00f5ukogude v\u00f5im uraanirikastustehase - J. P.), kui see moodustati.",
		"tgt": "For example, in New Pechory, many Setos went to work later in the closed city of Krasnoyarsk-45 (which is where the Soviet regime built a uranium plant \u2013 J. P.) once it was established."
	},
	{
		"src": "Kas setod moodustasid tollal siin piirkonnas elanikkonnast enamuse?",
		"tgt": "Did the Setos make up the majority of the population in this region?"
	},
	{
		"src": "Jah, nad elasid kompaktselt.",
		"tgt": "Yes, they lived in compact fashion."
	},
	{
		"src": "Lisaks s\u00e4ilis kaua traditsioon omavahel abielluda ning paljulapselisus.",
		"tgt": "The tradition of intermarriage and families with many children also survived for a long time."
	},
	{
		"src": "Seitse-kaheksa last peres oli tavaline.",
		"tgt": "It was common for families to have seven or eight children."
	},
	{
		"src": "Kui palju Siberi setode kultuur erines ja erineb emamaa setode omast?",
		"tgt": "How much did Siberian Seto culture differ from that of the motherland Setos?"
	},
	{
		"src": "Nad on erinevad, kuigi see, mis toodi siia, oli kunagi sama seal.",
		"tgt": "They\u2019re different, even though the aspects that were brought were once the same there."
	},
	{
		"src": "Nad t\u00f5id kaasa v\u00e4ga palju rahvariideid.",
		"tgt": "They brought with them a great many folk costumes."
	},
	{
		"src": "Nad tegid siis ise ka (rahvariideid), aga nad tegid alati vahet, mis oli kaasa toodud ja mis oli siin tehtud.",
		"tgt": "They made them as well, but they always drew a distinction between what they brought with them and what they had made on the spot."
	},
	{
		"src": "Kliimamuutus m\u00f5jutas tugevalt setode traditsioonilist riietust, sest siin on ju k\u00fclmem.",
		"tgt": "Climate change had a strong impact on the traditional clothing of the Setos, because it\u2019s colder here."
	},
	{
		"src": "Toidud muutusid.",
		"tgt": "Foods changed."
	},
	{
		"src": "N\u00e4iteks Setomaal liha soolati, aga siin lihtsalt k\u00fclmutati.",
		"tgt": "For example in Setomaa, meat was salted, but here it was just frozen."
	},
	{
		"src": "Kus asuvad Siberi setode k\u00fclad ja mis elu seal elatakse? / graafika: Alari Paluots",
		"tgt": "Where are the Siberian Seto villages located and what kind of life two people live there? /graphic: Alari Paluots"
	},
	{
		"src": "Side emamaaga oli vaimselt tugev, seda peeti v\u00e4ga oluliseks.",
		"tgt": "The ties with the motherland were spiritually strong, they were considered very important."
	},
	{
		"src": "Mulle tundub, et n\u00fc\u00fcd hakkab see Setumaa andma tagasi sinna, hakkab m\u00f5jutama neid.",
		"tgt": "It seems to me that Setomaa starting to \u201cfeed back\u201d there, it\u2019s starting to influence them."
	},
	{
		"src": "Need t\u00fcdrukud, kes on elanud siin peredes, on kuulanud h\u00e4mmastavaid lugusid.",
		"tgt": "The girls who have lived here in these families have heard astonishing stories."
	},
	{
		"src": "Piho peab silmas Eesti setode delegatsiooni inimesi, kes tulid juuli algul Haida k\u00fclla Seto kuningriigi p\u00e4evale ning elasid neli p\u00e4eva kodudes - J. P.",
		"tgt": "Piho is referring to people from the Estonian Seto delegation who came to Haida Village in early July for the Seto kingdom day and lived in homes for four days - J.P."
	},
	{
		"src": "See, mis siin alles on, see on vapustav.",
		"tgt": "What is left here is astonishing."
	},
	{
		"src": "\"Tapale on \u00fclilihtne tulla ja ka \u00e4ra minna, sest linnal on suurep\u00e4rane asupaik: raudtees\u00f5lmpunktis ja maanteede ristumiskohas\", \u00fctleb Tapalt p\u00e4rit ooperisolist Reigo Tamm.",
		"tgt": "\u201cIt\u2019s extremely easy to go to and from Tapa, because the city has a great location: at a railway junction and highway crossing,\u201d says opera soloist Reigo Tamm, who is from Tapa."
	},
	{
		"src": "Linn pole enam ammu pelgalt militaarpealinn, meil on palju loodust, spordi- ja kultuurpaiku ning pitsat saab igal nurgal.",
		"tgt": "The city has long ceased to be just a military capital; we have a lot of nature, sport and cultural venues and pizza on every corner."
	},
	{
		"src": "Tapa on tipp-topp linn!",
		"tgt": "Tapa is a top-class town!"
	},
	{
		"src": "Linnast l\u00e4bi jooksva Valgej\u00f5e \u00e4\u00e4res on v\u00e4ike saareke, kus tapalased tavatsevad jaanipidu pidada.",
		"tgt": "The Valgej\u00f5gi river flowing through the city has a little island where Tapa residents traditionally celebrate St. John\u2019s Eve."
	},
	{
		"src": "\"Seda kaunist kohta rongiaknast ei paista\", muheleb Reigo.",
		"tgt": "\u201cYou can\u2019t see that lovely place from the train window,\u201d chuckles Reigo."
	},
	{
		"src": "Kes k\u00fclma vett ei karda, saab ses j\u00f5es ujuda, sest j\u00f5gi on allikaid t\u00e4is.",
		"tgt": "If one isn\u2019t afraid of cold water, the river is swimmable, as it is full of springs."
	},
	{
		"src": "Mina olen seal ujumas k\u00e4inud k\u00fcll, saab t\u00e4itsa hakkama!",
		"tgt": "I\u2019ve gone swimming there, it\u2019s completely possible!"
	},
	{
		"src": "J\u00f5e veerel saab piknikku pidada ja lihtsalt romantikat teha - saab j\u00f5e voolamist silmitseda ning m\u00f5elda elule ette ja taha.",
		"tgt": "You can have a picnic on the riverbank for a romantic setting \u2013 you can watch the river flowing by and think about the past and future."
	},
	{
		"src": "Olen ka mina seal oma pruutidega jalutamas k\u00e4inud.",
		"tgt": "I have walked there with a girlfriend on occasion."
	},
	{
		"src": "Ooperisolist Tamm on peale k\u00f5ige muu k\u00e4inud j\u00f5ekaldal kolme silla vahel oma aariaidki harjutamas: \"Et see paik on linna \u00e4\u00e4res, ei pruugi keegi vastugi tulla, kui omi lugusid \u00fcmisen\".",
		"tgt": "Along with everything else, opera soloist Tamm has practised his arias between the three bridges on the riverbanks: \u201cSince the place is on the outskirts of the town, I won\u2019t necessarily encounter anyone when I\u2019m humming my tunes.\u201d"
	},
	{
		"src": "\"M\u00e4nnikum\u00e4elt avaneb imeline vaade Tapale, kuid seal on ka terviserajad, kus saab joosta, talviti suusatada ning praegu n\u00e4iteks discgolfi m\u00e4ngida - golfirada on tehtud, kettaid saab laenutada spordikeskusest\", juhatab Reigo.",
		"tgt": "\u201cThere\u2019s an amazing view of Tapa from M\u00e4nnikum\u00e4gi hill, but there\u2019s also recreational trails for running or skiing in winter, and, say, play disc golf \u2013 the disc golf course has been established, and the discs can be rented from the sports centre,\u201d says Reigo."
	},
	{
		"src": "Vanad profid k\u00e4ivad seal m\u00f5istagi oma ketastega, aga mina pole sinna veel m\u00e4ngima j\u00f5udnud.",
		"tgt": "Veteran players go there with their own discs, but I haven\u2019t made it there yet."
	},
	{
		"src": "Tuleb ilmselt kolleeg Rasmus Kull Tapale k\u00fclla kutsuda, sest tema on kogenud discgolfim\u00e4ngija ning tal on kettad olemas.",
		"tgt": "Colleague Rasmus Kull will probably have to be to be invited to Tapa as he is an experienced disc golf player and has his own discs."
	},
	{
		"src": "Vast ta laenab mulle!",
		"tgt": "Maybe he will lend them to me!"
	},
	{
		"src": "Reigo ja M\u00e4nnikum\u00e4gi olid praeguse ooperisolisti lapsep\u00f5lve aegu lahutamatud.",
		"tgt": "Reigo and M\u00e4nnikum\u00e4gi were inseparable during the current opera singer\u2019s childhood."
	},
	{
		"src": "V\u00e4hemasti suusatundide ajal.",
		"tgt": "At least during ski lessons."
	},
	{
		"src": "Sellele m\u00e4ele on j\u00e4\u00e4nud palju pisaraid, pettumusi ja v\u00f5ite minu spordielus.",
		"tgt": "I\u2019ve shed many tears, and had disappointments and triumphs on that hill in the sports part of my life."
	},
	{
		"src": "R\u00e4\u00e4kimata purunenud kelkudest ja suuskadest.",
		"tgt": "To say nothing of broken sleds and skis."
	},
	{
		"src": "\"Kogu kesklinn on praegu ehitust\u00f6id t\u00e4is, k\u00f5ik see muutub tundmatuseni\", kiidab Reigo.",
		"tgt": "\u201cThe whole city centre is now full of construction works, it is all changing beyond recognition,\u201d says Reigo by way of praise."
	},
	{
		"src": "Tapa vana ja v\u00e4sinud vaksalihoone on aga v\u00e4ga atraktiivne koht, kus m\u00e4ngitakse suvelavastusi.",
		"tgt": "Tapa\u2019s old and worn-out station building is a very attractive place, where summer performances are staged."
	},
	{
		"src": "Mul on hea meel, et aastal 2012 R.A.A.A.Mi juht M\u00e4rt Meos mu idee vastu v\u00f5ttis ning oma teatriga vaksalisse suveteatrit tegema tuli.",
		"tgt": "I\u2019m very glad that M\u00e4rt Meos, the director of R.A.A.A.M, in 2012 used embraced my idea and brought his theatre to the station building to put on a summer performance."
	},
	{
		"src": "Ehkki t\u00e4navune teatrihooaeg \"Aleksei Kareniniga\" sai just l\u00e4bi, siis 11. augustil on raudteejaamas \"Ellu\u00e4rkamine\", kui vanas vaksalihoones liigutakse ringi 1980. aastates.",
		"tgt": "Even though this year\u2019s theatre season just ended with Aleksei Karenin, on 11 August, Ellu\u00e4rkamine (Coming Back to Life) will be performed on 11 August at the railway station, when it will be the 1980s again in the old station building."
	},
	{
		"src": "\"11.-13. augustini on Tapa linna p\u00e4evad, mille raames on peale \u00e4rganud vaksalihoone avatud kodukohvikud ja toimub ridamisi kultuuri\u00fcritusi, muu hulgas ka rahvaralli\", k\u00f5neleb Reigo, kes soovitab just noil p\u00e4evil 91aastast linna k\u00fclastada.",
		"tgt": "\u201cThe Tapa city festival will be held 11-13 August, and pop-up caf\u00e9s will open up in the statin building and there will be many cultural events, including a rally race open to the public,\u201d says Reigo, who recommends visiting the 91-year-old town on those days."
	},
	{
		"src": "Pisikeses kollases majakeses 1. mai puiesteel on muuseum juba aastast 1994.",
		"tgt": "The tiny yellow house on the 1st of May Boulevard has been a museum since 1994."
	},
	{
		"src": "\"Maja on v\u00e4ike, aga eksponaate on h\u00e4sti palju ja infot tohutult\", kiidab Reigo paika, mis on t\u00e4is Tapa linna ajalugu, millest suurem osa keskendub raudteele ja s\u00f5jandusele.",
		"tgt": "\u201cThe house is small but there are great many exhibits and a huge amount of information,\u201d says Reigo in praising the place, which is full of the history of the town of Tapa, the majority of which focuses on the railway and the military."
	},
	{
		"src": "Reigo muigab, et kui Tapal k\u00f5ik soovitatud paigad l\u00e4bi k\u00e4ia, l\u00e4heb k\u00f5ht pikapeale t\u00fchjaks, kuid \u00f5nneks on v\u00e4ikelinn kohvikuid t\u00e4is.",
		"tgt": "Reigo chuckles that if one were to visit all the recommended places in Tapa, one would get hungry, but luckily the small city is full of cafes."
	},
	{
		"src": "\"Meil on nii head s\u00f6\u00f6gikohad ja kohvikutes istudes tekib m\u00f5nikord tunne, et oled v\u00e4lismaal\", kirjeldab ta.",
		"tgt": "\u201cWe have good places to eat and sometimes, siting in the caf\u00e9, you feel that you\u2019re abroad,\u201d he says."
	},
	{
		"src": "Haritud ja noored Tapale tulnud s\u00f5durid veedavad pubides-kohvikutes palju aega, sestap on seal istudes kummastav tunne, et oled k\u00fcll Eestis ja oma kodulinnas, aga \u00fcmberringi on selline rahvusvaheline seltskond koos.",
		"tgt": "Educated and younger soldiers who have come to Tapa spend a lot of time in the pubs and cafes, and thus there\u2019s the odd feeling that you\u2019re in Estonia and in your hometown, but all around you there\u2019s this international set."
	},
	{
		"src": "Usun, et oleks v\u00e4ga p\u00f5nev kuulata lugusid prantslaste v\u00f5i ameeriklaste k\u00e4est.",
		"tgt": "I believe it would be very exciting to hear stories from the French or Americans."
	},
	{
		"src": "S\u00f5dureid, jah, liigub meil palju!",
		"tgt": "Yes, we have a lot of soldiers about town!"
	},
	{
		"src": "Kreekas vahistati ebaseadusliku telkimise eest kaks bulgaarlast",
		"tgt": "Two Bulgarians Were Detained For Illegal Camping in Greece"
	},
	{
		"src": "Telekanal bTV tsiteeris v\u00e4lisministeeriumit, kes andis teada, et kaks bulgaarlast v\u00f5eti Kreekas ebaseadusliku telkimise eest vahi alla.",
		"tgt": "Two Bulgarians were detained for illegal camping in Greece, the Foreign Affairs Ministry announced, quoted by bTV."
	},
	{
		"src": "Politsei vahistas 1. augusti hommikul Sithonia poolsaarel r\u00fchma ebaseaduslikult telkinud inimesi, kelle hulgas oli ka kaks bulgaarlast.",
		"tgt": "A group of illegally camping people, including the two Bulgarians, was detained by the police in Sithonia in the morning of August 1."
	},
	{
		"src": "Nad lasti samal p\u00e4eval vabaks, aga praegu toimub uurimine.",
		"tgt": "The same day they were released, while an investigation is currently underway."
	},
	{
		"src": "V\u00e4lisministeerium \u00fctles telekanalile bTV, et bulgaarlased lasti hiljem vabaks.",
		"tgt": "The ministry of foreign affairs reported bTV that Bulgarians were later released."
	},
	{
		"src": "Kreeka ametiv\u00f5imud on suurendanud vaba telkimise piiranguid ja kehtestavad juba praegu karme trahve k\u00f5igile, kes j\u00e4\u00e4vad vahele puhkamisega kohas, mis pole selleks ette n\u00e4htud.",
		"tgt": "The Greek authorities have tightened control over free camping and are already imposing serious fines on anyone who is caught resting in a place not intended for the purpose."
	},
	{
		"src": "Kontrollid j\u00e4tkuvad kogu hooaja v\u00e4ltel.",
		"tgt": "Checks will continue throughout the season."
	},
	{
		"src": "Ministeeriumi s\u00f5nul v\u00f5ib kohus trahvi m\u00e4\u00e4rata.",
		"tgt": "The ministry said that the court may impose a fine."
	},
	{
		"src": "Kutsikaid \u00f5petavad hundid k\u00e4ivad lambaid murdmas.",
		"tgt": "Wolves teaching pups preying on sheep."
	},
	{
		"src": "Hiiumaa talunikud peavad peale aastast pausi j\u00e4lle huntidele oma karjast \"\u00f5ppematerjali\" andma - ilmselt kutsikaid \u00f5petanud hundid on juba murdnud hulga lambaid.",
		"tgt": "After a year\u2019s respite, Hiiumaa farmers\u2019 flocks are serving as \u201ctraining material\u201d again \u2013 wolves thought to be teaching their young to hunt have killed a number of sheep already."
	},
	{
		"src": "T\u00e4navu on hundid Hiiu maakonnas lambaid murdnud kolmel korral, kokku 23 lammast ja vigastanud on kaheksat, kirjutab Hiiu Leht.",
		"tgt": "Wolves have killed on three occasions in Hiiu County this year, killing a total of 23 sheep with eight injured, Hiiu Leht reported."
	},
	{
		"src": "Mullu oli vastav number vaid kolm, aasta varem 124.",
		"tgt": "Last year the corresponding figure was only three, and the year before that, 124."
	},
	{
		"src": "Murdmistega s\u00fcnkroonis on ka keskkonnaagentuuri andmed, et mullu Hiiumaal hundipesakondi ei s\u00fcndinud ja Hiiumaa jahindusn\u00f5ukogu info, et sel aastal on saarel fikseeritud kaks hundipesakonda.",
		"tgt": "The Environmental Agency\u2019s statistics \u2013 that no wolf litters were born last year in Hiiumaa \u2013 and the information from the Hiiumaa hunting board that two litters have been recorded this year \u2013 are consistent with the attacks."
	},
	{
		"src": "\u00d6\u00f6l vastu esmasp\u00e4eva murdsid hundid Emmaste valla Kabuna k\u00fclas 15 lammast ning vigastasid 18 elluj\u00e4\u00e4nud lambast pooli.",
		"tgt": "Late on Sunday night, wolves killed 15 sheep in Kabuna Village in Emmaste Rural Municipality and injured half of the 18 surviving sheep."
	},
	{
		"src": "Kolmap\u00e4eva varahommikul murdsid hundid Reheselja k\u00fcla karjamaal \u00fche lamba ja vigastasid r\u00e4ngalt teist, kellele tuli teha h\u00e4datapp.",
		"tgt": "Early Wednesday morning, wolves killed one sheep on Reheselja Village\u2019s pastureland and grievously injured another one; that sheep had to be put down."
	},
	{
		"src": "Geneetiliselt muundatud p\u00f5llukultuuride k\u00e4itlemise reeglid peavad olema selged",
		"tgt": "The rules for handling of genetic modified crops must be clear."
	},
	{
		"src": "Maaeluministeerium saatis koosk\u00f5lastusringile geneetiliselt muundatud organismide keskkonda viimise seaduse (GMOVS) ja taimekaitseseaduse muutmise seaduse eeln\u00f5u.",
		"tgt": "The Ministry of Rural Affairs has sent draft legislation amending the Release into Environment of Genetically Modified Organisms Act (GMOVS) and the Plant Protection Act to ministries for endorsement."
	},
	{
		"src": "Seaduse muudatusega loobutakse nii geneetiliselt muundatud (GM) p\u00f5llukultuuride asukohtade kui ka k\u00e4itlejate jaoks eraldi andmekogu loomisest, selleks kasutatakse edaspidi taimetervise registrit.",
		"tgt": "The amendment to the legislation forgoes the creation of a separate database on locations of genetically modified (GM) crops as well as for handlers; the plant health register will be used henceforth for this purpose."
	},
	{
		"src": "Lisaks muudetakse GM p\u00f5llukultuuri k\u00e4itleja kohustust omada eelnevat kokkulepet etten\u00e4htud raadiuses mesindusega tegeleva isikuga.",
		"tgt": "Also under the amendment, GM crop handlers have the obligation to have a pre-existing agreement with a person engaged in apiculture within a specified radius will be amended."
	},
	{
		"src": "Kuigi hetkel ei kasvatata Eestis geneetiliselt muundatud p\u00f5llukultuure, peame vajalikuks selgete reeglite olemasolu geneetiliselt muundatud ja muundamata p\u00f5llukultuuride kooseksisteerimiseks.",
		"tgt": "\u201dAlthough genetically modified crops are not currently grown in Estonia, we consider it necessary for there to be clear rules on the coexistence of GM and non-GM crops."
	},
	{
		"src": "Seda v\u00e4hemalt seniks, kuni ei ole otsustaud Eesti GMO-vabaks kuulutada\", \u00fctles Maaeluministeeriumi taimetervise osakonna juhataja Sigmar Suu.",
		"tgt": "At least until such time that a decision has been taken to declare Estonia GMO-free,\u201d said the head of the plant health department at the Ministry of Rural Affairs, Sigmar Suu."
	},
	{
		"src": "\"Samas tuleb arvesse v\u00f5tta, et v\u00e4ljat\u00f6\u00f6tatud meetmed peavad olema eesm\u00e4rgip\u00e4rased ja proportsionaalsed, arvestama nii era- kui ka riigisektorile kaasnevaid kulusid ja halduskoormust\", lisas Suu.",
		"tgt": "\u201cAt the same time, it must be taken into consideration that the measures developed must serve the required purpose, be proportional, and take into account the expenses and administrative burden of both private and public sector,\u201d added Suu."
	},
	{
		"src": "Seaduse eeln\u00f5uga tunnistatakse kehtetuks GMOVS-is GM p\u00f5llukultuuride asukohtade ja k\u00e4itlejate andmekoguga ja k\u00e4itlemise koolitusega seotud s\u00e4tted, kehtestatakse GM p\u00f5llukultuuri k\u00e4itlemise ning majandustegevusega alustamise n\u00f5uded.",
		"tgt": "The draft legislation repeals the provisions of the GMOVS on database of locations of GM crops and training to handle GM crops, and establishes requirements on handling GM crops and commencing economic activity."
	},
	{
		"src": "Spetsiifiliselt mesindusega seoses asendatakse GM p\u00f5llukultuuri kasvataja senine kohustus teavitada mesinikke GM p\u00f5llukultuuri kasvatamisega alustamisest kohustusega saavutada enne kasvatamisega alustamist mesinikuga asjakohane kokkuleppe.",
		"tgt": "Specifically in connection with apiculture, the current obligation of GM crop growers to notify beekeepers of commencement of growing GM crops will be supplanted with the obligation to achieve, before commencing growing of such crops, a corresponding agreement with the beekeeper."
	},
	{
		"src": "Seaduse eeln\u00f5u on saadetud koosk\u00f5lastamiseks ministeeriumitele.",
		"tgt": "The draft legislation has been sent to ministries for endorsement."
	},
	{
		"src": "K\u00f5ikidel huvipooltel on v\u00f5imalus sellega tutvuda eeln\u00f5ude infos\u00fcsteemis ning soovi korral esitada oma arvamus Maaeluministeeriumile.",
		"tgt": "All parties have the opportunity to familiarize themselves with it in the draft legislation information system and if desired, submit their opinion to the Ministry of Rural Affairs."
	},
	{
		"src": "Plaanitavad muudatused m\u00f5jutavad eelk\u00f5ige taimekasvatuse valdkonnas tegutsevaid isikuid, mesinikke ja P\u00f5llumajandusametit.",
		"tgt": "The planned changes affect, above all, persons engaged in the field of plant protection, beekeepers and the Agricultural Board."
	},
	{
		"src": "Euroopa Liidus, sealhulgas Eestis, on lubatud kasvatada ainult \u00fcht GM p\u00f5llukultuuri - maisi MON 810.",
		"tgt": "It is permitted to grow only one GM crop in the EU, including Estonia - MON 810 maize."
	},
	{
		"src": "Seni ei ole siiski \u00fckski Eesti p\u00f5llumajandustootja huvitunud GM p\u00f5llukultuuri kasvatamisest.",
		"tgt": "To this point, no Estonian agricultural producers are interested in growing GM crops."
	},
	{
		"src": "P\u00f5hjuseks on asjaolud, et Eestis ei esine maisikahjurit, euroopa varreleedikut, mille suhtes on maisiliin MON 810 resistentne.",
		"tgt": "The reason is the fact that a maize pest, the European stem borer, to which MON 810 is resistant, is not found in Estonia."
	},
	{
		"src": "Samuti on selle maisiliini sordid aretatud l\u00f5unapoolsetele piirkondadele ja see mais ei ole meie kliimatingimustesse sobiv.",
		"tgt": "The varieties of this maize line were bred in southern regions and this maize is not suitable for our climate conditions."
	},
	{
		"src": "Eeltoodus kindluse saamiseks on Maaeluministeerium tellinud 2015. ja 2016. aastal uuringuid v\u00f5imaliku GM organismidega saaste avastamiseks Eestis kasvatatavate erinevate suvirapsi, maisi ja soja sortide seemnetes.",
		"tgt": "To gain assurance in regard to the above, the Ministry of Rural Affairs commissioned studies in 2015 and 2016 to detect potential contamination by GM organisms of seeds of summer rape, maize and soybean varieties grown in Estonia."
	},
	{
		"src": "V\u00f5etud proovide anal\u00fc\u00fcsitulemused n\u00e4itasid, et seemned v\u00f5\u00f5rgeene ei sisaldanud ja uuringu tulemusena j\u00e4reldati, et Eestis kasvanud rapsi, maisi ja soja sortide seemned ei sisalda geneetiliselt muundatud organisme.",
		"tgt": "The test results for the samples collected showed that the seeds did not contain foreign genes and as a result of the study it was concluded that the rape, maize and soybean varieties\u2019 seeds did not contain GMOs."
	},
	{
		"src": "Eelnevast v\u00f5ib omakorda j\u00e4reldada, et Eestis ei kasvatata teadlikult geneetiliselt muundatud p\u00f5llukultuure ning samuti sai kinnitust, et pole toimunud ka juhuslikku saastumist.",
		"tgt": "From the above, it can be concluded in turn that no GM crops are being deliberately grown in Estonia and it was also confirmed that no accidental contamination has occurred."
	},
	{
		"src": "Jose Mourinho arvab, et Manchester United v\u00e4rbas Nemanja Maticu kujul \"geeniuse\"",
		"tgt": "Jose Mourinho thinks Manchester United have signed a 'genius' in Nemanja Matic"
	},
	{
		"src": "Jose Mourinho usub, et Manchester United on v\u00e4rvanud Nemanja Maticu n\u00e4ol \"geeniuse\", p\u00e4rast seda kui keskv\u00e4ljam\u00e4ngija Sampdoria vastu kolmap\u00e4eva \u00f5htul oma deb\u00fc\u00fcdi tegi.",
		"tgt": "Manchester United have signed a \"genius\" in Nemanja Matic, believes Jose Mourinho, after the midfielder made his debut against Sampdoria on Wednesday evening."
	},
	{
		"src": "40 miljoni naela eest Chelsea'lt \u00fcle ostetud m\u00e4ngija alustas Dublinis Unitedi viimases hooajaeelses m\u00e4ngus enne Uefa Super Cupi Real Madridi vastu teisip\u00e4eval 2-1 v\u00f5itu algrivistuses, avaldades muljet kaitserollis, samal ajal kui Paul Pogba ja Andreas Pereira said vabalt r\u00fcnderetkedel k\u00e4ia.",
		"tgt": "The \u00a340m signing from Chelsea started the 2-1 win in Dublin, United's final preseason game before the Uefa Super Cup against Real Madrid on Tuesday, and impressed in the holding role as the likes of Paul Pogba and Andreas Pereira marauded forward at will."
	},
	{
		"src": "Kuid olles j\u00e4\u00e4nud k\u00f5rvale Bluesi hooajaeelsest Aasia tuurist, j\u00e4i Maticul h\u00e4dasti vajaka mat\u0161ivormist ja ta pidas vastu ainult 45 minutit. Seda peab Mourinho s\u00f5nul kindlast enne Premier League'i hooaja algust parandama.",
		"tgt": "However, having been left out of the Blues' preseason tour of Asia, Matic was severely lacking match fitness and only managed 45 minutes, something Mourinho admitted needed to be improved before the start of the Premier League season."
	},
	{
		"src": "\"Ta vajab aega, kuid tal on kogemused, intelligentsus, geniaalne m\u00f5tteviis - tal on jalgpalli meelelaad,\" \u00fctles Mourinho.",
		"tgt": "\"He needs time but his experience, intelligence, a genius in the way he thinks - he thinks football,\" Mourinho said."
	},
	{
		"src": "\"Aitame tal saavutada vormi esimesel v\u00f5imalusel.\"",
		"tgt": "\"We will help him to be ready sooner rather than later.\""
	},
	{
		"src": "Nagu Matic, alustasid Aviva staadionil algrivistuses ka teised uued v\u00e4rvatud Victor Lindelof ja Romelu Lukaku ning Mourinho hakkas vaikselt panema hooaja alguseks paika oma \u00fchtteist alustavat meest.",
		"tgt": "As well as Matic, fellow new signings Victor Lindelof and Romelu Lukaku also started the game at the Aviva Stadium as Mourinho started to shape his starting XI for the start of the season."
	},
	{
		"src": "The Independent avalikustas sel n\u00e4dalal, et Mourinho soovib endiselt veel v\u00e4rvata kolm jalgpallurit, kuid ta kinnitas, et klubi on teinud juba \u00e4ra \"suurep\u00e4rase t\u00f6\u00f6\", s\u00f5lmides lepingud kolmega tema neljast prioriteetsest valikust.",
		"tgt": "The Independent revealed this week that Mourinho still wanted another three signings but he insisted that the club had already done a \"fantastic job\" of delivering three of his four priority signings."
	},
	{
		"src": "\"Ma olen klubile t\u00e4nulik, et nad suutsid realiseerida kolm neljast,\" lisas ta.",
		"tgt": "\"To get three out of four I thank the club for that,\" he added."
	},
	{
		"src": "\"Olen veel \u00f5nnelikum, kui nad suudavad teha teoks neljast neli, kuid nad on minu jaoks k\u00f5vasti vaeva n\u00e4inud.\"",
		"tgt": "\"I will be happier if they get me four of four but they did a great effort for me.\""
	},
	{
		"src": "J\u00e4rjekordne sookurepoeg sai jala k\u00fclge GSM-saatja 1. augustil ja sedakorda Muhus.",
		"tgt": "A GSM transmitter was attached to the leg of the latest young common crane on 1 August, this time on Muhu Island."
	},
	{
		"src": "S\u00f5rves elava linnuvaatleja Mati Martinsoni andmeil sai esimene kurepoeg saatjaga varustatud S\u00f5rves ning see pesakond lendab juba ringi, on pesapaigast lahkunud ja liitunud Mullutu-Suurlahe suure \u00f6\u00f6bimiskogumiga.",
		"tgt": "According to bird watcher Mati Martinson, who lives on S\u00f5rve peninsula, the first young crane to get a transmitter was tagged in S\u00f5rve, and this brood is already flying around, has left the nest area and joined the large population roosting on Mullutu-Suurlaht bay."
	},
	{
		"src": "Seda seep\u00e4rast, et S\u00f5rves ei ole ju viljap\u00f5lde, kirjutab Saarte H\u00e4\u00e4l.",
		"tgt": "This is because S\u00f5rve does not have any fields of grain, Saarte H\u00e4\u00e4l reports."
	},
	{
		"src": "Sel teisip\u00e4eval, kurgede r\u00f5ngastamiseks juba suhteliselt hilja, sai saatja k\u00fclge veel \u00fcks kurepoeg ja seda Muhu saarel.",
		"tgt": "This Tuesday, relatively late for this round of tagging cranes, another young crane got a transmitter, this one on Muhu Island."
	},
	{
		"src": "Martinsoni s\u00f5nul on saatjate paigaldamine tegelikult rahvusvaheline projekt, mida veavad Aivar Leito ja Ivar Ojaste.",
		"tgt": "Martinson says the radio tagging is actually an international project, led by Aivar Leito and Ivar Ojaste."
	},
	{
		"src": "Mullu varustati \u00fcks kurepoeg nimega Mati GSM-saatjaga S\u00f5rves T\u00fcrjul.",
		"tgt": "Last year one crane named Mati got a GSM radio tag in T\u00fcrju on S\u00f5rve peninsula."
	},
	{
		"src": "\"Tema tegemised on internetis k\u00f5ik vaadatavad: kuidas ta k\u00e4is Hispaanias talvitumas, tagasi tulles t\u00fckk aega Saksa ja Poola piiril toppas ning siis Saaremaale tuli\", k\u00f5neles Martinson.",
		"tgt": "\"Everything he does can be viewed over the Internet: How he flew to Spain to spend the winter, stopped for a while on the German-Polish border on the way out, then came to Saaremaa,\u201d said Martinson."
	},
	{
		"src": "Briti leiutaja lasi paigaldada enda kehasse mikrokiibi, et p\u00e4\u00e4seda k\u00e4eviipega majja ja autosse",
		"tgt": "British inventor microchips himself to get into house and car with a wave of hand"
	},
	{
		"src": "Briti leiutajast sai esimene inimene riigis, kellele paigaldati mikrokiip, et ta saaks pelgalt k\u00e4eviipega avada oma eesust, p\u00e4\u00e4seda kontorisse ja isegi k\u00e4ivitada autot.",
		"tgt": "A British inventor has become the first in the country to be fitted with a microchip so he can open his front door, access his office and even start his car with just a wave of his hand."
	},
	{
		"src": "33-aastane Steven Northam lasi paigaldada pisikese kiibi oma p\u00f6idla ja nimetiss\u00f5rme vahele ning pakub n\u00fc\u00fcd seda teenust oma ettev\u00f5tte BioTeq kaudu ka ettev\u00f5tetele ja eraisikutele, kes soovivad oma elu tehnoloogiaga lihtsamaks muuta.",
		"tgt": "Steven Northam, 33, had the tiny chip implanted between his thumb and finger and is now offering the service to businesses and individuals who want to simplify their life with technology through his company BioTeq."
	},
	{
		"src": "Ta on \u00fchendanud j\u00f5ud Winchesteris Hantsis asuva Hampshire'i maakonna kuningliku haigla konsultant-anestesioloogi dr Geoff Watsoniga, et tagada paigaldamisprotseduuri vastavus meditsiinilistele standarditele.",
		"tgt": "He has teamed up with Dr Geoff Watson, a consultant anesthetist at the Royal Hampshire County Hospital in Winchester, Hants, to ensure the implant procedure is carried out to a medical standard."
	},
	{
		"src": "Tehnoloogia sarnaneb kassidele ja koertele paigaldatava mikrokiibi omaga ning protseduuriks kulub k\u00f5igest 30 sekundit.",
		"tgt": "The technology is similar to a microchip implanted for cats and dogs, and takes just 30 seconds."
	},
	{
		"src": "Northami ettev\u00f5te vahetab \u00e4ra ka majade ja autode lukud, et need \u00fchilduksid kiibiga, k\u00fcsides \u00fche luku eest 300 naela.",
		"tgt": "Mr Northam's company will also alter locks on houses and cars so they are compatible with the chip, for a cost of \u00a3300 each lock."
	},
	{
		"src": "See abielus \u00fche lapse isa on paigaldanud tehnoloogia n\u00fc\u00fcdseks nii koju kui ka oma autosse BMW Z4, mis k\u00e4ivitub, kui ta k\u00e4si on roolil.",
		"tgt": "The married father of one now has technology fitted to both his home and his BMW Z4, which starts when his hand is on the wheel."
	},
	{
		"src": "Valge Maja eksponaat l\u00e4ks maksumaksjatele maksma tuhandeid",
		"tgt": "White House Prop Cost Taxpayers Thousands"
	},
	{
		"src": "Ajakirjale TIME avalikustatud s\u00f5jaliste dokumentide kohaselt l\u00e4ks Valge Maja otsus lennutada merev\u00e4e helikopter eelmisel kuul Ameerika tootmist t\u00e4histava \u00fcrituse jaoks l\u00f5unapoolsele \u00f5uele maksumaksjatele maksma lausa 24 000 dollarit.",
		"tgt": "The White House's decision to fly a Marine helicopter to the South Lawn for an event highlighting American manufacturing last month cost taxpayers as much as $24,000, according to military records released to TIME."
	},
	{
		"src": "Rohelist ja valget v\u00e4rvi Sikorsky VH-3D, mida nimetatakse presidendi pardaloleku ajal Marine One'iks, oli 17. juulil Valges Majas toimunud Ameerika ehitusprogramme tutvustava s\u00fcndmuse keskseks t\u00f5mbenumbriks.",
		"tgt": "The green-and-white Sikorsky VH-3D, known as Marine One when the President is aboard, was the centerpiece of the July 17 event at the White House showcasing American construction programs."
	},
	{
		"src": "President Donald Trump, asepresident Mike Pence ja Valge Maja k\u00f5rgemad ametnikud uudistasid oma ringk\u00e4igul t\u00f6\u00f6stustooteid k\u00f5igist 50 osariigist.",
		"tgt": "President Donald Trump, Vice President Mike Pence and senior White House officials toured manufacturing products from all 50 states."
	},
	{
		"src": "Connecticutis ehitatud helikopterit eksponeeriti \u00fcheskoos Maine'ist p\u00e4rit jahi, Wisconsinist tulnud tulet\u00f5rjeauto ja Mississippis valmistatud kahvelt\u00f5stukiga.",
		"tgt": "The Connecticut-made helicopter was displayed alongside a yacht from Maine, a fire truck from Wisconsin, and a forklift from Mississippi."
	},
	{
		"src": "Helikopteri opereerimise eest vastutava eskaadri Marine Helicopter Squadron One (HMX-1) dokumentide kohaselt n\u00f5udis Valge Maja s\u00f5jakabinet helikopteri kohalolu osak\u00e4su ehk FARGO-ga napilt 36 tundi enne seda, kui helikopter \"ebatavalise\" s\u00fcndmuse tarbeks l\u00f5unapoolsel \u00f5uel maandus.",
		"tgt": "The White House Military Office requested the helicopter's presence in a fragmentary order, or FRAGO, barely 36 hours before the helicopter landed on the South Lawn for the \"unusual\" event, according to the records of Marine Helicopter Squadron One (HMX-1), the unit responsible for operating the helicopter."
	},
	{
		"src": "\"Tahtsin, et oleksite sellest teadlik, sest tegu on ebatavaliselt suure t\u00e4helepanu all oleva \u00fcritusega,\" \u00fctles HMX-1 komand\u00f6r p\u00e4ev enne s\u00fcndmust e-kirjas oma \u00fclemusele, merev\u00e4e juhtiva ohvitseri aset\u00e4itjale lennunduse valdkonnas.",
		"tgt": "\"I just wanted you to make sure you were aware because it's such an unusual high visibility event,\" the commander of HMX-1 emailed his superior, the Marine Deputy Commandant for Aviation, the day before the event."
	},
	{
		"src": "S\u00f5numis oli m\u00e4rgitud, et helikopter saabub l\u00f5unapoolsele \u00f5uele 17. juuli hommikul kella 7 paiku kell 15 algavaks \u00fcrituseks ja j\u00e4\u00e4b sinna seniks, kuni \u00f5u samal \u00f5htul kella 18 ja 21 vahel puhtaks tehakse.",
		"tgt": "The message indicated the helicopter would arrive on the South Lawn at approximately 7 a.m. on July 17 for the 3 p.m. event, and remain until the lawn was cleared between 6 p.m. and 9 p.m. that evening."
	},
	{
		"src": "Lisatud oli asjaolu, et kui Valgest Majast lahkumine peaks viibima, on tagasilennuks vaja t\u00f6\u00f6aja piirangute t\u00f5ttu teist ekipaa\u017ei.",
		"tgt": "The note adds that should the departure from the White House be delayed, a second aircrew would be needed for the return flight due to duty-hour restrictions."
	},
	{
		"src": "Algne lennumeeskond oli \u00fcrituse ajal helikopteri juures ja eskaadri julgeolekumeeskond p\u00fcsis \u00f5hus\u00f5iduki l\u00e4hedal kogu selle maapinnal viibimise aja v\u00e4ltel.",
		"tgt": "The original flight crew was with the helicopter during the event, while unit security personnel remained with the aircraft while it was the ground."
	},
	{
		"src": "Ajakirjale TIME antud dokumentidest ei olnud v\u00f5imalik v\u00e4lja lugeda, kas teist ekipaa\u017ei l\u00e4ks l\u00f5puks vaja v\u00f5i mitte.",
		"tgt": "It was not clear from records provided to TIME whether a second flight crew was ultimately required."
	},
	{
		"src": "Hatchi seadus keelab f\u00f6deraalt\u00f6\u00f6tajatel kasutada valitsuse vara poliitilistel eesm\u00e4rkidel.",
		"tgt": "The Hatch Act prohibits federal employees from using government property for political purposes."
	},
	{
		"src": "Dokumendid n\u00e4itavad, et HMX-1 uuris, kas antud \u00fcritus v\u00f5ib seda s\u00e4tet rikkuda.",
		"tgt": "Records indicate that HMX-1 inquired about whether the event might violate the provision."
	},
	{
		"src": "\"K\u00fcsisime, kas see rikub Hatchi seadust, ja meile \u00f6eldi, et ei riku,\" kirjutas komand\u00f6r.",
		"tgt": "\"One question we asked was if it was a violation of the Hatch Act and were informed it was not,\" the commander wrote."
	},
	{
		"src": "\"Tundub, et teil pole valikut,\" vastas juhtiva ohvitseri aset\u00e4itja.",
		"tgt": "\"Sounds like you are locked,\" the Deputy Commandant replied."
	},
	{
		"src": "Valge Maja kuulutas \u00fcrituse \"Ameerikas valmistatud\" ametlikuks \u00fcrituseks ja Hatchi seadus poleks seda katnud.",
		"tgt": "The \"Made in America\" event was designated an official event by the White House, and would not have been covered by the Hatch Act."
	},
	{
		"src": "Aga isegi ametlikel \u00fcritustel on poliitilised alatoonid.",
		"tgt": "But even official events have political overtones."
	},
	{
		"src": "President toetas \u00fcritusel tol ajal senatis arutamisel olnud tervishoiureformi ponnistusi ja kiitis p\u00fc\u00fcdlusi valitsuse m\u00e4\u00e4rusi ohjes hoida.",
		"tgt": "At the event, the President made a push for healthcare reform efforts then underway in the Senate and touted efforts to rein in government regulations."
	},
	{
		"src": "Nime Marine One v\u00f5i Air Force One all tuntud \u00f5hus\u00f5iduki kasutamine poliitiliselt tulusal eesm\u00e4rgil ei ole mingi uus n\u00e4htus.",
		"tgt": "Using the aircraft known as Marine One or Air Force One for politically advantageous purposes is hardly a new phenomenon."
	},
	{
		"src": "Presidendid peavad kasutama neid reisimiseks.",
		"tgt": "Presidents are required to use them for travel."
	},
	{
		"src": "Ent n\u00f5ue kasutada neid puhtalt fotoseansiks on ebatavaline.",
		"tgt": "But requisitioning their use solely for a photo-op is unusual."
	},
	{
		"src": "Trump sattus veebruaris t\u00e4helepanu alla, kui tema esimesel kampaania\u00fcritusel Floridas Melbourne'is veeres taustale presidendi lennuk, ning ta Twitteri konto kubiseb s\u00f5numitest, mis kurdavad selle \u00fcle, kuidas tema eelk\u00e4ija presidendi lennukit kasutas.",
		"tgt": "Trump drew scrutiny in February when the presidential airplane taxied to the backdrop of his first campaign rally in Melbourne, Fla., and his Twitter account is flush with messages complaining about his predecessor's use of the presidential aircraft."
	},
	{
		"src": "\"Valgel Majal on v\u00e4ga hea meel v\u00e4ljapaneku \"Ameerikas valmistatud\" \u00fcle, kus olid esindatud tooted k\u00f5igist 50 osariigist, mille on valmistanud Ameerika materjalidest Ameerika t\u00f6\u00f6lised,\" \u00fctles Valge Maja pressiesindaja kohuset\u00e4itja Lindsay Walters.",
		"tgt": "\"The White House is thrilled with the 'Made In America' showcase that featured products from all 50 states that are made by American workers with American materials,\" said White House deputy press secretary Lindsay Walters."
	},
	{
		"src": "HMX-1 meeskonnad teevad tihtipeale Washingtoni \u00fcmbruses ja l\u00f5unapoolsel \u00f5uel proovilende, et harjutada Ameerika \u00dchendriikide presidendi Valge Maja juurde mahapanekut sentimeetrit\u00e4psusega.",
		"tgt": "HMX-1 crews frequently perform training flights around the Washington area and at the South Lawn to practice depositing the President of the United States at the White House with inches of precision."
	},
	{
		"src": "Kui Trump juuli alguses Saksamaal G20 tippkohtumisel oli, korraldas HMX-1 Valge Maja hoovis 58 proovimaandumist.",
		"tgt": "When Trump was at the G-20 summit in Germany in early July, HMX-1 conducted 58 practice landings at the White House."
	},
	{
		"src": "Ametniku s\u00f5nul arvati lend \u00fcritusele \"Ameerikas valmistatud\" lennumeeskonna tolle kuu \u00f5ppelendude normi hulka.",
		"tgt": "The flight for the Made in America event counted toward the aircrew's training requirement for the month, an official said."
	},
	{
		"src": "Eskaadri helikopterid lendasid tol p\u00e4eval lisaks veel 11 tundi \"presidendiga mitteseotud toetusmissioonide\" tarbeks.",
		"tgt": "Unit helicopters also flew an additional 11 hours that day for \"non-presidential support missions.\""
	},
	{
		"src": "Valge Maja s\u00f5nul ei koormanud mitte \u00fckski teine selle \u00fcrituse eksponaat maksumaksja rahakotti.",
		"tgt": "The White House said taxpayers did not pick up the burden for any of the other props featured at the event."
	},
	{
		"src": "Sikorsky esindaja s\u00f5nul ei olnud ettev\u00f5te helikopteri l\u00f5unapoolsel \u00f5uel eksponeerimise korraldamisega seotud.",
		"tgt": "A spokesperson for Sikorsky said the company was not involved in arranging for the helicopter to be displayed on the South Lawn."
	},
	{
		"src": "HMX-1 ei s\u00e4ilita presidendi lendude eelarvedokumente ja \u00fcritusest tingitud t\u00e4pseid kulusid on raske v\u00e4lja selgitada.",
		"tgt": "HMX-1 doesn't maintain budgetary records for presidential flights, and determining the precise cost incurred by the event is difficult."
	},
	{
		"src": "Aga kaitseministeeriumi 2017. majandusaasta tunnihindade j\u00e4rgi on VH-3D h\u00fcvitusm\u00e4\u00e4raks 24 380 dollarit lennutunni kohta.",
		"tgt": "But according to Department of Defense hourly rates for fiscal year 2017, the DoD reimbursement rate for the VH-3D is $24,380 per flight hour."
	},
	{
		"src": "Eskaadri dokumentides m\u00e4rgiti lennu pikkuseks selle p\u00f5hibaasist merev\u00e4e Quantico lennuv\u00e4ljalt Virginiast m\u00f5lemal suunal 30 minutit.",
		"tgt": "Unit records record the aircraft flight time as 30 minutes each way from its home base at Marine Corps Air Facility Quantico in Virginia."
	},
	{
		"src": "Valge Maja v\u00e4idab, et helikopteri kasutamise tegelik kulu on k\u00f5vasti alla selle summa.",
		"tgt": "The White House argues the true cost of operating the helicopter is well below that rate."
	},
	{
		"src": "\"Maksumaksjate kulude arvutamine hinnanguliste h\u00fcvitusm\u00e4\u00e4rade p\u00f5hjal on v\u00e4ga eksitav,\" lausus Walters.",
		"tgt": "\"To place a cost to taxpayers based on the reimbursement rate estimates is highly misleading,\" Walters said."
	},
	{
		"src": "\"Need hinnangulised h\u00fcvitusm\u00e4\u00e4rad sisaldavad personali-, hooldus- ja palju muid p\u00f6\u00f6rdumatuid kulusid, mida v\u00f5etakse iga-aastaste assigneeringute puhul arvesse.\"",
		"tgt": "\"These rate estimates include personnel, maintenance and many other sunk costs that are included in annual appropriations.\""
	},
	{
		"src": "2015. aasta RAND-i uuringu j\u00e4rgi ei sisalda kaitseministeeriumi h\u00fcvitusm\u00e4\u00e4rad personalikulusid, k\u00fcll aga katavad need k\u00fctuse, hoolduse ja lepingutega seotud kulusid.",
		"tgt": "According to a 2015 RAND study, DoD reimbursement rates do not include the cost of personnel, but do account for fuel, maintenance, and contracting costs."
	},
	{
		"src": "Valge Maja endine pressiesindaja Sean Spicer kaitses tol ajal helikopteri kasutamist \u00fcritusel.",
		"tgt": "At the time, former White House press secretary Sean Spicer defended the use of the helicopter for the event."
	},
	{
		"src": "\"Asja m\u00f5te on n\u00e4idata sel n\u00e4dalal Ameerikas valmistatud asju,\" \u00fctles Spicer.",
		"tgt": "\"The idea is to showcase this week things that are made in America,\" Spicer said."
	},
	{
		"src": "\"Ja ma tean, et Sikorsky ja Connecticuti osariik on v\u00e4ga uhked selle \u00fcle, et nad panustavad meie riiklikusse julgeolekusse ja et on olemas eeldatavasti sadu, kui mitte isegi tuhandeid inimesi, kelle t\u00f6\u00f6 sellest s\u00f5ltub.",
		"tgt": "\"And I know Sikorsky and the state of Connecticut are very proud of the fact that they contribute to our national security, that there are, I assume, hundreds if not thousands of people whose job depends on that."
	},
	{
		"src": "Ja ma usun, et t\u00e4pselt nagu enamik ameeriklasi, oleme me k\u00f5ik uhked selle helikopteri ja muu s\u00f5jalise varustuse \u00fcle, mille kallal nii paljud ameeriklased on v\u00e4simatult vaeva n\u00e4inud.",
		"tgt": "And I think, like most Americans, we're all proud of the helicopter and other military equipment that so many Americans worked tirelessly to do."
	},
	{
		"src": "Nii et loomulikult on \u00f5ige seda esile t\u00f5sta.\"",
		"tgt": "So, of course, it's appropriate to highlight that.\""
	},
	{
		"src": "Pole selge, kas Trump puutus l\u00f5unapoolsel \u00f5uel \u00fcrituse raames ringk\u00e4iku tehes helikopteriga kokku v\u00f5i mitte, aga tulet\u00f5rjeauto rooli taha istus ta k\u00fcll.",
		"tgt": "It wasn't clear whether Trump interacted with the helicopter as he toured the South Lawn for the event, but he did step into the driver's seat of a fire truck."
	},
	{
		"src": "Valges Majas sees p\u00f6\u00f6rdus Trump Sikorsky esindajate poole, heites meediav\u00e4ljaannetele nalja ettev\u00f5tte toodete \u00fcle tema isiklikus \u00f5hus\u00f5idukipargis.",
		"tgt": "Inside the White House, Trump addressed Sikorsky representatives, joking with the media about his own fleet of company products."
	},
	{
		"src": "\"Ma tunnen Sikorskyt v\u00e4ga h\u00e4sti,\" \u00fctles president, \"mul on kolm nende toodet.\"",
		"tgt": "\"I know Sikorsky very well,\" the President said, \"I have three of them.\""
	},
	{
		"src": "Grit \u0160adeiko - l\u00e4bi pisarate saabusid rahu ja r\u00f5\u00f5m",
		"tgt": "Grit \u0160adeiko \u2013 peace and happiness come through tears"
	},
	{
		"src": "2011. aasta MMil Daegus tabas \u0160adeikot viimasel alal, 800 m jooksus jalakramp ning staadionilt viidi piiga minema kanderaamiga.",
		"tgt": "At the 2011 world championships in Daegu, \u0160adeiko suffered a leg cramp in the last event, the 800 metres, and was carried out of the stadium on a stretcher."
	},
	{
		"src": "Vahetult enne seda oli ta saanud Hiinas peetud universiaadil kaugush\u00fcppes nulli.",
		"tgt": "Right before that, she had fouled out of the long jump at a tournament in China."
	},
	{
		"src": "2012. aasta Helsingi EMi rikkus odaviskes saadud vigastus, kuid Londonis peetud deb\u00fc\u00fctol\u00fcmpial sai ta 6013 punktiga 23. koha.",
		"tgt": "The 2012 European championships in Helsinki were marred by an injury sustained in the javelin throw, but in her debut Olympics in London, she got 23rd with 6013 points."
	},
	{
		"src": "Eba\u00f5nn siiski j\u00e4tkus.",
		"tgt": "Her bad luck continued, though."
	},
	{
		"src": "2013. aasta Moskva MMil sai avap\u00e4eva j\u00e4rel Eesti rekordi graafikus olnud eestlanna kaugush\u00fcppes p\u00f6iavigastuse.",
		"tgt": "At the 2013 Moscow World Championships, the Estonian was on track for an Estonian record when she suffered an foot injury in the long jump."
	},
	{
		"src": "Kaks aastat hiljem sai ta Pekingi MMil 15. koha ning t\u00e4itis ol\u00fcmpianormi, kuid seegi oli enamat tahtnud sportlasele pettumus.",
		"tgt": "Two years later, she got 15th at the Beijing World Championships, and qualified for the Olympics, but even this was a disappointment for the athlete, who had hoped for more."
	},
	{
		"src": "Raskeima kadalipu l\u00e4bis \u0160adeiko alles mullu, kui ei saanud algul Amsterdami EMil kaugush\u00fcppes tulemust kirja.",
		"tgt": "\u0160adeiko ran the hardest gauntlet last year when she didn\u2019t get a result in the long jump at the Amsterdam European championships"
	},
	{
		"src": "Tahaksin lihtsalt kas v\u00f5i \u00fcks kord \u00fche korraliku mitmev\u00f5istluse kokku panna.",
		"tgt": "I\u2019d just like to have a decent performance at the heptathlon or similar events."
	},
	{
		"src": "\u00dcks kord\", pihtis \u0160adeiko.",
		"tgt": "Just once,\u201d confessed \u0160adeiko."
	},
	{
		"src": "Halvem oli veel ees: kuu hiljem katkes tema ol\u00fcmpiav\u00f5istlus Rios reievigastuse t\u00f5ttu juba esimesel t\u00f5kkel.",
		"tgt": "The worst was yet to come: a month later, her Olympics in Rio ended due to a thigh injury at the first hurdle."
	},
	{
		"src": "Aeg tuli maha v\u00f5tta - kas seitsmev\u00f5istlusega \u00fcldse j\u00e4tkata?",
		"tgt": "She had to take time off \u2013 whether to continue in the heptathlon at all?"
	},
	{
		"src": "Kas kaks p\u00e4eva pingutust on ikka k\u00f5ike seda v\u00e4\u00e4rt?",
		"tgt": "Was two days of effort worth all this, anyway?"
	},
	{
		"src": "Neiu m\u00f5tles pikalt, kuid leidis endas rahu.",
		"tgt": "She thought for a long time, but then found peace of mind."
	},
	{
		"src": "Sain pea puhtaks m\u00f5elda",
		"tgt": "I achieved mental clarity"
	},
	{
		"src": "Seda kogemust on suhteliselt raske kirjeldada, aga olen m\u00f5elnud, et eelmine hooaeg ja Rio ol\u00fcmpia olid midagi sellist, mis lihtsalt pidid juhtuma.",
		"tgt": "It\u2019s relatively hard to describe this experience, but I\u2019ve thought that last season and the Rio Olympics were something that just had to happen."
	},
	{
		"src": "\u00d5nneks oli aega, et end terveks ravida ja pea puhtaks m\u00f5elda.",
		"tgt": "Luckily there was time to heal up and reach clarity."
	},
	{
		"src": "\"Teadsin, et pille ma veel kotti ei pane\", r\u00e4\u00e4gib \u0160adeiko oma enesepuhastusest.",
		"tgt": "\u201cI knew that it wasn\u2019t time to pack up and retire,\u201d says \u0160adeiko about her self-cleansing."
	},
	{
		"src": "Sain puhta lehe keerata ning uue hooga edasi minna.",
		"tgt": "I was able to turn a new page and continue with the same momentum."
	},
	{
		"src": "Treener Anne M\u00e4gi s\u00f5nul oli hoolealuse kannatusi v\u00e4ga raske vaadata, kuid ta m\u00f5istis, et eelk\u00f5ige peab sportlane ise endas selgusele j\u00f5udma.",
		"tgt": "Coach Anne M\u00e4gi said it was hard to watch her charge suffering, but she knew that above all, the athlete had to get clear herself on what she wanted."
	},
	{
		"src": "Ta oli ju k\u00f5ikide poolt nii maha materdatud.",
		"tgt": "She has been put down so much by everyone."
	},
	{
		"src": "Seda oli raske taluda.",
		"tgt": "It\u2019s hard to take."
	},
	{
		"src": "\"Grit aga \u00fctles, et ta ei anna alla ja ta tahab endale t\u00f5estada, mida ta v\u00e4\u00e4rt on\", \u00fctleb M\u00e4gi.",
		"tgt": "\u201cBut Grit said she won\u2019t give up and wants to prove to herself what she\u2019s worth,\u201d says M\u00e4gi."
	},
	{
		"src": "N\u00fc\u00fcd on temas mingisugune rahu.",
		"tgt": "Now there\u2019s some kind of peace within her."
	},
	{
		"src": "Ta teeb seda enda r\u00f5\u00f5muks.",
		"tgt": "She does it for pleasure."
	},
	{
		"src": "V\u00f5istlemislust tuli tagasi maikuus, kui \u0160adeiko p\u00fcstitas G\u00f6tzise mitmev\u00f5istlusel uue Eesti rekordi 6280 punkti.",
		"tgt": "Her lust for competing came back in May, when \u0160adeiko set a new Estonian record at the G\u00f6tzis with 6,280 points."
	},
	{
		"src": "K\u00f5rgetasemelisel v\u00f5istlusel parandas ta isiklikku tippmarki kuulit\u00f5ukes ligi meetriga (13.89) ning jooksis rekordil\u00e4hedase aja t\u00f5kkejooksus.",
		"tgt": "At this high-level competition, she bested her own top result in the shot put by close to a metre (13.89) and ran a near-record in the hurdles."
	},
	{
		"src": "Siis tunnetas mitmev\u00f5istleja, et see pole sugugi v\u00f5imete lagi, vaid kustutatud sai k\u00f5igest esmane v\u00f5istlusn\u00e4lg.",
		"tgt": "The heptathlete then realized that it was still far from her best; it only slaked her initial thirst for competing."
	},
	{
		"src": "Teda aastaid juhendanud M\u00e4gi s\u00f5nab, et \u0160adeiko on muster\u00f5pilane.",
		"tgt": "M\u00e4gi, who has been coaching her for years, says \u0160adeiko is a model student."
	},
	{
		"src": "Ta on valmis sportlane, teda on hea treenida.",
		"tgt": "She\u2019s a ready athlete, she\u2019s easy to coach."
	},
	{
		"src": "Kui midagi teeb h\u00e4da v\u00f5i on valesti, siis ta \u00fctleb seda kohe.",
		"tgt": "If something bothers her or is not right, she\u2019ll say so right away."
	},
	{
		"src": "Ta tunneb enda keha ja usaldab oma tunnetust.",
		"tgt": "She knows her own body and trusts her intuition."
	},
	{
		"src": "Sellest peamegi l\u00e4htuma.",
		"tgt": "That is what we have to start from."
	},
	{
		"src": "Ma ei saa \u00f6elda, mida t\u00e4pselt tegema peab ning j\u00e4rgime seda.",
		"tgt": "I can\u2019t say what exactly has to be done and we follow that."
	},
	{
		"src": "Uue l\u00e4henemise on leidnud ka \u0160adeiko.",
		"tgt": "\u0160adeiko has also found a new approach."
	},
	{
		"src": "\"Ma ei olegi selline, kes trennis maksimumile teeb\", r\u00e4\u00e4gib ta ja s\u00f5nab, et k\u00f5ige t\u00e4htsam on \u00f5ige tunnetuse k\u00e4ttesaamine, sest see tagab ka hea tulemuse.",
		"tgt": "\u201cI\u2019m not the kind of person who gives their all in practice,\u201d she says and adds that the most important thing is getting the right feeling, because that guarantees a good result."
	},
	{
		"src": "L\u00e4hedaste beebi\u00f5nn teeb r\u00f5\u00f5msaks",
		"tgt": "New arrivals in families of friends and relatives bring cheer"
	},
	{
		"src": "H\u00e4id emotsioone on \u0160adeikole pakkunud ka l\u00e4hedaste \u00f5nn.",
		"tgt": "\u0160adeiko is also riding high on happy events in the lives of people close to her."
	},
	{
		"src": "Nii tema endine treeningukaaslane Maris M\u00e4gi kui \u00f5de Grete said hiljuti lapsevanemateks ning mitmev\u00f5istleja on saanud uutelt ilmakodanikelt tuge.",
		"tgt": "Both her former training partners Maris M\u00e4gi and her sister Grete recently became new mothers, and the heptathlete draws support from the new additions to their families."
	},
	{
		"src": "\"P\u00e4ris huvitav on olnud\", s\u00f5nab \u0160adeiko.",
		"tgt": "\u201cIt\u2019s been pretty interesting,\u201d says \u0160adeiko."
	},
	{
		"src": "\u00dcks alkohol, mille joomine v\u00f5rdub aju \"treenimisega\".",
		"tgt": "A type of alcohol that gives your brain a \u201cworkout\u201d"
	},
	{
		"src": "Livestrong kirjutab, et dr Gordon Sheperd on suisa nii suur veinif\u00e4nn, et usub - veiniga saab treenida aju paremini kui \u00fchegi teise asjaga maailmas.",
		"tgt": "Livestrong writes that Dr. Gordon Shepherd is such a big wine fan that he believes that wine can give the brain a better workout than anything else in the world."
	},
	{
		"src": "Sheperd on Yale'i \u00fclikooli neuroteadlane.",
		"tgt": "Shepherd is a neuroscientist at Yale University."
	},
	{
		"src": "Tema s\u00f5nutsi ei ole asi mitte alkoholis v\u00f5i selles, kuidas see meie tundeid ja m\u00f5tteid m\u00f5jutab, vaid hoopis \"v\u00e4ga aktiivses\" veini maitsemise protsessis.",
		"tgt": "He says it\u2019s not about the alcohol or how it affects our feelings or thoughts but rather the \u201cvery active\u201d process of tasting wine."
	},
	{
		"src": "Klaasi nuusutades, veini suus keerutades, seda nautides ja j\u00e4relmaitset tajudes paneme me oma aju t\u00f6\u00f6le, et luua veinile maitse.",
		"tgt": "Sniffing the glass, swirling the wine in one\u2019s mouth, enjoying it and sensing the aftertaste, we make our brain work to create a taste for the wine."
	},
	{
		"src": "Sheperdi s\u00f5nul ei sisalda veinimolekulid tegelikult maitset, vaid maitse tekib viisist, kuidas vein aju stimuleerib.",
		"tgt": "Shepherd says the wine molecule don\u2019t actually contain flavour; the flavour is created by the way the wine stimulates the brain."
	},
	{
		"src": "Ta toob v\u00f5rdluseks selle, kuidas aju \"n\u00e4eb\" v\u00e4rve.",
		"tgt": "He draws a comparison to how the brain \u201csees\u201d colours."
	},
	{
		"src": "\"Maitse pole veinis, maitse loob veini maitsja\", \u00fctleb Sheperd.",
		"tgt": "\u201cThe taste isn\u2019t in the wine, the taste is created by the person tasting the wine,\u201d Shepherd says."
	},
	{
		"src": "Asjad, mis veel veini maitse tekkimist m\u00f5jutavad, on n\u00e4iteks meie vanus, sugu ja isegi s\u00fclje hulk, mida inimene toodab.",
		"tgt": "Other factors that influence the creation of the taste of wine are, for example, our age, gender and even the amount of saliva produced by a person."
	},
	{
		"src": "Sheperd muidugi manitseb, et vein pole selleks, et end t\u00e4is juua.",
		"tgt": "Of course, Shepherd admonishes that wine isn\u2019t for getting drunk on."
	},
	{
		"src": "\"Tegevuses peab olema rohkemat\", \u00fctleb ta.",
		"tgt": "\u201cThere\u2019s more to it than that,\u201d he says."
	},
	{
		"src": "Kui sa v\u00f5tad liiga suure lonksu, on s\u00fcsteem \u00fclek\u00fcllastunud.",
		"tgt": "If you take too big a sip, your system is oversaturated."
	},
	{
		"src": "Liigne veinijoomine v\u00f5ib ajule kasu asemel kahju teha - 2004. aasta uuringu kohaselt riskivad inimesed, kes joovad \u00fcle kolme klaasi veini, m\u00e4lukaotusega, tasakaalu kaotamisega ja v\u00e4henenud vaimse v\u00f5imekusega.",
		"tgt": "Excessive drinking of wine can hurt instead of benefiting the brain \u2013 a 2004 study found those who drank over three glasses of wine risk memory loss, loss of balance and lower mental capacity."
	},
	{
		"src": "10% Eesti IKT sektori t\u00f6\u00f6tajatest saavad kolleegidest v\u00e4hem palka",
		"tgt": "10% of Estonian ICT sector personnel get paid less than their colleagues"
	},
	{
		"src": "Personaliotsingufirma Fontes andmed paljastavad, et 10% Eesti IKT sektori t\u00f6\u00f6tajatest saavad kolleegidest v\u00e4hem palka.",
		"tgt": "Data from the recruiter Fontes reveal that 10% of Estonian ICT sector personnel get paid less than their colleagues."
	},
	{
		"src": "K\u00fcmne protsendiline palgal\u00f5he on meeste ja naiste vahel, kirjutab portaal Geenius.",
		"tgt": "There is a 10% salary gap between men and women, Geenius website writes."
	},
	{
		"src": "Fontese IKT sektori palgauuringus osales 59 IT ja telekommunikatsiooni ettev\u00f5tet.",
		"tgt": "Fifty-nine IT and telecom companies took part in the ICT sector salary survey conducted by Fontes."
	},
	{
		"src": "Kokku oli vaatluse alla 8 577 ametikohta.",
		"tgt": "A total of 8,577 positions were examined."
	},
	{
		"src": "63% ametikohtadest t\u00f6\u00f6tasid mehed.",
		"tgt": "Sixty-three per cent of the positions were filled by men."
	},
	{
		"src": "\"Kuigi ainult 3 ettev\u00f5tet nentisid, et palgaerinevus on meeste kasuks ja \u00fclej\u00e4\u00e4nute ettev\u00f5tete arvates palgaerinevus puudub, siis reaalsuses v\u00f5rreldes sarnaseid t\u00f6id omavahel on meeste kuu p\u00f5hipalk keskmiselt 10% k\u00f5rgem naiste omast ja meeste aasta kogupalk keskmiselt 8% k\u00f5rgem naiste omast\", s\u00f5nas Fontese anal\u00fc\u00fctik Ilmar P\u00f5hjala.",
		"tgt": "\u201cAlthough only three companies mentioned that the pay difference was in favour of the men and the rest of the companies believed there was no salary difference, in reality, comparing similar wok against each other, the men\u2019s basic salary was an average 10% higher than the women\u2019s and the men\u2019s total annual salary was an average of 8% higher than that of the women,\u201d said Fontes analyst Ilmar P\u00f5hjala."
	},
	{
		"src": "\"Narcose\" 3. hooaja reklaamklipp: n\u00fc\u00fcd, mil Pablo Escobar on l\u00e4inud, astub Netflixi hittsarjas kesksele kohale Cali kartell",
		"tgt": "Narcos season 3 trailer: With Pablo Escobar gone, the Cali Cartel take centre stage in Netflix's hit series"
	},
	{
		"src": "Hoolimata sellest, et \"Narcose\" teises hooajas paljastati Pablo Escobari tapja, ei ole Netflixi sari kaugeltki l\u00f5ppenud.",
		"tgt": "Despite season two of Narcos revealing Pablo Escobar's killer, Netflix's series is far from over."
	},
	{
		"src": "Kolmas ja neljas hooaeg on voogedastusteenuselt kinnituse saanud ning esimesele neist on valminud juba reklaamklipp, mis \u00f5rritab sarja uute pahalastega.",
		"tgt": "Season three and four have already been confirmed by the streaming service, the former receiving its first trailer, teasing the show's upcoming villains."
	},
	{
		"src": "Kolmandas hooajas p\u00f6\u00f6rab DEA oma t\u00e4helepanu maailma k\u00f5ige rikkamale narko\u00e4riorganisatsioonile - Cali kartellile.",
		"tgt": "With season three, the DEA has turned their attention towards the richest drug trafficking organisation in the world: the Cali Cartel."
	},
	{
		"src": "Nad tegutsevad nelja v\u00f5imsa ristiisa juhtimisel \"nagu Fortune 500 ettev\u00f5te\", lihtsalt rohkemate altk\u00e4emaksudega valitsusele ja v\u00e4givaldsemate tegudega.",
		"tgt": "Led by four powerful godfathers, they operate \"like a Fortune 500 company\" just with more government bribes and violent actions."
	},
	{
		"src": "Gilberto Rodriguez Orejuela (Damian Alcazar) on kartelli juht, Miguel Rodriguez Orejuela (Francisco Denis) selle aju, Pacho Herrera (Alberto Ammann) juhib sidemeid Mehhikoga ja Chepe Santacruz Londono (Pepe Rapazote) tegutseb New Yorgis.",
		"tgt": "Gilberto Rodriguez Orejuela (Damian Alcazar) is the cartel's leader, Miguel Rodriguez Orejuela (Francisco Denis) being the brains, Pacho Herrera (Alberto Ammann) running the Mexican connection, and Chepe Santacruz Londono (Pepe Rapazote) based in New York."
	},
	{
		"src": "V\u00e4rskelt v\u00e4lja lastud reklaamklipis n\u00e4eb Pedro Pascali naasmas Javier Penana, tegelasena, kes v\u00e4rbab Ameerika ja Colombia \u00f5iguskaitse appi s\u00f5jas narkootikumide vastu.",
		"tgt": "The newly released trailer sees Pedro Pascal return as Javier Pe\u00f1a, the character enlisting American and Colombian law enforcement to help with the war on drugs."
	},
	{
		"src": "Teiste uute n\u00e4itlejate hulka kuuluvad Matias Varela, Michael Stahl-David, Matt Whelan, Miguel Angel Silvestre, Kerry Bishe ja Arturo Castro.",
		"tgt": "Other new actors include Matias Varela, Michael Stahl-David, Matt Whelan, Miguel Angel Silvestre, Kerry Bishe, and Arturo Castro."
	},
	{
		"src": "\"Narcose\" kolmas hooaeg saab avapaugu 1. septembril.",
		"tgt": "Season three of Narcos will debut 1 September."
	},
	{
		"src": "\u00dcRO s\u00f5nul oleneb afgaanide demokraatia naiste rollist poliitikas",
		"tgt": "Afghan democracy depends on political role for women, U.N. says"
	},
	{
		"src": "\u00dcRO Afganistani missiooni juht \u00fctles kolmap\u00e4eval, et valimised saavad esindada rahvast ainult siis, kui k\u00f5ik \u00fchiskonna liikmed, sealhulgas naised, m\u00e4ngivad nendes rolli.",
		"tgt": "Elections can only be representative if all members of society, including women, play a role, the head of the U.N. mission in Afghanistan said Wednesday."
	},
	{
		"src": "\u00dcRO abimissiooni juht Nicholas Haysom \u00fctles, et sajad naised kandideerivad kohalike n\u00f5ukogude valimistel, kolm naist kandideerivad asepresidendiks ja rohkem kui 30 protsenti hiljuti registreerunud valijatest on naised.",
		"tgt": "Nicholas Haysom, acting head of the U.N. Assistance Mission said hundreds of women are running in provincial council elections, three women are running for vice president and more than 30 percent of the newly-registered voters are women."
	},
	{
		"src": "\"Naiste rolli olulisuse r\u00f5hutamisega ei ole v\u00f5imalik liialdada,\" \u00fctles ta kolmap\u00e4eval tehtud avalduses.",
		"tgt": "\"The role of women cannot be overstated,\" he said in a statement Wednesday."
	},
	{
		"src": "Valimised saavad rahvast t\u00f5eliselt esindada ja olla usutavad ainult siis, kui naised osalevad t\u00e4ielikult ja on kaasatud valimisprotsessi k\u00f5ikidesse etappidesse.",
		"tgt": "Elections can only be truly representative and credible when women fully participate and are included in all parts of the electoral process."
	},
	{
		"src": "Afganistani kohalike n\u00f5ukogude valimised ja presidendivalimised toimuvad 5. aprillil.",
		"tgt": "Afghan provincial council and presidential elections take place April 5."
	},
	{
		"src": "Taliban on \u00e4hvardanud omalt poolt valimisprotsessi, mis langeb kokku \u00fcleminekuperioodiga, mil rahvusvaheliste s\u00f5jaliste operatsioonide roll muutub n\u00f5ustavaks.",
		"tgt": "The Taliban has issued threats against an election process that coincides with the transition of international combat operations to an advisory role."
	},
	{
		"src": "Selle aasta valimised t\u00e4histavad esimest korda, mil v\u00f5im antakse rahulikult \u00fchelt demokraatlikult valitud valitsuselt \u00fcle j\u00e4rgmisele.",
		"tgt": "This year's elections mark the first time power is handed peacefully from one democratically elected government to the next."
	},
	{
		"src": "Haysomi s\u00f5nul suurendab naiste tugev roll demokraatia edu Afganistanis.",
		"tgt": "Haysom said a strong role for women will add to Afghanistan's democratic success."
	},
	{
		"src": "Afganistani s\u00f5ltumatu valimiskomisjoni andmetel on 3,6 miljonist registreerunud valijast 1,2 miljonit naised.",
		"tgt": "The Afghan Independent Election Commission reports 1.2 million women are registered out of 3.6 million total registered voters."
	},
	{
		"src": "Jagamise r\u00f5\u00f5m teeb iga asja \u00e4gedamaks nii suurtel kui ka v\u00e4ikestel.",
		"tgt": "The joy of sharing makes everything even cooler, for big as well as for small."
	},
	{
		"src": "\u00dchist aega on alati liiga v\u00e4he, aga trenn p\u00f5nnidega annab hea v\u00f5imaluse \u00fchendada koosolemine, m\u00e4ng, l\u00e4hedus ja koormus.",
		"tgt": "There\u2019s always too little time for shared activities, but working out with the rug rats is a good way to combine shared time, play, closeness and physical exertion."
	},
	{
		"src": "Ja milline mugav lahendus - \u00fcksk\u00f5ik kuhu sa suvel kruiisid, elusad hantlikesed on sul alati kaasas ning tuletavad oma peenikese h\u00e4\u00e4lekesega kannatamatult meelde: \"Teeme n\u00fc\u00fcd trenni ka!\"",
		"tgt": "And what a convenient solution \u2013 no matter where go in the summer, you always have the living dumbbells with you, impatiently reminding you with their little voices: \u201cLet\u2019s work out now!\u201d"
	},
	{
		"src": "Alusta soojendusega - v\u00e4ga hea on tavaline kullim\u00e4ng v\u00f5i m\u00f6\u00f6da rannariba lippamine.",
		"tgt": "Start by warming up \u2013 playing ordinary hide-and-seek or jogging down a stretch of beach is good."
	},
	{
		"src": "K\u00fckk on jalgade ja tuhara vormis p\u00fcsimise alustala - kes siis tahaks suve jooksul lainetest uhutud liivakoogi kuju v\u00f5tta?",
		"tgt": "Squats are the foundation of keeping legs and glutes in shape \u2013 who wants to take on the shape of a wave-smoothed sand castle over the summer?"
	},
	{
		"src": "Imetore on kasutada kangi asemel lapsi!",
		"tgt": "It\u2019s amazing to use children instead of weightlifting equipment!"
	},
	{
		"src": "Esiteks on see turvaline ja mugav, raskus kasvab tasapisi samas tempos nagu treenija j\u00f5ud.",
		"tgt": "First of all, it\u2019s safe and convenient, the weight increases little by little at the same pace as the exerciser\u2019s strength."
	},
	{
		"src": "Edasij\u00f5udnud saavad ka p\u00e4ris suurte lastega k\u00fckke teha.",
		"tgt": "More advanced lifters can also do squats with pretty big kids."
	},
	{
		"src": "Laps treenib tasakaalu, loeb kordusi ja tunneb l\u00f5bu v\u00f5imalusest k\u00f5rgel k\u00f5\u00f5luda ja t\u00e4htis olla.",
		"tgt": "For the kid, it\u2019s balance training, they count the repetitions, and it\u2019s fun to be able to sit high and mighty."
	},
	{
		"src": "Suuremad lapsed v\u00f5ivad samal ajal ise k\u00fckke teha.",
		"tgt": "Bigger children can also do squats at the same time."
	},
	{
		"src": "Liikumise ulatus pane paika maa puudutamise ja k\u00e4te \u00fcles sirutamisega.",
		"tgt": "Establish the range of movement by touching the ground and stretching your arms up."
	},
	{
		"src": "Hoia s\u00f5rmed otse, palu miniabilisel korralikult kinni hoida.",
		"tgt": "Keep your fingers straight, ask your mini-helper to hold on tight."
	},
	{
		"src": "Laps saab lugeda kordusi ja tunda end treenerina.",
		"tgt": "The kid can count repetitions and play coach."
	},
	{
		"src": "Plank on \u00fclikasulik, kuid lapsele jaoks lootusetult igav harjutus.",
		"tgt": "Planking is very beneficial but it\u2019s a hopelessly boring exercise for kids."
	},
	{
		"src": "Kuid asja on lihtne l\u00f5busamaks teha!",
		"tgt": "But it can be made more fun!"
	},
	{
		"src": "M\u00e4ngu-plank: v\u00f5tke pikka plangukolonni, millest kordam\u00f6\u00f6da l\u00e4bi pugeda.",
		"tgt": "Pretend-plank: form a long plank column through which to take turns crawling through."
	},
	{
		"src": "Tegelikult tavalisest raskem, aga palju l\u00f5busam teha, kui vahepeal saab s\u00f5brale k\u00e4tt anda.",
		"tgt": "It\u2019s actually harder than the ordinary version, but much more fun, as you can high-five your friend from time to time."
	},
	{
		"src": "Koormuse lisamiseks v\u00f5ib p\u00fcsida plangus, pisike turjal, ja selles asendis ka ringi k\u00f5ndida.",
		"tgt": "To add resistance, you can stay in the plank position, the little one on your back, and walk around in that position as well."
	},
	{
		"src": "Lisaraskuseks v\u00f5ib pisema lapse puusadele istuma panna, kuid see harjutus pakub l\u00f5bu k\u00f5igile lastele.",
		"tgt": "For extra difficulty, you can put a smaller kid piggy-back on your hips, but this exercise is fun for all kids."
	},
	{
		"src": "Samal ajal kui krabid liival siblida, saavad triitseps, tuhar ja k\u00f5hulihased koormust nagu naksti.",
		"tgt": "While you\u2019re at it, scurrying on the sand, your triceps, glutes and abs will get a workout in no time flat."
	},
	{
		"src": "Laps laskub jalgadele nii, et tema keharaskus jaotub v\u00f5rdselt ette ja taha.",
		"tgt": "Your kid will descend to your legs so that his or her body weight will be evenly spread out to the front and back."
	},
	{
		"src": "Turvalisuseks v\u00f5ib k\u00e4test kinni hoida.",
		"tgt": "You can link hands for safety."
	},
	{
		"src": "K\u00f5verda jalad ja siruta otse \u00fcles.",
		"tgt": "Bend your knees and straighten up."
	},
	{
		"src": "P\u00f5nn saab lennata, l\u00f5butseda, tasakaalu treenida ja raskuseks olla.",
		"tgt": "Your tyke can fly, have fun, practice balance and serve as a resistance weight."
	},
	{
		"src": "V\u00e4ikese treeneri elu on ekstral\u00f5bus, kui ta igal \u00fclestulekul v\u00e4ikese musi saab.",
		"tgt": "Life for the little coach is especially jolly when he gets a little kiss at the top of each movement."
	},
	{
		"src": "Lisakoormust annab jalgade sirutamine ette.",
		"tgt": "Stretching out your legs adds resistance."
	},
	{
		"src": "Kontrolli, et selg p\u00fcsiks neutraalses asendis.",
		"tgt": "Make sure that your back stays in a neutral position."
	},
	{
		"src": "Lastel endil on k\u00f5hulihaseid palju l\u00f5busam teha paaris ja plaksuga.",
		"tgt": "The kids themselves will find it much more fun to train abs in tandem and by clapping."
	},
	{
		"src": "K\u00e4tet\u00f6\u00f6 ja pulsiga k\u00fckk.",
		"tgt": "Arm action and pulsating squats"
	},
	{
		"src": "J\u00e4lgi lapse turvalisust, p\u00f5lve asendit, ja hoia selg neutraalses asendis.",
		"tgt": "Keep an eye on the child\u2019s safety, the position of your knee, and keep your back in a neutral position."
	},
	{
		"src": "K\u00f5igi laste lemmik ja suur l\u00f5bu!",
		"tgt": "A favourite for all kids and a lot of fun!"
	},
	{
		"src": "Vanemale samas t\u00f5eliselt t\u00f5hus kogu keha trenn.",
		"tgt": "For the parents, a truly effective way to work out the whole body."
	},
	{
		"src": "Spordivahenditeks olid Ott (10), S\u00e4de (8), \u00d5nne (4).",
		"tgt": "Ott (10), S\u00e4de (8) and \u00d5nne (4) served as the exercise equipment."
	},
	{
		"src": "Filipiinidelt laia maailma ehk \u00d5lgkoti reis moef\u00e4nnide s\u00fcdamesse",
		"tgt": "From the Philippines to the wide world \u2013 straw bags journey into the hearts of fashion fans"
	},
	{
		"src": "\u00d5lgedest punutud kotid on suveklassika, millest on saanud viimastel aastatel omaette hitttoode, mis \u00fchel \u00f5igel suvenautlejal lausa peab k\u00e4e otsas rippuma ning millele on osanud kaupmehed selle tagasihoidlikust p\u00e4ritolust hoolimata keevitada juurde hitile kohase hinnasildi.",
		"tgt": "Bags woven of straw are a summer classic that in recent years has become a hit product in its own right, which is de rigueur to hang on an arm for anyone properly enjoying the summer. Despite its humble origins, merchants have managed to tack on a price befitting a hit."
	},
	{
		"src": "\u00d5lgedest punutud kott on ilmselt \u00fcks selliseid asju, mis on igal\u00fchel korra elus olemas olnud ja mille omamine pole erilisi emotsioone tekitanud.",
		"tgt": "A bag woven from straw is one of the things that everyone has had at some point in their life and owning which didn\u2019t conjure up any particular emotions."
	},
	{
		"src": "See lihtsalt on olemas ja kui ei ole, siis pole ka midagi katki.",
		"tgt": "You just had it and if you didn\u2019t, there was nothing wrong."
	},
	{
		"src": "N\u00fc\u00fcd on aga \u00f5lgkotid tegemas t\u00f5elist v\u00f5iduk\u00e4iku ja moef\u00e4nnid on oma peened disainerikotid vahetanud suvekuudeks hoopis lihtsate \u00f5lgedest punutud kottide vastu.",
		"tgt": "But now, straw bags are really taking the world by storm, and for the summer months, fashionistas have swapped their sophisticated designer bags for simple bags woven from straw."
	},
	{
		"src": "Seejuures tegemist pole sugugi ainult rannakotiga, vaid t\u00e4naseks on see niisama populaarne ka t\u00e4navakotina ning julgemad naised jalutavad sellega isegi kontorisse.",
		"tgt": "It\u2019s far from just a beach bag, but just as popular as a purse for urban settings, and bolder women even walk into the office carrying them."
	},
	{
		"src": "Siinkohal tasub siiski enne selgeks teha, kas \u00fclemusele taoline suvine look ikka istub v\u00f5i tasub m\u00e4rmik ja s\u00fclearvuti siiski veidi ametlikumasse sumadani l\u00fckata.",
		"tgt": "Yet it would be wise to be certain whether such a summery style is all right with your boss or whether it would be good to stick your day-planner and laptop into a bit more official-looking case."
	},
	{
		"src": "Vaheldusrikkus on \u00f5lgkottidest teinud aga naiste t\u00f5elise suvearmastuse.",
		"tgt": "The amount of variety has made straw bags a real summer fling for women."
	},
	{
		"src": "N\u00e4iteks lugedes v\u00e4lismaiseid moeblogisid, siis esimese asjana j\u00e4\u00e4bki silma see, et moegurmaanid t\u00f5ttavad puhkusereisil esimese asjana kohalikule turule ning soetavad endale m\u00f5ne \u00f5lgkoti, millele siis terve puhkuseaja truu ollakse ning mis k\u00e4ib kaasas rannas, turul ja ka s\u00f5brannadega linna peal h\u00e4ngides.",
		"tgt": "For example, reading foreign fashion blogs, the first thing that catches the eye is that the first thing fashion connoisseurs do when they\u2019re travelling on holiday abroad is rush to the local market as the first thing and buy a straw bag they are loyal to the entire holiday and which accompanies them to the beach, marketplace and while hanging out on the town with girlfriends."
	},
	{
		"src": "M\u00f5ned blogijad on lausa nii heldeld, et ostavad turult kotte suurema hunniku ja m\u00fc\u00fcvad v\u00f5i annavad \u00e4ra neid oma lojaalsetele lugejatele.",
		"tgt": "Some bloggers have been so generous that they buy a larger pile of bags and sell or give them away to their loyal readers."
	},
	{
		"src": "Seejuures v\u00e4\u00e4rib m\u00e4rkimist, et kottide j\u00e4rele on lugejate seas n\u00f5udlus nii suur, et p\u00e4rismaailmas l\u00e4heksid naised (ja mehed!) ilmselt k\u00e4ttpidi \u00fcksteisele kallala, et m\u00f5ne koti \u00f5nnelikuks omanikuks saada.",
		"tgt": "It is worth mentioning that demand for the bags is so high among readers that in the real world women (and men!) would probably have to resort to violence to become the owner of a bag."
	},
	{
		"src": "M\u00f5nes m\u00f5ttes on selline hullus ka arusaadav, sest harvad on need korrad, kui moeilmas on v\u00f5imalik endale m\u00f5ni hitistaatusesse t\u00f5usnud asi osta k\u00f5igest m\u00f5nek\u00fcmne euro eest.",
		"tgt": "In some sense the craze is understandable as it is rare to be able to acquire something with hit status in the fashion world for just a few dozen euros."
	},
	{
		"src": "T\u00f5si, kavalad kaupmehed on avastanud siinkohal ka lihtsa rahateenimisv\u00f5imaluse ning nii m\u00fc\u00fcvad peenemad luksusbr\u00e4ndid \u00f5lekotte ka m\u00f5nesaja ja -tuhande euro eest.",
		"tgt": "True, crafty merchants have hit upon an easy money making opportunity and thus finer luxury brands are selling straw bags for several hundred or thousand euros."
	},
	{
		"src": "Ilmselt ikka selleks, et rikkamad kliendid ei peaks end lihtsurelikena tundma, kes mingite odavate kottidega ringi promeneerivad.",
		"tgt": "No doubt so that wealthier customers don\u2019t have to feel that they are mere mortals promenading around with some cheap bags."
	},
	{
		"src": "N\u00e4iteks on v\u00f5imalik endale osta Dolce & Gabbana \u00fcle tuhande euro maksev \u00f5lgkott.",
		"tgt": "For example, you can buy yourself a Dolce & Gabbana straw bag that costs over a thousand euros."
	},
	{
		"src": "Chaneli \u00f5lgkoti t\u00f5lgenduse eest v\u00f5ib aga v\u00e4lja k\u00e4ia 6000 euro ringis.",
		"tgt": "Chanel\u2019s version of the straw bag will set you back about 6,000 euros."
	},
	{
		"src": "Erinevalt enamikust moehittidest, ei p\u00e4rine \u00f5lgkotid aga sugugi m\u00f5nest suurest moemekast, vaid nende lugu sai alguse hoopis kaugemalt.",
		"tgt": "Unlike most fashion hits, straw bags are not from some big fashion mecca but their origins lie further off."
	},
	{
		"src": "Nimelt p\u00e4rinevad \u00f5lgkotid v\u00e4idetavalt hoopis kaugelt Filipiinidelt, kust need laia ilma kandunud on.",
		"tgt": "Namely, the straw bags originate in the distant Philippines, from which they spread to the wide world."
	},
	{
		"src": "\u00d5lgedest koti punumine on seal eelk\u00f5ige ekspori\u00e4ri ja kohalikke nendega ringi k\u00e4imas v\u00e4ga sageli ei n\u00e4egi.",
		"tgt": "There, weaving bags from straw is an export business above all and locals don\u2019t often go around with them."
	},
	{
		"src": "V\u00e4idetavalt p\u00e4rineb \u00f5lepunumistehnika 14. sajandist ja on k\u00fcllaltki sarane tavalise korvipunumisega.",
		"tgt": "It\u2019s claimed straw-weaving techniques date from the 14th century and they are quite similar to ordinary basket weaving."
	},
	{
		"src": "Kuna aga \u00f5lgkotti ei pea nii tugevalt punuma kui korvi, saab neisse p\u00f5imida musterid ja teisi materjale, mis teevad koti isikup\u00e4rasemaks ja selle v\u00f5rra ka aktraktiivsemaks.",
		"tgt": "As straw bags don\u2019t have to be woven as strongly as a basket, patterns and other materials can be interwoven into them, which makes the bag more distinctive and, on that account, more attractive."
	},
	{
		"src": "N\u00e4iteks on viimasel ajal eriti trendikad kotid, kuhu on sisse punutud v\u00e4rvilised paelad v\u00f5i nahkribad.",
		"tgt": "For instance, bags into which coloured ribbons or leather strips have been woven are particularly trendy."
	},
	{
		"src": "T\u00e4nukirja v\u00f5ivad \u00f5lgkotid eelk\u00f5ige saata aga n\u00e4itlejatar Jane Birkinile, kellest suurimat punutud \u00f5lgkotif\u00e4nni polnud enne n\u00e4htud.",
		"tgt": "Straw bags owe a thank you note above all to actress Jane Birkin, as a bigger fan of straw bags has yet to be seen."
	},
	{
		"src": "Nimelt sobitas ta \u00f5lgkotti k\u00f5ikv\u00f5imalike r\u00f5ivakomplektide juurde ega pidanud paljuks sellega isegi Cannes'i filmifestivalile minna.",
		"tgt": "Namely, she paired a straw bag with all conceivable clothing ensembles and even went to Cannes film festival with one."
	},
	{
		"src": "Kottide populaarsuse juures t\u00e4nap\u00e4eval ei m\u00e4ngi v\u00e4iksemat rolli aga ka see, et nende eest hoolitsemine on kukepea ning erinevalt k\u00f5iksugustest teistest sumadanidest ei pea neid spetsiaalsete vahenditega hooldama, vaid asja ajab \u00e4ra ka vesi ja m\u00e4rg r\u00e4tik.",
		"tgt": "No less of a role in the popularity of the bags today is the fact that it\u2019s easy to care for them and unlike all sorts of other totes, they don\u2019t need to be maintained with special products. Water and a damp towel will suffice."
	},
	{
		"src": "Nagu trendir\u00f6\u00f6gatuste puhul ikka, on peale klassikalise v\u00e4limuse tulnud br\u00e4ndid v\u00e4lja k\u00f5ikv\u00f5imalike t\u00f5lgendustega.",
		"tgt": "As with fad products, brand have come up with all sorts of interpretations besides the classic look."
	},
	{
		"src": "N\u00e4iteks v\u00f5ib soovi korral endale soetada \u00f5lgedest punutud ridik\u00fcli v\u00f5i hoopis tillukese \u00f5lakoti.",
		"tgt": "For instance, you can buy yourself a lady\u2019s handbag woven from straw or even a tiny shoulder bag woven from straw."
	},
	{
		"src": "Samas tasub meeles pidada, et klassikaline \u00f5lgkott ei l\u00e4he iial moest, \u00f5lgridik\u00fcl aga k\u00fcll.",
		"tgt": "It pays to remember that a classic straw bag will not go out of fashion, but a lady\u2019s straw handbag will."
	},
	{
		"src": "Kuid, milline on siis klassikaline \u00f5lgkott?",
		"tgt": "But what is a classic straw bag?"
	},
	{
		"src": "Juba sajandeid on klassikaliseks peetud sellist \u00f5lgedest punutud kotti, mis meenutab oma stiililt korvi, on pealt avatud ning sellele on l\u00fchikesed, samuti \u00f5lgedest, sangad.",
		"tgt": "The type of straw bag that has been considered classic for centuries is reminiscent of a basket, open at the top, with short handles, also made of straw."
	},
	{
		"src": "Viis tervislikku j\u00e4\u00e4tist, mida on kodus imelihtne valmistada",
		"tgt": "Five healthful ice creams that are very easy to make at home"
	},
	{
		"src": "Lifehack.org t\u00f5i v\u00e4lja viisid, kuidas valmistada kodus erinevat sorti j\u00e4\u00e4tiseid, mis sisaldavad v\u00e4hem kaloreid kui poej\u00e4\u00e4tised.",
		"tgt": "Lifehack.org listed ways of making various kinds of homemade ice cream that have fewer calories than store-bought ice creams."
	},
	{
		"src": "Sidruni- ja petij\u00e4\u00e4tis - vispelda suures kausis sidrunimahl suhkruga, lisa pett ja vahukoor ning sega k\u00f5ik \u00fchtlaseks massiks, aseta segu k\u00fclmikusse.",
		"tgt": "Lemon and buttermilk ice cream \u2013 whisk lemon juice with sugar in a big bowl, add the buttermilk and whipping cream and blend until an even consistency is reached, then chill in the fridge."
	},
	{
		"src": "\u0160okolaadi- ja p\u00e4hkliv\u00f5ij\u00e4\u00e4tis - blenderda kreeka jogurt, k\u00fclmutatud banaanid, kakaopulber ja vahtrasiirup \u00fchtlaseks massiks.",
		"tgt": "Chocolate and peanut butter ice cream \u2013 in a blender, combine Greek yoghurt, frozen bananas, cocoa powder and maple syrup until an even consistency is reached."
	},
	{
		"src": "Seej\u00e4rel lisa segule natuke maap\u00e4hkliv\u00f5id ja blenderda segu paar sekundit.",
		"tgt": "Then add a little peanut butter to the mixture and blitz for a few seconds."
	},
	{
		"src": "J\u00e4\u00e4tis on valmis kohe s\u00f6\u00f6miseks.",
		"tgt": "The ice cream is ready to be eaten immediately."
	},
	{
		"src": "Virsikuj\u00e4\u00e4tis - mikserda kausis rasvavaba piim, suhkruasendaja, muna, k\u00fclmutatud v\u00f5i tavalised virsikuviilud ja mandliekstrakt \u00fchtlaseks massiks ning aseta saadud segu k\u00fclmikusse tahenema.",
		"tgt": "Peach ice cream \u2013 using an immersion mixer in a bowl, combine fat-free milk, a sugar substitute, an egg, frozen or fresh sliced peaches and almond extract until an even consistency is reached and place the mixture into the fridge to solidify."
	},
	{
		"src": "Kookosej\u00e4\u00e4tis - blenderda kookospiim, kookoshelbed, vanilliekstrakt, vahtrasiirup ja k\u00fclmutatud banaanid ning aseta saadud segu k\u00fclmikusse.",
		"tgt": "Coconut ice cream \u2013 in a blender, blitz coconut milk, coconut flakes, maple syrup and frozen bananas and place the resulting mixture into the fridge."
	},
	{
		"src": "Banaanij\u00e4\u00e4tis - mikserda kausis k\u00fclmutatud banaanit\u00fckid koos v\u00e4herasvase piimaga \u00fchtlaseks massiks, serveeri kreeka p\u00e4hklitega ja tarbi kohe.",
		"tgt": "Banana ice cream \u2013 using an immersion mixer in a bowl, blend frozen banana chunks with lowfat milk until an even consistency is reached, serve with walnuts and eat right away."
	},
	{
		"src": "Need olid lemmikkodud kinnisvaraturul juulikuus - stiilised, kallid ja luksuslikud!",
		"tgt": "These were the favourite homes in the real estate market in July \u2013 stylish, expensive and luxurious!"
	},
	{
		"src": "Suvi on suur kodu ehitamise, otsimise ja remontimise aeg.",
		"tgt": "Summer is a big time for home construction, buying and repair."
	},
	{
		"src": "Millised kaunid elamised k\u00f6itsid juulikuus kinnisvaraportaali City24.ee k\u00fclastajaid k\u00f5ige enam?",
		"tgt": "What beautiful experiences captivated the visitors to City24.ee the most in July?"
	},
	{
		"src": "Huvi pakkusid kallimas hinnaklassis majad v\u00f5i majaosad.",
		"tgt": "Buildings and parts of houses in the highest price category were of interest."
	},
	{
		"src": "Ilmselt paneb jahe ja heitlike ilmadega suvi rohkem unistama oma \u00f5dusast ja soojast pesast.",
		"tgt": "No doubt the cool and changeable summer weather makes people dream of a cosy warm nest."
	},
	{
		"src": "Majaosa, Tallinn, 285 000 \u20ac Majaosa rahulikus Meriv\u00e4lja elamurajoonis.",
		"tgt": "Part of a house, Tallinn, \u20ac285,000, in peaceful Meriv\u00e4lja residential neighbourhood."
	},
	{
		"src": "Majal on suur katuse ja klaasist l\u00fckandustega terrass, aga leiab muudki ligit\u00f5mbavat, nagu n\u00e4iteks teise korruse suur vannituba.",
		"tgt": "The house has a big roof and terrace with sliding glass door, but there are also other draws, such as the big upstairs bathroom."
	},
	{
		"src": "Vaata l\u00e4hemalt siit.",
		"tgt": "For more information, see here."
	},
	{
		"src": "Maja, Harjumaa, 218 000 \u20ac Huvitava ajalooga, v\u00e4ga hea energia ning planeeringuga klassikaline taluh\u00e4\u00e4rberi t\u00fc\u00fcpi maja on ehitatud 1930. aastatel.",
		"tgt": "House, Harju County, \u20ac218,000. Classical rambling farmhouse type of house built in the 1930s, with an interesting history, very good energy and floor plan."
	},
	{
		"src": "Renoveerimisel on s\u00e4ilitatud vanad laudp\u00f5randad, aknad, uksed, kamin, ahi ja soem\u00fc\u00fcrid.",
		"tgt": "The old floorboards, windows, doors, fireplace, stove and heat-retaining walls were all spared during the renovation."
	},
	{
		"src": "Disainmaja, P\u00e4rnu, 495 000 \u20ac Ainulaadne kaasaegse disainiga eramu P\u00e4rnus.",
		"tgt": "Designer house, P\u00e4rnu, \u20ac495,000 A detached home in P\u00e4rnu with a unique contemporary design."
	},
	{
		"src": "Maja on v\u00e4ga energias\u00e4\u00e4stlik privaatne k\u00f5rghaljastus, teiselt korruselt merevaade.",
		"tgt": "The building has high energy performance and trees give it privacy, sea view from upstairs."
	},
	{
		"src": "Maja, Harjumaa, 469 000 \u20ac Arhitekt Oliver Alveri loodud hoonete kompleks looduslikult kaunis asukohas P\u00fc\u00fcnsi k\u00fclas, Viimsis.",
		"tgt": "House, Harju County, \u20ac469,000 A complex of buildings designed by architect Oliver Alver in a naturally scenic location in P\u00fc\u00fcnsi Village, Viimsi."
	},
	{
		"src": "Hooned on valdavalt tumedast tellisest, andes hoonetekompleksile nii soliidse ja rahuliku v\u00e4limuse kui ka tagades hoone fassaadi hooldamise lihtsuse.",
		"tgt": "The buildings are mainly dark brick, which gives the complex a presentable and calm appearance and makes it easy to maintain the fa\u00e7ade."
	},
	{
		"src": "Maja, Tallinn, 550 000 \u20ac Looduslikult kaunil Meriv\u00e4ljal asuva kolmekorruselise eramu arhitekt on Rein Karp.",
		"tgt": "House, Tallinn, \u20ac550,000 The architect of the three-storey residence in Meriv\u00e4lja is Rein Karp."
	},
	{
		"src": "Maja on v\u00e4ga heas korras ja stabiilselt hooldatud.",
		"tgt": "The house is in very good condition and has been kept regularly maintained."
	},
	{
		"src": "Avar ja l\u00e4bim\u00f5eldud planeering kokku kolmel korrusel.",
		"tgt": "The spacious, well-designed floor plan extends throughout three storeys."
	},
	{
		"src": "N\u00f5elasilmast tulnud minimalism - detailideni l\u00e4bi m\u00f5eldud kodu",
		"tgt": "Minimalism through the eye of a needle \u2013 a home conceived down to the details"
	},
	{
		"src": "Kuldse puudutusega kodu milj\u00f6\u00f6v\u00e4\u00e4rtuslikus Tammelinnas",
		"tgt": "A home with the golden touch in the historic Tammelinn district."
	},
	{
		"src": "Naine ehitab kodu - funkmaja asemel kerkis puitmaja",
		"tgt": "Woman builds home \u2013 timber house goes up instead of Functionalist house."
	},
	{
		"src": "Saaremaal kolme p\u00e4eva eest kadunud mees leiti \u00fcles",
		"tgt": "Man missing for three days on Saaremaa is found"
	},
	{
		"src": "Aare lahkus kolmap\u00e4eva \u00f5htul oma kodust K\u00e4rla alevikus teadmata suunas.",
		"tgt": "Aare left his home in K\u00e4rla hamlet on Wednesday evening, direction unknown."
	},
	{
		"src": "Aarega oli telefoni teel viimane kontakt eile, reede \u00f5htul ning telefoni positsioneering andis mehe asukohaks L\u00e4\u00e4ne-Saare valla, M\u00f5nnuste k\u00fcla, kust otsiti teda helikopteriga s\u00fcda\u00f6\u00f6ni ning koertega varahommikuni.",
		"tgt": "The last telephone contact with Aare was yesterday, on Friday evening, and mobile positioning gave his location as M\u00f5nnuste village in L\u00e4\u00e4ne-Saare municipality, where searches were conducted by helicopter until midnight and, with dogs, until early morning."
	},
	{
		"src": "Seej\u00e4rel sai tema telefoni aku t\u00fchjaks ning mehe asukohta polnud seet\u00f5ttu enam v\u00f5imalik kindlaks teha.",
		"tgt": "His telephone battery then ran out and it was no longer possible to position his location."
	},
	{
		"src": "Politsei j\u00e4tkas otsinguid t\u00e4na hommikul.",
		"tgt": "The police continued the search this morning."
	},
	{
		"src": "Politsei t\u00e4nab k\u00f5iki, kes aitasid kaasa Aare leidmisele.",
		"tgt": "The police thanks everyone who assisted in finding Aare."
	},
	{
		"src": "GMB muretseb investeeringute p\u00e4rast ettev\u00f5tte McVitie's Glasgow tehasesse",
		"tgt": "GMB concern over investment at McVitie's Glasgow factory"
	},
	{
		"src": "Ameti\u00fching ootab k\u00fcpsisetootja McVitie's juhtidelt kinnitust pikaajaliste tootmisplaanide kohta ettev\u00f5tte Glasgow tehases.",
		"tgt": "A union is seeking reassurance from managers at biscuit maker McVitie's over its long-term commitment to production at its factory in Glasgow."
	},
	{
		"src": "GMB Scotlandi s\u00f5nul on ettev\u00f5te vaikinud Tollcrossi objekti investeeringu tuleviku teemal.",
		"tgt": "GMB Scotland said the company had been silent over the future of investment at the Tollcross site."
	},
	{
		"src": "Tehases, kus toodetakse Hobnobsi ja Rich Tea k\u00fcpsiseid ning teisigi tooteid, t\u00f6\u00f6tab rohkem kui 500 inimest.",
		"tgt": "More than 500 people work at the plant, which produces Hobnobs and Rich Tea biscuits, among other products."
	},
	{
		"src": "Ettev\u00f5tte McVitie's omanik Pladis \u00fctles, et nad on investeerinud objekti viimase paari aasta jooksul rohkem kui 5 miljonit naela.",
		"tgt": "McVitie's owner Pladis said it had invested more than \u00a35m at the site in the last few years."
	},
	{
		"src": "Sinna palgati juurde t\u00f6\u00f6tajaid ja ameti\u00fchingu esimehed \"on esimesed, kes kuulevad\", kui midagi tehase tegevuses muutub.",
		"tgt": "It added employees and union representatives \"will be the first to know\" if there were any changes to its operations."
	},
	{
		"src": "Ettev\u00f5tte objektijuhile saadetud kirjas p\u00f6\u00f6rdus GMB Scotland ettev\u00f5tte McVitie's poole palvega \"lahata muresid seoses sellega, et rahastust ei kasutata tootmisliinide n\u00fc\u00fcdisajastamiseks\".",
		"tgt": "In a letter to the company's site manager, GMB Scotland called on McVitie's to \"address concerns that funding is not being brought forward for the modernisation of production lines.\""
	},
	{
		"src": "GMB vanemorganisaator Drew Duffy s\u00f5nas: \"Asjaolu, et me ei saa objekti peajuhatajalt selgust Tollcrossi \u00e4rivajaduste ja tuleviku investeerimisplaani osas, paneb meie liikmeid s\u00fcgavalt muretsema.",
		"tgt": "GMB senior organiser Drew Duffy, said: \"The fact that we cannot get clarity from the general site manager over the business needs and investment plan for the future of Tollcross is deeply concerning our members."
	},
	{
		"src": "Siin on t\u00f6\u00f6tanud mitme p\u00f5lvkonna jagu perekondi ning t\u00f6\u00f6j\u00f5ud koosneb suuresti kohalikust kogukonnast ja Glasgow \u00fcmbruskonna inimestest, olles h\u00e4davajalik tugisammas korraliku t\u00f6\u00f6h\u00f5ive tagamiseks piirkonnas, kus on k\u00f5rge t\u00f6\u00f6tus ja valitseb sotsiaalne ilmaj\u00e4etus.",
		"tgt": "Generations of families have worked here and the workforce is highly concentrated in the local community and the greater Glasgow area, a crucial pillar of decent employment in an area of high unemployment and social deprivation."
	},
	{
		"src": "Seega vajab Glasgow idaosa t\u00f6\u00f6kohtade, palga ja heaolu seisukohalt ning Brexiti, elamiskulude t\u00f5usu ning tootmise kroonilise kahanemise taustal h\u00e4dasti j\u00f5udsalt kasvava tootlusega ettev\u00f5ttet McVitie's.\"",
		"tgt": "So, from the perspective of jobs, pay and prosperity, and against the backdrop of Brexit, rising cost of living and chronic manufacturing decline, the east end of Glasgow desperately needs a thriving manufacturing presence at McVitie's.\""
	},
	{
		"src": "Pladise esindaja \u00fctles: \"Tollcrossi objektijuht sai GMB Scotlandilt kirja alles eile ning ettev\u00f5te vastab talle otse, kuna v\u00e4\u00e4rtustame aktiivset suhtlust t\u00f6\u00f6tajate ja ameti\u00fchingu esindajatega.",
		"tgt": "A spokeswoman for Pladis said: \"The site manager at Tollcross received a letter from GMB Scotland only yesterday and the company will be responding directly as we value ongoing engagement with employees and union representatives."
	},
	{
		"src": "Kaks kuud tagasi toimus Tollcrossis t\u00f6\u00f6tajate ja GMB esindajate vaheline regulaarne kohtumine, kus arutati avatult mitmeid probleeme.",
		"tgt": "We had a regular meeting with employees and GMB representatives at Tollcross two months ago at which a number of issues were discussed openly."
	},
	{
		"src": "Arutasime siis t\u00f6\u00f6tajatega, et nagu k\u00f5ik teised \u00e4\u00e4rmiselt konkurentsirohkes ja ebakindlas majanduskliimas tegutsevad ettev\u00f5tted, vaatame oma tegevusi jooksvalt \u00fcle - ja see kehtib k\u00f5igi meie ettev\u00f5tete ning objektide kohta -, et tagada oma konkurentsiv\u00f5imelisus.",
		"tgt": "We discussed with employees then that like all companies operating in an extremely competitive and uncertain economic climate, we review our operations on an ongoing basis - and that applies across our all our businesses and sites - in order to remain competitive."
	},
	{
		"src": "Ta lisas: \"Viimastel aastatel oleme investeerinud Tollcrossi objekti \u00fcle 5 miljoni naela, suurem osa sellest on l\u00e4inud tootmisliinidesse ja toimingute t\u00e4iustamisse.",
		"tgt": "She added: \"In recent years, we have invested over \u00a35m in our Tollcross site, notably on production lines and operational improvements."
	},
	{
		"src": "M\u00f5istame t\u00e4ielikult Tollcrossi kui tootmisobjekti p\u00e4randit ja kui objekti tegevuses peaks toimuma mingeid muutusi, on t\u00f6\u00f6tajad ja ameti\u00fchingu esindajad esimesed, kes sellest kuulevad.\"",
		"tgt": "We fully recognise the heritage of Tollcross as a manufacturing site and should there be any changes to our operations at the site, employees and their union representatives will be the first to know.\""
	},
	{
		"src": "Kas PSG hoiatas Barcelonat kolm aastat tagasi Neymarile l\u00e4henemise eest?",
		"tgt": "Did PSG warn Barcelona about move for Neymar three years ago?"
	},
	{
		"src": "La Liga v\u00f5ib kahetseda oma huvi Marco Verratti vastu",
		"tgt": "La Liga side may rue their interest in Marco Verratti"
	},
	{
		"src": "Paris Saint-Germain ei anna alla p\u00fc\u00fcdlustes meelitada Neymar oma ridadesse, tehes tema v\u00e4ljaostmiseks 189 miljoni naela suuruse pakkumise. Kuid kas nad hoiatasid Barcelonat kolm aastat tagasi selle rekordilise vallutusretke eest?",
		"tgt": "Paris Saint-Germain will not let up in their pursuit of Neymar after lodging a \u00a3189m offer to trigger his release clause, but did they warn Barcelona of the world-record raid three years ago?"
	},
	{
		"src": "See k\u00f5muline l\u00e4henemine on avanud suvise \u00fcleminekuakna ning Ligue 1 klubi on valmis purustama rohkem kui kahekordselt \u00fcleostmise praeguse maailmarekordi, mis p\u00fcstitati eelmisel hooajal Paul Pogba naasmisega Manchester Unitedisse 89 miljoni naela eest.",
		"tgt": "The sensational approach has lit up the summer transfer window, with the Ligue 1 club ready to break the world transfer record by more than double the previous mark, which saw Paul Pogba return to Manchester United last season for \u00a389m."
	},
	{
		"src": "Kui \u00fcleminek on l\u00f5pule viidud, saab Neymarist selle tulemusel maailma k\u00f5ige kallim m\u00e4ngija ja \u00fchtlasi k\u00f5ige k\u00f5rgemini tasustatud professionaalne sportlane maailmas, kes hakkab saama p\u00e4rast makse PSG-lt palgaks \u00fcle 500 000 naela n\u00e4dalas.",
		"tgt": "Once completed, the move will see Neymar become the world's most expensive player and also the highest-paid professional sportsman in the world, with PSG offering wages of over \u00a3500,000-a-week after tax."
	},
	{
		"src": "Barcelona on teadagi vihane nii l\u00e4henemise viisi kui ka Neymari vabaks murdmise t\u00f5ttu, kuigi Catalansi juhatusele l\u00e4hedane allikas kinnitab, et klubi on jalgpalluri eest alates tema Santosest saabumisest 2013. aastal alati parimat hoolt kandnud.",
		"tgt": "Barcelona are known to be furious with the manner of the approach and the way that Neymar has forced his way out, despite a source close to the Catalans' board insisting that the club have always done their best to look after him since his arrival from Santos in 2013."
	},
	{
		"src": "Kuid kas PSG president hoiatas jalgpallimaailma sellise v\u00f5imaluse eest kolm aastat tagasi?",
		"tgt": "But was the football world warned of this prospect three years ago by the PSG president?"
	},
	{
		"src": "Kui Manchester City n\u00e4itas 2014. aastal v\u00e4lja huvi Blaise Matuidiga lepingu s\u00f5lmimise vastu, hoiatas Nasser Al-Khelaifi karmilt k\u00f5iki klubisid, kes m\u00f5tlevad m\u00f5ne PSG parima m\u00e4ngija v\u00e4rbamise peale.",
		"tgt": "When Manchester City expressed an interest in signing Blaise Matuidi in 2014, Nasser Al-Khelaifi had a stern warning for any club looking to sign one of PSG's best players."
	},
	{
		"src": "\"Ma ei muretse, kuna nad teavad, et kui nad puudutavad m\u00f5nda meie m\u00e4ngijat, siis me astume neile vastu ja v\u00f5tame \u00fchendust nende m\u00e4ngijatega,\" s\u00f5nas Al-Khelaifi.",
		"tgt": "\"I am not worried because they know that if they touch one of our players, then we will be in opposition to them, we'll contact their players,\" Al-Khelaifi said."
	},
	{
		"src": "\"Me austame k\u00f5iki klubisid.",
		"tgt": "\"We respect all clubs."
	},
	{
		"src": "Aga kui nad p\u00fc\u00fcavad s\u00f5lmida lepingut m\u00f5ne meie m\u00e4ngijaga, tuleb neil tagaj\u00e4rgedega silmitsi seista.\"",
		"tgt": "But if they try to sign one of our players, they'll face consequences.\""
	},
	{
		"src": "Barcelona n\u00e4ib olevat sellest piirist \u00fcle astunud, kuna Hispaania klubi n\u00e4itas varem sel suvel \u00fcles huvi PSG keskv\u00e4ljam\u00e4ngija Marco Verratti vastu.",
		"tgt": "Barcelona appear to have crossed this line, with the Spanish club expressing an interesting in PSG midfielder Marco Verratti earlier this summer."
	},
	{
		"src": "PSG tegi selgeks, et nad ei lase itaallasel \u00fchelgi tingimusel lahkuda ja et Barcelona v\u00f5ib saada selle huvi tulemusel tagasil\u00f6\u00f6gi, kaotades Neymari kujul \u00fche oma kallitest varadest.",
		"tgt": "PSG made it clear that they would not allow the Italy international to leave under any circumstances, and Barcelona could well be feeling the repercussions of that interest by losing one of their prize assets in Neymar."
	},
	{
		"src": "Peaminister: Iirimaa tahab p\u00e4rast Brexitit ehitada sildu, mitte piire.",
		"tgt": "Prime minister: After Brexit, Ireland wants to build bridges, not borders."
	},
	{
		"src": "\"Brexit \u00e4hvardab t\u00f5siselt l\u00fc\u00fca kiilu P\u00f5hja-Iirimaa ja Iirimaa, Suurbritannia ja Iirimaa vahele\", hoiatas Varadkar esimesel visiidil P\u00f5hja-Iirimaale p\u00e4rast ametisseastumist juunis.",
		"tgt": "\u201cBrexit seriously threatens to drive a wedge between Northern Ireland and Ireland as well as between Great Britain and Ireland,\u201d Varadkar warned on his first visit to Northern Ireland since taking office in June."
	},
	{
		"src": "\"Ma ei suuda ette kujutada, kes sellest kasu saaks\", lisas ta.",
		"tgt": "\u201cI can\u2019t imagine who would gain from this,\u201d he added."
	},
	{
		"src": "Piiri\u00fclesed taristuprojektid muutsid v\u00f5imalikuks praeguse inimeste ja kaupade vaba liikumise, \u00fctles Varadkar.",
		"tgt": "Cross-border infrastructure projects made possible the current freedom of movement of people and goods, he said."
	},
	{
		"src": "\"See on meie visioon tulevikuks: ehitada sildu, mitte piire\", r\u00f5hutas ta.",
		"tgt": "\u201cThis is our vision for the future: to build bridges, not borders,\u201d he stressed."
	},
	{
		"src": "Varadkari s\u00f5nul eelistaks ta Suurbritannia j\u00e4\u00e4mist osaks Euroopa Liidust, ja kuna seda ei suudeta, siis j\u00e4\u00e4mist osaks Euroopa \u00fchisturust.",
		"tgt": "Varadkar said he would prefer Great Britain to remain part of the European Union, or since this is not possible, to remain part of the European Single market."
	},
	{
		"src": "See s\u00e4ilitaks praeguse vabakaubanduse Iiri Vabariigi ja \u00dchendkuningriigi vahel.",
		"tgt": "This would preserve the current free trade between the Republic of Ireland and the United Kingdom."
	},
	{
		"src": "Teine v\u00f5imalus muuta Suurbritannia lahkumine sujuvamaks oleks Euroopa Liidu ja \u00dchendkuningriigi tolliliidu loomine, seletas Iiri peaminister.",
		"tgt": "Another way to make the exit of Britain smoother would be to establish a customs union between the European Union and the United Kingdom, explained the Irish prime minister."
	},
	{
		"src": "M\u00e4rkides, et selline kokkulepe eksisteeris T\u00fcrgiga, s\u00f5nas Varadkar: \"Kindlasti v\u00f5iks meil olla selline Suurbritanniaga\".",
		"tgt": "Noting that such an agreement existed with Turkey, Varadkar said: \u201cCertainly we could have such an agreement with Great Britain.\u201d"
	},
	{
		"src": "Alternatiiv sellele oleks naasmine tollipunktide juurde, mis kuulutaksid ajaloolist l\u00f5hestatust ja poliitilist l\u00e4bikukkumist.",
		"tgt": "An alternative to this would be going back to customs checkpoints, which would be a declaration of historical fragmentation and political failure."
	},
	{
		"src": "\"T\u00f5ke kaubandusele, \u00f5itsengule ja rahule\", s\u00f5nas Iiri peaminister.",
		"tgt": "\u201cA barrier to trade, prosperity and peace,\u201d said the Taoiseach."
	},
	{
		"src": "Ta nimetas Brexitit \"meie p\u00f5lvkonna v\u00e4ljakutseks\" ning hoiatas, et selle tulemus v\u00f5ib m\u00f5jutada P\u00f5hja-Iiri igap\u00e4evaelu iga aspekti.",
		"tgt": "He called Brexit \u201cour generation\u2019s challenge\u201d and warned that the outcome could affect all aspects of everyday life for Northern Ireland."
	},
	{
		"src": "Iiri peaminister kohtus Belfasti k\u00fclastades P\u00f5hja-Iiri peamiste parteide liidritega.",
		"tgt": "The Taoiseach met with the leaders of Northern Ireland\u2019s primary political parties on a visit to Belfast."
	},
	{
		"src": "Oma esimese poolpika triatloni l\u00e4binud M\u00e4rt Avandi: Ironman'i suudab l\u00e4bida iga\u00fcks.",
		"tgt": "M\u00e4rt Avandi after first full triathlon: Anyone can make it through an Ironman."
	},
	{
		"src": "T\u00e4na peeti talvepealinnas Otep\u00e4\u00e4l Baltimaade suurimat triatlonifestivali, kui poolpika Ironmani v\u00f5istlustulle asus ligikaudu tuhat triatleeti \u00fcle kolmek\u00fcmnest riigist.",
		"tgt": "Today, in the winter capital of Estonia Otep\u00e4\u00e4, the biggest triathlon festival in the Baltics was held, with close to a thousand triathletes from over 30 countries entering the fray in the Ironman."
	},
	{
		"src": "70,3 miili pikkune distants koosnes 1,9 km ujumisest, 90 km rattas\u00f5idust ning 21,1 km rattas\u00f5idust.",
		"tgt": "The 70.3 mile distance was made up of a 1.9 km swim, 90 km of cycling and 21.1 km of cycling."
	},
	{
		"src": "Teiste seas l\u00f5petas v\u00f5idukalt oma elu esimese triatloni ka M\u00e4rt Avandi.",
		"tgt": "Among others, M\u00e4rt Avandi who triumphantly completed his first triathlon ever."
	},
	{
		"src": "\"Arvasin, et osutub keeruliseks ning l\u00f5puks oligi keeruline\", t\u00f5des Avandi fini\u0161is.",
		"tgt": "\u201cI thought it would be complicated and in the end it was complicated,\u201d Avandi admitted at the finish."
	},
	{
		"src": "Hoolimata keerukusest t\u00f5des Avandi, et tegelikult on triatlon j\u00f5ukohane pea k\u00f5igile.",
		"tgt": "In spite of the difficulty, Avandi said that a triathlon was actually within anyone\u2019s ability."
	},
	{
		"src": "\"Mitte distants ei tapa, vaid tempo tapab\", \u00fctles ta, vihjates et j\u00f5ukohase tempoga j\u00f5uab fini\u0161isse pea iga\u00fcks.",
		"tgt": "\u201cIt\u2019s not the distance that does you in, but the pace,\u201d he says, intimating that nearly anyone should be able to finish if they go at a manageable pace."
	},
	{
		"src": "V\u00e4lja arvatud Ott Sepp: \"Oti f\u00fc\u00fcsisega on k\u00fcll k\u00f5ik korras, kuid paraku ei oska ta ujuda\".",
		"tgt": "Except for Ott Sepp: \u201cOtt is fine physique-wise, but unfortunately he doesn\u2019t know how to swim.\u201d"
	},
	{
		"src": "Avandi oli agaralt trenni teinud juba veebruarist saati.",
		"tgt": "Avandi has been training hard since February."
	},
	{
		"src": "Alguses 4-5 tundi n\u00e4dalas, hiljem aga juba k\u00fcmme tundi n\u00e4dalas.",
		"tgt": "At first, 4-5 hours a week, but later on, ten hours a week."
	},
	{
		"src": "Ajaga 05:34:12 saavutas ta \u00fcldarvestuses 270. koha.",
		"tgt": "His time of 5:34:12 gave him 270th overall."
	},
	{
		"src": "Kuigi Avandi kaotas nii Raio Piirojale (aeg 04:59:53) kui ka J\u00fcrgen Ligile (aeg 05:06:37), v\u00f5itis ta teisi niinimetatud \"prominentide klassis\" v\u00f5istelnuid.",
		"tgt": "Although Avandi was behind both Raio Piiroja (4:59:53) and J\u00fcrgen Ligi (5:06:37), he did beat the other competitors in the \u201ccelebrity\u201d category."
	},
	{
		"src": "Eelmisel aastal \"hea eeskuju persooniks\" olnud Tanel Padar kaotas Avandile seitsme minutiga (aeg 05:41:54), ajakirjanik Sten Teppan 16 minutiga (aeg 05:50:23), Kalev Kruus ja Raivo E. Tamm ligikaudu tunniga (ajad vastavalt 06:31:53 ja 06:45:18).",
		"tgt": "Tanel Padar, featured as a \u201cgood role model\u201d last year, was seven minutes behind Avandi (5:41:54), journalist Sten Teppan was 16 minutes behind (5:50:23), and Kalev Kruus and Raivo E. Tamm nearly an hour behind (6:31:53 and 6:45:18, respectively)."
	},
	{
		"src": "Ironman'i sarja kuuluva Otep\u00e4\u00e4 etapi meeste arvestuse \u00fcldv\u00f5itjaks krooniti sakslane Johannes Moldan ajaga 3:58:27, eestlastest oli parim Ivo Suur ajaga 04:14:09.",
		"tgt": "The overall winner on the men\u2019s side of the Otep\u00e4\u00e4 round of the Ironman series was the German Johannes Moldan with a time of 3:58:27, and Ivo Suur was the best among the Estonians with a time of 4:14:09."
	},
	{
		"src": "Naiste seas v\u00f5idutses taanlane Helle Frederiksen ajaga 04:24:01, eestlastest aga Maria J\u00e4nese, kes kaotas Frederiksenile ligi poole tunniga ning sai ajaks 04:58:58.",
		"tgt": "Among the women, the Dane Helle Frederiksen won with a time of 4:24:01, and of the Estonians, Maria J\u00e4nese, who was close to half an hour behind Frederiksen with a time of 4:58:58."
	},
	{
		"src": "Avandi l\u00e4bis 1,9 km pikkuse ujumisdistantsi 42 minuti ja 14 sekundiga.",
		"tgt": "Avandi covered the 1.9 km swimming distance in a time of 42 minutes and 14 seconds."
	},
	{
		"src": "Veest v\u00e4lja tuli ta 410. positsioonil.",
		"tgt": "He came out of the water in 410th place."
	}
]